    task.spawn(function()
        repeat
            task.wait()
        until Store.map or vape.Loaded == nil
        if vape.Loaded == nil then
            return
        end
        local RayParams: RaycastParams = RaycastParams.new()
        RayParams.FilterType = Enum.RaycastFilterType.Include
        RayParams.FilterDescendantsInstances = {Store.map}
        Store.airRay = RayParams

        repeat
            if Entity.isAlive then
                Entity.character.AirTime = Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air and tick() or Entity.character.AirTime
            end

            local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position or nil
            local Gravity, Now = workspace.Gravity, tick()
            for _, v: any in Entity.List do
                local Velocity: Vector3 = v.RootPart.AssemblyLinearVelocity
                v.LandTick = math.abs(Velocity.Y) < 0.1 and v.LandTick or Now
                if (Now - v.LandTick) > 0.2 and v.Jumps ~= 0 then
                    v.Jumps = 0
                    v.Jumping = false
                end

                local Moving: boolean = Velocity.Magnitude > 1
                if v.Targetable and (Now - (v.TrackTick or 0)) >= (Moving and 1 / 30 or 0.2) then
                    v.TrackTick = Now
                    PredictionLib.Observe(v.RootPart, v.RootPart.Position, Velocity, v.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Velocity.Y) > 0.01, Gravity, Moving and LocalPosition or nil, v.HipHeight, v.Jumping and 42.6 or nil)
                end
            end
            task.wait()
        until vape.Loaded == nil
    end)

