        local LastKits, Notified
        repeat
            local Kits: {string} = Store.equippedKits or {}
            local Key: string = table.concat(Kits, ",")
            if Key ~= LastKits then
                for _, v: any in Highlighted do
                    v:SetHighlight(nil)
                end
                table.clear(Highlighted)
                LastKits, Notified = Key, false
            end

            if #Highlighted == 0 then
                local Shown: {string} = {}
                local Supported: {string} = {}
                for _, Kit: string in Kits do
                    local Found: boolean = false
                    for _, v: string in KitModules[Kit] or {} do
                        local Module = vape.Modules[v]
                        if Module and Module.SetHighlight then
                            Found = true
                            if not table.find(Highlighted, Module) then
                                table.insert(Highlighted, Module)
                                table.insert(Shown, Module.Name)
                                Module:SetHighlight(#Highlighted)
                            end
                        end
                    end

                    if Found then
                        local Meta = bedwars.BedwarsKitMeta[Kit]
                        table.insert(Supported, (Meta and Meta.name or Kit):lower())
                    end
                end

                if #Shown > 0 and not Notified then
                    Notified = true
                    SendNotification("Kits", `This script supports the {table.concat(Supported, " and ")} kit{#Supported > 1 and "s" or ""}!\nModules: {table.concat(Shown, ", ")}`, 20, "info")
                end
            end
            task.wait(1)
        until vape.Loaded == nil
    end)

    task.spawn(function()
        local Identity = getthreadidentity and setthreadidentity and getthreadidentity()
        repeat
            if Identity then
                setthreadidentity(2)
            end

            local Success, Shop = pcall(function()
                require(ReplicatedStorage.TS.games.bedwars.shop["bedwars-shop-override"]).getBedwarsShopOverrides()
                return require(ReplicatedStorage.TS.games.bedwars.shop["bedwars-shop"]).BedwarsShop
            end)

            if Identity then
                setthreadidentity(Identity)
            end

            if Success and Shop then
                bedwars.Shop = Shop
                Store.shopLoaded = true
                return
            end

            task.wait(2)
        until vape.Loaded == nil
    end)

    task.spawn(function()
        local Signals: {string} = {"Heartbeat", "PostSimulation", "PreAnimation", "PreRender", "PreSimulation", "RenderStepped", "Stepped"}

        local function CleanSignals()
            if not getconnections or not getfunctionhash or not isexecutorclosure then
                return
            end

            local Seen = {}
            for _, v: string in Signals do
                for _, Connection: any in getconnections(RunService[v]) do
                    if Connection.Function and not Connection.ForeignState and isexecutorclosure(Connection.Function) then
                        local Hash: string = `{v}{getfunctionhash(Connection.Function)}`
                        if Seen[Hash] then
                            Connection:Disconnect()
                        else
                            Seen[Hash] = true
                        end
                    end
                end
            end

            for _, v: any in bedwars.SyncEvents do
                if typeof(v) == "table" and typeof(v.entries) == "table" then
                    table.clear(Seen)
                    for i: any, Entry: any in v.entries do
                        local Callback = Entry.callbackInfo and Entry.callbackInfo.callback
                        if Callback and isexecutorclosure(Callback) then
                            local Hash: string = getfunctionhash(Callback)
                            if Seen[Hash] then
                                v.entries[i] = nil
                                if typeof(v.sortedEntries) == "table" then
                                    v.sortedEntries.isSorted = false
                                end
                            else
                                Seen[Hash] = true
                            end
                        end
                    end
                end
            end
        end

        local function CleanDummies()
            if not getconnections then
                return
            end

            for _, Dummy: Instance in CollectionService:GetTagged("trainingRoomDummy") do
                local Kept = {}
                for i: number, Connection: any in getconnections(Dummy.Destroying) do
                    local Callback = Connection.Function
                    local Source: string? = Callback and debug.info(Callback, "s")
                    if Source and Source:find("training-room-entity-controller", 1, true) then
                        local Ok, Target = pcall(debug.getupvalue, Callback, 1)
                        local Key = if Ok and Target ~= nil then Target else Callback
                        if Kept[Key] then
                            Connection:Disconnect()
                        else
                            Kept[Key] = true
                        end
                    end

                    if i % 2000 == 0 then
                        task.wait()
                    end
                end
                task.wait()
            end
        end

        task.wait(5)
        repeat
            pcall(CleanSignals)
            pcall(CleanDummies)
            task.wait(30)
        until vape.Loaded == nil
    end)

    vape:Clean(function()
        task.wait(1)
        Client.Get = OldGet
        bedwars.BlockBreaker.hitBlock = OldHit
        bedwars.BlockController.isBlockBreakable = OldBreak
        BlockStore.setBlock = OldSetBlock
        ClearStaleHooks()
        Navigation:SetWorld(nil)
        Store.blockPlacer:disable()
        for _, v: BindableEvent in VapeEvents do
            v:Destroy()
        end
        table.clear(Store.blockPlacer)
        table.clear(VapeEvents)
        table.clear(bedwars)
        table.clear(Store)
        table.clear(PathCache)
        table.clear(Sides)
        StoreChanged:disconnect()
        StoreChanged = nil
    end)
end)

local function GetFunctionRange(Func)
    if not canDebug then
        return nil
    end

    local Found: boolean = false
    for _, v: number | string | boolean in debug.getconstants(Func) do
        if v == "maxActivationDistance" then
            Found = true
        elseif Found then
            return v and typeof(v) == "number" and v or nil
        end
    end
    return nil
end
getgenv().getFunctionRange = GetFunctionRange

for _, v: string in {"AntiRagdoll", "TriggerBot", "SilentAim", "Jesus", "Invisible", "AutoRejoin", "Rejoin", "Disabler", "Timer", "ServerHop", "Wallhop", "Xray", "MouseTP", "MurderMystery"} do
    vape:Remove(v)
end

Run(function()
	local AimAssist
	local AimMode
	local Mode
	local Targets
	local Sort
	local AimPart
	local AimSpeed
	local Smoothness
	local Shake
	local Distance
	local AngleSlider
	local StrafeIncrease
	local BlockBreak
	local KillauraTarget
	local ClickAim
	local Mouse
	local Limit
	local Projectiles
	local ProjectileRange
	
	local RandomGenerator: Random = Random.new()
	local CharacterParts: {[Model]: {Instance}} = setmetatable({}, {__mode = "k"})
	
	local function GetAim(Ent): Vector3
	    if AimPart.Value == "Closest" then
	        if not CharacterParts[Ent.Character] then
	            CharacterParts[Ent.Character] = Ent.Character:GetChildren()
	        end
	        local MousePosition, ClosestDistance, ClosestPart = UserInputService.TouchEnabled and Camera.ViewportSize / 2 or UserInputService:GetMouseLocation(), 9e9, nil
	        for _, v: Instance in CharacterParts[Ent.Character] do
	            if v and v.Parent and v:IsA("BasePart") then
	                local ScreenPosition, Visible = Camera:WorldToViewportPoint(v.Position)
	                if Visible then
	                    local PartDistance: number = (MousePosition - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
	                    if PartDistance < ClosestDistance then
	                        ClosestDistance = PartDistance
	                        ClosestPart = v
	                    end
	                end
	            end
	        end
	        if ClosestPart then
	            return ClosestPart.Position
	        end
	    end
	    return Ent.RootPart.Position
	end
	
	local function GetProjectile()
	    if not Projectiles.Enabled then
	        return nil
	    end
	
	    local Tool: Tool? = Store.hand.tool
	    local ItemMeta = Tool and bedwars.ItemMeta[Tool.Name]
	    local ProjectileSource = ItemMeta and not ItemMeta.sword and ItemMeta.projectileSource
	    if not ProjectileSource or not ProjectileSource.projectileType then
	        return nil
	    end
	
	    local Source = bedwars.DefaultProjectileSourceController
	    local Handler = Source and Source.projectileHandler
	    local HandlerItem = Handler and Handler.projectileSourceController and Handler.projectileSourceController:getHandItem()
	    if Handler and (not HandlerItem or HandlerItem.tool ~= Tool) then Handler = nil end
	    local ProjectileType: string? = Handler and Handler.projectile
	    if not ProjectileType then
	        local Ammo: string? = Tool.Name
	        if ProjectileSource.ammoItemTypes and #ProjectileSource.ammoItemTypes > 0 then
	            Ammo = nil
	            for _, v: any in Store.inventory.inventory.items do
	                if table.find(ProjectileSource.ammoItemTypes, v.itemType) then
	                    Ammo = v.itemType
	                    break
	                end
	            end
	        end
	        ProjectileType = Ammo and ProjectileSource.projectileType(Ammo)
	    end
	
	    local ProjectileMeta = ProjectileType and bedwars.ProjectileMeta[ProjectileType]
	    if not ProjectileMeta or not ProjectileMeta.combat or type(ProjectileMeta.launchVelocity) ~= "number" then
	        return nil
	    end
	
	    return ProjectileMeta, Handler
	end
	
	local function GetCameraAim(LaunchPosition: Vector3, AimPosition: Vector3, Handler): Vector3
	    local Constants = bedwars.BowConstantsTable or {}
	    local CameraPosition: Vector3 = Camera.CFrame.Position
	    local Direction: Vector3 = (AimPosition - LaunchPosition).Unit
	    local Offset: Vector3 = LaunchPosition - CameraPosition
	    local Reach: number = Offset.Magnitude * (Constants.CameraMultiplier or 10)
	    local LookDirection: Vector3 = Direction
	    if Reach > 0.01 then
	        local Along: number = Offset:Dot(Direction)
	        local Travel: number = math.sqrt(math.max(Along * Along - Offset:Dot(Offset) + Reach * Reach, 0)) - Along
	        LookDirection = (Offset + Direction * Travel).Unit
	    end
	
	    local Lift: number = Constants.YTargetOffset or 0.05
	    local Scale: number = LookDirection.Y * Lift + math.sqrt(math.max(LookDirection.Y * LookDirection.Y * Lift * Lift - Lift * Lift + 1, 0))
	    local DesiredRay: Vector3 = LookDirection * Scale - Vector3.new(0, Lift, 0)
	    local MousePosition: Vector2 = UserInputService:GetMouseLocation() - GuiService:GetGuiInset()
	    if Handler and Handler.startAtCenterOfCamera then MousePosition = Camera.ViewportSize / 2 end
	    local ActualRay: Vector3 = Camera:ScreenPointToRay(MousePosition.X, MousePosition.Y).Direction
	    local LocalRay: Vector3 = Camera.CFrame:VectorToObjectSpace(ActualRay)
	    local Vertical: number = math.sqrt(LocalRay.Y * LocalRay.Y + LocalRay.Z * LocalRay.Z)
	    local Pitch: number = math.asin(math.clamp(DesiredRay.Y / math.max(Vertical, 0.001), -1, 1)) - math.atan2(LocalRay.Y, -LocalRay.Z)
	    local Forward: number = LocalRay.Y * math.sin(Pitch) + LocalRay.Z * math.cos(Pitch)
	    local Yaw: number = math.atan2(-DesiredRay.X, -DesiredRay.Z) - math.atan2(-LocalRay.X, -Forward)
	    local DesiredCamera: CFrame = CFrame.new(CameraPosition) * CFrame.Angles(0, Yaw, 0) * CFrame.Angles(Pitch, 0, 0)
	    return CameraPosition + DesiredCamera.LookVector * (AimPosition - CameraPosition).Magnitude
	end
	
	local function GetProjectileAim(Ent, TargetPosition: Vector3, ProjectileMeta, Handler): Vector3?
	    local LaunchPosition: Vector3 = (bedwars.ProjectileController:getLaunchPosition(Store.hand.tool) or Entity.character.RootPart.Position) + (Handler and Handler.fromPositionOffset or Vector3.new(0, 2, 0))
	    local LaunchValues = Handler and bedwars.ProjectileController:calculateImportantLaunchValues(Handler, false, Store.hand.tool)
	    local Speed: number = LaunchValues and LaunchValues.initialVelocity.Magnitude or ProjectileMeta.launchVelocity
	    local Gravity: number = LaunchValues and LaunchValues.gravitationalAcceleration or ProjectileMeta.gravitationalAcceleration or 196.2
	    LaunchPosition = LaunchValues and LaunchValues.positionFrom or LaunchPosition
	    local TargetVelocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity
	    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(LaunchPosition, Speed, Gravity, TargetPosition, TargetVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true)
	    if not AimPosition or not TravelTime or TravelTime > (ProjectileMeta.lifetimeSec or 3) then
	        return nil
	    end
	
	    return GetCameraAim(LaunchPosition, AimPosition, Handler)
	end
	
	local Started, LastTarget, NextSearch = 0, nil, 0
	local RolledSpeed: number = 0
	local AimFunctions = {
	    Simple = function(LocalCFrame: CFrame, Point: Vector3, DeltaTime: number)
	        local Speed: number = (RolledSpeed + (StrafeIncrease.Enabled and (UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 0)) / Smoothness.Value
	        return LocalCFrame:Lerp(CFrame.lookAt(LocalCFrame.p, Point + Vector3.new((RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime)), math.clamp(Speed * DeltaTime, 0, 1)), Speed
	    end,
	    Adaptive = function(LocalCFrame: CFrame, Point: Vector3, DeltaTime: number)
	        local T: number = math.min(tick() - Started, 1)
	        local Progress: number = T < 0.5 and 4 * T * T * T or 1 - math.pow(-2 * T + 2, 3) / 2
	        local Speed: number = ((RolledSpeed * 0.1 * Progress) + (1 - Progress) + (StrafeIncrease.Enabled and (UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 5)) / Smoothness.Value
	        return LocalCFrame:Lerp(CFrame.lookAt(LocalCFrame.p, Point + Vector3.new((RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime)), math.clamp(Speed * DeltaTime, 0, 1)), Speed
	    end
	}
	
	AimAssist = vape.Categories.Combat:CreateModule({
	    Name = "AimAssist",
	    Function = function(Callback: boolean)
	        if Callback then
	            local RotateTime: number = 0
	            AimAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)
	                if Entity.isAlive then
	                    Entity.character.Humanoid.AutoRotate = tick() > RotateTime
	
	                    local ProjectileMeta, Handler = GetProjectile()
	                    local Charging: boolean = ProjectileMeta ~= nil and bedwars.ProjectileController.isTargeting == true
	                    local Range: number = ProjectileMeta and ProjectileRange.Value or Distance.Value
	
	                    local Blocked: boolean = Mouse.Enabled and not Charging and not UserInputService:IsMouseButtonPressed(0) and (tick() - bedwars.SwordController.lastSwing) > 0.15
	                    Blocked = Blocked or (ClickAim.Enabled and not Charging and (tick() - bedwars.SwordController.lastSwing) > 0.3)
	                    Blocked = Blocked or (BlockBreak.Enabled and (tick() - Store.lastHit) < 0.3)
	                    Blocked = Blocked or (Limit.Enabled and Store.hand.toolType ~= "sword" and not ProjectileMeta)
	
	                    local Ent
	                    if not Blocked then
	                        if Entity.isAlive and LastTarget and LastTarget.Character and LastTarget.Character.Parent and LastTarget.RootPart and LastTarget.RootPart.Parent and LastTarget.Targetable and Entity.isVulnerable(LastTarget) and (Entity.character.RootPart.Position - LastTarget.RootPart.Position).Magnitude <= Range and not (Targets.Walls.Enabled and Entity.Wallcheck(Entity.character.RootPart.Position, LastTarget.RootPart.Position, Targets.Walls.Enabled, LastTarget)) and tick() < NextSearch then
	                            Ent = LastTarget
	                        else
	                            local Target = Store.KillauraTarget
	                            Ent = KillauraTarget.Enabled and Entity.isAlive and Target and Target.Character and Target.Character.Parent and Target.RootPart and Target.RootPart.Parent and Target.Targetable and Entity.isVulnerable(Target) and (Entity.character.RootPart.Position - Target.RootPart.Position).Magnitude <= Range and not (Targets.Walls.Enabled and Entity.Wallcheck(Entity.character.RootPart.Position, Target.RootPart.Position, Targets.Walls.Enabled, Target)) and Target or Entity.EntityPosition({
	                                Range = Range,
	                                Part = "RootPart",
	                                Wallcheck = Targets.Walls.Enabled,
	                                Players = Targets.Players.Enabled,
	                                NPCs = Targets.NPCs.Enabled,
	                                Priority = Targets.Priority.Value,
	                                Sort = SortMethods[Sort.Value]
	                            })
	                            if Ent ~= LastTarget then
	                                Started = tick()
	                            end
	                            LastTarget = Ent
	                            NextSearch = tick() + 1
	                            RolledSpeed = AimSpeed:GetRandomValue()
	                        end
	                    end
	
	                    if Ent then
	                        local Root: BasePart = Entity.character.RootPart
	                        local Offset: Vector3 = (Ent.RootPart.Position - Root.Position)
	                        local LocalFacing: Vector3 = Root.CFrame.LookVector * Vector3.new(1, 0, 1)
	                        local Horizontal: Vector3 = Offset * Vector3.new(1, 0, 1)
	                        local Angle: number = LocalFacing.Magnitude > 0 and Horizontal.Magnitude > 0 and math.acos(math.clamp(LocalFacing.Unit:Dot(Horizontal.Unit), -1, 1)) or 0
	                        if Angle >= (math.rad(AngleSlider.Value) / 2) then
	                            return
	                        end
	
	                        local AimPoint: Vector3? = if ProjectileMeta then Ent.RootPart.Position else GetAim(Ent)
	                        if ProjectileMeta then
	                            AimPoint = GetProjectileAim(Ent, AimPoint, ProjectileMeta, Handler)
	                            if not AimPoint then
	                                return
	                            end
	                        end
	                        TargetInfo.Targets[Ent] = tick() + 1
	
	                        local FirstPerson: boolean = Entity.character.Head.LocalTransparencyModifier == 1
	                        local Perspective: string = AimMode.Value
	                        if Perspective == "Mouse" then
	                            local AimCFrame, Speed = AimFunctions[Mode.Value](Camera.CFrame, AimPoint, DeltaTime)
	                            local Viewport: Vector3 = Camera:WorldToViewportPoint(AimCFrame.Position + AimCFrame.LookVector * (AimPoint - AimCFrame.Position).Magnitude)
	                            local MouseOffset: Vector2 = (Vector2.new(Viewport.X, Viewport.Y) - UserInputService:GetMouseLocation()) * (Speed / 15)
	                            mousemoverel(MouseOffset.X, MouseOffset.Y)
	                        elseif Perspective == "First person" or (Perspective == "Dynamic" and FirstPerson) then
	                            if not FirstPerson then
	                                return
	                            end
	                            local AimCFrame: CFrame = AimFunctions[Mode.Value](Camera.CFrame, AimPoint, DeltaTime)
	                            Camera.CFrame = AimCFrame
	                        elseif Perspective == "Third person" or (Perspective == "Dynamic" and not FirstPerson) then
	                            if FirstPerson then
	                                return
	                            end
	
	                            if ProjectileMeta then
	                                local AimCFrame: CFrame = AimFunctions[Mode.Value](Camera.CFrame, AimPoint, DeltaTime)
	                                Camera.CFrame = AimCFrame
	                            else
	                                local AimCFrame: CFrame = AimFunctions[Mode.Value](Root.CFrame, AimPoint, DeltaTime)
	                                local Direction: Vector3 = AimCFrame.LookVector * Vector3.new(1, 0, 1)
	                                if Direction.Magnitude > 0 then
	                                    Entity.character.Humanoid.AutoRotate = false
	                                    Root.CFrame = CFrame.lookAlong(Root.Position, Direction)
	                                    RotateTime = tick() + 0.1
	                                end
	                            end
	                        end
	                    end
	                else
	                    LastTarget = nil
	                end
	            end))
	        else
	            LastTarget = nil
	            if Entity.isAlive then
	                Entity.character.Humanoid.AutoRotate = true
	            end
	        end
	    end,
	    Tooltip = "Smoothly aims to closest valid target with sword"
	})
	
	AimMode = AimAssist:CreateDropdown({
	    Name = "Aim perspective",
	    Tooltip = "First person - Uses your camera to aim\nThird person - Moves your character to where your supposed to look\nMouse - Moves your mouse & camera\nDynamic - Uses first person mode if ur in first person, and uses third person if ur in third person",
	    List = {"First person", "Third person", "Dynamic"},
	    Default = "First person"
	})
	Mode = AimAssist:CreateDropdown({
	    Name = "Mode",
	    List = {"Simple", "Adaptive"},
	    Tooltip = "Simple - Smooth aiming\nAdaptive - Advanced tracking with adaptive behavior",
	    Default = "Simple"
	})
	Targets = AimAssist:CreateTargets({
	    Players = true,
	    Walls = true
	})
	local Methods: {string} = {"Angle", "Damage", "Distance"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	ClickAim = AimAssist:CreateToggle({
	    Name = "Click aim",
	    Default = true
	})
	Mouse = AimAssist:CreateToggle({Name = "Require mouse down"})
	StrafeIncrease = AimAssist:CreateToggle({Name = "Strafe increase"})
	BlockBreak = AimAssist:CreateToggle({Name = "Check block break"})
	KillauraTarget = AimAssist:CreateToggle({Name = "Use killaura target"})
	AimSpeed = AimAssist:CreateTwoSlider({
	    Name = "Aim speed",
	    Min = 1,
	    Max = 20,
	    DefaultMin = 6,
	    DefaultMax = 6,
	    Tooltip = "Picks a random speed between the two values every time it looks for a target, so on each lock-on and once a second while it stays on the same one"
	})
	Smoothness = AimAssist:CreateSlider({
	    Name = "Smoothness",
	    Min = 1,
	    Max = 20,
	    Default = 1,
	    Decimal = 10,
	    Tooltip = "Divides the aim speed to soften the snap, 1 leaves aiming unchanged"
	})
	Distance = AimAssist:CreateSlider({
	    Name = "Distance",
	    Min = 1,
	    Max = 30,
	    Default = 30,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	Shake = AimAssist:CreateSlider({
	    Name = "Shake",
	    Min = 0,
	    Max = 100,
	    Default = 0,
	    Tooltip = "Adds random jitter to simulate human aim"
	})
	AngleSlider = AimAssist:CreateSlider({
	    Name = "Max angle",
	    Min = 1,
	    Max = 360,
	    Default = 70
	})
	Limit = AimAssist:CreateToggle({
	    Name = "Limit to items",
	    Tooltip = "Only attacks when sword is held, or a projectile weapon while Projectiles is on"
	})
	Projectiles = AimAssist:CreateToggle({
	    Name = "Projectiles",
	    Function = function(Callback: boolean)
	        ProjectileRange.Object.Visible = Callback
	    end,
	    Tooltip = "While you hold a bow or another damaging projectile, aims where the shot will meet a moving target instead of at their body, always at the body's center. Click aim then aims while you draw, and third person turns your camera since shots follow it"
	})
	ProjectileRange = AimAssist:CreateSlider({
	    Name = "Projectile Range",
	    Min = 1,
	    Max = 300,
	    Default = 200,
	    Darker = true,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end,
	    Tooltip = "How far away a target can be while you hold a projectile, used instead of Distance"
	})
	Sort = AimAssist:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Angle"
	})
	AimPart = AimAssist:CreateDropdown({
	    Name = "Target area",
	    List = {"Center", "Closest"},
	    Default = "Center"
	})
end)

Run(function()
	local AutoClicker
	local CPS
	local Place
	local Wool
	local BlockCPS = {}
	local Thread: thread?
	
	local function IsAttackInput(Input: InputObject): boolean
	    local Keybinds = bedwars.KeybindLoadController.getKeybinds and bedwars.KeybindLoadController:getKeybinds()
	    local Keyboard = Keybinds and Keybinds.keyboard and Keybinds.keyboard.controlActions.Attack
	    local Gamepad = Keybinds and Keybinds.gamepad and Keybinds.gamepad.controlActions.Attack
	    Keyboard = typeof(Keyboard) == "EnumItem" and Keyboard or Enum.UserInputType.MouseButton1
	    Gamepad = typeof(Gamepad) == "EnumItem" and Gamepad or Enum.KeyCode.ButtonR2
	
	    return Input.UserInputType == Keyboard or Input.KeyCode == Keyboard or Input.KeyCode == Gamepad
	end
	
	local function AutoClick()
	    if Thread then
	        task.cancel(Thread)
	    end
	
	    Thread = task.delay(Store.hand.toolType == "block" and math.max(1 / BlockCPS:GetRandomValue(), 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) or 1 / CPS:GetRandomValue(), function()
	        repeat
	            if not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then
	                local BlockPlacer = bedwars.BlockPlacementController.blockPlacer
	                if Store.hand.toolType == "block" and Place.Enabled and (Wool.Enabled and Store.hand.tool.Name:find("wool_") or not Wool.Enabled) and BlockPlacer and CanPlace() then
	                    if (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= ((1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) * 0.5) then
	                        if UserInputService.TouchEnabled then
	                            task.spawn(BlockPlacer.autoBridge, BlockPlacer, workspace:GetServerTimeNow() - bedwars.KnockbackController:getLastKnockbackTime() >= 0.2)
	                        else
	                            local Selector = BlockPlacer.clientManager:getBlockSelector()
	                            local MouseInfo = Selector and Selector:getMouseInfo(0)
	                            if MouseInfo and MouseInfo.placementPosition == MouseInfo.placementPosition then
	                                task.spawn(BlockPlacer.placeBlock, BlockPlacer, MouseInfo.placementPosition, MouseInfo)
	                            end
	                        end
	                    end
	                elseif Store.hand.toolType == "sword" then
	                    if UserInputService.TouchEnabled then
	                        bedwars.SwordController:mobileSwingPressed()
	                    elseif CanSwing() and not bedwars.SwordController.disableSwingState then
	                        bedwars.SwordController:swingSwordAtMouse(0.39)
	                    end
	                elseif Store.hand.tool and bedwars.IsItemClaw(Store.hand.tool.Name) then
	                    bedwars.SummonerClawHandController:attack(Store.hand.tool.Name)
	                end
	            end
	
	            task.wait(Store.hand.toolType == "block" and math.max(1 / BlockCPS:GetRandomValue(), 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) or 1 / CPS:GetRandomValue())
	        until not AutoClicker.Enabled
	    end)
	end
	
	AutoClicker = vape.Categories.Combat:CreateModule({
	    Name = "AutoClicker",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoClicker:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)
	                if IsAttackInput(Input) then
	                    AutoClick()
	                end
	            end))
	
	            AutoClicker:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
	                if IsAttackInput(Input) and Thread then
	                    task.cancel(Thread)
	                    Thread = nil
	                end
	            end))
	
	            if UserInputService.TouchEnabled then
	                local Hooked: {[Instance]: boolean} = {}
	                local function HookButton(Button: Instance)
	                    if Hooked[Button] or not Button:IsA("GuiButton") or not tonumber(Button.Name) then
	                        return
	                    end
	                    Hooked[Button] = true
	                    AutoClicker:Clean(Button.MouseButton1Down:Connect(AutoClick))
	                    AutoClicker:Clean(Button.MouseButton1Up:Connect(function()
	                        if Thread then
	                            task.cancel(Thread)
	                            Thread = nil
	                        end
	                    end))
	                end
	
	                task.spawn(function()
	                    local MobileUI: Instance? = LocalPlayer.PlayerGui:WaitForChild("MobileUI", 20)
	                    if not MobileUI or not AutoClicker.Enabled then
	                        return
	                    end
	
	                    for _, v: Instance in MobileUI:GetChildren() do
	                        HookButton(v)
	                    end
	                    AutoClicker:Clean(MobileUI.ChildAdded:Connect(HookButton))
	                end)
	            end
	        else
	            if Thread then
	                task.cancel(Thread)
	                Thread = nil
	            end
	        end
	    end,
	    Tooltip = "Hold attack button to automatically click"
	})
	
	CPS = AutoClicker:CreateTwoSlider({
	    Name = "CPS",
	    Min = 1,
	    Max = 20,
	    DefaultMin = 7,
	    DefaultMax = 7
	})
	Place = AutoClicker:CreateToggle({
	    Name = "Place Blocks",
	    Function = function(Callback: boolean)
	        if BlockCPS.Object then
	            BlockCPS.Object.Visible = Callback
	        end
	
	        if Wool then
	            Wool.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Wool = AutoClicker:CreateToggle({Name = "Wool only", Tooltip = "Only clicks when you are holding wool.", Darker = true})
	BlockCPS = AutoClicker:CreateTwoSlider({
	    Name = "Block CPS",
	    Min = 1,
	    Max = 20,
	    DefaultMin = 20,
	    DefaultMax = 20,
	    Darker = true
	})
end)

Run(function()
	local BowAssist
	local Targets
	local Sort
	local AimPart
	local FOV
	local AimSpeed
	local Smoothness
	local Distance
	local Shake
	local Clear
	local Blacklist
	
	local DrawStart, OldStart, OldStop = 0
	local RandomGenerator: Random = Random.new()
	
	local ArcCheck: RaycastParams = RaycastParams.new()
	ArcCheck.FilterType = Enum.RaycastFilterType.Exclude
	
	BowAssist = vape.Categories.Combat:CreateModule({
	    Name = "BowAssist",
	    Function = function(Callback: boolean)
	        if Callback then
	            OldStart = bedwars.DefaultProjectileSourceController.onStartCharging
	            bedwars.DefaultProjectileSourceController.onStartCharging = function(self, ...)
	                DrawStart = tick()
	                return OldStart(self, ...)
	            end
	
	            OldStop = bedwars.DefaultProjectileSourceController.onStopCharging
	            bedwars.DefaultProjectileSourceController.onStopCharging = function(self, ...)
	                DrawStart = 0
	                return OldStop(self, ...)
	            end
	
	            BowAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)
	                if DrawStart == 0 or not Entity.isAlive then
	                    return
	                end
	
	                local ItemMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]
	                local ProjectileSource = ItemMeta and ItemMeta.projectileSource
	                if not ProjectileSource or not ProjectileSource.projectileType then
	                    return
	                end
	
	                local Ammo = Store.hand.tool.Name
	                if ProjectileSource.ammoItemTypes and #ProjectileSource.ammoItemTypes > 0 then
	                    Ammo = nil
	                    for _, v: any in Store.inventory.inventory.items do
	                        if table.find(ProjectileSource.ammoItemTypes, v.itemType) then
	                            Ammo = v.itemType
	                            break
	                        end
	                    end
	                end
	                if not Ammo then
	                    return
	                end
	
	                local ProjectileType: string = ProjectileSource.projectileType(Ammo)
	                if table.find(Blacklist.ListEnabled or {}, ((ProjectileType == "glue_trap" or ProjectileType == "glue_projectile") and "gloop" or ProjectileType)) then
	                    return
	                end
	
	                local ProjectileMeta = bedwars.ProjectileMeta[ProjectileType]
	                if not ProjectileMeta or type(ProjectileMeta.launchVelocity) ~= "number" then
	                    return
	                end
	
	                local Scalar: number = ProjectileSource.minStrengthScalar or 1
	                local Ratio: number = ProjectileSource.maxStrengthChargeSec and math.clamp((tick() - DrawStart) / ProjectileSource.maxStrengthChargeSec, 0, 1) or 1
	                local ProjectileSpeed: number = ProjectileMeta.launchVelocity * (Scalar + (1 - Scalar) * Ratio)
	
	                local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                local Ent = Entity.EntityMouse({
	                    Range = FOV.Value,
	                    Part = "RootPart",
	                    Wallcheck = Targets.Walls.Enabled,
	                    Players = Targets.Players.Enabled,
	                    NPCs = Targets.NPCs.Enabled,
	                    Priority = Targets.Priority.Value,
	                    Origin = LocalPosition,
	                    Sort = SortMethods[Sort.Value]
	                })
	                if not Ent or (LocalPosition - Ent.RootPart.Position).Magnitude > Distance.Value then
	                    return
	                end
	
	                local TargetPosition: Vector3 = Ent[AimPart.Value].Position
	                local ShootPosition: Vector3 = (CFrame.new(LocalPosition, TargetPosition) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
	                local Gravity: number = ProjectileMeta.gravitationalAcceleration or 196.2
	                local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(ShootPosition, ProjectileSpeed, Gravity, TargetPosition, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                if not AimPosition then
	                    return
	                end
	
	                if Clear.Enabled and TravelTime then
	                    local IgnoreList: {Instance} = {Camera, LocalPlayer.Character}
	                    for _, v: any in Entity.List do
	                        if v.Character then
	                            table.insert(IgnoreList, v.Character)
	                        end
	                    end
	                    ArcCheck.FilterDescendantsInstances = IgnoreList
	                    if not PredictionLib.IsTrajectoryClear(ShootPosition, AimPosition - ShootPosition, Gravity, TravelTime, ArcCheck) then
	                        return
	                    end
	                end
	
	                TargetInfo.Targets[Ent] = tick() + 1
	                local Jitter: Vector3 = Vector3.new((RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime, (RandomGenerator:NextNumber() - 0.5) * Shake.Value * DeltaTime)
	                Camera.CFrame = Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.Position, AimPosition + Jitter), math.clamp((AimSpeed.Value / Smoothness.Value) * DeltaTime, 0, 1))
	            end))
	        else
	            DrawStart = 0
	            bedwars.DefaultProjectileSourceController.onStartCharging = OldStart
	            bedwars.DefaultProjectileSourceController.onStopCharging = OldStop
	        end
	    end,
	    Tooltip = "Eases your camera onto the arrow drop while you draw a bow"
	})
	
	Targets = BowAssist:CreateTargets({
	    Players = true,
	    Walls = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = BowAssist:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Distance"
	})
	AimPart = BowAssist:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head"}
	})
	FOV = BowAssist:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Default = 220,
	    Tooltip = "How far from your crosshair a target can sit before it gets ignored"
	})
	Distance = BowAssist:CreateSlider({
	    Name = "Distance",
	    Min = 1,
	    Max = 300,
	    Default = 200,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	AimSpeed = BowAssist:CreateSlider({
	    Name = "Aim speed",
	    Min = 1,
	    Max = 20,
	    Default = 5
	})
	Smoothness = BowAssist:CreateSlider({
	    Name = "Smoothness",
	    Min = 1,
	    Max = 20,
	    Default = 2,
	    Decimal = 10,
	    Tooltip = "Divides the aim speed to soften the pull, 1 leaves it unchanged"
	})
	Shake = BowAssist:CreateSlider({
	    Name = "Shake",
	    Min = 0,
	    Max = 100,
	    Default = 0,
	    Tooltip = "Adds random jitter so the pull does not read as a straight line"
	})
	Clear = BowAssist:CreateToggle({
	    Name = "Clear shot only",
	    Default = true,
	    Tooltip = "Stops assisting when a block is in the way of the arc"
	})
	Blacklist = BowAssist:CreateTextList({
	    Name = "Blacklist",
	    Default = {"gloop", "telepearl"},
	    Darker = true,
	    Placeholder = "projectile",
	    Tooltip = "Projectile types the assist leaves alone"
	})
end)

Run(function()
	local NoClickDelay
	local SwingLock
	local Drill
	local Old, OldDrill, OldLock
	
	NoClickDelay = vape.Categories.Combat:CreateModule({
	    Name = "NoClickDelay",
	    Function = function(Callback: boolean)
	        if Callback then
	            Old = bedwars.SwordController.isClickingTooFast
	            bedwars.SwordController.isClickingTooFast = function(self)
	                self.lastSwing = tick()
	                return false
	            end
	
	            if SwingLock.Enabled then
	                OldLock = bedwars.SwordController.getSwordSwingDisabled
	                bedwars.SwordController.getSwordSwingDisabled = function()
	                    return false
	                end
	            end
	
	            if Drill.Enabled then
	                OldDrill = bedwars.DrillTabletController.isClickingTooFast
	                bedwars.DrillTabletController.isClickingTooFast = function()
	                    return false
	                end
	            end
	        else
	            bedwars.SwordController.isClickingTooFast = Old
	
	            if OldLock then
	                bedwars.SwordController.getSwordSwingDisabled = OldLock
	                OldLock = nil
	            end
	
	            if OldDrill then
	                bedwars.DrillTabletController.isClickingTooFast = OldDrill
	                OldDrill = nil
	            end
	        end
	    end,
	    Tooltip = "Removes the 9 clicks a second cap the client puts on swinging"
	})
	
	SwingLock = NoClickDelay:CreateToggle({
	    Name = "Swing lock",
	    Function = function()
	        if NoClickDelay.Enabled then
	            NoClickDelay:Toggle()
	            NoClickDelay:Toggle()
	        end
	    end,
	    Tooltip = "Also lets you swing while a kit ability has swinging turned off, like sigrid on her elk"
	})
	Drill = NoClickDelay:CreateToggle({
	    Name = "Drill",
	    Function = function()
	        if NoClickDelay.Enabled then
	            NoClickDelay:Toggle()
	            NoClickDelay:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Removes the same cap on the drill tablet"
	})
end)

Run(function()
	local BlockReach
	local BlockRange
	local BreakReach
	local BreakRange
	local SwordReach
	local SwordRange
	local AirHits
	
	local RandomGenerator, Old, OldSend = Random.new()
	local SwingConnection
	local LastExtendedSwing: number = 0
	
	local function ExtendedSwordHit()
	    if not Entity.isAlive then
	        return
	    end
	
	    local Sword = GetSword()
	    if not Sword or (tick() - LastExtendedSwing) < GetSwordSpeed(Sword.tool) then
	        return
	    end
	
	    local ReachDistance: number = GetReach(Sword.tool)
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Target = Entity.EntityPosition({
	        Origin = LocalPosition,
	        Range = SwordRange.Value + 2,
	        Part = "RootPart",
	        Players = true,
	        NPCs = true,
	        Wallcheck = true
	    })
	    if not Target then
	        return
	    end
	
	    local Delta: Vector3 = Target.RootPart.Position - LocalPosition
	    if Delta.Magnitude <= ReachDistance or (Target.Humanoid and Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Target.RootPart.AssemblyLinearVelocity.Y) > 0.01) and RandomGenerator:NextNumber(0, 100) > AirHits:GetRandomValue() then
	        return
	    end
	
	    local Direction: Vector3 = CFrame.lookAt(LocalPosition, Target.RootPart.Position).LookVector
	    LastExtendedSwing = tick()
	    bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
	    bedwars.Handler:Get("SwordHit"):Fire("SendToServer", {
	        weapon = Sword.tool,
	        chargedAttack = {chargeRatio = 0},
	        entityInstance = Target.Character,
	        validate = {
	            raycast = {
	                cameraPosition = {value = Camera.CFrame.Position},
	                cursorDirection = {value = Direction}
	            },
	            targetPosition = {value = Target.Character:GetPivot().Position},
	            selfPosition = {value = LocalPosition + Direction * math.max(Delta.Magnitude - (ReachDistance - 0.001), 0)}
	        }
	    })
	end
	
	Reach = vape.Categories.Combat:CreateModule({
	    Name = "Reach",
	    Function = function(Callback: boolean)
	        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Callback and SwordReach.Enabled and SwordRange.Value + 2 or 14.4
	        if Callback then
	            Old = bedwars.BlockSelector.getMouseInfo
	            bedwars.BlockSelector.getMouseInfo = function(self, Mode: number, Arguments)
	                Arguments = Arguments or {}
	                if Mode == 0 then
	                    Arguments.range = BlockReach.Enabled and BlockRange.Value or 24
	                elseif Mode == 1 then
	                    Arguments.range = BreakReach.Enabled and BreakRange.Value or 18
	                end
	                return Old(self, Mode, Arguments)
	            end
	            OldSend = bedwars.SwordController.sendServerRequest
	            bedwars.SwordController.sendServerRequest = function(self, Ent, ...)
	                local Character = Ent and Ent:getInstance()
	                local Humanoid: Humanoid? = Character and Character:FindFirstChildWhichIsA("Humanoid")
	                if Character and Character.PrimaryPart and Entity.isAlive and (Character.PrimaryPart.Position - Entity.character.RootPart.Position).Magnitude > GetReach(self:getHandItem().tool) and (Humanoid and Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Character.PrimaryPart.AssemblyLinearVelocity.Y) > 0.01) and RandomGenerator:NextNumber(0, 100) > AirHits:GetRandomValue() then
	                    return
	                end
	
	                return OldSend(self, Ent, ...)
	            end
	        else
	            bedwars.BlockSelector.getMouseInfo = Old
	            bedwars.SwordController.sendServerRequest = OldSend
	        end
	
	        if SwingConnection then
	            SwingConnection:Disconnect()
	            SwingConnection = nil
	        end
	        if not canDebug and Reach.Enabled and SwordReach.Enabled then
	            SwingConnection = UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)
	                if Processed then
	                    return
	                end
	                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
	                    return
	                end
	
	                ExtendedSwordHit()
	            end)
	        end
	    end,
	    Tooltip = "Allows you to place, attack, and break further"
	})
	
	SwordReach = Reach:CreateToggle({
	    Name = "Sword Reach",
	    Function = function(Callback: boolean)
	        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and Callback and SwordRange.Value + 2 or 14.4
	        if AirHits then
	            SwordRange.Object.Visible = Callback
	            AirHits.Object.Visible = Callback
	        end
	
	        if SwingConnection then
	            SwingConnection:Disconnect()
	            SwingConnection = nil
	        end
	        if not canDebug and Reach.Enabled and Callback then
	            SwingConnection = UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)
	                if Processed then
	                    return
	                end
	                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
	                    return
	                end
	
	                ExtendedSwordHit()
	            end)
	        end
	    end,
	    Default = true
	})
	SwordRange = Reach:CreateSlider({
	    Name = "Sword Range",
	    Min = 1,
	    Max = 18,
	    Decimal = 5,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Function = function(Val: number)
	        bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and SwordReach.Enabled and Val or 14.4
	    end,
	    Default = 18
	})
	AirHits = Reach:CreateTwoSlider({
	    Name = "Air reach hit chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 100,
	    DefaultMax = 100,
	    Darker = true,
	    Tooltip = "Chance for a hit past normal reach to land while the target is off the ground, rolled fresh between the two values on every swing"
	})
	BlockReach = Reach:CreateToggle({
	    Name = "Placement Reach",
	    Function = function(Callback: boolean)
	        BlockRange.Object.Visible = Callback
	    end
	})
	BlockRange = Reach:CreateSlider({
	    Name = "Placement Range",
	    Min = 1,
	    Max = 60,
	    Default = 18,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Visible = false
	})
	BreakReach = Reach:CreateToggle({
	    Name = "Break Reach",
	    Function = function(Callback: boolean)
	        BreakRange.Object.Visible = Callback
	    end
	})
	BreakRange = Reach:CreateSlider({
	    Name = "Break Range",
	    Min = 1,
	    Max = 30,
	    Default = 30,
	    Decimal = 5,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Visible = false
	})
	Reach:CreateButton({
	    Name = "Reset to default reach",
	    Function = function()
	        BreakRange:SetValue(18)
	        BlockRange:SetValue(24)
	        SwordRange:SetValue(12.4)
	    end,
	    Tooltip = "Resets every range back to default"
	})
end)

Run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local Prediction
	local FOV
	local HitChance
	local HeadshotChance
	local OtherProjectiles
	local Blacklist
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local OldNamecall
	local LastWarn: number = 0
	local RandomGenerator: Random = Random.new()
	
	local function SolveSilent(Arguments): Vector3?
	    local Origin, Velocity, ProjectileType = Arguments[4], Arguments[6], Arguments[3]
	    if typeof(Origin) ~= "Vector3" or typeof(Velocity) ~= "Vector3" or type(ProjectileType) ~= "string" then
	        return
	    end
	
	    if (not OtherProjectiles.Enabled) and not ProjectileType:find("arrow") then
	        return
	    end
	
	    if table.find(Blacklist.ListEnabled or {}, ((ProjectileType == "glue_trap" or ProjectileType == "glue_projectile") and "gloop" or ProjectileType)) then
	        return
	    end
	
	    local ProjectileMeta = bedwars.ProjectileMeta[ProjectileType]
	    if not ProjectileMeta then
	        return
	    end
	
	    local Speed: number = Velocity.Magnitude
	    if Speed <= 0 then
	        return
	    end
	
	    if RandomGenerator:NextNumber(0, 100) > HitChance:GetRandomValue() then
	        return
	    end
	
	    local Map: Instance? = workspace:FindFirstChild("Map")
	    if Map ~= RayCheck.FilterDescendantsInstances[1] then
	        RayCheck.FilterDescendantsInstances = Map and {Map} or {}
	    end
	    local Gravity: number = ProjectileMeta.gravitationalAcceleration or 196.2
	
	    local Target = Entity.EntityMouse({
	        Part = "RootPart",
	        Range = FOV.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Sort = SortMethods[Sort.Value or "Distance"],
	        MouseOrigin = Camera.ViewportSize / 2,
	        Origin = Origin
	    })
	    if not Target then
	        return
	    end
	
	    local PartName: string = RandomGenerator:NextNumber(0, 100) < HeadshotChance:GetRandomValue() and "Head" or TargetPart.Value
	    local SelectedPart = GetTargetPart(Target, PartName)
	    local TargetPosition: Vector3?
	    if PartName == "Closest" then
	        local Center, ClosestDistance = Camera.ViewportSize / 2, 9e9
	        for _, v: Instance in Target.Character:GetChildren() do
	            if v:IsA("BasePart") then
	                local ScreenPosition, Visible = Camera:WorldToViewportPoint(v.Position)
	                if Visible then
	                    local PartDistance: number = (Center - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
	                    if PartDistance < ClosestDistance then
	                        ClosestDistance, TargetPosition = PartDistance, v.Position
	                    end
	                end
	            end
	        end
	        TargetPosition = TargetPosition or Target.Character.PrimaryPart and Target.Character.PrimaryPart.Position
	    elseif PartName == "Dynamic" then
	        local Tool = Store.hand.tool
	        if IsHeadshotProjectile(Tool and Tool.Name) and Target.Character:FindFirstChild("Head") then
	            TargetPosition = Target.Character.Head.Position
	        else
	            TargetPosition = Target.Character.PrimaryPart and Target.Character.PrimaryPart.Position
	        end
	    end
	
	    TargetPosition = TargetPosition or SelectedPart and SelectedPart.Position
	    if not TargetPosition then
	        return
	    end
	    local PlayerGravity: number = workspace.Gravity
	    local Balloons = Target.Character:GetAttribute("InflatedBalloons")
	    if Balloons and Balloons > 0 then
	        PlayerGravity = workspace.Gravity * (1 - (Balloons >= 4 and 1.2 or Balloons >= 3 and 1 or 0.975))
	    end
	
	    if Target.Character.PrimaryPart and Target.Character.PrimaryPart:FindFirstChild("rbxassetid://8200754399") then
	        PlayerGravity = 6
	    end
	
	    if Target.Player and Target.Player:GetAttribute("IsOwlTarget") then
	        for _, v: Instance in CollectionService:GetTagged("Owl") do
	            if v:GetAttribute("Target") == Target.Player.UserId and v:GetAttribute("Status") == 2 then
	                PlayerGravity = 0
	            end
	        end
	    end
	
	    local IsPearl: boolean = ProjectileType == "telepearl"
	    local TargetVelocity: Vector3 = IsPearl and Vector3.zero or Target.RootPart.AssemblyLinearVelocity
	    local TargetAirborne: boolean = not IsPearl and Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01
	    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(Origin, Speed * Prediction.Value, Gravity, TargetPosition, TargetVelocity, PlayerGravity, Target.HipHeight, Target.Jumping and 42.6 or nil, RayCheck, TargetAirborne, Target.RootPart.Position, Target.RootPart, nil, true)
	    if not AimPosition or not TravelTime or TravelTime > (ProjectileMeta.lifetimeSec or 3) then
	        return
	    end
	
	    TargetInfo.Targets[Target] = tick() + 1
	    Store.hitchance.SilentAim = {Value = GetHitChance(Target, TravelTime), Clock = tick()}
	    return CFrame.lookAt(Origin, AimPosition).LookVector * Speed
	end
	
	SilentAim = vape.Categories.Combat:CreateModule({
	    Name = "SilentAim",
	    Function = function(Callback: boolean)
	        if Callback and not OldNamecall then
	            OldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(...)
	                if SilentAim.Enabled and not checkcaller() and getnamecallmethod() == "InvokeServer" and tostring(...) == "ProjectileFire" then
	                    local self = ...
	                    local Arguments = table.pack(select(2, ...))
	                    local Success, NewVelocity = pcall(SolveSilent, Arguments)
	                    if Success and typeof(NewVelocity) == "Vector3" then
	                        Arguments[6] = NewVelocity
	                    elseif not Success and shared.VapeDeveloper and tick() > LastWarn then
	                        LastWarn = tick() + 5
	                        warn(`[catvape] silentaim solve failed: {NewVelocity}`)
	                    end
	                    return self.InvokeServer(self, table.unpack(Arguments, 1, Arguments.n))
	                end
	                return OldNamecall(...)
	            end))
	        end
	    end,
	    Tooltip = "Redirects only the projectile values sent to the server, so enemies get hit while your shot flies exactly where you aimed on your own screen"
	})
	
	Targets = SilentAim:CreateTargets({
	    Players = true,
	    Walls = true
	})
	TargetPart = SilentAim:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head", "Torso", "Left arm", "Right arm", "Left leg", "Right leg", "Random", "Dynamic", "Closest"}
	})
	local Methods: {string} = {"Damage", "Distance"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = SilentAim:CreateDropdown({
	    Name = "Target Mode",
	    List = Methods,
	    Default = "Distance"
	})
	Prediction = SilentAim:CreateSlider({
	    Name = "Prediction",
	    Min = 0.1,
	    Max = 2,
	    Default = 1,
	    Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Default = 1000
	})
	HitChance = SilentAim:CreateTwoSlider({
	    Name = "Hit Chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 100,
	    DefaultMax = 100,
	    Tooltip = "Chance in % for each shot to be redirected, rolled fresh between the two values on every shot. A missed roll leaves the shot where you aimed"
	})
	HeadshotChance = SilentAim:CreateTwoSlider({
	    Name = "Headshot Chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 0,
	    DefaultMax = 0,
	    Tooltip = "Chance in % for each redirected shot to aim at the head instead of the Part setting, rolled fresh between the two values on every shot"
	})
	OtherProjectiles = SilentAim:CreateToggle({
	    Name = "Other Projectiles",
	    Function = function(Callback: boolean)
	        if Blacklist then
	            Blacklist.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Blacklist = SilentAim:CreateTextList({
	    Name = "Blacklist",
	    Default = {"gloop", "telepearl"},
	    Darker = true,
	    Placeholder = "projectile"
	})
end)

Run(function()
	local Sprint
	local Old: (...any) -> ...any
	
	Sprint = vape.Categories.Combat:CreateModule({
	    Name = "Sprint",
	    Function = function(Callback: boolean)
	        if Callback then
	            Old = bedwars.SprintController.stopSprinting
	            bedwars.SprintController.stopSprinting = function(...)
	                local Call = Old(...)
	                bedwars.SprintController:startSprinting()
	                return Call
	            end
	
	            Sprint:Clean(Entity.Events.LocalAdded:Connect(function()
	                task.delay(0.1, function()
	                    bedwars.SprintController:stopSprinting()
	                end)
	            end))
	
	            bedwars.SprintController:stopSprinting()
	        else
	            bedwars.SprintController.stopSprinting = Old
	            bedwars.SprintController:stopSprinting()
	        end
	    end,
	    Tooltip = "Sets your sprinting to true."
	})
end)

Run(function()
	local TriggerBot
	local Targets
	local Range
	local Angle
	local CPS
	local Limit
	local Region
	local Continue
	local Duration
	local Mouse
	local AFKCheck
	local GUI
	local BoxColor
	local BoxTween
	local BoxSpeed
	
	local Box: BoxHandleAdornment?
	local SizeTween: Tween?
	local SizeGoal: Vector3?
	local LastTarget, LastSwing, KillUntil = nil, 0, 0
	local RayParams: RaycastParams = RaycastParams.new()
	
	local function GetTarget(LocalPosition: Vector3, AttackRange: number, ConeAngle: number)
	    if ConeAngle > 0 then
	        local Origin, Facing = Camera.CFrame.Position, Camera.CFrame.LookVector
	        local CosineLimit: number = math.cos(math.rad(math.min(ConeAngle, 360)) / 2)
	        for _, v: any in Entity.AllPosition({
	            Part = "RootPart",
	            Range = AttackRange,
	            Origin = LocalPosition,
	            Players = Targets.Players.Enabled,
	            NPCs = Targets.NPCs.Enabled,
	            Priority = Targets.Priority.Value,
	            Wallcheck = Targets.Walls.Enabled or nil,
	            Sort = SortMethods.Distance
	        }) do
	            local Delta: Vector3 = v.RootPart.Position - Origin
	            if Delta.Magnitude < 0.001 or Facing:Dot(Delta.Unit) >= CosineLimit then
	                return v
	            end
	        end
	
	        return nil
	    end
	
	    local MouseRay: Ray = LocalPlayer:GetMouse().UnitRay
	    RayParams.FilterDescendantsInstances = {LocalPlayer.Character}
	    local RayResult: RaycastResult? = bedwars.QueryUtil:raycast(MouseRay.Origin, MouseRay.Direction * 200, RayParams)
	    if not RayResult then
	        return nil
	    end
	
	    for _, v: any in Entity.List do
	        if v.Targetable and RayResult.Instance:IsDescendantOf(v.Character) and (LocalPosition - v.RootPart.Position).Magnitude <= AttackRange then
	            if Targets.Players.Enabled and v.Player or Targets.NPCs.Enabled and not v.Player then
	                if not Targets.Walls.Enabled or not Entity.Wallcheck(LocalPosition, v.RootPart.Position, true, v) then
	                    return v
	                end
	            end
	        end
	    end
	
	    return nil
	end
	
	TriggerBot = vape.Categories.Combat:CreateModule({
	    Name = "TriggerBot",
	    Function = function(Callback: boolean)
	        if Callback then
	            LastTarget, LastSwing, KillUntil = nil, 0, 0
	
	            repeat
	                local Ent, DoAttack
	                if Entity.isAlive and (not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) and (not Mouse.Enabled or UserInputService:IsMouseButtonPressed(0)) and (not AFKCheck.Enabled or not IsAfk()) then
	                    if (not Limit.Enabled or Store.hand.toolType == "sword") and bedwars.DaoController.chargingMaid == nil then
	                        local AttackRange: number = math.clamp(Range.Value, 0, GetReach(Store.hand.tool) * 2)
	                        Ent = GetTarget(Entity.character.RootPart.Position, AttackRange, Angle.Value)
	                        DoAttack = Ent ~= nil
	
	                        if LastTarget and LastTarget.Health <= 0 then
	                            if tick() - LastSwing <= 1 then
	                                KillUntil = tick() + Duration.Value
	                            end
	                            LastTarget = nil
	                        end
	
	                        if not DoAttack and Region.Enabled then
	                            DoAttack = bedwars.SwordController:getTargetInRegion(AttackRange, 0) ~= nil
	                        end
	
	                        if not DoAttack and Continue.Enabled and tick() < KillUntil then
	                            DoAttack = true
	                        end
	
	                        if Ent then
	                            LastTarget = Ent
	                            TargetInfo.Targets[Ent] = tick() + 1
	                        end
	
	                        if DoAttack and CanSwing() then
	                            if Ent then
	                                LastSwing = tick()
	                            end
	                            bedwars.SwordController:swingSwordAtMouse()
	                        end
	                    end
	                end
	
	                if Box then
	                    Box.Adornee = Ent and Ent.RootPart or nil
	                    local Goal: Vector3 = Ent and Vector3.new(4, 6, 4) or Vector3.zero
	                    if Goal ~= SizeGoal or not SizeTween or SizeTween.PlaybackState ~= Enum.PlaybackState.Completed then
	                        SizeTween = TweenService:Create(Box, TweenInfo.new(BoxSpeed.Value, Enum.EasingStyle[BoxTween.Value]), {
	                            Size = Goal
	                        })
	                        SizeTween:Play()
	                        SizeGoal = Goal
	                    end
	
	                    if Ent then
	                        Box.Color3 = Color3.fromHSV(BoxColor.Hue, BoxColor.Sat, BoxColor.Value)
	                        Box.Transparency = 1 - BoxColor.Opacity
	                    end
	                end
	
	                task.wait(DoAttack and 1 / CPS:GetRandomValue() or 0.016)
	            until not TriggerBot.Enabled
	        end
	    end,
	    Tooltip = "Automatically swings when hovering over a entity"
	})
	
	Targets = TriggerBot:CreateTargets({
	    Players = true,
	    NPCs = true,
	    Walls = true
	})
	Range = TriggerBot:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 18,
	    Default = 18,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Clamped by the reach of whatever you are holding"
	})
	Angle = TriggerBot:CreateSlider({
	    Name = "Angle",
	    Min = 0,
	    Max = 360,
	    Default = 0,
	    Suffix = "degrees",
	    Tooltip = "Swings at anything within this cone of where you are looking instead of only the one under your cursor, 360 reaches behind you"
	})
	CPS = TriggerBot:CreateTwoSlider({
	    Name = "CPS",
	    Min = 1,
	    Max = 9,
	    DefaultMin = 7,
	    DefaultMax = 7
	})
	Limit = TriggerBot:CreateToggle({
	    Name = "Limit to items",
	    Default = true,
	    Tooltip = "Only swings when the sword is held"
	})
	Region = TriggerBot:CreateToggle({
	    Name = "Region check",
	    Default = true,
	    Tooltip = "Also swings when the game reports anything inside your sword region"
	})
	Continue = TriggerBot:CreateToggle({
	    Name = "Continue after kill",
	    Function = function(Callback: boolean)
	        Duration.Object.Visible = Callback
	    end,
	    Tooltip = "Keeps swinging for a moment after the entity you were on dies, so a second one walking in gets hit right away"
	})
	Duration = TriggerBot:CreateSlider({
	    Name = "Continue time",
	    Min = 0.05,
	    Max = 2,
	    Default = 0.4,
	    Decimal = 100,
	    Darker = true,
	    Visible = false,
	    Suffix = "seconds"
	})
	Mouse = TriggerBot:CreateToggle({Name = "Require mouse down"})
	AFKCheck = TriggerBot:CreateToggle({
	    Name = "AFK check",
	    Tooltip = "Stops attacking once you have not touched your mouse or keyboard for 30 seconds"
	})
	GUI = TriggerBot:CreateToggle({Name = "GUI check"})
	TriggerBot:CreateToggle({
	    Name = "Show target",
	    Function = function(Callback: boolean)
	        BoxColor.Object.Visible = Callback
	        BoxTween.Object.Visible = Callback
	        BoxSpeed.Object.Visible = Callback
	        if Callback then
	            Box = Instance.new("BoxHandleAdornment")
	            Box.Adornee = nil
	            Box.AlwaysOnTop = true
	            Box.Size = Vector3.zero
	            Box.CFrame = CFrame.new(0, -0.5, 0)
	            Box.ZIndex = 0
	            Box.Parent = vape.gui
	            SizeTween = nil
	        elseif Box then
	            Box:Destroy()
	            Box = nil
	        end
	    end
	})
	local AnimationList: {string} = {"Bounce"}
	for _, v: EnumItem in Enum.EasingStyle:GetEnumItems() do
	    if not table.find(AnimationList, v.Name) then
	        table.insert(AnimationList, v.Name)
	    end
	end
	BoxTween = TriggerBot:CreateDropdown({
	    Name = "Box Animation",
	    List = AnimationList,
	    Darker = true,
	    Visible = false
	})
	BoxSpeed = TriggerBot:CreateSlider({
	    Name = "Animation Speed",
	    Min = 0,
	    Max = 10,
	    Default = 0.9,
	    Decimal = 30,
	    Darker = true,
	    Visible = false
	})
	BoxColor = TriggerBot:CreateColorSlider({
	    Name = "Target Color",
	    Darker = true,
	    DefaultHue = 0.6,
	    DefaultOpacity = 0.5,
	    Visible = false
	})
end)

Run(function()
	local Velocity
	local Horizontal
	local Vertical
	local Chance
	local TargetCheck
	local AFKCheck
	local AFKTime
	local RandomGenerator, Old, LastInput = Random.new()
	local KnockbackModule: Instance = ReplicatedStorage.TS.damage["knockback-util"]
	local Defaults
	
	Velocity = vape.Categories.Combat:CreateModule({
	    Name = "Velocity",
	    Function = function(Callback: boolean)
	        if not canDebug then
	            if Callback then
	                Defaults = Defaults or {
	                    horizontal = KnockbackModule:GetAttribute("ConstantManager_kbDirectionStrength"),
	                    vertical = KnockbackModule:GetAttribute("ConstantManager_kbUpwardStrength")
	                }
	                KnockbackModule:SetAttribute("ConstantManager_kbDirectionStrength", Defaults.horizontal * (Horizontal.Value / 100))
	                KnockbackModule:SetAttribute("ConstantManager_kbUpwardStrength", Defaults.vertical * (Vertical.Value / 100))
	            elseif Defaults then
	                KnockbackModule:SetAttribute("ConstantManager_kbDirectionStrength", Defaults.horizontal)
	                KnockbackModule:SetAttribute("ConstantManager_kbUpwardStrength", Defaults.vertical)
	            end
	            return
	        end
	
	        if Callback then
	            LastInput = tick()
	            Velocity:Clean(UserInputService.InputBegan:Connect(function()
	                LastInput = tick()
	            end))
	            Old = bedwars.KnockbackUtil.applyKnockback
	            bedwars.KnockbackUtil.applyKnockback = function(Root, Mass, Direction, Knockback, ...)
	                if RandomGenerator:NextNumber(0, 100) > Chance:GetRandomValue() or AFKCheck.Enabled and (tick() - LastInput) >= AFKTime.Value and Entity.isAlive and Entity.character.Humanoid.MoveDirection.Magnitude == 0 then
	                    return Old(Root, Mass, Direction, Knockback, ...)
	                end
	                local Check = (not TargetCheck.Enabled) or Entity.EntityPosition({
	                    Range = 50,
	                    Part = "RootPart",
	                    Players = true
	                })
	
	                if Check then
	                    Knockback = Knockback or {}
	                    if Horizontal.Value == 0 and Vertical.Value == 0 then
	                        return
	                    end
	                    Knockback.horizontal = (Knockback.horizontal or 1) * (Horizontal.Value / 100)
	                    Knockback.vertical = (Knockback.vertical or 1) * (Vertical.Value / 100)
	                end
	
	                return Old(Root, Mass, Direction, Knockback, ...)
	            end
	        else
	            bedwars.KnockbackUtil.applyKnockback = Old
	        end
	    end,
	    Tooltip = "Reduces knockback taken"
	})
	
	Horizontal = Velocity:CreateSlider({
	    Name = "Horizontal",
	    Min = 0,
	    Max = 100,
	    Suffix = "%",
	    Function = function()
	        if not canDebug and Velocity.Enabled and Defaults then
	            KnockbackModule:SetAttribute("ConstantManager_kbDirectionStrength", Defaults.horizontal * (Horizontal.Value / 100))
	            KnockbackModule:SetAttribute("ConstantManager_kbUpwardStrength", Defaults.vertical * (Vertical.Value / 100))
	        end
	    end,
	    Default = 0
	})
	Vertical = Velocity:CreateSlider({
	    Name = "Vertical",
	    Min = 0,
	    Max = 100,
	    Suffix = "%",
	    Function = function()
	        if not canDebug and Velocity.Enabled and Defaults then
	            KnockbackModule:SetAttribute("ConstantManager_kbDirectionStrength", Defaults.horizontal * (Horizontal.Value / 100))
	            KnockbackModule:SetAttribute("ConstantManager_kbUpwardStrength", Defaults.vertical * (Vertical.Value / 100))
	        end
	    end,
	    Default = 0
	})
	Chance = Velocity:CreateTwoSlider({
	    Name = "Chance",
	    Min = 0,
	    Max = 100,
	    DefaultMin = 100,
	    DefaultMax = 100,
	    Tooltip = "Chance in % for each knockback to be reduced, rolled fresh between the two values on every hit"
	})
	TargetCheck = Velocity:CreateToggle({Name = "Only when targeting"})
	AFKCheck = Velocity:CreateToggle({
	    Name = "AFK check",
	    Function = function(Callback: boolean)
	        AFKTime.Object.Visible = Callback
	    end,
	    Tooltip = "Takes full knockback while you stand still and have not pressed anything for the AFK time"
	})
	AFKTime = Velocity:CreateSlider({
	    Name = "AFK time",
	    Min = 1,
	    Max = 60,
	    Default = 10,
	    Darker = true,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end
	})
end)

Run(function()
	local AntiDeath
	local StopThreshold
	local Threshold
	local Notify
	local Delay
	local Mode
	
	local OldRoot, OldCharacter, Clone, HipHeight
	local Paused, Activated = 0, 0
	
	local function DestroyClone()
	    if not OldRoot then
	        return false
	    end
	
	    local Restored: boolean = false
	    if OldRoot.Parent and OldCharacter and OldCharacter.Parent then
	        OldCharacter.Parent = ReplicatedStorage
	        OldRoot.Parent = OldCharacter
	        if Clone then
	            Clone:Destroy()
	        end
	        OldCharacter.PrimaryPart = OldRoot
	        OldCharacter.Parent = workspace
	        OldRoot.CanCollide = true
	        local Humanoid: Humanoid? = OldCharacter:FindFirstChildOfClass("Humanoid")
	        if Humanoid then
	            Humanoid.HipHeight = HipHeight
	        end
	        Restored = true
	    elseif Clone then
	        Clone:Destroy()
	    end
	
	    OldRoot, OldCharacter, Clone = nil, nil, nil
	    Store.rootpart = nil
	    return Restored
	end
	
	AntiDeath = vape.Categories.Blatant:CreateModule({
	    Name = "AntiDeath",
	    Function = function(Callback: boolean)
	        if Callback then
	            local FloatTime: number = tick()
	            AntiDeath:Clean(RunService.PreSimulation:Connect(function()
	                if not OldRoot or not OldRoot.Parent or not Entity.isAlive then
	                    return
	                end
	
	                if (tick() - Entity.character.AirTime) > 1.7 then
	                    FloatTime = tick() + 0.2
	                end
	                OldRoot.AssemblyLinearVelocity = Vector3.new(0, 1, 0)
	                OldRoot.CFrame = Clone.CFrame - (tick() > FloatTime and Vector3.new(0, 200, 0) or Vector3.zero)
	            end))
	
	            repeat
	                if tick() > Paused and Entity.isAlive and (Entity.character.Health / Entity.character.MaxHealth) <= (Threshold.Value / 100) and (tick() - Activated) >= Delay.Value then
	                    Activated = tick()
	                    if Notify.Enabled then
	                        SendNotification("AntiDeath", `Health below {Threshold.Value}%`, 12, "warning")
	                    end
	
	                    if Mode.Value == "Teleport" then
	                        LocalPlayer.Character.PrimaryPart.CFrame += Vector3.new(0, 100, 0)
	                        Paused = tick() + 5
	                    elseif Mode.Value == "Invincibility" and not Store.rootpart and Entity.isAlive and Entity.character.Humanoid.Health > 0 and not (OldRoot and OldRoot.Parent) and LocalPlayer.Character.Parent then
	                        OldCharacter = LocalPlayer.Character
	                        OldRoot = Entity.character.HumanoidRootPart
	                        HipHeight = Entity.character.Humanoid.HipHeight
	                        OldCharacter.Parent = ReplicatedStorage
	                        Clone = OldRoot:Clone()
	                        Clone.Parent = OldCharacter
	                        OldRoot.Transparency = 1
	                        OldRoot.Parent = workspace
	                        Store.rootpart = OldRoot
	                        OldCharacter.PrimaryPart = Clone
	                        OldCharacter.Parent = workspace
	                        bedwars.QueryUtil:setQueryIgnored(Clone, true)
	                        bedwars.QueryUtil:setQueryIgnored(OldRoot, true)
	                        Paused = tick() + 5
	                        task.delay(0, function()
	                            repeat
	                                task.wait()
	                            until not AntiDeath.Enabled or not Entity.isAlive or (Entity.character.Health / Entity.character.MaxHealth) >= (StopThreshold.Value / 100)
	                            local OldCFrame: CFrame? = Clone and Clone.CFrame or nil
	                            if DestroyClone() and OldCFrame then
	                                Entity.character.RootPart.CFrame = OldCFrame
	                            end
	
	                            Paused = tick() + 5
	
	                            if AntiDeath.Enabled and Notify.Enabled then
	                                SendNotification("AntiDeath", "You are visible again", 12, "info")
	                            end
	                        end)
	                    end
	                end
	                task.wait()
	            until not AntiDeath.Enabled
	        else
	            DestroyClone()
	        end
	    end,
	    Tooltip = "Uses selected mode when on a threshold"
	})
	
	Mode = AntiDeath:CreateDropdown({
	    Name = "Mode",
	    List = {"Invincibility", "Teleport"},
	    Default = "Invincibility",
	    Tooltip = "Teleport - Teleports you high up\nInvincibility - Makes you unhittable"
	})
	StopThreshold = AntiDeath:CreateSlider({
	    Name = "Stop Threshold",
	    Min = 1,
	    Max = 100,
	    Default = 30,
	    Suffix = function()
	        return "%"
	    end,
	    Tooltip = "Health percentage to untrigger at"
	})
	Threshold = AntiDeath:CreateSlider({
	    Name = "Threshold",
	    Min = 1,
	    Max = 100,
	    Default = 30,
	    Suffix = function()
	        return "%"
	    end,
	    Tooltip = "Health percentage to trigger at"
	})
	Delay = AntiDeath:CreateSlider({
	    Name = "Delay",
	    Min = 1,
	    Max = 20,
	    Default = 5,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end,
	    Tooltip = "Delay between triggers"
	})
	Notify = AntiDeath:CreateToggle({
	    Name = "Notify on trigger",
	    Default = true
	})
end)

local AntiFallDirection
Run(function()
    local AntiFall
    local Mode
    local Material
    local Color
    local Connection: RBXScriptConnection?
    local RayCheck: RaycastParams = RaycastParams.new()
    RayCheck.RespectCanCollide = true

    AntiFall = vape.Categories.Blatant:CreateModule({
        Name = "AntiFall",
        Function = function(Callback: boolean)
            if Callback then
                repeat
                    task.wait()
                until Store.matchState ~= 0 or not AntiFall.Enabled
                if not AntiFall.Enabled then
                    return
                end

                local LowGround, Debounce = math.huge, tick()
                for _, v: Vector3 in bedwars.BlockController:getStore():getAllBlockPositions() do
                    v = v * 3
                    if v.Y < LowGround and not GetPlacedBlock(v + Vector3.new(0, 3, 0)) then
                        LowGround = v.Y
                    end
                end
                if LowGround == math.huge then
                    return
                end

                AntiFallPart = Instance.new("Part")
                AntiFallPart.Size = Vector3.new(10000, 1, 10000)
                AntiFallPart.Transparency = 1 - Color.Opacity
                AntiFallPart.Material = Enum.Material[Material.Value]
                AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                AntiFallPart.Position = Vector3.new(0, LowGround - 2, 0)
                AntiFallPart.CanCollide = Mode.Value == "Collide"
                AntiFallPart.Anchored = true
                AntiFallPart.CanQuery = false
                AntiFallPart.Parent = workspace
                AntiFall:Clean(AntiFallPart)
                AntiFall:Clean(AntiFallPart.Touched:Connect(function(TouchedPart: BasePart)
                    if TouchedPart.Parent ~= LocalPlayer.Character or not Entity.isAlive or vape.MovementOwner or Debounce >= tick() then
                        return
                    end
                    Debounce = tick() + 0.1

                    if Mode.Value == "Normal" then
                        local Top: Vector3? = GetNearGround()
                        if not Top then
                            return
                        end

                        local LastTeleport = LocalPlayer:GetAttribute("LastTeleported")
                        RayCheck.FilterDescendantsInstances = {Camera, LocalPlayer.Character}
                        RayCheck.CollisionGroup = Entity.character.RootPart.CollisionGroup
                        if Connection then
                            Connection:Disconnect()
                        end
                        Connection = RunService.PreSimulation:Connect(function()
                            if vape.Modules.Fly.Enabled or vape.Modules.LongJump.Enabled or vape.MovementOwner or not Entity.isAlive or LocalPlayer:GetAttribute("LastTeleported") ~= LastTeleport then
                                Connection:Disconnect()
                                AntiFallDirection = nil
                                return
                            end

                            local Root: BasePart = Entity.character.RootPart
                            local Delta: Vector3 = (Top - Root.Position) * Vector3.new(1, 0, 1)
                            AntiFallDirection = Delta.Unit == Delta.Unit and Delta.Unit or Vector3.zero
                            Root.AssemblyLinearVelocity *= Vector3.new(1, 0, 1)

                            local WallRay: RaycastResult? = workspace:Raycast(Root.Position, AntiFallDirection, RayCheck)
                            if WallRay then
                                local BlockPosition: Vector3 = RoundPosition(WallRay.Position + WallRay.Normal * 1.5) + Vector3.new(0, 3, 0)
                                for _ = 1, 10 do
                                    if not GetPlacedBlock(BlockPosition) then
                                        Top = Vector3.new(Top.X, BlockPosition.Y, Top.Z)
                                        break
                                    end
                                    BlockPosition += Vector3.new(0, 3, 0)
                                end
                            end

                            Root.CFrame += Vector3.new(0, Top.Y - Root.Position.Y, 0)
                            if not FrictionTable.Speed then
                                Root.AssemblyLinearVelocity = (AntiFallDirection * GetSpeed()) + Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
                            end

                            if Delta.Magnitude < 1 then
                                Connection:Disconnect()
                                AntiFallDirection = nil
                            end
                        end)
                    elseif Mode.Value == "Velocity" then
                        local Root: BasePart = Entity.character.RootPart
                        Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 100, Root.AssemblyLinearVelocity.Z)
                    end
                end))
            else
                if Connection then
                    Connection:Disconnect()
                    Connection = nil
                end
                AntiFallDirection = nil
                AntiFallPart = nil
            end
        end,
        Tooltip = "Help's you with your Parkinson's\nPrevents you from falling into the void."
    })

    Mode = AntiFall:CreateDropdown({
        Name = "Move Mode",
        List = {"Normal", "Collide", "Velocity"},
        Function = function(Val: string)
            if AntiFallPart then
                AntiFallPart.CanCollide = Val == "Collide"
            end
        end,
        Tooltip = "Normal - Smoothly moves you towards the nearest safe point\nVelocity - Launches you upward after touching\nCollide - Allows you to walk on the part"
    })
    local Materials: {string} = {"ForceField"}
    for _, v: EnumItem in Enum.Material:GetEnumItems() do
        if v.Name ~= "ForceField" then
            table.insert(Materials, v.Name)
        end
    end
    Material = AntiFall:CreateDropdown({
        Name = "Material",
        List = Materials,
        Function = function(Val: string)
            if AntiFallPart then
                AntiFallPart.Material = Enum.Material[Val]
            end
        end
    })
    Color = AntiFall:CreateColorSlider({
        Name = "Color",
        DefaultOpacity = 0.5,
        Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
            if AntiFallPart then
                AntiFallPart.Color = Color3.fromHSV(Hue, Sat, Val)
                AntiFallPart.Transparency = 1 - Opacity
            end
        end
    })
end)

Run(function()
	local AutoChargeProj
	local Percentage
	local Items
	
	local Old, Hook
	
	local function MatchesSelected(Selected: {string}, Tool: string?, Projectile: string)
	    for _, Name: string in Selected do
	        if Name == Tool or Name == Projectile then
	            return true
	        end
	    end
	    return false
	end
	
	AutoChargeProj = vape.Categories.Blatant:CreateModule({
	    Name = "AutoChargeProj",
	    Function = function(Callback: boolean)
	        if Callback then
	            if Hook then
	                return
	            end
	            Old = bedwars.ProjectileController.calculateImportantLaunchValues
	            Hook = function(self, LaunchData, ...)
	                if not AutoChargeProj.Enabled then
	                    return Old(self, LaunchData, ...)
	                end
	                local ProjectileMeta = bedwars.ProjectileMeta[LaunchData.projectile]
	                local Tool: Tool? = Store.hand.tool
	                local Selected: {string} = Items.ListEnabled or {}
	                local Allowed: boolean = #Selected == 0 or MatchesSelected(Selected, Tool and Tool.Name, LaunchData.projectile)
	                if Allowed and ProjectileMeta and ProjectileMeta.predictionLifetimeSec and LaunchData.drawDurationSeconds then
	                    LaunchData.drawDurationSeconds = math.max(LaunchData.drawDurationSeconds, ProjectileMeta.predictionLifetimeSec * (Percentage.Value / 100))
	                    LaunchData.velocityMultiplier = math.max(LaunchData.velocityMultiplier or 0, Percentage.Value / 100)
	                end
	                return Old(self, LaunchData, ...)
	            end
	            bedwars.ProjectileController.calculateImportantLaunchValues = Hook
	        elseif Hook and bedwars.ProjectileController.calculateImportantLaunchValues == Hook then
	            bedwars.ProjectileController.calculateImportantLaunchValues = Old
	            Old, Hook = nil, nil
	        end
	    end,
	    Tooltip = "Instantly charges your projectile item to a certain percentage"
	})
	
	Percentage = AutoChargeProj:CreateSlider({
	    Name = "Percentage",
	    Min = 0,
	    Max = 100,
	    Default = 50,
	    Suffix = "%"
	})
	
	Items = AutoChargeProj:CreateTextList({
	    Name = "Items",
	    Default = {},
	    Tooltip = "Item or projectile ids to charge; empty charges every chargeable projectile"
	})
end)

