	        return Val == 1 and "stud" or "studs"
	    end
	})
	Targets = DeathAdderAimbot:CreateTargets({
	    Players = true,
	    Walls = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = DeathAdderAimbot:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Distance",
	    Darker = true
	})
	TargetPart = DeathAdderAimbot:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head"},
	    Darker = true
	})
	FOV = DeathAdderAimbot:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Default = 1000,
	    Darker = true
	})
