	            Old = bedwars.BlockBreaker.hitBlock
	            bedwars.BlockBreaker.hitBlock = function(self, ...)
	                local RayParams = select(2, ...)
	                pcall(function()
	                    local MouseInfo = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = RayParams})
	                    local Block = MouseInfo and MouseInfo.target and MouseInfo.target.blockInstance
	                    local IsBlacklisted: boolean = false
	                    for _, v: string in Block and Blacklist.Enabled and BlockList or {} do
	                        if v == Block.Name or Block.Name:find(v, 1, true) then
	                            IsBlacklisted = true
	                            break
	                        end
