Run(function()
	local Value
	local CameraDirection
	local Start: Vector3?
	local JumpTick, JumpSpeed, Direction = tick(), 0
	local Coast: number = 1.1
	local ProjectileRemote = {InvokeServer = function() end}
	task.spawn(function()
	    ProjectileRemote = bedwars.Handler:Get("ProjectileFire").Remote.instance
	end)
	
	local Boosts = {
	    cannon = {Multiplier = 5.25, Duration = 2.3},
	    cat = {Multiplier = 4, Duration = 2.5},
	    grappling_hook = {Multiplier = 2.5, Duration = 2.5},
	    jade_hammer = {Multiplier = 1.4, Duration = 2.5},
	    wood_dao = {Multiplier = 4.5, Duration = 2.4}
	}
	for _, v: string in {"stone_dao", "iron_dao", "diamond_dao", "emerald_dao"} do
	    Boosts[v] = Boosts.wood_dao
	end
	Boosts.void_axe = Boosts.jade_hammer
	
	local function Scaled(Name: string)
	    local Boost = Boosts[Name]
	    if not Boost then
	        return nil
	    end
	    return Boost.Multiplier * Value.Value, Boost.Duration
	end
	
	local function JumpAbility(Item): string
	    return `{Item.itemType:find("jade_hammer") and "jade_hammer" or Item.itemType}_jump`
	end
	
	local function Ready(Name: string, Item): boolean
	    local Options = {disableBlockedAbilityAlert = true}
	    if Name == "cat" then
	        return bedwars.AbilityController:canUseAbility("CAT_POUNCE", Options)
	    elseif Name:find("_dao") then
	        return (LocalPlayer.Character:GetAttribute("CanDashNext") or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility("dash", Options)
	    elseif Boosts[Name] == Boosts.jade_hammer then
	        return bedwars.AbilityController:canUseAbility(JumpAbility(Item), Options)
	    end
	    return true
	end
	
	local function Knockback(DamageTable)
	    if DamageTable.entityInstance ~= LocalPlayer.Character or DamageTable.fromEntity ~= LocalPlayer.Character or DamageTable.knockbackMultiplier and DamageTable.knockbackMultiplier.disabled then
	        return nil
	    end
	
	    local Position: Vector3? = DamageTable.fromPosition and Vector3.new(DamageTable.fromPosition.X, DamageTable.fromPosition.Y, DamageTable.fromPosition.Z) or DamageTable.fromEntity and DamageTable.fromEntity.PrimaryPart.Position
	    if not Position then
	        return nil
	    end
	    local Speed: number = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
	        vertical = 0,
	        horizontal = (DamageTable.knockbackMultiplier and DamageTable.knockbackMultiplier.horizontal or 1)
	    }).Magnitude * 1.1
	    return Speed, 2.5, Entity.character.RootPart.Position - Position
	end
	
	local function Transit(DataTable)
	    if DataTable.hookFunction == "PLAYER_IN_TRANSIT" then
	        return Scaled("grappling_hook")
	    end
	    return nil
	end
	
	local function Propel(LookVector: Vector3, Speed: number, Duration: number)
	    JumpSpeed = Speed
	    JumpTick = tick() + Duration
	    Direction = Vector3.new(LookVector.X, 0, LookVector.Z).Unit
	end
	
	local Launcher = {
	    Active = function(): boolean
	        return LongJump.Enabled
	    end,
	    Propel = Propel,
	    Anchor = function(Position: Vector3)
	        Start = Position
	    end,
	    Clean = function(Connection)
	        LongJump:Clean(Connection)
	    end
	}
	
	local LongJumpMethods = {
	    cannon = function(_, Position: Vector3, LookVector: Vector3, Launch)
	        Position = Position - Vector3.new(0, (Entity.character.HipHeight + (Entity.character.RootPart.Size.Y / 2)) - 3, 0)
	        local Rounded: Vector3 = Vector3.new(math.round(Position.X / 3) * 3, math.round(Position.Y / 3) * 3, math.round(Position.Z / 3) * 3)
	        bedwars.placeBlock(Rounded, "cannon", false)
	
	        task.delay(0, function()
	            local Block, BlockPosition = GetPlacedBlock(Rounded)
	            if Block and Block.Name == "cannon" and (Entity.character.RootPart.Position - Block.Position).Magnitude < 20 then
	                local BreakType = bedwars.ItemMeta[Block.Name].block.breakType
	                local Tool = Store.tools[BreakType]
	                if Tool then
	                    SwitchItem(Tool.tool)
	                end
	
	                bedwars.Handler:Get("AimCannon"):Fire("SendToServer", {
	                    cannonBlockPos = BlockPosition,
	                    lookVector = LookVector
	                })
	
	                local BreakDelay: number = 0.1
	                if bedwars.BlockController:calculateBlockDamage(LocalPlayer, {blockPosition = BlockPosition}) < Block:GetAttribute("Health") then
	                    BreakDelay = 0.4
	                    bedwars.breakBlock(Block, true, true)
	                end
	
	                task.delay(BreakDelay, function()
	                    for _ = 1, 3 do
	                        local Call = bedwars.Handler:Get("LaunchSelfFromCannon"):Fire("CallServer", {cannonBlockPos = BlockPosition})
	                        if Call then
	                            bedwars.breakBlock(Block, true, true)
	                            Launch.Propel(LookVector, Scaled("cannon"))
	                            break
	                        end
	                        task.wait(0.1)
	                    end
	                end)
	            end
	        end)
	    end,
	    cat = function(_, _, LookVector: Vector3, Launch)
	        Launch.Clean(VapeEvents.CatPounce.Event:Connect(function()
	            Launch.Propel(LookVector, Scaled("cat"))
	            Entity.character.RootPart.AssemblyLinearVelocity = Vector3.zero
	        end))
	
	        if not Ready("cat") then
	            repeat
	                task.wait()
	            until Ready("cat") or not Launch.Active()
	        end
	
	        if Ready("cat") and Launch.Active() then
	            bedwars.AbilityController:useAbility("CAT_POUNCE")
	        end
	    end,
	    fireball = function(Item, Position: Vector3?, LookVector: Vector3)
	        if not Position then
	            return
	        end
	
	        Position = Position - LookVector * 0.1
	        local ShootCFrame: CFrame = (CFrame.lookAlong(Position, Vector3.new(0, -60, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
	        SwitchItem(Item.tool, 0)
	        task.wait(0.1)
	        if ProjectileRemote:InvokeServer(Item.tool, "fireball", "fireball", ShootCFrame.Position, Position, ShootCFrame.LookVector * 60, HttpService:GenerateGUID(true), {drawDurationSeconds = 1}, workspace:GetServerTimeNow() - 0.045) then
	            local LaunchSound = bedwars.ItemMeta[Item.itemType].projectileSource.launchSound
	            LaunchSound = LaunchSound and LaunchSound[math.random(1, #LaunchSound)] or nil
	            if LaunchSound then
	                bedwars.AudioManager:playAudio(LaunchSound)
	            end
	        end
	    end,
	    grappling_hook = function(Item, Position: Vector3?, LookVector: Vector3)
	        if not Position then
	            return
	        end
	
	        Position = Position - LookVector * 0.1
	        local ShootCFrame: CFrame = (CFrame.lookAlong(Position, Vector3.new(0, -140, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
	        SwitchItem(Item.tool, 0)
	        task.wait(0.1)
	        if ProjectileRemote:InvokeServer(Item.tool, "grappling_hook_projectile", "grappling_hook_projectile", ShootCFrame.Position, Position, ShootCFrame.LookVector * 140, HttpService:GenerateGUID(true), {drawDurationSeconds = 1}, workspace:GetServerTimeNow() - 0.045) then
	            local LaunchSound = bedwars.ItemMeta[Item.itemType].projectileSource.launchSound
	            LaunchSound = LaunchSound and LaunchSound[math.random(1, #LaunchSound)] or nil
	            if LaunchSound then
	                bedwars.AudioManager:playAudio(LaunchSound)
	            end
	        end
	    end,
	    jade_hammer = function(Item, Position: Vector3, LookVector: Vector3, Launch)
	        if not Ready("jade_hammer", Item) then
	            repeat
	                task.wait()
	            until Ready("jade_hammer", Item) or not Launch.Active()
	        end
	
	        if Ready("jade_hammer", Item) and Launch.Active() then
	            SwitchItem(Item.tool, 0)
	            LocalPlayer.Character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	            Launch.Anchor(Position + Vector3.new(0, 3.1, 0))
	            task.wait(0.1)
	            bedwars.AbilityController:useAbility(JumpAbility(Item))
	            Launch.Propel(LookVector, Scaled("jade_hammer"))
	        end
	    end,
	    tnt = function(Item, Position: Vector3?, LookVector: Vector3, Launch)
	        if not Position then
	            return
	        end
	
	        local Feet: Vector3 = Position - Vector3.new(0, (Entity.character.HipHeight + (Entity.character.RootPart.Size.Y / 2)) - 3, 0)
	        local Rounded: Vector3 = Vector3.new(math.round(Feet.X / 3) * 3, math.round(Feet.Y / 3) * 3, math.round(Feet.Z / 3) * 3)
	        Launch.Anchor(Vector3.new(Rounded.X, Position.Y, Rounded.Z) + (LookVector * (Item.itemType == "pirate_gunpowder_barrel" and 2.6 or 0.2)))
	        bedwars.placeBlock(Rounded, Item.itemType, false)
	    end,
	    wood_dao = function(Item, Position: Vector3, LookVector: Vector3, Launch)
	        if not Ready("wood_dao") then
	            repeat
	                task.wait()
	            until Ready("wood_dao") or not Launch.Active()
	        end
	
	        if Launch.Active() then
	            bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
	            SwitchItem(Item.tool, 0.1)
	            ReplicatedStorage["events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"].useAbility:FireServer("dash", {
	                direction = LookVector,
	                origin = Position,
	                weapon = Item.itemType
	            })
	            Launch.Propel(LookVector, Scaled("wood_dao"))
	        end
	    end
	}
	for _, v: string in {"stone_dao", "iron_dao", "diamond_dao", "emerald_dao"} do
	    LongJumpMethods[v] = LongJumpMethods.wood_dao
	end
	LongJumpMethods.void_axe = LongJumpMethods.jade_hammer
	LongJumpMethods.siege_tnt = LongJumpMethods.tnt
	LongJumpMethods.pirate_gunpowder_barrel = LongJumpMethods.tnt
	
	LongJump = vape.Categories.Blatant:CreateModule({
	    Name = "LongJump",
	    Function = function(Callback: boolean)
	        if Callback and vape.MovementOwner then
	            SendNotification("LongJump", `Unavailable until {vape.MovementOwner} has landed`, 3, "warning")
	            LongJump:Toggle()
	            return
	        end
	        FrictionTable.LongJump = Callback or nil
	        UpdateVelocity()
	        if Callback then
	            LongJump:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                local Speed, Duration, Away = Knockback(DamageTable)
	                if Speed and Speed >= JumpSpeed then
	                    Propel(Away, Speed, Duration)
	                end
	            end))
	            LongJump:Clean(VapeEvents.GrapplingHookFunctions.Event:Connect(function(DataTable)
	                local Speed, Duration = Transit(DataTable)
	                if Speed then
	                    Propel(Entity.character.RootPart.CFrame.LookVector, Speed, Duration)
	                end
	            end))
	
	            Start = Entity.isAlive and Entity.character.RootPart.Position or nil
	            LongJump:Clean(RunService.PreSimulation:Connect(function(Delta: number)
	                local Root = Entity.isAlive and Entity.character.RootPart or nil
	                if vape.MovementOwner then
	                    return
	                elseif Root and isnetworkowner(Root) then
	                    if JumpTick > tick() then
	                        local CurrentSpeed: number = GetSpeed()
	                        local Destination: Vector3 = (Direction * math.max(((JumpTick - tick()) > Coast and JumpSpeed or 0), 0) * Delta)
	                        Root.CFrame += Destination
	                        Root.AssemblyLinearVelocity = (Direction * CurrentSpeed) + Vector3.new(0, 15, 0)
	                        Start = nil
	                    else
	                        if Start then
	                            Root.CFrame = CFrame.lookAlong(Start, Root.CFrame.LookVector)
	                        end
	                        Root.AssemblyLinearVelocity = Vector3.zero
	                        JumpSpeed = 0
	                    end
	                else
	                    Start = nil
	                end
	            end))
	
	            if Store.hand and LongJumpMethods[Store.hand.tool.Name] then
	                task.spawn(LongJumpMethods[Store.hand.tool.Name], GetItem(Store.hand.tool.Name), Start, (CameraDirection.Enabled and Camera or Entity.character.RootPart).CFrame.LookVector, Launcher)
	                return
	            end
	
	            for Name: string, Method: (...any) -> ...any in LongJumpMethods do
	                local Item = GetItem(Name, nil, true)
	                if Item or Store.equippedKit == Name then
	                    task.spawn(Method, Item, Start, (CameraDirection.Enabled and Camera or Entity.character.RootPart).CFrame.LookVector, Launcher)
	                    break
	                end
	            end
	        else
	            JumpTick = tick()
	            Direction = nil
	            JumpSpeed = 0
	        end
	    end,
	    ExtraText = function()
	        return "Heatseeker"
	    end,
	    Tooltip = "Lets you jump farther"
	})
	LongJump.Launch = {
	    Methods = LongJumpMethods,
	    Coast = Coast,
	    Ready = Ready,
	    Scaled = Scaled,
	    Knockback = Knockback,
	    Transit = Transit
	}
	
	Value = LongJump:CreateSlider({
	    Name = "Speed",
	    Min = 1,
	    Max = 37,
	    Default = 37,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	CameraDirection = LongJump:CreateToggle({
	    Name = "Camera Direction"
	})
end)

Run(function()
	local NoFall
	local Damage
	local Disabled: {[Humanoid]: {any}} = setmetatable({}, {__mode = "k"})
	local GroundHit = bedwars.Handler:Get("GroundHit")
	
	NoFall = vape.Categories.Blatant:CreateModule({
	    Name = "NoFall",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Humanoid = Entity.isAlive and Entity.character.Humanoid
	            if Humanoid and not Disabled[Humanoid] and getconnections then
	                Disabled[Humanoid] = {}
	                for _, v: any in getconnections(Humanoid.StateChanged) do
	                    v:Disable()
	                    table.insert(Disabled[Humanoid], v)
	                end
	            end
	
	            local Tracked: number = 0
	            NoFall:Clean(RunService.PostSimulation:Connect(function()
	                if Entity.isAlive and Store.matchState == 1 and not Store.cannonFlight then
	                    local Root: BasePart = Entity.character.RootPart
	                    local Velocity: Vector3 = Root.AssemblyLinearVelocity
	
	                    if Tracked < -(45 + (Damage.Value * 0.75)) then
	                        local Cushion: Vector3 = Vector3.new(0, 2.5, 0)
	                        Root.AssemblyLinearVelocity = Cushion
	                        Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Landed)
	                        RunService.PreRender:Wait()
	                        if Root.AssemblyLinearVelocity == Cushion then
	                            Root.AssemblyLinearVelocity = Velocity
	                        end
	                        GroundHit:Fire("SendToServer", nil, Vector3.new(0, Tracked, 0), workspace:GetServerTimeNow())
	                    end
	                    Tracked = Velocity.Y
	                else
	                    Tracked = 0
	                end
	            end))
	
	            NoFall:Clean(Entity.Events.LocalAdded:Connect(function(Ent)
	                if Ent.Humanoid:WaitForChild("Animator", 5) then
	                    task.wait(0.5)
	                    if NoFall.Enabled and not Disabled[Ent.Humanoid] and getconnections then
	                        Disabled[Ent.Humanoid] = {}
	                        for _, v: any in getconnections(Ent.Humanoid.StateChanged) do
	                            v:Disable()
	                            table.insert(Disabled[Ent.Humanoid], v)
	                        end
	                    end
	                end
	            end))
	        else
	            for _, Connections: {any} in Disabled do
	                for _, v: any in Connections do
	                    v:Enable()
	                end
	            end
	
	            table.clear(Disabled)
	        end
	    end,
	    Tooltip = "Prevents taking fall damage."
	})
	
	Damage = NoFall:CreateSlider({
	    Name = "Damage",
	    Min = 0,
	    Max = 100,
	    Default = 0,
	    Suffix = "%",
	    Tooltip = "How much of each fall lands on you, it only starts saving you once you are dropping faster than this lets through"
	})
end)

Run(function()
	local Old: (...any) -> ...any
	
	vape.Categories.Blatant:CreateModule({
	    Name = "NoSlow",
	    Function = function(Callback: boolean)
	        local Modifier = bedwars.SprintController:getMovementStatusModifier()
	        if Callback then
	            Old = Modifier.addModifier
	            Modifier.addModifier = function(self, NewModifier)
	                if NewModifier.moveSpeedMultiplier then
	                    NewModifier.moveSpeedMultiplier = math.max(NewModifier.moveSpeedMultiplier, 1)
	                end
	                return Old(self, NewModifier)
	            end
	
	            for ActiveModifier: any in Modifier.modifiers do
	                if (ActiveModifier.moveSpeedMultiplier or 1) < 1 then
	                    Modifier:removeModifier(ActiveModifier)
	                end
	            end
	        else
	            Modifier.addModifier = Old
	        end
	    end,
	    Tooltip = "Prevents slowing down when using items."
	})
end)

Run(function()
	local OwlAura
	local Targets
	local Mode
	local Range
	
	OwlAura = vape.Categories.Blatant:CreateModule({
	    Name = "OwlAura",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Owls = Collection("Owl", OwlAura, function(List, Object)
	                task.delay(1, function()
	                    if Object and Object.Parent and Object:GetAttribute("Owner") == LocalPlayer.UserId then
	                        table.insert(List, Object)
	                    end
	                end)
	            end)
	            repeat
	                if Store.equippedKit ~= "owl" then
	                    task.wait(1)
	                    continue
	                end
	
	                if Entity.isAlive then
	                    local Owl = Owls[1]
	                    if Owl then
	                        local Origin: Vector3 = Owl.Part.Position
	                        local Ent = Entity.EntityPosition({
	                            Origin = Origin,
	                            Range = Range.Value,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled,
	                            Priority = Targets.Priority.Value,
	                            Wallcheck = Targets.Walls.Enabled,
	                            Sort = SortMethods[Mode.Value]
	                        })
	
	                        if Ent then
	                            local ProjectileMeta = bedwars.ProjectileMeta.owl_projectile
	                            local TargetVelocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity
	                            local TargetAirborne: boolean = Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01
	                            local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(Origin, ProjectileMeta.launchVelocity, ProjectileMeta.gravitationalAcceleration, Ent.RootPart.Position, TargetVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, Store.airRay, TargetAirborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                            if AimPosition and TravelTime and TravelTime <= (ProjectileMeta.lifetimeSec or 3) then
	                                local Direction: Vector3 = CFrame.lookAt(Origin, AimPosition).LookVector * ProjectileMeta.launchVelocity
	                                bedwars.Handler:Get("OwlAiming"):Fire("SendToServer", {
	                                    owl = Owl.Part,
	                                    starting = true
	                                })
	                                bedwars.Handler:Get("OwlFireProjectile"):Fire("SendToServer", {
	                                    ProjectileRefId = HttpService:GenerateGUID(true),
	                                    direction = Direction,
	                                    fromPosition = Origin,
	                                    initialVelocity = Direction
	                                })
	                                task.wait(Store.ping.total or 0)
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not OwlAura.Enabled
	        else
	            bedwars.Handler:Get("OwlAiming"):Fire("SendToServer", {starting = false})
	        end
	    end,
	    Tooltip = "Automatically shoots projectiles with whisper kit"
	})
	
	Targets = OwlAura:CreateTargets({
	    Players = true,
	    Wallcheck = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Mode = OwlAura:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Distance"
	})
	Range = OwlAura:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 50,
	    Default = 50,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local ProjectileAimbot
	local TargetPart
	local Targets
	local Sort
	local FOV
	local CircleColor
	local CircleTransparency
	local CircleThickness
	local CircleFilled
	local CircleObject
	local Horizontal
	local Vertical
	local AutoCharge
	local Aim = {}
	local OtherProjectiles
	local UseUmeko
	local Potions
	local Blacklist
	local Old, Hook
	local ArcCheck: RaycastParams = RaycastParams.new()
	ArcCheck.FilterType = Enum.RaycastFilterType.Exclude
	
	local function GetMouseOrigin()
	    return UserInputService.TouchEnabled and Camera.ViewportSize / 2 or UserInputService:GetMouseLocation()
	end
	
	ProjectileAimbot = vape.Categories.Blatant:CreateModule({
	    Name = "ProjectileAimbot",
	    Function = function(Callback: boolean)
	        if CircleObject then
	            CircleObject.Visible = Callback
	        end
	
	        if Callback then
	            local function UpdateCircle()
	                if CircleObject then
	                    CircleObject.Position = GetMouseOrigin()
	                end
	            end
	
	            ProjectileAimbot:Clean(RunService.RenderStepped:Connect(UpdateCircle))
	            ProjectileAimbot:Clean(Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
	                UpdateCircle()
	            end))
	            if Hook then
	                return
	            end
	            Old = bedwars.ProjectileController.calculateImportantLaunchValues
	            local function AimLaunchValues(self, LaunchData, WorldMeta, Origin, ShootPosition: Vector3?)
	                local LaunchPosition: Vector3? = ShootPosition or self:getLaunchPosition(Origin)
	                if not LaunchPosition then
	                    return
	                end
	
	                if LaunchData.projectile:find("splash_potion") then
	                    if not Potions.Enabled then
	                        return
	                    end
	                elseif (not OtherProjectiles.Enabled) and not LaunchData.projectile:find("arrow") and not (UseUmeko.Enabled and LaunchData.projectile:find("^ninja_chakram")) then
	                    return
	                end
	
	                if table.find(Blacklist.ListEnabled or {}, ((LaunchData.projectile == "glue_trap" or LaunchData.projectile == "glue_projectile") and "gloop" or LaunchData.projectile)) then
	                    return
	                end
	
	                local ProjectileMeta = LaunchData:getProjectileMeta()
	                local Lifetime: number = (WorldMeta and ProjectileMeta.predictionLifetimeSec or ProjectileMeta.lifetimeSec or 3)
	                local Gravity: number = (ProjectileMeta.gravitationalAcceleration or 196.2) * LaunchData.gravityMultiplier
	                local ProjectileSpeed: number = (ProjectileMeta.launchVelocity or 100) * ((AutoCharge.Enabled or not Aim.Enabled) and 1 or LaunchData.velocityMultiplier)
	                local OffsetPosition: Vector3 = LaunchPosition + (LaunchData.projectile == "owl_projectile" and Vector3.zero or LaunchData.fromPositionOffset)
	                local Tool = Store.hand.tool
	                local PartName: string = TargetPart.Value == "Dynamic" and (IsHeadshotProjectile(Tool and Tool.Name) and "Head" or "RootPart") or TargetPart.Value
	                local Filtered: boolean = false
	
	                local function GetLaunchValues(Ent)
	                    local Balloons: number? = Ent.Character:GetAttribute("InflatedBalloons")
	                    local PlayerGravity: number = workspace.Gravity
	
	                    if Balloons and Balloons > 0 then
	                        PlayerGravity = (workspace.Gravity * (1 - ((Balloons >= 4 and 1.2 or Balloons >= 3 and 1 or 0.975))))
	                    end
	
	                    if Ent.Character.PrimaryPart:FindFirstChild("rbxassetid://8200754399") then
	                        PlayerGravity = 6
	                    end
	
	                    if Ent.Player and Ent.Player:GetAttribute("IsOwlTarget") then
	                        for _, v: Instance in CollectionService:GetTagged("Owl") do
	                            if v:GetAttribute("Target") == Ent.Player.UserId and v:GetAttribute("Status") == 2 then
	                                PlayerGravity = 0
	                            end
	                        end
	                    end
	
	                    local AimPart: BasePart = GetTargetPart(Ent, PartName)
	                    local Velocity: Vector3 = LaunchData.projectile == "telepearl" and Vector3.zero or AimPart.AssemblyLinearVelocity
	                    local Airborne: boolean = Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01
	                    local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(OffsetPosition, ProjectileSpeed, Gravity, AimPart.Position, Velocity, PlayerGravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, Store.airRay, Airborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                    if AimPosition and TravelTime and (Horizontal.Value ~= 1 or Vertical.Value ~= 1) then
	                        local Rise: number = (Velocity.Y * TravelTime) - (PlayerGravity * TravelTime * TravelTime * 0.5)
	                        local Lead: Vector3 = Vector3.new(Velocity.X * TravelTime * (Horizontal.Value - 1), Rise * (Vertical.Value - 1), Velocity.Z * TravelTime * (Horizontal.Value - 1))
	                        local AdjustedPosition, _, AdjustedTime = PredictionLib.SolveTrajectory(OffsetPosition, ProjectileSpeed, Gravity, AimPart.Position + Lead, Velocity, PlayerGravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, Store.airRay, Airborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                        if AdjustedPosition then
	                            AimPosition, TravelTime = AdjustedPosition, AdjustedTime or TravelTime
	                        end
	                    end
	
	                    if not AimPosition or not TravelTime or TravelTime > Lifetime then
	                        return nil
	                    end
	
	                    Store.hitchance.ProjectileAimbot = {Value = GetHitChance(Ent, TravelTime), Clock = tick()}
	                    local LaunchVelocity: Vector3 = (AimPosition - OffsetPosition).Unit * ProjectileSpeed
	                    if Targets.Walls.Enabled and TravelTime then
	                        if not Filtered then
	                            local IgnoreList: {Instance} = {Camera, LocalPlayer.Character}
	                            for _, v: any in Entity.List do
	                                if v.Character then
	                                    table.insert(IgnoreList, v.Character)
	                                end
	                            end
	                            ArcCheck.FilterDescendantsInstances = IgnoreList
	                            Filtered = true
	                        end
	
	                        if not PredictionLib.IsTrajectoryClear(OffsetPosition, LaunchVelocity, Gravity, TravelTime, ArcCheck) then
	                            return nil
	                        end
	                    end
	
	                    return {
	                        initialVelocity = LaunchVelocity,
	                        positionFrom = OffsetPosition,
	                        deltaT = Lifetime,
	                        gravitationalAcceleration = Gravity,
	                        drawDurationSeconds = AutoCharge.Enabled and 5 or LaunchData.drawDurationSeconds
	                    }
	                end
	
	                local Values, Attempts, Started = nil, 0, os.clock()
	                local Ent = Entity.EntityMouse({
	                    Part = "RootPart",
	                    Range = FOV.Value,
	                    Players = Targets.Players.Enabled,
	                    NPCs = Targets.NPCs.Enabled,
	                    Priority = Targets.Priority.Value,
	                    Origin = Entity.isAlive and (ShootPosition or Entity.character.RootPart.Position) or Vector3.zero,
	                    MouseOrigin = GetMouseOrigin(),
	                    Sort = SortMethods[Sort.Value],
	                    Check = function(Entity)
	                        if Attempts >= 10 or (Attempts > 0 and (os.clock() - Started) > 0.0015) then
	                            return false
	                        end
	                        Attempts += 1
	                        Values = GetLaunchValues(Entity)
	                        return Values ~= nil
	                    end
	                })
	
	                if Ent and Values then
	                    TargetInfo.Targets[Ent] = tick() + 1
	                    return Values
	                end
	            end
	
	            Hook = function(self, LaunchData, WorldMeta, Origin, ShootPosition: Vector3?, ...)
	                if ProjectileAimbot.Enabled then
	                    local Success, Values = pcall(AimLaunchValues, self, LaunchData, WorldMeta, Origin, ShootPosition)
	                    if Success and Values then
	                        return Values
	                    end
	                end
	
	                return Old(self, LaunchData, WorldMeta, Origin, ShootPosition, ...)
	            end
	            bedwars.ProjectileController.calculateImportantLaunchValues = Hook
	        elseif Hook and bedwars.ProjectileController.calculateImportantLaunchValues == Hook then
	            bedwars.ProjectileController.calculateImportantLaunchValues = Old
	            Old, Hook = nil, nil
	        end
	    end,
	    Tooltip = "Silently adjusts your aim towards the enemy"
	})
	
	Targets = ProjectileAimbot:CreateTargets({
	    Players = true,
	    Walls = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = ProjectileAimbot:CreateDropdown({
	    Name = "Target mode",
	    List = Methods,
	    Default = "Distance"
	})
	TargetPart = ProjectileAimbot:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head", "Torso", "Left arm", "Right arm", "Left leg", "Right leg", "Random", "Dynamic"},
	    Tooltip = "Dynamic aims at the head with headshot-capable bows, including tactical bows and Archer, and at the body with everything else"
	})
	FOV = ProjectileAimbot:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Radius = Val
	        end
	    end,
	    Default = 1000
	})
	ProjectileAimbot:CreateToggle({
	    Name = "Range Circle",
	    Function = function(Callback: boolean)
	        if Callback then
	            CircleObject = Drawing.new("Circle")
	            CircleObject.Filled = CircleFilled.Enabled
	            CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)
	            CircleObject.Position = GetMouseOrigin()
	            CircleObject.Radius = FOV.Value
	            CircleObject.NumSides = 100
	            CircleObject.Thickness = CircleThickness.Value
	            CircleObject.Transparency = 1 - CircleTransparency.Value
	            CircleObject.Visible = ProjectileAimbot.Enabled
	        else
	            pcall(function()
	                CircleObject.Visible = false
	                CircleObject:Remove()
	            end)
	            CircleObject = nil
	        end
	        CircleColor.Object.Visible = Callback
	        CircleTransparency.Object.Visible = Callback
	        CircleThickness.Object.Visible = Callback
	        CircleFilled.Object.Visible = Callback
	    end
	})
	CircleColor = ProjectileAimbot:CreateColorSlider({
	    Name = "Circle Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        if CircleObject then
	            CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
	CircleTransparency = ProjectileAimbot:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 10,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Transparency = 1 - Val
	        end
	    end,
	    Darker = true,
	    Default = 0.5,
	    Visible = false
	})
	CircleThickness = ProjectileAimbot:CreateSlider({
	    Name = "Thickness",
	    Min = 1,
	    Max = 10,
	    Decimal = 10,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Thickness = Val
	        end
	    end,
	    Darker = true,
	    Default = 1,
	    Visible = false,
	    Tooltip = "How wide the circle's outline is, has no effect while Circle Filled is on"
	})
	CircleFilled = ProjectileAimbot:CreateToggle({
	    Name = "Circle Filled",
	    Function = function(Callback: boolean)
	        if CircleObject then
	            CircleObject.Filled = Callback
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
	Horizontal = ProjectileAimbot:CreateSlider({
	    Name = "Horizontal prediction",
	    Min = 0,
	    Max = 2,
	    Default = 1,
	    Decimal = 100,
	    Tooltip = "Scales how far ahead of the target you aim sideways"
	})
	Vertical = ProjectileAimbot:CreateSlider({
	    Name = "Vertical prediction",
	    Min = 0,
	    Max = 2,
	    Default = 1,
	    Decimal = 100,
	    Tooltip = "Scales how far ahead of the target you aim while it rises or falls"
	})
	AutoCharge = ProjectileAimbot:CreateToggle({
	    Name = "Auto Charge",
	    Function = function(Callback: boolean)
	        if Aim.Object then
	            Aim.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Fully charges your bow, Allowing your projectile to deal more damage"
	})
	Aim = ProjectileAimbot:CreateToggle({
	    Name = "Aim change",
	    Default = true,
	    Darker = true,
	    Tooltip = "Changes your trajectory to match charge percentage."
	})
	OtherProjectiles = ProjectileAimbot:CreateToggle({
	    Name = "Other Projectiles",
	    Default = true,
	    Tooltip = "Aims everything that is not an arrow or a splash potion"
	})
	UseUmeko = ProjectileAimbot:CreateToggle({
	    Name = "Use umeko",
	    Tooltip = "Aims umeko's chakram even with Other Projectiles off"
	})
	Potions = ProjectileAimbot:CreateToggle({
	    Name = "Shoot pots",
	    Default = true,
	    Tooltip = "Aims heal, poison and sleep splash potions, separate from Other Projectiles"
	})
	Blacklist = ProjectileAimbot:CreateTextList({
	    Name = "Blacklist",
	    Default = {"telepearl"}
	})
end)

Run(function()
	local ProjectileAura
	local Targets
	local Part
	local FireRate
	local Range
	local AFKCheck
	local List
	local UseSophia
	local UseWhim
	local UseNazar
	local UseUmeko
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Exclude
	local ProjectileRemote = {InvokeServer = function() end}
	local FireDelays: {[string]: number} = {}
	task.spawn(function()
	    ProjectileRemote = bedwars.Handler:Get("ProjectileFire").Remote.instance
	end)
	
	ProjectileAura = vape.Categories.Blatant:CreateModule({
	    Name = "ProjectileAura",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.5 and (not AFKCheck.Enabled or not IsAfk()) then
	                    local Ent = Entity.EntityPosition({
	                        Part = "RootPart",
	                        Range = Range.Value,
	                        Players = Targets.Players.Enabled,
	                        NPCs = Targets.NPCs.Enabled,
	                        Priority = Targets.Priority.Value,
	                        Wallcheck = Targets.Walls.Enabled
	                    })
	
	                    if Ent then
	                        local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                        for _, v: {any} in GetProjectiles(List.ListEnabled, UseSophia.Enabled, UseWhim.Enabled, UseNazar.Enabled, UseUmeko.Enabled) do
	                            local Item, Ammo, Projectile, ItemMeta = unpack(v)
	                            local AimPart: BasePart = GetTargetPart(Ent, Part.Value == "Dynamic" and (IsHeadshotProjectile(Item.itemType) and "Head" or "RootPart") or Part.Value)
	                            if (FireDelays[Item.itemType] or 0) < tick() then
	                                RayCheck.FilterDescendantsInstances = {LocalPlayer.Character, Camera}
	                                local ProjectileMeta = bedwars.ProjectileMeta[Projectile]
	                                local ProjectileSpeed, Gravity = ProjectileMeta.launchVelocity, ProjectileMeta.gravitationalAcceleration or 196.2
	                                local TargetVelocity: Vector3 = Ent.RootPart.AssemblyLinearVelocity
	                                local TargetAirborne: boolean = Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(TargetVelocity.Y) > 0.01
	                                local AimPosition: Vector3? = PredictionLib.SolveTrajectory(LocalPosition, ProjectileSpeed, Gravity, AimPart.Position, TargetVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, RayCheck, TargetAirborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                                if AimPosition then
	                                    local Switched = SwitchItem(Item.tool)
	
	                                    TargetInfo.Targets[Ent] = tick() + 1
	
	                                    task.spawn(function()
	                                        local ShootPosition: Vector3 = (CFrame.new(LocalPosition, AimPosition) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
	                                        local Aim, _, FlightTime = PredictionLib.SolveTrajectory(ShootPosition, ProjectileSpeed, Gravity, AimPart.Position, TargetVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, RayCheck, TargetAirborne, Ent.RootPart.Position, Ent.RootPart, nil, true)
	                                        Store.hitchance.ProjectileAura = {Value = GetHitChance(Ent, FlightTime), Clock = tick()}
	                                        Aim = Aim or AimPosition
	                                        local Direction, ShotId = CFrame.lookAt(ShootPosition, Aim).LookVector, HttpService:GenerateGUID(true)
	                                        if FlightTime and not PredictionLib.IsTrajectoryClear(ShootPosition, Direction * ProjectileSpeed, Gravity, FlightTime, RayCheck, Ent.Character) then
	                                            FireDelays[Item.itemType] = tick()
	                                            return
	                                        end
	                                        WatchProjectile(ShotId, ShootPosition, Direction * ProjectileSpeed, Gravity, Ent, ProjectileMeta.lifetimeSec)
	                                        local Response = ProjectileRemote:InvokeServer(Item.tool, Ammo, Projectile, ShootPosition, LocalPosition, Direction * ProjectileSpeed, ShotId, {drawDurationSeconds = 1, shotId = HttpService:GenerateGUID(false)}, workspace:GetServerTimeNow() - 0.045)
	                                        PredictionLib.trackShot(Ent.RootPart)
	                                        ExpectKnockback(Ent.RootPart, FlightTime, ShootPosition, ItemMeta.knockback)
	                                        if not Response then
	                                            FireDelays[Item.itemType] = tick()
	                                        else
	                                            local LaunchSound = ItemMeta.launchSound
	                                            LaunchSound = LaunchSound and LaunchSound[math.random(1, #LaunchSound)] or nil
	                                            if LaunchSound then
	                                                bedwars.AudioManager:playAudio(LaunchSound)
	                                            end
	                                        end
	                                    end)
	
	                                    FireDelays[Item.itemType] = tick() + ItemMeta.fireDelaySec
	                                    if Switched then
	                                        task.wait(FireRate:GetRandomValue())
	                                    end
	                                end
	                            end
	                        end
	                    end
	                end
	                task.wait(0.03)
	            until not ProjectileAura.Enabled
	        end
	    end,
	    Tooltip = "Shoots people around you"
	})
	
	Targets = ProjectileAura:CreateTargets({
	    Players = true,
	    Walls = true
	})
	Part = ProjectileAura:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head", "Torso", "Left arm", "Right arm", "Left leg", "Right leg", "Random", "Dynamic"},
	    Tooltip = "Dynamic aims at the head with headshot-capable bows, including tactical bows and Archer, and at the body with everything else"
	})
	List = ProjectileAura:CreateTextList({
	    Name = "Projectiles",
	    Default = {"arrow", "snowball"}
	})
	UseSophia = ProjectileAura:CreateToggle({
	    Name = "Use sophia",
	    Tooltip = "Also shoots sophia's frost staff, swapping it out of mist mode on its own"
	})
	UseWhim = ProjectileAura:CreateToggle({
	    Name = "Use whim",
	    Tooltip = "Also casts whim's magic book, follows whatever element you have cycled"
	})
	UseNazar = ProjectileAura:CreateToggle({
	    Name = "Use nazar",
	    Tooltip = "Also shoots nazar's life bow, crossbow and headhunter"
	})
	UseUmeko = ProjectileAura:CreateToggle({
	    Name = "Use umeko",
	    Tooltip = "Also throws umeko's chakram, waiting for it to come back between throws"
	})
	FireRate = ProjectileAura:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	AFKCheck = ProjectileAura:CreateToggle({
	    Name = "AFK check",
	    Tooltip = "Stops firing once you have not touched your mouse or keyboard for 30 seconds"
	})
	Range = ProjectileAura:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 50,
	    Default = 50,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local Speed
	local Mode
	local Value
	local WallCheck
	local AutoJump
	local AlwaysJump
	local Modifier = {}
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	local FilterCharacter: Model?
	
	Speed = vape.Categories.Blatant:CreateModule({
	    Name = "Speed",
	    Function = function(Callback: boolean)
	        local Blatant: boolean = Callback and Mode.Value == "Blatant"
	        FrictionTable.Speed = Blatant or nil
	        UpdateVelocity()
	        debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, Blatant and "constantSpeedMultiplier" or "moveSpeedMultiplier")
	        bedwars.StatefulEntityKnockbackController.lastImpulseTime = Blatant and math.huge or time()
	
	        if Callback then
	            if not Blatant then
	                Modifier.moveSpeedMultiplier = Value.Value / 20
	                local Handle = bedwars.SprintController:getMovementStatusModifier():addModifier(Modifier)
	                Speed:Clean(function()
	                    Handle:Destroy()
	                end)
	            end
	
	            Speed:Clean(RunService.PreSimulation:Connect(function(Delta: number)
	                if Blatant then
	                    bedwars.StatefulEntityKnockbackController.lastImpulseTime = math.huge
	                end
	                if Entity.isAlive and not Fly.Enabled and not LongJump.Enabled and (not Store.cannonFlight or Store.cannonFlight.Root ~= Entity.character.RootPart) and isnetworkowner(Entity.character.RootPart) then
	                    local State: Enum.HumanoidStateType = Entity.character.Humanoid:GetState()
	                    if State == Enum.HumanoidStateType.Climbing then
	                        return
	                    end
	
	                    local MoveDirection: Vector3 = AntiFallDirection or Entity.character.Humanoid.MoveDirection
	                    if Blatant then
	                        local Root, CurrentSpeed = Entity.character.RootPart, GetSpeed()
	                        local Destination: Vector3 = MoveDirection * math.max(Value.Value - CurrentSpeed, 0) * Delta
	                        if WallCheck.Enabled then
	                            if not LocalPlayer.Character or FilterCharacter ~= LocalPlayer.Character then
	                                FilterCharacter = LocalPlayer.Character
	                                RayCheck.FilterDescendantsInstances = {FilterCharacter, Camera}
	                            end
	                            RayCheck.CollisionGroup = Root.CollisionGroup
	                            local WallRay: RaycastResult? = workspace:Raycast(Root.Position, Destination, RayCheck)
	                            if WallRay then
	                                Destination = (WallRay.Position + WallRay.Normal) - Root.Position
	                            end
	                        end
	
	                        Root.CFrame += Destination
	                        Root.AssemblyLinearVelocity = (MoveDirection * CurrentSpeed) + Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
	                    end
	                    if AutoJump.Enabled and (State == Enum.HumanoidStateType.Running or State == Enum.HumanoidStateType.Landed) and MoveDirection ~= Vector3.zero and (Store.attacking or AlwaysJump.Enabled) then
	                        Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	                    end
	                end
	            end))
	        end
	    end,
	    ExtraText = function()
	        return Mode.Value
	    end,
	    Tooltip = "Increases your movement with various methods."
	})
	
	Mode = Speed:CreateDropdown({
	    Name = "Mode",
	    List = {"Blatant", "Legit"},
	    Function = function(Val: string)
	        if WallCheck then
	            WallCheck.Object.Visible = Val == "Blatant"
	        end
	        if Speed.Enabled then
	            Speed:Toggle()
	            Speed:Toggle()
	        end
	    end,
	    Default = "Blatant",
	    Tooltip = "Blatant - Heatseeker, moves your root forward every frame\nLegit - Raises your walkspeed through the games own speed system"
	})
	Value = Speed:CreateSlider({
	    Name = "Speed",
	    Function = function(Val: number)
	        if Speed.Enabled and Mode.Value == "Legit" then
	            Modifier.moveSpeedMultiplier = Val / 20
	            bedwars.SprintController:getMovementStatusModifier():updateModifiers()
	        end
	    end,
	    Min = 1,
	    Max = 23,
	    Default = 23,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	WallCheck = Speed:CreateToggle({
	    Name = "Wall Check",
	    Default = true
	})
	AutoJump = Speed:CreateToggle({
	    Name = "AutoJump",
	    Function = function(Callback: boolean)
	        AlwaysJump.Object.Visible = Callback
	    end
	})
	AlwaysJump = Speed:CreateToggle({
	    Name = "Always Jump",
	    Visible = false,
	    Darker = true
	})
end)

Run(function()
	local TerraAimbot
	local Targets
	local Sort
	local TargetPart
	local FOV
	local Horizontal
	local Vertical
	local Old: (...any) -> ...any
	local ArcCheck: RaycastParams = RaycastParams.new()
	ArcCheck.FilterType = Enum.RaycastFilterType.Exclude
	
	TerraAimbot = vape.Categories.Blatant:CreateModule({
	    Name = "TerraAimbot",
	    Function = function(Callback: boolean)
	        if Callback then
	            Old = bedwars.BlockKickerKitController.onAbilityUsed
	            bedwars.BlockKickerKitController.onAbilityUsed = function(self, Character, Data, ...)
	                if not Data or Data.ability ~= "BLOCK_KICK" or not Entity.isAlive then
	                    return Old(self, Character, Data, ...)
	                end
	
	                local Look: Vector3 = Camera.CFrame.LookVector
	                local Origin: Vector3 = self:getKickBlockProjectileOriginPosition(Entity.character.RootPart.Position, Look)
	                local PartName: string = TargetPart.Value
	                local Aim: Vector3?
	
	                local Ent = Entity.EntityMouse({
	                    Part = "RootPart",
	                    Range = FOV.Value,
	                    Players = Targets.Players.Enabled,
	                    NPCs = Targets.NPCs.Enabled,
	                    Priority = Targets.Priority.Value,
	                    Origin = Origin,
	                    MouseOrigin = Camera.ViewportSize / 2,
	                    Sort = SortMethods[Sort.Value],
	                    Check = function(Target)
	                        local AimPart: BasePart = GetTargetPart(Target, PartName)
	                        local Velocity: Vector3 = AimPart.AssemblyLinearVelocity
	                        local PlayerGravity: number = workspace.Gravity
	                        local Balloons: number? = Target.Character:GetAttribute("InflatedBalloons")
	                        if Balloons and Balloons > 0 then
	                            PlayerGravity = workspace.Gravity * (1 - (Balloons >= 4 and 1.2 or Balloons >= 3 and 1 or 0.975))
	                        end
	
	                        local Airborne: boolean = Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Target.RootPart.AssemblyLinearVelocity.Y) > 0.01
	                        local AimPosition, _, TravelTime = PredictionLib.SolveTrajectory(Origin, 100, 20, AimPart.Position, Velocity, PlayerGravity, Target.HipHeight, Target.Jumping and 42.6 or nil, Store.airRay, Airborne, Target.RootPart.Position, Target.RootPart, nil, true)
	                        if AimPosition and TravelTime and (Horizontal.Value ~= 1 or Vertical.Value ~= 1) then
	                            local Rise: number = (Velocity.Y * TravelTime) - (PlayerGravity * TravelTime * TravelTime * 0.5)
	                            local Lead: Vector3 = Vector3.new(Velocity.X * TravelTime * (Horizontal.Value - 1), Rise * (Vertical.Value - 1), Velocity.Z * TravelTime * (Horizontal.Value - 1))
	                            local AdjustedPosition, _, AdjustedTime = PredictionLib.SolveTrajectory(Origin, 100, 20, AimPart.Position + Lead, Velocity, PlayerGravity, Target.HipHeight, Target.Jumping and 42.6 or nil, Store.airRay, Airborne, Target.RootPart.Position, Target.RootPart, nil, true)
	                            if AdjustedPosition then
	                                AimPosition, TravelTime = AdjustedPosition, AdjustedTime or TravelTime
	                            end
	                        end
	                        if not AimPosition or (AimPosition - Origin).Magnitude <= 0 then
	                            return false
	                        end
	
	                        if Targets.Walls.Enabled and TravelTime then
	                            local IgnoreList: {Instance} = {Camera, LocalPlayer.Character}
	                            for _, v: any in Entity.List do
	                                if v.Character then
	                                    table.insert(IgnoreList, v.Character)
	                                end
	                            end
	                            ArcCheck.FilterDescendantsInstances = IgnoreList
	                            if not PredictionLib.IsTrajectoryClear(Origin, (AimPosition - Origin).Unit * 100, 20, TravelTime, ArcCheck) then
	                                return false
	                            end
	                        end
	
	                        Store.hitchance.TerraAimbot = {Value = GetHitChance(Target, TravelTime), Clock = tick()}
	                        Aim = (AimPosition - Origin).Unit
	                        return true
	                    end
	                })
	
	                if not Ent or not Aim then
	                    return Old(self, Character, Data, ...)
	                end
	
	                TargetInfo.Targets[Ent] = tick() + 1
	                if bedwars.CameraPerspectiveController:getCameraPerspective() == 1 then
	                    local Scale: number = ((0.7 * Aim.Y) + math.sqrt((0.49 * Aim.Y * Aim.Y) + 3.51)) / 2
	                    Aim = (Aim * Scale) - Vector3.new(0, 0.35, 0)
	                end
	
	                local OldCFrame: CFrame = Camera.CFrame
	                Camera.CFrame = CFrame.lookAt(OldCFrame.Position, OldCFrame.Position + Aim)
	                local Call = Old(self, Character, Data, ...)
	                Camera.CFrame = OldCFrame
	                return Call
	            end
	        else
	            bedwars.BlockKickerKitController.onAbilityUsed = Old
	        end
	    end,
	    Tooltip = "Silently aims Terra's block kick at the enemy"
	})
	
	Targets = TerraAimbot:CreateTargets({
	    Players = true,
	    Walls = true
	})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = TerraAimbot:CreateDropdown({
	    Name = "Target mode",
	    List = Methods
	})
	TargetPart = TerraAimbot:CreateDropdown({
	    Name = "Part",
	    List = {"RootPart", "Head", "Torso", "Left arm", "Right arm", "Left leg", "Right leg", "Random"}
	})
	FOV = TerraAimbot:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Default = 1000
	})
	Horizontal = TerraAimbot:CreateSlider({
	    Name = "Horizontal prediction",
	    Min = 0,
	    Max = 2,
	    Decimal = 100,
	    Default = 1,
	    Tooltip = "How much of the targets sideways movement to lead, 1 is the honest amount"
	})
	Vertical = TerraAimbot:CreateSlider({
	    Name = "Vertical prediction",
	    Min = 0,
	    Max = 2,
	    Decimal = 100,
	    Default = 1,
	    Tooltip = "How much of the targets rise and fall to lead, 1 is the honest amount"
	})
end)

Run(function()
	local TPDown
	local Delay
	local Touchdown
	local Return
	local ShowProgressbar
	local AirOnly
	
	local RayParams: RaycastParams = RaycastParams.new()
	RayParams.RespectCanCollide = true
	
	local Bar = nil
	
	local function RemoveBar()
	    if Bar then
	        Bar.Frame:Destroy()
	        Bar = nil
	    end
	end
	
	local function CreateBar()
	    RemoveBar()
	    Bar = CreateProgressBar()
	end
	
	local function HandledElsewhere(): boolean
	    for _, Name: string in {"Fly", "InfiniteJump"} do
	        local Module = vape.Modules[Name]
	        local Option = Module and Module.Options["TP Down"]
	        if Module and Module.Enabled and Option and Option.Enabled then
	            return true
	        end
	    end
	    return false
	end
	
	local function UpdateBar(AirTime: number, Airborne: boolean)
	    if not Bar then
	        return
	    end
	
	    Bar.Frame.Visible = TPDown.Enabled and Entity.isAlive and (Airborne or not AirOnly.Enabled)
	    Bar.Set(Delay.Value - AirTime, Delay.Value)
	end
	
	TPDown = vape.Categories.Blatant:CreateModule({
	    Name = "TPDown",
	    Function = function(Callback: boolean)
	        TPDown.PullIn = nil
	        if Callback then
	            local OldY: number? = nil
	            local ReturnTick: number = 0
	            local NextPull: number = 0
	
	            TPDown:Clean(RunService.PreSimulation:Connect(function()
	                if not Entity.isAlive or vape.MovementOwner or HandledElsewhere() then
	                    OldY = nil
	                    TPDown.PullIn = nil
	                    UpdateBar(0, false)
	                    return
	                end
	
	                local Root: BasePart = Entity.character.RootPart
	                local Airborne: boolean = Entity.character.Humanoid.FloorMaterial == Enum.Material.Air
	                local AirTime: number = Airborne and (tick() - (Entity.character.AirTime or tick())) or 0
	
	                if ReturnTick > tick() then
	                    Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 0, Root.AssemblyLinearVelocity.Z)
	                    UpdateBar(0, Airborne)
	                    return
	                end
	
	                if OldY then
	                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, OldY, Root.Position.Z), Root.CFrame.LookVector)
	                    Entity.character.AirTime = tick()
	                    OldY = nil
	                    UpdateBar(0, true)
	                    return
	                end
	
	                TPDown.PullIn = Airborne and (Delay.Value - AirTime) or nil
	                UpdateBar(AirTime, Airborne)
	
	                if Airborne and AirTime > Delay.Value and NextPull < tick() and isnetworkowner(Root) then
	                    RayParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera, AntiFallPart}
	                    RayParams.CollisionGroup = Root.CollisionGroup
	                    local Ground: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), RayParams)
	                    if Ground then
	                        OldY = Return.Enabled and Root.Position.Y or nil
	                        ReturnTick = tick() + Touchdown.Value
	                        NextPull = ReturnTick + 0.2
	                        Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, Ground.Position.Y + Entity.character.HipHeight, Root.Position.Z), Root.CFrame.LookVector)
	                        Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 0, Root.AssemblyLinearVelocity.Z)
	                    end
	                end
	            end))
	        else
	            UpdateBar(0, false)
	        end
	    end,
	    Tooltip = "Teleports you down to the ground for a moment after you have been in the air too long, then back up, so hovering does not get flagged. Stands down while Fly or InfiniteJump are using their own TP Down"
	})
	
	Delay = TPDown:CreateSlider({
	    Name = "Air Time",
	    Min = 0.5,
	    Max = 3,
	    Default = 1.7,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long you can stay in the air before it pulls you down"
	})
	Touchdown = TPDown:CreateSlider({
	    Name = "Touchdown",
	    Min = 0.05,
	    Max = 0.5,
	    Default = 0.11,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long you stay on the ground before going back up"
	})
	Return = TPDown:CreateToggle({
	    Name = "Return",
	    Default = true,
	    Tooltip = "Teleports you back up to the height you were pulled down from"
	})
	ShowProgressbar = TPDown:CreateToggle({
	    Name = "Show Progressbar",
	    Function = function(Callback: boolean)
	        if AirOnly then
	            AirOnly.Object.Visible = Callback
	        end
	
	        if Callback then
	            CreateBar()
	        else
	            RemoveBar()
	        end
	    end,
	    Tooltip = "Shows a bar counting down until you get pulled down"
	})
	AirOnly = TPDown:CreateToggle({
	    Name = "Air Only",
	    Darker = true,
	    Visible = false,
	    Tooltip = "Only shows the bar while you are in the air"
	})
	vape:Clean(RemoveBar)
end)

Run(function()
	local ArmorChanger
	local Trim
	local Color
	local Effect
	local Rank
	local AddedInstances: {Instance} = {}
	local Trims, Colors, Effects = {}, {}, {}
	local TrimValues, ColorValues, EffectValues = {}, {}, {}
	
	for _, v: string in bedwars.ArmorTrimType do
	    local Meta = bedwars.ArmorTrimMeta[v]
	    local Label: string = Meta and Meta.name or (tostring(v):gsub("_", " "):gsub("%a+", function(Word: string)
	        return `{Word:sub(1, 1):upper()}{Word:sub(2):lower()}`
	    end))
	    if TrimValues[Label] == nil then
	        TrimValues[Label] = v
	        table.insert(Trims, Label)
	    end
	end
	table.sort(Trims)
	
	for Name: string, v: string in bedwars.ArmorTrimColor do
	    local Label: string = (tostring(Name):gsub("_", " "):gsub("%a+", function(Word: string)
	        return `{Word:sub(1, 1):upper()}{Word:sub(2):lower()}`
	    end))
	    if ColorValues[Label] == nil then
	        ColorValues[Label] = v
	        table.insert(Colors, Label)
	    end
	end
	table.sort(Colors)
	
	for _, v: string in bedwars.ArmorTrimEffectType do
	    local Meta = bedwars.ArmorTrimEffectMeta[v]
	    local Label: string = Meta and Meta.name or (tostring(v):gsub("_", " "):gsub("%a+", function(Word: string)
	        return `{Word:sub(1, 1):upper()}{Word:sub(2):lower()}`
	    end))
	    if EffectValues[Label] == nil then
	        EffectValues[Label] = v
	        table.insert(Effects, Label)
	    end
	end
	table.sort(Effects)
	
	local SlotNames: {[number]: string} = {[0] = "helmet", [1] = "chestplate", [2] = "boots"}
	
	local function WornSlots()
	    local Worn: {[string]: boolean} = {}
	    for _, v: any in Store.inventory.inventory.armor or {} do
	        local ItemMeta = typeof(v) == "table" and bedwars.ItemMeta[v.itemType]
	        if ItemMeta and ItemMeta.armor and SlotNames[ItemMeta.armor.slot] then
	            Worn[SlotNames[ItemMeta.armor.slot]] = true
	        end
	    end
	    return Worn
	end
	
	local function ApplyTrim()
	    for _, v: Instance in AddedInstances do
	        if v.Parent then
	            v:Destroy()
	        end
	    end
	    table.clear(AddedInstances)
	    if not ArmorChanger.Enabled or not LocalPlayer.Character then return end
	
	    local TrimType = TrimValues[Trim.Value]
	    local TrimColor = ColorValues[Color.Value]
	    local EffectType = EffectValues[Effect.Value]
	    if not TrimType or not TrimColor or not EffectType then return end
	
	    local Before: {[Instance]: boolean} = {}
	    for _, v: Instance in LocalPlayer.Character:GetDescendants() do
	        Before[v] = true
	    end
	
	    bedwars.ArmorTrimController:attachArmorTrimEffects(LocalPlayer.Character, TrimType, TrimColor, Rank.Value - 1, EffectType)
	
	    local ColorMeta = bedwars.ArmorTrimColorMeta[TrimColor]
	    local Worn: {[string]: boolean} = WornSlots()
	    for _, v: Instance in bedwars.ArmorTrimUtil.createArmorTrims(TrimType, ColorMeta and ColorMeta.color or Color3.new(1, 1, 1), Rank.Value - 1) do
	        local Slot: string?
	        for Piece: string in Worn do
	            if table.find(v.Name:split("_"), Piece) then
	                Slot = Piece
	                break
	            end
	        end
	
	        if Slot then
	            bedwars.AccessoryUtil:addAccessory(LocalPlayer.Character, v)
	        else
	            v:Destroy()
	        end
	    end
	    bedwars.WeldTable:weldCharacterAccessories(LocalPlayer.Character)
	
	    for _, v: Instance in LocalPlayer.Character:GetDescendants() do
	        if not Before[v] then
	            table.insert(AddedInstances, v)
	        end
	    end
	end
	
	ArmorChanger = vape.Categories.Render:CreateModule({
	    Name = "ArmorChanger",
	    Function = function(Callback: boolean)
	        if Callback then
	            ArmorChanger:Clean(LocalPlayer.CharacterAdded:Connect(function()
	                task.wait(1)
	                ApplyTrim()
	            end))
	            ArmorChanger:Clean(function()
	                for _, v: Instance in AddedInstances do
	                    if v.Parent then
	                        v:Destroy()
	                    end
	                end
	                table.clear(AddedInstances)
	            end)
	        end
	        ApplyTrim()
	    end,
	    Tooltip = "Puts an armor trim on yourself, only you can see it"
	})
	
	Trim = ArmorChanger:CreateDropdown({
	    Name = "Trim",
	    List = Trims,
	    Function = function()
	        if ArmorChanger.Enabled then
	            ApplyTrim()
	        end
	    end
	})
	Color = ArmorChanger:CreateDropdown({
	    Name = "Color",
	    List = Colors,
	    Function = function()
	        if ArmorChanger.Enabled then
	            ApplyTrim()
	        end
	    end
	})
	Effect = ArmorChanger:CreateDropdown({
	    Name = "Effect",
	    List = Effects,
	    Function = function()
	        if ArmorChanger.Enabled then
	            ApplyTrim()
	        end
	    end
	})
	Rank = ArmorChanger:CreateSlider({
	    Name = "Tier",
	    Min = 1,
	    Max = 7,
	    Function = function()
	        if ArmorChanger.Enabled then
	            ApplyTrim()
	        end
	    end,
	    Default = 7,
	    Suffix = function(Val: number)
	        local Meta = bedwars.ArmorTrimEffectRankMeta[Val - 1]
	        return Meta and Meta.tier and (tostring(Meta.tier):gsub("_", " "):gsub("%a+", function(Word: string)
	            return `{Word:sub(1, 1):upper()}{Word:sub(2):lower()}`
	        end)) or ""
	    end,
	    Tooltip = "Higher tiers use the fancier version of the effect"
	})
end)

Run(function()
	local BedDefense
	local Target
	local MaxLayers
	local View
	local ShowBed
	local AutoRotate
	local RotateSpeed
	local Transparency
	local Holder, Viewport, ViewportCamera, Empty, ButtonRow, BedLabel
	local Layers, Buttons, Tracked = {}, {}, {}
	local TrackedCount, Detected = 0, 0
	local Current, Manual, BedClone
	local Accent
	local Yaw, Pitch, Radius, Center, Zoom = 0, math.rad(28), 12, Vector3.zero, 1
	local Dragging, LastDrag, Pending = nil, Vector3.zero, false
	local Touches, PinchDistance = {}, nil
	
	local function CloneModel(Object: Instance)
	    local Clone: Instance? = Object:Clone()
	    if not Clone then return end
	    for _, Tag: string in Clone:GetTags() do
	        Clone:RemoveTag(Tag)
	    end
	    for _, v: Instance in Clone:GetDescendants() do
	        for _, Tag: string in v:GetTags() do
	            v:RemoveTag(Tag)
	        end
	    end
	    return Clone
	end
	
	local function GetBeds()
	    local Beds: {Instance} = {}
	    local Team: string = tostring(LocalPlayer:GetAttribute("Team"))
	    for _, Bed: Instance in CollectionService:GetTagged("bed") do
	        if Bed:IsDescendantOf(workspace) and tostring(Bed:GetAttribute("TeamId")) ~= Team and not table.find(Beds, Bed) then
	            table.insert(Beds, Bed)
	        end
	    end
	    table.sort(Beds, function(A: Instance, B: Instance)
	        return (tonumber(A:GetAttribute("TeamId")) or 0) < (tonumber(B:GetAttribute("TeamId")) or 0)
	    end)
	    return Beds
	end
	
	local function GetBedName(Bed: Instance)
	    local TeamId: number? = tonumber(Bed:GetAttribute("TeamId"))
	    local Queue = bedwars.QueueMeta[Store.queueType]
	    local Team = Queue and TeamId and Queue.teams[TeamId]
	    return `{Team and Team.displayName or `Team {TeamId or "?"}`} Bed`
	end
	
	local function GetTargetBed()
	    local Beds: {Instance} = GetBeds()
	    if Target.Value == "Manual" then
	        return Manual and Manual.Parent and Manual or Beds[1]
	    end
	
	    local Origin: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Camera.CFrame.Position
	    local Best, BestScore
	    for _, Bed: BasePart in Beds do
	        local Score: number = Target.Value == "Crosshair" and -Camera.CFrame.LookVector:Dot((Bed.Position - Camera.CFrame.Position).Unit) or (Bed.Position - Origin).Magnitude
	        if not BestScore or Score < BestScore then
	            Best, BestScore = Bed, Score
	        end
	    end
	    return Best
	end
	
	local function ScanLayers(Bed: BasePart)
	    local Depth, Queue, BlockLayers = {}, {}, {}
	    for _, v: Vector3 in {RoundPosition(Bed.Position), RoundPosition(Bed.CFrame * Vector3.new(0, 0, 3))} do
	        Depth[v] = 0
	        table.insert(Queue, v)
	    end
	
	    local Head: number = 0
	    while Head < #Queue do
	        Head += 1
	        local Position: Vector3 = Queue[Head]
	        local Level: number = Depth[Position]
	        if Level >= MaxLayers.Value then continue end
	
	        for _, Side: Vector3 in Sides do
	            local NextPosition: Vector3 = Position + Side
	            if Depth[NextPosition] ~= nil then continue end
	            local Block: Instance? = GetPlacedBlock(NextPosition)
	            if Block and Block ~= Bed and Block.Name ~= "bed" and not Block:GetAttribute("NoBreak") then
	                Depth[NextPosition] = Level + 1
	                BlockLayers[Level + 1] = BlockLayers[Level + 1] or {}
	                table.insert(BlockLayers[Level + 1], Block)
	                table.insert(Queue, NextPosition)
	            else
	                Depth[NextPosition] = false
	            end
	        end
	    end
	
	    return BlockLayers
	end
	
	local function GetSelected()
	    local Index: number? = tonumber(View.Value:match("%d+"))
	    return Index and Index <= Detected and Index or nil
	end
	
	local function UpdateCamera()
	    local Distance: number = Radius / math.tan(math.rad(ViewportCamera.FieldOfView / 2)) * 1.15 * Zoom
	    ViewportCamera.CFrame = CFrame.new(Center) * CFrame.Angles(0, Yaw, 0) * CFrame.Angles(-Pitch, 0, 0) * CFrame.new(0, 0, Distance)
	end
	
	local function SetZoom(Value: number)
	    Zoom = math.clamp(Value, 0.35, 3)
	    UpdateCamera()
	end
	
	local function GetPinchDistance()
	    return (Touches[1].Position - Touches[2].Position).Magnitude
	end
	
	local function GetAccent()
	    return Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
	end
	
	local function UpdateButtons()
	    local Selected: number? = GetSelected()
	    Accent = GetAccent()
	    for Name: string, Button: TextButton in Buttons do
	        local Active: boolean = Selected and Name == `Layer {Selected}` or not Selected and Name == "All"
	        Button.BackgroundColor3 = Active and Accent or Color.Light(UIPallet.Main, 0.034)
	        Button.Label.TextColor3 = Active and UIPallet.Text or Color.Dark(UIPallet.Text, 0.16)
	    end
	end
	
	local function AddShadow(Label: TextLabel)
	    local Shadow: TextLabel = Label:Clone()
	    Shadow.Name = "Shadow"
	    Shadow.Position = Label.Position + UDim2.fromOffset(1, 1)
	    Shadow.TextColor3 = Color3.new()
	    Shadow.TextTransparency = 0.65
	    Shadow.ZIndex = Label.ZIndex - 1
	    Shadow.Parent = Label.Parent
	    Label:GetPropertyChangedSignal("Text"):Connect(function()
	        Shadow.Text = Label.Text
	    end)
	    Label:GetPropertyChangedSignal("Visible"):Connect(function()
	        Shadow.Visible = Label.Visible
	    end)
	end
	
	local function BuildButtons()
	    if not ButtonRow then return end
	    for _, Button: TextButton in Buttons do
	        Button:Destroy()
	    end
	    table.clear(Buttons)
	
	    local Names: {string} = {}
	    for i: number = 1, Detected do
	        table.insert(Names, `Layer {i}`)
	    end
	    table.insert(Names, "All")
	
	    for i: number, Name: string in Names do
	        local Button: TextButton = Instance.new("TextButton")
	        Button.Name = Name
	        Button.AutoButtonColor = false
	        Button.BorderSizePixel = 0
	        Button.LayoutOrder = i
	        Button.Size = UDim2.new(1 / #Names, -4, 1, 0)
	        Button.Text = ""
	        Button.Parent = ButtonRow
	        local Corner: UICorner = Instance.new("UICorner")
	        Corner.CornerRadius = UDim.new(0, 4)
	        Corner.Parent = Button
	        local Label: TextLabel = Instance.new("TextLabel")
	        Label.Name = "Label"
	        Label.BackgroundTransparency = 1
	        Label.FontFace = UIPallet.Font
	        Label.Size = UDim2.fromScale(1, 1)
	        Label.Text = Detected > 3 and Name ~= "All" and Name:match("%d+") or Name
	        Label.TextSize = 12
	        Label.ZIndex = 2
	        Label.Parent = Button
	        AddShadow(Label)
	        Button.MouseButton1Click:Connect(function()
	            View:SetValue(Name)
	        end)
	        Buttons[Name] = Button
	    end
	
	    UpdateButtons()
	end
	
	local function UpdateView()
	    if not Viewport then return end
	    local Selected: number? = GetSelected()
	    local Min, Max = Vector3.one * math.huge, Vector3.one * -math.huge
	    local Shown: number = 0
	
	    for i: number, Folder: Folder in Layers do
	        local Visible: boolean = not Selected or i == Selected
	        Folder.Parent = Visible and Viewport or nil
	        if Visible then
	            for _, Part: BasePart in Folder:QueryDescendants("BasePart") do
	                Min, Max = Min:Min(Part.Position - Part.Size / 2), Max:Max(Part.Position + Part.Size / 2)
	                Shown += 1
	            end
	        end
	    end
	
	    if BedClone then
	        BedClone.Parent = ShowBed.Enabled and Viewport or nil
	        Min, Max = Min:Min(Current.Position - Vector3.one * 3), Max:Max(Current.Position + Vector3.one * 3)
	    end
	
	    if Min.X ~= math.huge then
	        Center = (Min + Max) / 2
	        Radius = math.max((Max - Min).Magnitude / 2, 6)
	    end
	
	    local BedPart: Instance? = Current and Current:FindFirstChild("Bed")
	    BedLabel.Text = Current and GetBedName(Current) or "No bed"
	    BedLabel.TextColor3 = BedPart and BedPart.Color or Color.Dark(UIPallet.Text, 0.16)
	    Empty.Visible = not Current or Shown == 0
	    Empty.Text = not Current and "No bed found" or Selected and `Layer {Selected} is empty` or "No defense"
	    UpdateButtons()
	    UpdateCamera()
	end
	
	local function IsUnchanged(BlockLayers)
	    local Count: number = 0
	    for Level: number, List: {Instance} in BlockLayers do
	        for _, Block: Instance in List do
	            if Tracked[Block] ~= Level then return false end
	            Count += 1
	        end
	    end
	    return Count == TrackedCount
	end
	
	local function Rebuild(Bed: Instance?, BlockLayers)
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	    Pending = false
	
	    for _, Folder: Folder in Layers do
	        Folder:Destroy()
	    end
	    table.clear(Layers)
	    table.clear(Tracked)
	    TrackedCount = 0
	    if BedClone then
	        BedClone:Destroy()
	        BedClone = nil
	    end
	
	    Current = Bed or GetTargetBed()
	    BlockLayers = Current and (BlockLayers or ScanLayers(Current)) or {}
	    if Detected ~= #BlockLayers then
	        Detected = #BlockLayers
	        BuildButtons()
	    end
	    if Current then
	        for i: number = 1, Detected do
	            local Folder: Folder = Instance.new("Folder")
	            Folder.Name = `Layer{i}`
	            for _, Block: Instance in BlockLayers[i] or {} do
	                Tracked[Block] = i
	                TrackedCount += 1
	                local Clone: Instance? = CloneModel(Block)
	                if Clone then
	                    Clone.Parent = Folder
	                end
	            end
	            Layers[i] = Folder
	        end
	        BedClone = CloneModel(Current)
	    end
	
	    UpdateView()
	end
	
	local function CycleBed(Step: number)
	    local Beds: {Instance} = GetBeds()
	    if #Beds == 0 then return end
	
	    local Index: number = table.find(Beds, Current) or 0
	    Manual = Beds[((Index - 1 + Step) % #Beds) + 1]
	
	    if Target.Value ~= "Manual" then
	        Target:SetValue("Manual")
	    elseif BedDefense.Button.Enabled then
	        Rebuild()
	    end
	end
	
	local function RefreshNear(Data)
	    if not Current then return end
	
	    local Position = Data and Data.blockRef and Data.blockRef.blockPosition
	    if Position and ((Position * 3) - Current.Position).Magnitude <= 30 then
	        Pending = true
	    end
	end
	
	local function CreateArrow(Position: UDim2, Step: number)
	    local Button: TextButton = Instance.new("TextButton")
	    Button.AnchorPoint = Vector2.new(0.5, 0.5)
	    Button.AutoButtonColor = false
	    Button.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)
	    Button.BorderSizePixel = 0
	    Button.Name = Step < 0 and "Previous" or "Next"
	    Button.Position = Position
	    Button.Size = UDim2.fromOffset(22, 22)
	    Button.Text = ""
	    Button.Parent = Holder
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Button
	    local Arrow: ImageLabel = Instance.new("ImageLabel")
	    Arrow.AnchorPoint = Vector2.new(0.5, 0.5)
	    Arrow.BackgroundTransparency = 1
	    Arrow.Image = GetVapeAsset("GyuvapeBedwarsCheat/assets/new/expandright.png")
	    Arrow.ImageColor3 = Color.Dark(UIPallet.Text, 0.16)
	    Arrow.Position = UDim2.fromScale(0.5, 0.5)
	    Arrow.Rotation = Step < 0 and 180 or 0
	    Arrow.Size = UDim2.fromOffset(6, 12)
	    Arrow.Parent = Button
	    Button.MouseButton1Click:Connect(function()
	        CycleBed(Step)
	    end)
	    Button.MouseEnter:Connect(function()
	        Button.BackgroundColor3 = Color.Light(UIPallet.Main, 0.1)
	        Arrow.ImageColor3 = UIPallet.Text
	    end)
	    Button.MouseLeave:Connect(function()
	        Button.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)
	        Arrow.ImageColor3 = Color.Dark(UIPallet.Text, 0.16)
	    end)
	end
	
	BedDefense = vape:CreateOverlay({
	    Name = "Bed Defense",
	    Icon = GetVapeAsset("GyuvapeBedwarsCheat/assets/new/legit_bedalarm.png"),
	    Size = UDim2.fromOffset(16, 16),
	    Position = UDim2.fromOffset(12, 13),
	    CategorySize = 240,
	    Function = function(Callback: boolean)
	        if Callback then
	            BedDefense:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(RefreshNear))
	            BedDefense:Clean(VapeEvents.BreakBlockEvent.Event:Connect(RefreshNear))
	            BedDefense:Clean(UserInputService.InputChanged:Connect(function(Input: InputObject)
	                if PinchDistance and table.find(Touches, Input) then
	                    local Distance: number = GetPinchDistance()
	                    if Distance > 0 then
	                        SetZoom(Zoom * PinchDistance / Distance)
	                        PinchDistance = Distance
	                    end
	                    return
	                end
	                if not Dragging then return end
	                if Input == Dragging or Input.UserInputType == Enum.UserInputType.MouseMovement and Dragging.UserInputType == Enum.UserInputType.MouseButton1 then
	                    local Delta: Vector3 = Input.Position - LastDrag
	                    LastDrag = Input.Position
	                    Yaw -= Delta.X * 0.01
	                    Pitch = math.clamp(Pitch + Delta.Y * 0.01, math.rad(-80), math.rad(80))
	                    UpdateCamera()
	                end
	            end))
	            BedDefense:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
	                local Index: number? = table.find(Touches, Input)
	                if Index then
	                    table.remove(Touches, Index)
	                    PinchDistance = nil
	                end
	                if Dragging and (Input == Dragging or Input.UserInputType == Enum.UserInputType.MouseButton1) then
	                    Dragging = nil
	                end
	            end))
	            BedDefense:Clean(RunService.RenderStepped:Connect(function(DeltaTime: number)
	                if AutoRotate.Enabled and not Dragging and not PinchDistance and Holder.AbsoluteSize.X > 0 and BedDefense.Children.Parent.Visible then
	                    Yaw += DeltaTime * math.rad(RotateSpeed.Value)
	                    UpdateCamera()
	                end
	            end))
	
	            Rebuild()
	
	            local Checked: number = tick()
	            repeat
	                if GetAccent() ~= Accent then
	                    UpdateButtons()
	                end
	                local Bed: Instance? = GetTargetBed()
	                if Pending or Bed ~= Current then
	                    Rebuild(Bed)
	                elseif Bed and (tick() - Checked) > 0.5 then
	                    Checked = tick()
	                    local BlockLayers = ScanLayers(Bed)
	                    if not IsUnchanged(BlockLayers) then
	                        Rebuild(Bed, BlockLayers)
	                    end
	                end
	                task.wait(0.1)
	            until not BedDefense.Button.Enabled
	        else
	            Dragging, Pending, PinchDistance = nil, false, nil
	            table.clear(Touches)
	            for _, Folder: Folder in Layers do
	                Folder:Destroy()
	            end
	            table.clear(Layers)
	            if BedClone then
	                BedClone:Destroy()
	                BedClone = nil
	            end
	            Current = nil
	        end
	    end
	})
	
	local OldColor = BedDefense.Color
	function BedDefense:Color(Hue: number, Sat: number, Val: number, IsRainbow: boolean)
	    OldColor(self, Hue, Sat, Val, IsRainbow)
	    if Holder then
	        UpdateButtons()
	    end
	end
	
	Target = BedDefense:CreateDropdown({
	    Name = "Bed",
	    List = {"Nearest", "Crosshair", "Manual"},
	    Function = function()
	        if BedDefense.Button.Enabled then
	            Rebuild()
	        end
	    end,
	    Tooltip = "Nearest - The closest enemy bed\nCrosshair - The enemy bed closest to where you are looking\nManual - The enemy bed you pick with the arrows on the viewer"
	})
	View = BedDefense:CreateDropdown({
	    Name = "View",
	    List = {"All", "Layer 1", "Layer 2", "Layer 3", "Layer 4", "Layer 5", "Layer 6", "Layer 7", "Layer 8", "Layer 9", "Layer 10"},
	    Function = function()
	        UpdateView()
	    end,
	    Tooltip = "Which layer of the defense to show, the buttons under the viewer change this too"
	})
	MaxLayers = BedDefense:CreateSlider({
	    Name = "Max layers",
	    Min = 1,
	    Max = 10,
	    Default = 6,
	    Function = function()
	        if Holder and BedDefense.Button.Enabled then
	            Rebuild()
	        end
	    end,
	    Tooltip = "The most layers to scan out from the bed, the viewer shows a button for every layer it finds"
	})
	ShowBed = BedDefense:CreateToggle({
	    Name = "Show bed",
	    Function = function()
	        UpdateView()
	    end,
	    Default = true
	})
	AutoRotate = BedDefense:CreateToggle({
	    Name = "Auto rotate",
	    Function = function(Callback: boolean)
	        if RotateSpeed then
	            RotateSpeed.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	RotateSpeed = BedDefense:CreateSlider({
	    Name = "Rotate speed",
	    Min = 5,
	    Max = 90,
	    Default = 20,
	    Darker = true,
	    Suffix = "°/s"
	})
	Transparency = BedDefense:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Default = 0.5,
	    Decimal = 10,
	    Function = function(Val: number)
	        if Holder then
	            Holder.BackgroundTransparency = Val
	        end
	    end
	})
	
	Holder = Instance.new("Frame")
	Holder.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.1)
	Holder.BackgroundTransparency = Transparency.Value
	Holder.ClipsDescendants = true
	Holder.Size = UDim2.fromOffset(240, 246)
	Holder.Parent = BedDefense.Children
	AddBlur(Holder)
	local Corner: UICorner = Instance.new("UICorner")
	Corner.CornerRadius = UDim.new(0, 5)
	Corner.Parent = Holder
	
	BedLabel = Instance.new("TextLabel")
	BedLabel.BackgroundTransparency = 1
	BedLabel.FontFace = UIPallet.Font
	BedLabel.Position = UDim2.fromOffset(32, 0)
	BedLabel.Size = UDim2.new(1, -64, 0, 32)
	BedLabel.Text = "No bed"
	BedLabel.TextColor3 = Color.Dark(UIPallet.Text, 0.16)
	BedLabel.TextSize = 13
	BedLabel.TextTruncate = Enum.TextTruncate.AtEnd
	BedLabel.Parent = Holder
	AddShadow(BedLabel)
	
	CreateArrow(UDim2.fromOffset(16, 16), -1)
	CreateArrow(UDim2.new(1, -16, 0, 16), 1)
	
	local TopDivider: Frame = Instance.new("Frame")
	TopDivider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)
	TopDivider.BorderSizePixel = 0
	TopDivider.Position = UDim2.fromOffset(0, 32)
	TopDivider.Size = UDim2.new(1, 0, 0, 1)
	TopDivider.Parent = Holder
	
	Viewport = Instance.new("ViewportFrame")
	Viewport.Ambient = Color3.fromRGB(170, 170, 170)
	Viewport.BackgroundTransparency = 1
	Viewport.LightColor = Color3.new(1, 1, 1)
	Viewport.LightDirection = Vector3.new(-0.4, -1, -0.3)
	Viewport.Position = UDim2.fromOffset(0, 33)
	Viewport.Size = UDim2.new(1, 0, 0, 176)
	Viewport.Parent = Holder
	ViewportCamera = Instance.new("Camera")
	ViewportCamera.FieldOfView = 40
	ViewportCamera.Parent = Viewport
	Viewport.CurrentCamera = ViewportCamera
	
	local Capture: TextButton = Instance.new("TextButton")
	Capture.BackgroundTransparency = 1
	Capture.Position = Viewport.Position
	Capture.Size = Viewport.Size
	Capture.Text = ""
	Capture.Parent = Holder
	Capture.InputBegan:Connect(function(Input: InputObject)
	    if Input.UserInputType == Enum.UserInputType.Touch then
	        table.insert(Touches, Input)
	        if #Touches == 2 then
	            Dragging, PinchDistance = nil, GetPinchDistance()
	            return
	        end
	    end
	    if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
	        Dragging, LastDrag = Input, Input.Position
	    end
	end)
	Capture.InputChanged:Connect(function(Input: InputObject)
	    if Input.UserInputType == Enum.UserInputType.MouseWheel then
	        SetZoom(Zoom * (1 - Input.Position.Z * 0.12))
	    end
	end)
	
	Empty = Instance.new("TextLabel")
	Empty.BackgroundTransparency = 1
	Empty.FontFace = UIPallet.Font
	Empty.Position = UDim2.fromOffset(0, 186)
	Empty.Size = UDim2.new(1, 0, 0, 20)
	Empty.Text = "No bed found"
	Empty.TextColor3 = Color.Dark(UIPallet.Text, 0.16)
	Empty.TextSize = 12
	Empty.ZIndex = 2
	Empty.Parent = Holder
	AddShadow(Empty)
	
	local BottomDivider: Frame = TopDivider:Clone()
	BottomDivider.Position = UDim2.fromOffset(0, 209)
	BottomDivider.Parent = Holder
	
	ButtonRow = Instance.new("Frame")
	ButtonRow.BackgroundTransparency = 1
	ButtonRow.Position = UDim2.fromOffset(4, 214)
	ButtonRow.Size = UDim2.new(1, -8, 0, 26)
	ButtonRow.Parent = Holder
	local Layout: UIListLayout = Instance.new("UIListLayout")
	Layout.FillDirection = Enum.FillDirection.Horizontal
	Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	Layout.Padding = UDim.new(0, 4)
	Layout.SortOrder = Enum.SortOrder.LayoutOrder
	Layout.Parent = ButtonRow
	BuildButtons()
end)

Run(function()
	local BedESP
	local Method
	local Color
	local TeamColor
	local BoundingBox
	local Filled
	local HealthBar
	local Name
	local Background
	local HideOwn
	local Distance
	local DistanceLimit
	local Reference = {}
	local BedData = {}
	local Shown: {[Instance]: boolean} = {}
	local MethodUsed: string
	
	local CornerSigns: {Vector3} = {
	    Vector3.new(1, 1, 1),
	    Vector3.new(1, -1, 1),
	    Vector3.new(-1, 1, 1),
	    Vector3.new(-1, -1, 1),
	    Vector3.new(1, 1, -1),
	    Vector3.new(1, -1, -1),
	    Vector3.new(-1, 1, -1),
	    Vector3.new(-1, -1, -1)
	}
	
	local function ESPWorldToViewport(Position: Vector3): Vector2
	    local ViewportPoint: Vector3 = Camera:WorldToViewportPoint(Position)
	    return Vector2.new(ViewportPoint.X, ViewportPoint.Y)
	end
	
	local function GetBedColor(Bed: Instance)
	    local Part: Instance? = Bed:FindFirstChild("Bed")
	    return TeamColor.Enabled and Part and Part.Color or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	end
	
	local function GetBedName(Bed: Instance)
	    local TeamId: number? = tonumber(Bed:GetAttribute("TeamId"))
	    local Queue = bedwars.QueueMeta[Store.queueType]
	    local Team = Queue and TeamId and Queue.teams[TeamId]
	    return `{Team and Team.displayName or `Team {TeamId or "?"}`} Bed`
	end
	
	local function GetBedData(Bed: BasePart)
	    local Origin: CFrame = Bed.CFrame
	    local Min, Max = Vector3.one * math.huge, Vector3.one * -math.huge
	    for _, v: Instance in Bed:GetChildren() do
	        if v:IsA("BasePart") and v.Name ~= "Blanket" then
	            local PartCFrame, HalfSize = Origin:ToObjectSpace(v.CFrame), v.Size / 2
	            if v.Name == "Legs" then
	                PartCFrame, HalfSize = PartCFrame * CFrame.new(0, -0.4, 0), HalfSize - Vector3.new(0, 0.5, 0)
	            end
	            for _, Sign: Vector3 in CornerSigns do
	                local Position: Vector3 = PartCFrame * (HalfSize * Sign)
	                Min, Max = Min:Min(Position), Max:Max(Position)
	            end
	        end
	    end
	    if Min.X == math.huge then
	        Min, Max = -Bed.Size / 2, Bed.Size / 2
	    end
	
	    local Center, Extents = (Min + Max) / 2, (Max - Min) / 2
	    local Corners: {Vector3} = {}
	    for i: number, Sign: Vector3 in CornerSigns do
	        Corners[i] = Origin * (Center + Extents * Sign)
	    end
	
	    return {
	        Center = Origin * Center,
	        Corners = Corners,
	        TeamId = tonumber(Bed:GetAttribute("TeamId")),
	        BlockPosition = bedwars.BlockController:getBlockPosition(Bed.Position)
	    }
	end
	
	local function GetBedHealth(Bed: BasePart, Data)
	    local BlockData = bedwars.BlockController:getStore():getBlockData(Data.BlockPosition)
	    local Health: number = BlockData and (BlockData:GetAttribute("1") or BlockData:GetAttribute("Health")) or Bed:GetAttribute("Health") or 1
	    return math.clamp(Health / (Bed:GetAttribute("MaxHealth") or 1), 0, 1)
	end
	
	local function IsHidden(Bed: Instance, Data, LocalPosition: Vector3?, LocalTeam: number?)
	    if HideOwn.Enabled and Data.TeamId == LocalTeam then return true end
	    if Distance.Enabled then
	        local BedDistance: number = LocalPosition and (LocalPosition - Data.Center).Magnitude or math.huge
	        return BedDistance < DistanceLimit.ValueMin or BedDistance > DistanceLimit.ValueMax
	    end
	    return false
	end
	
	local ESPAdded = {
	    Drawing2D = function(Bed: Instance)
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	        local BedDrawings = {}
	        BedDrawings.Main = Drawing.new("Square")
	        BedDrawings.Main.Transparency = BoundingBox.Enabled and 1 or 0
	        BedDrawings.Main.ZIndex = 2
	        BedDrawings.Main.Filled = false
	        BedDrawings.Main.Thickness = 1
	        BedDrawings.Main.Color = GetBedColor(Bed)
	
	        if BoundingBox.Enabled then
	            BedDrawings.Border = Drawing.new("Square")
	            BedDrawings.Border.Transparency = 0.35
	            BedDrawings.Border.ZIndex = 1
	            BedDrawings.Border.Thickness = 1
	            BedDrawings.Border.Filled = false
	            BedDrawings.Border.Color = Color3.new()
	            BedDrawings.Border2 = Drawing.new("Square")
	            BedDrawings.Border2.Transparency = 0.35
	            BedDrawings.Border2.ZIndex = 1
	            BedDrawings.Border2.Thickness = 1
	            BedDrawings.Border2.Filled = Filled.Enabled
	            BedDrawings.Border2.Color = Color3.new()
	        end
	
	        if HealthBar.Enabled then
	            BedDrawings.HealthLine = Drawing.new("Line")
	            BedDrawings.HealthLine.Thickness = 1
	            BedDrawings.HealthLine.ZIndex = 2
	            BedDrawings.HealthBorder = Drawing.new("Line")
	            BedDrawings.HealthBorder.Thickness = 3
	            BedDrawings.HealthBorder.Transparency = 0.35
	            BedDrawings.HealthBorder.ZIndex = 1
	            BedDrawings.HealthBorder.Color = Color3.new()
	        end
	
	        if Name.Enabled then
	            if Background.Enabled then
	                BedDrawings.TextBKG = Drawing.new("Square")
	                BedDrawings.TextBKG.Transparency = 0.35
	                BedDrawings.TextBKG.ZIndex = 0
	                BedDrawings.TextBKG.Thickness = 1
	                BedDrawings.TextBKG.Filled = true
	                BedDrawings.TextBKG.Color = Color3.new()
	            end
	            BedDrawings.Drop = Drawing.new("Text")
	            BedDrawings.Drop.Color = Color3.new()
	            BedDrawings.Drop.Text = GetBedName(Bed)
	            BedDrawings.Drop.ZIndex = 1
	            BedDrawings.Drop.Center = true
	            BedDrawings.Drop.Size = 20
	            BedDrawings.Text = Drawing.new("Text")
	            BedDrawings.Text.Text = BedDrawings.Drop.Text
	            BedDrawings.Text.ZIndex = 2
	            BedDrawings.Text.Color = BedDrawings.Main.Color
	            BedDrawings.Text.Center = true
	            BedDrawings.Text.Size = 20
	        end
	        Reference[Bed] = BedDrawings
	    end,
	    Drawing3D = function(Bed: Instance)
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	        local BedDrawings = {}
	        for i: number = 1, 12 do
	            BedDrawings[`Line{i}`] = Drawing.new("Line")
	        end
	
	        local BedColor: Color3 = GetBedColor(Bed)
	        for _, v: any in BedDrawings do
	            v.Thickness = 1
	            v.Color = BedColor
	        end
	
	        Reference[Bed] = BedDrawings
	    end
	}
	
	local function ESPRemoved(Bed: Instance)
	    local BedDrawings = Reference[Bed]
	    if BedDrawings then
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	        Reference[Bed] = nil
	        BedData[Bed] = nil
	        Shown[Bed] = nil
	        for _, v: any in BedDrawings do
	            pcall(function()
	                v.Visible = false
	                v:Remove()
	            end)
	        end
	    end
	end
	
	local ColorFunc = {
	    Drawing2D = function()
	        for Bed: Instance, v: any in Reference do
	            v.Main.Color = GetBedColor(Bed)
	            if v.Text then
	                v.Text.Color = v.Main.Color
	            end
	        end
	    end,
	    Drawing3D = function()
	        for Bed: Instance, v: any in Reference do
	            local BedColor: Color3 = GetBedColor(Bed)
	            for _, Line: any in v do
	                Line.Color = BedColor
	            end
	        end
	    end
	}
	
	local ESPLoop = {
	    Drawing2D = function()
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	
	        local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
	        local LocalTeam: number? = tonumber(LocalPlayer:GetAttribute("Team"))
	
	        for Bed: Instance, v: any in Reference do
	            local Data = BedData[Bed]
	            local _, RootVisible = Camera:WorldToViewportPoint(Data.Center)
	            RootVisible = RootVisible and not IsHidden(Bed, Data, LocalPosition, LocalTeam)
	            if Shown[Bed] ~= RootVisible then
	                Shown[Bed] = RootVisible
	                for _, Object: any in v do
	                    Object.Visible = RootVisible
	                end
	            end
	            if not RootVisible then continue end
	
	            local MinX, MinY, MaxX, MaxY = math.huge, math.huge, -math.huge, -math.huge
	            for _, Corner: Vector3 in Data.Corners do
	                local Position: Vector3 = Camera:WorldToViewportPoint(Corner)
	                MinX, MinY = math.min(MinX, Position.X), math.min(MinY, Position.Y)
	                MaxX, MaxY = math.max(MaxX, Position.X), math.max(MaxY, Position.Y)
	            end
	            local PosX, PosY, SizeX, SizeY = MinX, MinY, MaxX - MinX, MaxY - MinY
	            v.Main.Position = Vector2.new(PosX, PosY) // 1
	            v.Main.Size = Vector2.new(SizeX, SizeY) // 1
	            if v.Border then
	                v.Border.Position = Vector2.new(PosX - 1, PosY - 1) // 1
	                v.Border.Size = Vector2.new(SizeX + 2, SizeY + 2) // 1
	                v.Border2.Position = Vector2.new(PosX + 1, PosY + 1) // 1
	                v.Border2.Size = Vector2.new(SizeX - 2, SizeY - 2) // 1
	            end
	
	            if v.HealthLine then
	                local Health: number = GetBedHealth(Bed, Data)
	                v.HealthLine.Color = Color3.fromHSV(Health / 2.5, 0.89, 0.75)
	                v.HealthLine.From = Vector2.new(PosX - 6, PosY + SizeY) // 1
	                v.HealthLine.To = Vector2.new(PosX - 6, PosY + SizeY - (SizeY * Health)) // 1
	                v.HealthBorder.From = Vector2.new(PosX - 6, PosY + SizeY + 1) // 1
	                v.HealthBorder.To = Vector2.new(PosX - 6, PosY - 1) // 1
	            end
	
	            if v.Text then
	                local TextPosition: Vector2 = Vector2.new(PosX + (SizeX / 2), PosY - 28) // 1
	                v.Text.Position = TextPosition
	                v.Drop.Position = TextPosition + Vector2.new(1, 1)
	                if v.TextBKG then
	                    local TextBounds: Vector2 = v.Text.TextBounds
	                    v.TextBKG.Size = TextBounds + Vector2.new(8, 4)
	                    v.TextBKG.Position = TextPosition - Vector2.new(4 + (TextBounds.X / 2), 0)
	                end
	            end
	        end
	    end,
	    Drawing3D = function()
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	
	        local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
	        local LocalTeam: number? = tonumber(LocalPlayer:GetAttribute("Team"))
	
	        for Bed: Instance, v: any in Reference do
	            local Data = BedData[Bed]
	            local _, RootVisible = Camera:WorldToViewportPoint(Data.Center)
	            RootVisible = RootVisible and not IsHidden(Bed, Data, LocalPosition, LocalTeam)
	            if Shown[Bed] ~= RootVisible then
	                Shown[Bed] = RootVisible
	                for _, Object: any in v do
	                    Object.Visible = RootVisible
	                end
	            end
	            if not RootVisible then continue end
	
	            local Corners: {Vector3} = Data.Corners
	            local Point1: Vector2 = ESPWorldToViewport(Corners[1])
	            local Point2: Vector2 = ESPWorldToViewport(Corners[2])
	            local Point3: Vector2 = ESPWorldToViewport(Corners[3])
	            local Point4: Vector2 = ESPWorldToViewport(Corners[4])
	            local Point5: Vector2 = ESPWorldToViewport(Corners[5])
	            local Point6: Vector2 = ESPWorldToViewport(Corners[6])
	            local Point7: Vector2 = ESPWorldToViewport(Corners[7])
	            local Point8: Vector2 = ESPWorldToViewport(Corners[8])
	            v.Line1.From = Point1
	            v.Line1.To = Point2
	            v.Line2.From = Point3
	            v.Line2.To = Point4
	            v.Line3.From = Point5
	            v.Line3.To = Point6
	            v.Line4.From = Point7
	            v.Line4.To = Point8
	            v.Line5.From = Point1
	            v.Line5.To = Point3
	            v.Line6.From = Point1
	            v.Line6.To = Point5
	            v.Line7.From = Point5
	            v.Line7.To = Point7
	            v.Line8.From = Point7
	            v.Line8.To = Point3
	            v.Line9.From = Point2
	            v.Line9.To = Point4
	            v.Line10.From = Point2
	            v.Line10.To = Point6
	            v.Line11.From = Point6
	            v.Line11.To = Point8
	            v.Line12.From = Point8
	            v.Line12.To = Point4
	        end
	    end
	}
	
	local function Added(Bed: Instance)
	    if not BedESP.Enabled or not Bed.Parent then return end
	    if Reference[Bed] then
	        ESPRemoved(Bed)
	    end
	    BedData[Bed] = GetBedData(Bed)
	    ESPAdded[MethodUsed](Bed)
	end
	
	local function Refresh()
	    if BedESP.Enabled then
	        BedESP:Toggle()
	        BedESP:Toggle()
	    end
	end
	
	BedESP = vape.Categories.Render:CreateModule({
	    Name = "BedESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            MethodUsed = `Drawing{Method.Value}`
	            BedESP:Clean(CollectionService:GetInstanceAddedSignal("bed"):Connect(function(Bed: Instance)
	                task.delay(0.2, Added, Bed)
	            end))
	            BedESP:Clean(CollectionService:GetInstanceRemovedSignal("bed"):Connect(ESPRemoved))
	            BedESP:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
	                ColorFunc[MethodUsed]()
	            end))
	            BedESP:Clean(RunService.RenderStepped:Connect(ESPLoop[MethodUsed]))
	            for _, v: Instance in CollectionService:GetTagged("bed") do
	                Added(v)
	            end
	        else
	            for Bed: Instance in Reference do
	                ESPRemoved(Bed)
	            end
	        end
	    end,
	    Tooltip = "Render Beds through walls"
	})
	
	Method = BedESP:CreateDropdown({
	    Name = "Mode",
	    List = {"2D", "3D"},
	    Function = function(Val: string)
	        Refresh()
	        BoundingBox.Object.Visible = (Val == "2D")
	        Filled.Object.Visible = (Val == "2D")
	        HealthBar.Object.Visible = (Val == "2D")
	        Name.Object.Visible = (Val == "2D")
	        Background.Object.Visible = Name.Object.Visible and Name.Enabled
	    end
	})
	Color = BedESP:CreateColorSlider({
	    Name = "Bed Color",
	    Function = function()
	        if BedESP.Enabled and ColorFunc[MethodUsed] then
	            ColorFunc[MethodUsed]()
	        end
	    end
	})
	TeamColor = BedESP:CreateToggle({
	    Name = "Use Team Color",
	    Function = function()
	        if BedESP.Enabled and ColorFunc[MethodUsed] then
	            ColorFunc[MethodUsed]()
	        end
	    end,
	    Default = true,
	    Darker = true
	})
	BoundingBox = BedESP:CreateToggle({
	    Name = "Bounding Box",
	    Function = Refresh,
	    Default = true,
	    Darker = true
	})
	Filled = BedESP:CreateToggle({
	    Name = "Filled",
	    Function = Refresh,
	    Darker = true
	})
	HealthBar = BedESP:CreateToggle({
	    Name = "Health Bar",
	    Function = Refresh,
	    Darker = true
	})
	Name = BedESP:CreateToggle({
	    Name = "Name",
	    Function = function(Callback: boolean)
	        Refresh()
	        Background.Object.Visible = Callback
	    end,
	    Darker = true
	})
	Background = BedESP:CreateToggle({
	    Name = "Show Background",
	    Function = Refresh,
	    Darker = true
	})
	HideOwn = BedESP:CreateToggle({
	    Name = "Hide Own Bed",
	    Default = true,
	    Tooltip = "Hides your own team's bed"
	})
	Distance = BedESP:CreateToggle({
	    Name = "Distance Check",
	    Function = function(Callback: boolean)
	        DistanceLimit.Object.Visible = Callback
	    end
	})
	DistanceLimit = BedESP:CreateTwoSlider({
	    Name = "Bed Distance",
	    Min = 0,
	    Max = 512,
	    DefaultMin = 0,
	    DefaultMax = 256,
	    Darker = true,
	    Visible = false
	})
end)

Run(function()
	local HiveESP
	local Color
	local Transparency
	local Scale
	local Reference = {}
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local function Added(Ent: Instance)
	    local UserId: number? = Ent:GetAttribute("PlacedByUserId")
	    local Placer: Player? = UserId and Players:GetPlayerByUserId(UserId)
	    local Name: string? = Placer and Placer.Name
	    if not Name and UserId then
	        local Success, Response = pcall(Players.GetNameFromUserIdAsync, Players, UserId)
	        Name = Success and Response or nil
	    end
	
	    local Level: number = Ent:GetAttribute("Level") or 0
	    local NameTag: TextLabel = Instance.new("TextLabel")
	    NameTag.Name = Name or "Unknown"
	    NameTag.Text = `{NameTag.Name}'s beehive | {Level} Bee{Level >= 2 and "s" or ""}`
	    NameTag.TextSize = 14 * Scale.Value
	    NameTag.Font = Enum.Font.Arial
	    local Size: Vector2 = GetFontBounds(RemoveTags(NameTag.Text), NameTag.TextSize, NameTag.FontFace)
	    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	    NameTag.AnchorPoint = Vector2.new(0.5, 1)
	    NameTag.BackgroundColor3 = Color3.new()
	    NameTag.BackgroundTransparency = Transparency.Value
	    NameTag.BorderSizePixel = 0
	    NameTag.Visible = false
	    NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    NameTag.RichText = true
	    NameTag.Parent = Folder
	    Reference[Ent] = NameTag
	end
	
	HiveESP = vape.Categories.Render:CreateModule({
	    Name = "BeehiveESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, v: Instance in CollectionService:GetTagged("beehive") do
	                Added(v)
	            end
	            HiveESP:Clean(CollectionService:GetInstanceAddedSignal("beehive"):Connect(Added))
	            HiveESP:Clean(CollectionService:GetInstanceRemovedSignal("beehive"):Connect(function(Ent: Instance)
	                if Reference[Ent] then
	                    Reference[Ent]:Destroy()
	                    Reference[Ent] = nil
	                end
	            end))
	            HiveESP:Clean(RunService.PreRender:Connect(function()
	                for Hive: BasePart, v: TextLabel in Reference do
	                    if not Hive.Parent then
	                        v:Destroy()
	                        Reference[Hive] = nil
	                        continue
	                    end
	
	                    local ScreenPos, Visible = Camera:WorldToViewportPoint(Hive.Position + Vector3.new(0, 1, 0))
	                    v.Visible = Visible
	                    if not Visible then continue end
	
	                    local Level: number = Hive:GetAttribute("Level") or 0
	                    local Text: string = `{v.Name}'s beehive | {Level} Bee{Level >= 2 and "s" or ""}`
	                    if v.Text ~= Text then
	                        v.Text = Text
	                        local Size: Vector2 = GetFontBounds(RemoveTags(Text), v.TextSize, v.FontFace)
	                        v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	                    end
	                    v.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)
	                end
	            end))
	        else
	            for Hive: Instance, v: TextLabel in Reference do
	                v:Destroy()
	                Reference[Hive] = nil
	            end
	        end
	    end,
	    Tooltip = "Renders hives locations and info"
	})
	
	Color = HiveESP:CreateColorSlider({
	    Name = "Text Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        if not HiveESP.Enabled then return end
	        for _, v: TextLabel in Reference do
	            v.TextColor3 = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end
	})
	Transparency = HiveESP:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Function = function(Value: number)
	        if not HiveESP.Enabled then return end
	        for _, v: TextLabel in Reference do
	            v.BackgroundTransparency = Value
	        end
	    end,
	    Default = 0.5
	})
	Scale = HiveESP:CreateSlider({
	    Name = "Scale",
	    Min = 0.1,
	    Max = 1.5,
	    Decimal = 10,
	    Function = function(Value: number)
	        if not HiveESP.Enabled then return end
	        for _, v: TextLabel in Reference do
	            v.TextSize = 14 * Value
	            local Size: Vector2 = GetFontBounds(RemoveTags(v.Text), v.TextSize, v.FontFace)
	            v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	        end
	    end,
	    Default = 1
	})
end)

Run(function()
	local Clouds
	local Scale
	local CloudColor
	local Folder, FolderConnection
	local Reference = setmetatable({}, {__mode = "k"})
	
	local function ApplyAll()
	    if not Clouds.Enabled or not Folder then return end
	    for _, v: Instance in Folder:GetChildren() do
	        if v:IsA("BasePart") then
	            if not Reference[v] then
	                Reference[v] = {v.Size, v.Color, v.Transparency}
	            end
	            v.Size = Reference[v][1] * (Scale.Value / 100)
	            v.Color = Color3.fromHSV(CloudColor.Hue, CloudColor.Sat, CloudColor.Value)
	            v.Transparency = 1 - CloudColor.Opacity
	        end
	    end
	end
	
	local function BindFolder(New: Instance?)
	    if FolderConnection then
	        FolderConnection:Disconnect()
	        FolderConnection = nil
	    end
	
	    Folder = New
	    if not Folder then return end
	
	    FolderConnection = Folder.ChildAdded:Connect(function(Part: Instance)
	        task.defer(function()
	            if not Clouds.Enabled or not Part:IsA("BasePart") then return end
	            if not Reference[Part] then
	                Reference[Part] = {Part.Size, Part.Color, Part.Transparency}
	            end
	            Part.Size = Reference[Part][1] * (Scale.Value / 100)
	            Part.Color = Color3.fromHSV(CloudColor.Hue, CloudColor.Sat, CloudColor.Value)
	            Part.Transparency = 1 - CloudColor.Opacity
	        end)
	    end)
	    ApplyAll()
	end
	
	Clouds = vape.Categories.Render:CreateModule({
	    Name = "Clouds",
	    Function = function(Callback: boolean)
	        if Callback then
	            Clouds:Clean(workspace.ChildAdded:Connect(function(Child: Instance)
	                if Child.Name == "Clouds" then
	                    BindFolder(Child)
	                end
	            end))
	            BindFolder(workspace:FindFirstChild("Clouds"))
	        else
	            BindFolder(nil)
	            for Part: BasePart, v: {any} in Reference do
	                if Part.Parent then
	                    Part.Size = v[1]
	                    Part.Color = v[2]
	                    Part.Transparency = v[3]
	                end
	            end
	            table.clear(Reference)
	        end
	    end,
	    Tooltip = "Restyles the clouds around the map"
	})
	
	Scale = Clouds:CreateSlider({
	    Name = "Size",
	    Min = 5,
	    Max = 300,
	    Function = ApplyAll,
	    Default = 100,
	    Suffix = function()
	        return "%"
	    end
	})
	CloudColor = Clouds:CreateColorSlider({
	    Name = "Color",
	    DefaultSat = 0,
	    Darker = true,
	    Function = ApplyAll
	})
end)

