Run(function()
	local FPSBooster
	local Cosmetics
	local Accessories
	local Animations
	local Clouds
	local Quality
	local Shadows
	local Lights
	local Post
	local Water
	local Reflections
	local Compatibility
	local Kill
	local Visualizer
	local Particles
	local Explosions
	local Nametags
	local Hidden: {[Instance]: Instance} = {}
	local Watching: {[Instance]: RBXScriptConnection} = setmetatable({}, {__mode = "k"})
	local Saved: {[Instance]: {[string]: any}} = {}
	local Effects = {}
	local KillEffects, Visualizers = {}, {}
	local WaterOld
	local QualityOld
	local TechnologyOld
	local NametagOld
	local PostHook: RBXScriptConnection?
	local Generation: number = 0
	local ParticleClasses: {string} = {"ParticleEmitter", "Trail", "Beam", "Smoke", "Fire", "Sparkles"}
	
	local function Override(Object: Instance, Property: string, Value: any)
	    local Properties: {[string]: any} = Saved[Object] or {}
	    Saved[Object] = Properties
	
	    if Properties[Property] == nil then
	        Properties[Property] = Object[Property]
	    end
	    Object[Property] = Value
	end
	
	local function Pin(Object: Instance, Property: string, Value: any)
	    Override(Object, Property, Value)
	    FPSBooster:Clean(Object:GetPropertyChangedSignal(Property):Connect(function()
	        if Object[Property] ~= Value then
	            Saved[Object][Property] = Object[Property]
	            Object[Property] = Value
	        end
	    end))
	end
	
	local function SilenceParticle(Object: Instance)
	    if not table.find(ParticleClasses, Object.ClassName) or Object.Parent and Object.Parent.Name == "ProjectileTargeting" then return end
	    Override(Object, "Enabled", false)
	end
	
	local function Scan(Object: Instance)
	    if Particles.Enabled then
	        SilenceParticle(Object)
	    end
	
	    if Lights.Enabled and Object:IsA("Light") then
	        Override(Object, "Enabled", false)
	    elseif Reflections.Enabled and Object:IsA("BasePart") and Object.Reflectance > 0 then
	        Override(Object, "Reflectance", 0)
	    elseif Explosions.Enabled and Object:IsA("Explosion") then
	        Override(Object, "Visible", false)
	    end
	end
	
	local function Sweep(Current: number)
	    local Clock: number = os.clock()
	    local Stack: {Instance} = {workspace}
	
	    while #Stack > 0 do
	        local Container: Instance = table.remove(Stack)
	        for _, v: Instance in Container:GetChildren() do
	            Scan(v)
	            table.insert(Stack, v)
	
	            if os.clock() - Clock > 0.002 then
	                task.wait()
	                if Generation ~= Current then return end
	                Clock = os.clock()
	            end
	        end
	    end
	end
	
	local function StripEffect(Effect: Instance)
	    if Effects[Effect] ~= nil then return end
	    for _, v: Instance in vape.BlurEffects or {} do
	        if v == Effect then return end
	    end
	
	    if Effect:IsA("PostEffect") then
	        Effects[Effect] = Effect.Enabled
	        Effect.Enabled = false
	    elseif Effect:IsA("Atmosphere") then
	        Effects[Effect] = Effect.Density
	        Effect.Density = 0
	    end
	end
	
	local function SetSpeed(Speed: number)
	    for _, v: any in Entity.List do
	        if v.Player ~= LocalPlayer then
	            local Humanoid: Humanoid? = v.Character:FindFirstChildWhichIsA("Humanoid")
	            local Animator: Animator? = Humanoid and Humanoid:FindFirstChildWhichIsA("Animator")
	            for _, Track: AnimationTrack in Animator and Animator:GetPlayingAnimationTracks() or {} do
	                Track:AdjustSpeed(Speed)
	            end
	        end
	    end
	end
	
	local function IsAvatarAccessory(Object: Instance): boolean
	    return Object:IsA("Accessory") and not bedwars.ItemMeta[Object.Name] and not Object:GetAttribute("ArmorSlot") and not Object:GetAttribute("IsBackpack") and not Object:GetAttribute("NoArmorHide")
	end
	
	local function Strip(Ent, Child: Instance)
	    if Cosmetics.Enabled and (Child.Name == "Clothing" or Child.Name == "3DClothing") then
	        Hidden[Child] = Ent.Character
	        Child.Parent = nil
	    elseif Accessories.Enabled and Ent.Player and IsAvatarAccessory(Child) then
	        for _, v: Instance in Child:GetDescendants() do
	            if v:IsA("BasePart") then
	                Override(v, "LocalTransparencyModifier", 1)
	            end
	        end
	    end
	end
	
	local function Added(Ent)
	    if Ent.Player == LocalPlayer or not (Cosmetics.Enabled or Accessories.Enabled) then return end
	
	    for _, v: Instance in Ent.Character:GetChildren() do
	        Strip(Ent, v)
	    end
	
	    if not Watching[Ent.Character] then
	        Watching[Ent.Character] = Ent.Character.ChildAdded:Connect(function(Child: Instance)
	            task.defer(function()
	                if FPSBooster.Enabled and Child.Parent == Ent.Character then
	                    Strip(Ent, Child)
	                end
	            end)
	        end)
	    end
	end
	
	local function Removed(Ent)
	    if Watching[Ent.Character] then
	        Watching[Ent.Character]:Disconnect()
	        Watching[Ent.Character] = nil
	    end
	
	    for Object: Instance, Parent: Instance in Hidden do
	        if Parent == Ent.Character then
	            Hidden[Object] = nil
	        end
	    end
	end
	
	FPSBooster = vape.Categories.Render:CreateModule({
	    Name = "FPSBooster",
	    Function = function(Callback: boolean)
	        Generation += 1
	
	        if Callback then
	            if Quality.Enabled then
	                pcall(function()
	                    QualityOld = settings().Rendering.QualityLevel
	                    settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
	                end)
	            end
	
	            if Shadows.Enabled then
	                Pin(Lighting, "GlobalShadows", false)
	            end
	
	            if Reflections.Enabled then
	                Pin(Lighting, "EnvironmentSpecularScale", 0)
	            end
	
	            if Post.Enabled then
	                for _, v: Instance in Lighting:GetChildren() do
	                    StripEffect(v)
	                end
	
	                PostHook = Lighting.ChildAdded:Connect(function(Child: Instance)
	                    if FPSBooster.Enabled and Post.Enabled then
	                        task.defer(StripEffect, Child)
	                    end
	                end)
	            end
	
	            if Water.Enabled then
	                WaterOld = {
	                    Size = workspace.Terrain.WaterWaveSize,
	                    Speed = workspace.Terrain.WaterWaveSpeed,
	                    Reflectance = workspace.Terrain.WaterReflectance,
	                    Transparency = workspace.Terrain.WaterTransparency
	                }
	                workspace.Terrain.WaterWaveSize = 0
	                workspace.Terrain.WaterWaveSpeed = 0
	                workspace.Terrain.WaterReflectance = 0
	                workspace.Terrain.WaterTransparency = 1
	            end
	
	            if Compatibility.Enabled then
	                TechnologyOld = Lighting.Technology
	                Lighting.Technology = Enum.Technology.Compatibility
	            end
	
	            if Kill.Enabled then
	                for Name: string, KillEffect: any in bedwars.KillEffectController.killEffects do
	                    if not Name:find("Custom") then
	                        KillEffects[Name] = KillEffect
	                        bedwars.KillEffectController.killEffects[Name] = {
	                            new = function()
	                                return {
	                                    onKill = function() end,
	                                    isPlayDefaultKillEffect = function()
	                                        return true
	                                    end
	                                }
	                            end
	                        }
	                    end
	                end
	            end
	
	            if Visualizer.Enabled then
	                for Name: string, Utility: (...any) -> ...any in bedwars.VisualizerUtils do
	                    Visualizers[Name] = Utility
	                    bedwars.VisualizerUtils[Name] = function() end
	                end
	            end
	
	            if Particles.Enabled or Lights.Enabled or Reflections.Enabled or Explosions.Enabled then
	                FPSBooster:Clean(workspace.DescendantAdded:Connect(Scan))
	                task.spawn(Sweep, Generation)
	            end
	
	            if Explosions.Enabled then
	                local ExplosionFolder: Instance? = workspace:FindFirstChild("Explosions")
	                if ExplosionFolder then
	                    FPSBooster:Clean(ExplosionFolder.ChildAdded:Connect(function(Child: Instance)
	                        task.defer(function()
	                            if FPSBooster.Enabled and Explosions.Enabled and Child.Parent == ExplosionFolder then
	                                Child.Parent = nil
	                            end
	                        end)
	                    end))
	                end
	            end
	
	            if Nametags.Enabled then
	                task.spawn(function()
	                    repeat task.wait() until Store.matchState ~= 0 or not FPSBooster.Enabled
	                    if not FPSBooster.Enabled or not Nametags.Enabled or not bedwars.AppController then return end
	
	                    NametagOld = bedwars.NametagController.addGameNametag
	                    bedwars.NametagController.addGameNametag = function() end
	                    for _, v: any in bedwars.AppController:getOpenApps() do
	                        if tostring(v):find("Nametag") then
	                            bedwars.AppController:closeApp(tostring(v))
	                        end
	                    end
	                end)
	            end
	
	            if Clouds.Enabled then
	                local CloudsFolder: Instance? = workspace:FindFirstChild("Clouds")
	                if CloudsFolder then
	                    Hidden[CloudsFolder] = CloudsFolder.Parent
	                    CloudsFolder.Parent = nil
	                end
	            end
	
	            if Cosmetics.Enabled or Accessories.Enabled then
	                FPSBooster:Clean(Entity.Events.EntityAdded:Connect(Added))
	                FPSBooster:Clean(Entity.Events.EntityRemoved:Connect(Removed))
	                for _, v: any in Entity.List do
	                    Added(v)
	                end
	            end
	
	            if Animations.Enabled then
	                task.spawn(function()
	                    repeat
	                        SetSpeed(0)
	                        task.wait(0.5)
	                    until not FPSBooster.Enabled or not Animations.Enabled
	                end)
	            end
	        else
	            if PostHook then
	                PostHook:Disconnect()
	                PostHook = nil
	            end
	
	            for Effect: Instance, OldValue: boolean | number in Effects do
	                if Effect.Parent then
	                    if Effect:IsA("Atmosphere") then
	                        Effect.Density = OldValue
	                    else
	                        Effect.Enabled = OldValue
	                    end
	                end
	            end
	            table.clear(Effects)
	
	            for Object: Instance, Properties: {[string]: any} in Saved do
	                if Object.Parent then
	                    for Property: string, Value: any in Properties do
	                        Object[Property] = Value
	                    end
	                end
	            end
	            table.clear(Saved)
	
	            for Name: string, KillEffect: any in KillEffects do
	                bedwars.KillEffectController.killEffects[Name] = KillEffect
	            end
	            table.clear(KillEffects)
	
	            for Name: string, Utility: (...any) -> ...any in Visualizers do
	                bedwars.VisualizerUtils[Name] = Utility
	            end
	            table.clear(Visualizers)
	
	            if NametagOld then
	                bedwars.NametagController.addGameNametag = NametagOld
	                NametagOld = nil
	            end
	
	            if TechnologyOld then
	                Lighting.Technology = TechnologyOld
	                TechnologyOld = nil
	            end
	
	            if WaterOld then
	                workspace.Terrain.WaterWaveSize = WaterOld.Size
	                workspace.Terrain.WaterWaveSpeed = WaterOld.Speed
	                workspace.Terrain.WaterReflectance = WaterOld.Reflectance
	                workspace.Terrain.WaterTransparency = WaterOld.Transparency
	                WaterOld = nil
	            end
	
	            for _, v: RBXScriptConnection in Watching do
	                v:Disconnect()
	            end
	            table.clear(Watching)
	
	            for Object: Instance, Parent: Instance in Hidden do
	                if Parent.Parent then
	                    Object.Parent = Parent
	                end
	            end
	
	            table.clear(Hidden)
	            SetSpeed(1)
	
	            if QualityOld then
	                pcall(function()
	                    settings().Rendering.QualityLevel = QualityOld
	                end)
	                QualityOld = nil
	            end
	        end
	    end,
	    Tooltip = "Strips the parts of the scene that actually cost frames"
	})
	
	Cosmetics = FPSBooster:CreateToggle({
	    Name = "Cosmetics",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Hides everyone else's skins, the biggest win of the four.\nBodies and held items stay visible"
	})
	Accessories = FPSBooster:CreateToggle({
	    Name = "Accessories",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Tooltip = "Hides everyone else's avatar hats, hair and other accessories.\nHeld items, armor and backpacks stay visible"
	})
	Animations = FPSBooster:CreateToggle({
	    Name = "Freeze animations",
	    Function = function(Callback: boolean)
	        if FPSBooster.Enabled and not Callback then
	            SetSpeed(1)
	        end
	
	        if FPSBooster.Enabled and Callback then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Tooltip = "Stops everyone else animating, they slide around instead.\nUnverified on your machine, A/B it yourself"
	})
	Clouds = FPSBooster:CreateToggle({
	    Name = "Clouds",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Removes the cloud decoration, around 700 parts on most maps"
	})
	Quality = FPSBooster:CreateToggle({
	    Name = "Render quality",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Drops the engine render quality to its lowest level"
	})
	Shadows = FPSBooster:CreateToggle({
	    Name = "Shadows",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Turns off global shadows and keeps them off when the game turns them back on"
	})
	Lights = FPSBooster:CreateToggle({
	    Name = "Lights",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Turns off every point, spot and surface light in the map"
	})
	Post = FPSBooster:CreateToggle({
	    Name = "Post effects",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Turns off sun rays, depth of field and colour correction, whole render passes the card does every frame.\nThe GUI blur is left alone"
	})
	Water = FPSBooster:CreateToggle({
	    Name = "Water",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Flattens terrain water, no waves and no reflection.\nOnly does anything on maps that have water"
	})
	Reflections = FPSBooster:CreateToggle({
	    Name = "Reflections",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Turns off sky reflections and shiny part reflections.\nThe sky reflections stay off when the game turns them back on"
	})
	Compatibility = FPSBooster:CreateToggle({
	    Name = "Compatibility lighting",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Drops the map to compatibility lighting, the cheapest renderer Roblox has"
	})
	Kill = FPSBooster:CreateToggle({
	    Name = "Kill effects",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Stops other peoples kill effects from playing"
	})
	Visualizer = FPSBooster:CreateToggle({
	    Name = "Visualizer",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Turns off the games own visual effect helpers"
	})
	Particles = FPSBooster:CreateToggle({
	    Name = "Particles",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Stops every particle, trail and beam in the map from rendering"
	})
	Explosions = FPSBooster:CreateToggle({
	    Name = "Explosions",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Hides TNT, fireball and other explosion effects.\nThe blast itself still happens"
	})
	Nametags = FPSBooster:CreateToggle({
	    Name = "Nametags",
	    Function = function()
	        if FPSBooster.Enabled then
	            FPSBooster:Toggle()
	            FPSBooster:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Hides the game nametags once the match starts"
	})
end)

Run(function()
	local GeneratorESP
	local Transparency
	local Scale
	local ShowIron
	local ShowDiamond
	local ShowEmerald
	local Window, InfoLabel
	local Expanded: boolean = false
	local Timers = setmetatable({}, {__mode = "k"})
	local Order: {string} = {"iron", "diamond", "emerald"}
	local Names: {[string]: string} = {
	    iron = "Iron",
	    diamond = "Diamond",
	    emerald = "Emerald"
	}
	local Colors: {[string]: string} = {
	    iron = "rgb(255,255,255)",
	    diamond = "rgb(85,170,255)",
	    emerald = "rgb(85,255,85)"
	}
	
	local function IsShown(Resource: string): boolean
	    if Resource == "diamond" then
	        return ShowDiamond.Enabled
	    elseif Resource == "emerald" then
	        return ShowEmerald.Enabled
	    end
	    return ShowIron.Enabled
	end
	
	local function GetResource(Generator: Instance): string?
	    local Id: string = Generator:GetAttribute("Id") or ""
	    local Owner: string? = Id:match("^(.-)_generator$")
	    if Owner then
	        return Owner == tostring(LocalPlayer:GetAttribute("Team")) and "iron" or nil
	    end
	    return Id:match("^(diamond)_") or Id:match("^(emerald)_")
	end
	
	local function GetCountdown(Generator: Instance): number?
	    local Label = Timers[Generator]
	    if not Label or not Label.Parent then
	        local App: Instance? = Generator:FindFirstChild("RoactTree")
	        App = App and App:FindFirstChild("TeamOreGeneratorApp")
	        Label = App and (App:FindFirstChild("Countdown", true) or App:FindFirstChild("Timer", true))
	        Timers[Generator] = Label
	    end
	
	    local Text: string? = Label and Label.Text
	    local Seconds: number? = Text and tonumber(Text:match("%[([%d%.]+)%]") or Text:match("([%d%.]+)"))
	    return Seconds and math.ceil(Seconds)
	end
	
	local function GetStored(Position: Vector3, Resource: string, Drops: {Instance}): number
	    local Stored: number = 0
	    for _, v: Instance in Drops do
	        if v.Name == Resource and v:IsA("BasePart") then
	            local Offset: Vector3 = v.Position - Position
	            if Vector2.new(Offset.X, Offset.Z).Magnitude <= 6 and Offset.Y >= -12 and Offset.Y <= 4 then
	                Stored += v:GetAttribute("Amount") or 1
	            end
	        end
	    end
	    return Stored
	end
	
	local function Describe(Entry, ShowDistance: boolean): string
	    local Parts: {string} = {`{Names[Entry.Resource]} T{Entry.Level}`}
	    if Entry.Countdown then
	        table.insert(Parts, `{Entry.Countdown}s`)
	    end
	    table.insert(Parts, `{Entry.Stored} stored`)
	    if ShowDistance then
	        table.insert(Parts, `{math.floor(Entry.Distance)} studs`)
	    end
	    return `<font color="{Colors[Entry.Resource]}">{table.concat(Parts, " | ")}</font>`
	end
	
	local function Refresh()
	    if not Window then
	        return
	    end
	
	    local Origin: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Camera.CFrame.Position
	    local Drops: {Instance} = CollectionService:GetTagged("ItemDrop")
	    local Entries = {}
	    for _, v: Instance in CollectionService:GetTagged("Generator") do
	        local Resource: string? = v:IsA("BasePart") and GetResource(v) or nil
	        if Resource and IsShown(Resource) then
	            table.insert(Entries, {
	                Resource = Resource,
	                Level = v:GetAttribute("GeneratorLevel") or 0,
	                Countdown = GetCountdown(v),
	                Stored = GetStored(v.Position, Resource, Drops),
	                Distance = (v.Position - Origin).Magnitude
	            })
	        end
	    end
	    table.sort(Entries, function(First, Second): boolean
	        return First.Distance < Second.Distance
	    end)
	
	    local Lines: {string} = {"<b>GeneratorESP</b>", '<font size="4"> </font>'}
	    for _, Resource: string in Order do
	        for _, Entry: any in Entries do
	            if Entry.Resource == Resource then
	                table.insert(Lines, Describe(Entry, false))
	                break
	            end
	        end
	    end
	    if #Entries == 0 then
	        table.insert(Lines, "No generators")
	    end
	
	    local ShowList: boolean = Expanded and #Entries > 0
	    if ShowList then
	        table.insert(Lines, '<font size="4"> </font>')
	        for i: number, Entry: any in Entries do
	            if i > 8 then
	                break
	            end
	            table.insert(Lines, Describe(Entry, true))
	        end
	    end
	
	    InfoLabel.Text = table.concat(Lines, "\n")
	    local Bounds: Vector2 = GetFontBounds(RemoveTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)
	    local TitleBounds: Vector2 = GetFontBounds("GeneratorESP", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))
	    Window.Size = UDim2.fromOffset(math.max(Bounds.X, TitleBounds.X) + 16, Bounds.Y + (ShowList and -8 or 4))
	end
	
	local function CreateWindow()
	    Window = Instance.new("TextButton")
	    Window.Name = "GeneratorViewer"
	    Window.Position = UDim2.fromOffset(12, 330)
	    Window.BackgroundColor3 = Color3.new()
	    Window.BackgroundTransparency = Transparency.Value
	    Window.Text = ""
	    Window.AutoButtonColor = false
	    Window.Visible = false
	    Window.Parent = vape.gui.ScaledGui
	    AddBlur(Window)
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 5)
	    Corner.Parent = Window
	
	    InfoLabel = Instance.new("TextLabel")
	    InfoLabel.Size = UDim2.new(1, -16, 1, -16)
	    InfoLabel.Position = UDim2.fromOffset(8, 8)
	    InfoLabel.BackgroundTransparency = 1
	    InfoLabel.TextXAlignment = Enum.TextXAlignment.Left
	    InfoLabel.TextYAlignment = Enum.TextYAlignment.Top
	    InfoLabel.TextSize = 16 * Scale.Value
	    InfoLabel.TextColor3 = Color3.new(1, 1, 1)
	    InfoLabel.TextStrokeColor3 = Color3.new()
	    InfoLabel.TextStrokeTransparency = 0.8
	    InfoLabel.Font = Enum.Font.Arial
	    InfoLabel.RichText = true
	    InfoLabel.Parent = Window
	    GeneratorESP:AddHUD(Window)
	
	    local PressPosition: UDim2? = nil
	    Window.MouseButton1Down:Connect(function()
	        PressPosition = Window.Position
	    end)
	
	    Window.MouseButton1Click:Connect(function()
	        if PressPosition == Window.Position then
	            Expanded = not Expanded
	            Refresh()
	        end
	    end)
	end
	
	GeneratorESP = vape.Categories.Render:CreateModule({
	    Name = "GeneratorESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            if not Window then
	                CreateWindow()
	            end
	            Window.Visible = true
	
	            repeat
	                Refresh()
	                task.wait(0.25)
	            until not GeneratorESP.Enabled
	        elseif Window then
	            Window.Visible = false
	        end
	    end,
	    Tooltip = "Shows a panel with the nearest generator of each type: its tier, the time until its next drop and how much is waiting at it.\nClick the panel to list every generator by distance, drag it while the GUI is open to move it.\nIron only counts your own team's generator"
	})
	
	Transparency = GeneratorESP:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Function = function(Value: number)
	        if Window then
	            Window.BackgroundTransparency = Value
	        end
	    end,
	    Default = 0.5
	})
	Scale = GeneratorESP:CreateSlider({
	    Name = "Scale",
	    Min = 0.5,
	    Max = 1.5,
	    Decimal = 10,
	    Function = function(Value: number)
	        if InfoLabel then
	            InfoLabel.TextSize = 16 * Value
	            Refresh()
	        end
	    end,
	    Default = 1
	})
	ShowIron = GeneratorESP:CreateToggle({
	    Name = "Show Iron Generator",
	    Function = Refresh,
	    Default = true,
	    Tooltip = "Shows your team's iron generator"
	})
	ShowDiamond = GeneratorESP:CreateToggle({
	    Name = "Show Diamond Generator",
	    Function = Refresh,
	    Default = true,
	    Tooltip = "Shows diamond generators, in blue"
	})
	ShowEmerald = GeneratorESP:CreateToggle({
	    Name = "Show Emerald Generator",
	    Function = Refresh,
	    Tooltip = "Shows emerald generators, in green"
	})
end)

Run(function()
	local Headless
	local Hats
	
	local Hidden: {[Decal]: number} = setmetatable({}, {__mode = "k"})
	local Decals, Handles = {}, {}
	local Watchers: {RBXScriptConnection} = {}
	local Head
	
	local function Refresh(Character)
	    for _, v: RBXScriptConnection in Watchers do
	        v:Disconnect()
	    end
	
	    table.clear(Watchers)
	    table.clear(Decals)
	    table.clear(Handles)
	    Head = Character and Character:FindFirstChild("Head")
	    if not Head then return end
	
	    for _, v: Instance in Head:GetChildren() do
	        if v:IsA("Decal") then
	            if not Hidden[v] then
	                Hidden[v] = v.Transparency
	            end
	
	            table.insert(Decals, v)
	            v.Transparency = 1
	        end
	    end
	
	    for _, v: Instance in Character:GetChildren() do
	        if v:IsA("Accessory") and v.Handle and v.Handle:FindFirstChild("HatAttachment") then
	            table.insert(Handles, v.Handle)
	        end
	    end
	
	    for _, v: RBXScriptSignal in {Character.ChildAdded, Character.ChildRemoved, Head.ChildAdded} do
	        table.insert(Watchers, v:Connect(function()
	            task.defer(function()
	                if Headless.Enabled and Character.Parent then
	                    Refresh(Character)
	                end
	            end)
	        end))
	    end
	end
	
	Headless = vape.Categories.Render:CreateModule({
	    Name = "Headless",
	    Function = function(Callback: boolean)
	        if Callback then
	            Refresh(Entity.isAlive and LocalPlayer.Character)
	
	            Headless:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)
	                Character:WaitForChild("Head", 5)
	                Refresh(Character)
	            end))
	
	            Headless:Clean(RunService.PreRender:Connect(function()
	                if not Head then return end
	
	                Head.LocalTransparencyModifier = 1
	                if Hats.Enabled then
	                    for _, v: BasePart in Handles do
	                        v.LocalTransparencyModifier = 1
	                    end
	                end
	            end))
	
	            Headless:Clean(function()
	                if Head then
	                    Head.LocalTransparencyModifier = 0
	                end
	
	                for _, v: Decal in Decals do
	                    v.Transparency = Hidden[v] or 0
	                end
	
	                for _, v: BasePart in Handles do
	                    v.LocalTransparencyModifier = 0
	                end
	
	                for _, v: RBXScriptConnection in Watchers do
	                    v:Disconnect()
	                end
	
	                Head = nil
	                table.clear(Watchers)
	                table.clear(Decals)
	                table.clear(Handles)
	            end)
	        end
	    end,
	    Tooltip = "Hides your own head"
	})
	Hats = Headless:CreateToggle({
	    Name = "Hide hats",
	    Function = function(Callback: boolean)
	        if not Callback then
	            for _, v: BasePart in Handles do
	                v.LocalTransparencyModifier = 0
	            end
	        end
	    end,
	    Default = true,
	    Tooltip = "Hides anything worn on your head too"
	})
end)

