Run(function()
	local NoTextures
	local Materials = {}
	local Decals = {}
	local Meshes = {}
	local Reference = {}
	
	local function Remember(Object: Instance, Property: string)
	    local Properties = Reference[Object]
	    if not Properties then
	        Properties = {}
	        Reference[Object] = Properties
	    end
	
	    if Properties[Property] == nil then
	        Properties[Property] = Object[Property]
	    end
	end
	
	local function StripObject(Object: Instance)
	    if Decals.Enabled and Object:IsA("Decal") then
	        local Parent: Instance? = Object.Parent
	        if Parent and Parent:IsA("BasePart") and Parent.Transparency > 0.5 then
	            return
	        end
	
	        Remember(Object, "Transparency")
	        Object.Transparency = 1
	        return
	    end
	
	    if Decals.Enabled and Object:IsA("SurfaceAppearance") then
	        Remember(Object, "Parent")
	        Object.Parent = nil
	        return
	    end
	
	    if Meshes.Enabled and Object:IsA("SpecialMesh") then
	        Remember(Object, "TextureId")
	        Object.TextureId = ""
	        return
	    end
	
	    if Object:IsA("BasePart") then
	        if Meshes.Enabled and Object:IsA("MeshPart") then
	            Remember(Object, "TextureID")
	            Object.TextureID = ""
	        end
	
	        if Materials.Enabled then
	            Remember(Object, "Material")
	            Object.Material = Enum.Material.SmoothPlastic
	        end
	    end
	end
	
	local function Scan()
	    local Descendants: {Instance} = Store.map:GetDescendants()
	    for i: number, v: Instance in Descendants do
	        if not NoTextures.Enabled then return end
	        StripObject(v)
	
	        if i % 500 == 0 then
	            task.wait()
	        end
	    end
	end
	
	local function Refresh()
	    if not NoTextures.Enabled then return end
	    for Object: Instance, Properties: {[string]: any} in Reference do
	        pcall(function()
	            for Property: string, Value: any in Properties do
	                Object[Property] = Value
	            end
	        end)
	    end
	    table.clear(Reference)
	    Scan()
	end
	
	NoTextures = vape.Categories.Render:CreateModule({
	    Name = "NoTextures",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat task.wait() until Store.map or not NoTextures.Enabled
	            if not NoTextures.Enabled then return end
	
	            NoTextures:Clean(Store.map.DescendantAdded:Connect(function(Object: Instance)
	                task.defer(StripObject, Object)
	            end))
	            Scan()
	        else
	            for Object: Instance, Properties: {[string]: any} in Reference do
	                pcall(function()
	                    for Property: string, Value: any in Properties do
	                        Object[Property] = Value
	                    end
	                end)
	            end
	            table.clear(Reference)
	        end
	    end,
	    Tooltip = "Removes textures and materials from the map"
	})
	
	Materials = NoTextures:CreateToggle({
	    Name = "Materials",
	    Function = Refresh,
	    Default = true,
	    Tooltip = "Flattens every part to smooth plastic"
	})
	Decals = NoTextures:CreateToggle({
	    Name = "Decals",
	    Function = Refresh,
	    Default = true,
	    Tooltip = "Hides decals, textures and PBR surfaces, but keeps the textures of see-through blocks since they are all you can see of them"
	})
	Meshes = NoTextures:CreateToggle({
	    Name = "Meshes",
	    Function = Refresh,
	    Default = true,
	    Tooltip = "Clears textures off meshes"
	})
end)

Run(function()
	local OverlayEditor
	local FillColor
	local OutlineColor
	local Thickness
	local Animate
	local Speed
	local Overlay, OverlayBox, OverlayTween
	local ActivePart: BasePart?
	
	local function BindPart(Part: Instance)
	    if not OverlayEditor.Enabled or not Overlay then return end
	    if not Part:IsA("BasePart") or not Part.Anchored or Part.Transparency ~= 1 then return end
	    local Box: SelectionBox? = Part:FindFirstChildOfClass("SelectionBox")
	    if not Box then return end
	
	    Box.Visible = false
	    ActivePart = Part
	    if OverlayTween then
	        OverlayTween:Cancel()
	        OverlayTween = nil
	    end
	
	    if Animate.Enabled and Overlay.Parent == Camera then
	        OverlayTween = TweenService:Create(Overlay, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
	            CFrame = Part.CFrame,
	            Size = Part.Size
	        })
	        OverlayTween:Play()
	    else
	        Overlay.CFrame = Part.CFrame
	        Overlay.Size = Part.Size
	        Overlay.Parent = Camera
	    end
	end
	
	OverlayEditor = vape.Categories.Render:CreateModule({
	    Name = "OverlayEditor",
	    Function = function(Callback: boolean)
	        if Callback then
	            Overlay = Instance.new("Part")
	            Overlay.Size = Vector3.one * 3
	            Overlay.Anchored = true
	            Overlay.CanCollide = false
	            Overlay.CanQuery = false
	            Overlay.CanTouch = false
	            Overlay.CastShadow = false
	            Overlay.Transparency = 1
	            OverlayBox = Instance.new("SelectionBox")
	            OverlayBox.Adornee = Overlay
	            OverlayBox.LineThickness = Thickness.Value
	            OverlayBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
	            OverlayBox.Transparency = 1 - OutlineColor.Opacity
	            OverlayBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
	            OverlayBox.SurfaceTransparency = 1 - FillColor.Opacity
	            OverlayBox.Parent = Overlay
	            bedwars.QueryUtil:setQueryIgnored(Overlay, true)
	
	            for _, v: Instance in workspace:GetChildren() do
	                BindPart(v)
	            end
	
	            OverlayEditor:Clean(workspace.ChildAdded:Connect(function(Child: Instance)
	                task.defer(BindPart, Child)
	            end))
	            OverlayEditor:Clean(workspace.ChildRemoved:Connect(function(Child: Instance)
	                if Child ~= ActivePart then return end
	
	                ActivePart = nil
	                task.delay(0.06, function()
	                    if ActivePart or not OverlayEditor.Enabled then return end
	                    if OverlayTween then
	                        OverlayTween:Cancel()
	                        OverlayTween = nil
	                    end
	                    if Overlay then
	                        Overlay.Parent = nil
	                    end
	                end)
	            end))
	        else
	            if ActivePart then
	                local Box: SelectionBox? = ActivePart:FindFirstChildOfClass("SelectionBox")
	                if Box then
	                    Box.Visible = true
	                end
	                ActivePart = nil
	            end
	
	            if OverlayTween then
	                OverlayTween:Cancel()
	                OverlayTween = nil
	            end
	            if Overlay then
	                Overlay:Destroy()
	                Overlay, OverlayBox = nil, nil
	            end
	        end
	    end,
	    Tooltip = "Restyles the outline on the block you are aiming at"
	})
	
	FillColor = OverlayEditor:CreateColorSlider({
	    Name = "Fill Color",
	    DefaultSat = 0,
	    DefaultOpacity = 0.25,
	    Darker = true,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if OverlayBox then
	            OverlayBox.SurfaceColor3 = Color3.fromHSV(Hue, Sat, Val)
	            OverlayBox.SurfaceTransparency = 1 - Opacity
	        end
	    end
	})
	OutlineColor = OverlayEditor:CreateColorSlider({
	    Name = "Outline Color",
	    DefaultSat = 0,
	    Darker = true,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if OverlayBox then
	            OverlayBox.Color3 = Color3.fromHSV(Hue, Sat, Val)
	            OverlayBox.Transparency = 1 - Opacity
	        end
	    end
	})
	Thickness = OverlayEditor:CreateSlider({
	    Name = "Thickness",
	    Min = 0.01,
	    Max = 0.2,
	    Decimal = 100,
	    Function = function(Value: number)
	        if OverlayBox then
	            OverlayBox.LineThickness = Value
	        end
	    end,
	    Default = 0.04
	})
	Animate = OverlayEditor:CreateToggle({
	    Name = "Animate",
	    Default = true,
	    Tooltip = "Glides the overlay onto the next block instead of snapping to it"
	})
	Speed = OverlayEditor:CreateSlider({
	    Name = "Animation time",
	    Min = 0.01,
	    Max = 0.5,
	    Default = 0.08,
	    Decimal = 100,
	    Suffix = "s"
	})
end)

Run(function()
	local PotESP
	local Background
	local Color = {}
	local Reference = {}
	local Template
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local function Added(Block: Instance)
	    if Block.Name ~= "desert_pot" or Reference[Block] then return end
	
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Parent = Folder
	    Billboard.Name = Block.Name
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	    Billboard.Size = UDim2.fromOffset(36, 36)
	    Billboard.AlwaysOnTop = true
	    Billboard.ClipsDescendants = false
	    Billboard.Adornee = Block
	    local Blur: ImageLabel = AddBlur(Billboard)
	    Blur.Visible = Background.Enabled
	    local Viewport: ViewportFrame = Instance.new("ViewportFrame")
	    Viewport.Size = UDim2.fromOffset(36, 36)
	    Viewport.Position = UDim2.fromScale(0.5, 0.5)
	    Viewport.AnchorPoint = Vector2.new(0.5, 0.5)
	    Viewport.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    Viewport.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	    Viewport.BorderSizePixel = 0
	    Viewport.Ambient = Color3.new(1, 1, 1)
	    Viewport.LightColor = Color3.new(1, 1, 1)
	    Viewport.Parent = Billboard
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Viewport
	
	    if Template == nil then
	        local Assets: Instance? = ReplicatedStorage:FindFirstChild("Assets")
	        local Blocks: Instance? = Assets and Assets:FindFirstChild("Blocks")
	        local Model: Instance? = Blocks and Blocks:FindFirstChild("desert_pot")
	        Template = Model and Model:FindFirstChildWhichIsA("MeshPart", true) or false
	    end
	
	    if Template then
	        local Mesh: MeshPart = Template:Clone()
	        Mesh.CFrame = CFrame.Angles(0, math.rad(25), 0)
	        Mesh.Parent = Viewport
	        local Camera: Camera = Instance.new("Camera")
	        Camera.CFrame = CFrame.lookAt(Vector3.new(0, 0.75, 3.9), Vector3.new(0, 0.05, 0))
	        Camera.Parent = Viewport
	        Viewport.CurrentCamera = Camera
	    end
	
	    Reference[Block] = Billboard
	end
	
	PotESP = vape.Categories.Render:CreateModule({
	    Name = "PotESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, v: Instance in CollectionService:GetTagged("block") do
	                Added(v)
	            end
	            PotESP:Clean(CollectionService:GetInstanceAddedSignal("block"):Connect(Added))
	            PotESP:Clean(CollectionService:GetInstanceRemovedSignal("block"):Connect(function(Block: Instance)
	                if Reference[Block] then
	                    Reference[Block]:Destroy()
	                    Reference[Block] = nil
	                end
	            end))
	        else
	            for Block: Instance, v: BillboardGui in Reference do
	                v:Destroy()
	                Reference[Block] = nil
	            end
	        end
	    end,
	    Tooltip = "Renders an icon over desert pots"
	})
	
	Background = PotESP:CreateToggle({
	    Name = "Background",
	    Function = function(Callback: boolean)
	        if Color.Object then
	            Color.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            v.ViewportFrame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
	            v.Blur.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Color = PotESP:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        for _, v: BillboardGui in Reference do
	            v.ViewportFrame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            v.ViewportFrame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
	        end
	    end,
	    Darker = true
	})
end)

Run(function()
	local BulletTracers
	local Material
	local Lifetime
	local Curve
	local Opacity
	local Thickness
	local Color
	local Fade
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Exclude
	
	BulletTracers = vape.Categories.Render:CreateModule({
	    Name = "ProjectileTracers",
	    Function = function(Callback: boolean)
	        if Callback then
	            BulletTracers:Clean(workspace.ChildAdded:Connect(function(Projectile: Instance)
	                task.delay(0, function()
	                    if not BulletTracers.Enabled or not Projectile.Parent or Projectile:GetAttribute("ProjectileShooter") ~= LocalPlayer.UserId then
	                        return
	                    end
	                    local Filter: {Instance} = {Projectile}
	                    if LocalPlayer.Character then table.insert(Filter, LocalPlayer.Character) end
	                    RayCheck.FilterDescendantsInstances = Filter
	                    local Root = Projectile:IsA("BasePart") and Projectile or Projectile:IsA("Model") and Projectile.PrimaryPart
	                    local Meta = bedwars.ProjectileMeta[Projectile.Name]
	                    if not Root or not Meta then return end
	                    local Origin: Vector3 = Root.Position
	                    local Velocity: Vector3 = Root.AssemblyLinearVelocity
	                    local VelocityMagnitude: number = Velocity.Magnitude
	                    if VelocityMagnitude <= 0 then
	                        return
	                    end
	                    local VelocityUnit: Vector3 = Velocity / VelocityMagnitude
	                    local Gravity: number = Meta.gravitationalAcceleration or workspace.Gravity
	                    local Ray: RaycastResult? = workspace:Raycast(Origin, VelocityUnit * 2000, RayCheck)
	                    local Endpoint: Vector3 = Ray and Ray.Position or (Origin + VelocityUnit * 2000)
	                    local TravelTime: number = (Endpoint - Origin).Magnitude / VelocityMagnitude
	                    PredictionLib.SpawnArcTracer(Origin, VelocityUnit, VelocityMagnitude, Gravity, TravelTime, Curve.Value, {
	                        Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value),
	                        Transparency = Opacity.Value,
	                        Thick = Thickness.Value,
	                        Material = Enum.Material[Material.Value],
	                        Lifetime = Lifetime.Value,
	                        Fade = Fade.Enabled
	                    })
	                end)
	            end))
	        end
	    end,
	    Tooltip = "Replacement tracers for projectiles"
	})
	
	local Materials: {string} = {"SmoothPlastic"}
	for _, v: EnumItem in Enum.Material:GetEnumItems() do
	    if v.Name ~= "SmoothPlastic" then
	        table.insert(Materials, v.Name)
	    end
	end
	Material = BulletTracers:CreateDropdown({
	    Name = "Material",
	    List = Materials
	})
	Color = BulletTracers:CreateColorSlider({
	    Name = "Tracer Color",
	    DefaultOpacity = 0.5
	})
	Thickness = BulletTracers:CreateSlider({
	    Name = "Thickness",
	    Min = 0.01,
	    Max = 1,
	    Default = 0.1,
	    Decimal = 100
	})
	Curve = BulletTracers:CreateSlider({
	    Name = "Curveness",
	    Min = 1,
	    Max = 100,
	    Default = 40,
	    Tooltip = "How curve the projectile is gonna be\n(More curve = more lag)"
	})
	Opacity = BulletTracers:CreateSlider({
	    Name = "Opacity",
	    Min = 0,
	    Max = 1,
	    Default = 0,
	    Decimal = 100
	})
	Lifetime = BulletTracers:CreateSlider({
	    Name = "Lifetime",
	    Min = 0,
	    Max = 5,
	    Decimal = 100,
	    Default = 2,
	    Suffix = "secs"
	})
	Fade = BulletTracers:CreateToggle({
	    Name = "Fade",
	    Default = true
	})
end)

Run(function()
	local SkinChanger
	local Options = {}
	local Skins, Families, Groups, Order = {}, {}, {}, {}
	local Names, Extras = {}, {}
	local Sounds = {}
	local Applied = setmetatable({}, {__mode = "k"})
	local Watching, LastHand, Queued
	local Tiers: {[string]: boolean} = {leather = true, chainmail = true, wood = true, stone = true, gold = true, iron = true, diamond = true, emerald = true}
	
	for _, v: string in bedwars.ItemSkinType do
	    local Meta = bedwars.getItemSkinMeta(v)
	    local Item = Meta and Meta.itemType and bedwars.ItemMeta[Meta.itemType]
	    if Item then
	        local Label: string = `_{v}_`
	        for Segment: string in Meta.itemType:gmatch("[^_]+") do
	            Label = Label:gsub(`_{Segment}_`, "_")
	        end
	        Label = Label:gsub("^_+", ""):gsub("_+$", "")
	        Label = (tostring(Label ~= "" and Label or v):gsub("_", " "):gsub("%a+", function(Word: string)
	            return `{Word:sub(1, 1):upper()}{Word:sub(2)}`
	        end))
	
	        Skins[Meta.itemType] = Skins[Meta.itemType] or {}
	        Skins[Meta.itemType][Label] = v
	    end
	end
	
	for ItemType: string in Skins do
	    local Family: string = ItemType:gsub("_%d+$", "")
	    local Tier, Base = Family:match("^([^_]+)_(.+)$")
	    Family = Tier and Tiers[Tier] and Base or Family
	    if not Groups[Family] then
	        Groups[Family] = {}
	        table.insert(Order, Family)
	    end
	    Families[ItemType] = Family
	    table.insert(Groups[Family], ItemType)
	end
	
	for Family: string, Members: {string} in Groups do
	    Names[Family] = (tostring(#Members > 1 and Family or Members[1]):gsub("_", " "):gsub("%a+", function(Word: string)
	        return `{Word:sub(1, 1):upper()}{Word:sub(2)}`
	    end))
	end
	table.sort(Order, function(A: string, B: string)
	    return Names[A] < Names[B]
	end)
	
	for _, v: string in {"lobby_kaida_claw", "bear_claws", "summoner_claw_1", "summoner_claw_2", "summoner_claw_3", "summoner_claw_4"} do
	    if ReplicatedStorage.Items:FindFirstChild(v) then
	        local Label: string = (tostring((v:gsub("^lobby_", ""))):gsub("_", " "):gsub("%a+", function(Word: string)
	            return `{Word:sub(1, 1):upper()}{Word:sub(2)}`
	        end))
	        Extras[Label] = v
	    end
	end
	
	local function GetModel(ItemType: string): string?
	    local Family = SkinChanger.Enabled and Families[ItemType]
	    local Option = Family and Options[Family]
	    local Label = Option and Option.Value
	    return Label and (Extras[Label] or Skins[ItemType][Label]) or nil
	end
	
	local function ApplyModel(Accessory: Instance)
	    local Model: string? = GetModel(Accessory.Name)
	    if not Model then return end
	
	    local Handle: Instance? = Accessory:FindFirstChild("Handle")
	    local Template: Instance? = ReplicatedStorage.Items:FindFirstChild(Model)
	    if not Handle or not Template or Applied[Accessory] then return end
	
	    local Grip: Instance? = Handle:FindFirstChild("RightGripAttachment")
	    local TemplateGrip: Instance? = Template.Handle:FindFirstChild("RightGripAttachment")
	    local Record = {
	        Model = Model,
	        Parts = {},
	        Size = Handle.Size,
	        Grip = Grip and Grip.CFrame or nil
	    }
	    Applied[Accessory] = Record
	
	    for _, v: Instance in Handle:GetChildren() do
	        if v:IsA("BasePart") and v:GetAttribute("SkinHidden") == nil then
	            v:SetAttribute("SkinHidden", v.Transparency)
	            v.Transparency = 1
	        end
	    end
	
	    if Handle:IsA("MeshPart") and Template.Handle:IsA("MeshPart") then
	        Handle:ApplyMesh(Template.Handle)
	    end
	    Handle.Size = Template.Handle.Size
	    if Grip and TemplateGrip then
	        Grip.CFrame = TemplateGrip.CFrame
	    end
	
	    for _, v: Instance in Template.Handle:GetChildren() do
	        if v:IsA("BasePart") then
	            local Part: BasePart = v:Clone()
	            Part.CanCollide = false
	            Part.CanTouch = false
	            Part.CanQuery = false
	            Part.Massless = true
	            Part.CFrame = Handle.CFrame * (Template.Handle.CFrame:Inverse() * v.CFrame)
	            Part.Parent = Handle
	
	            local Weld: WeldConstraint = Instance.new("WeldConstraint")
	            Weld.Part0 = Handle
	            Weld.Part1 = Part
	            Weld.Parent = Part
	            table.insert(Record.Parts, Part)
	        end
	    end
	end
	
	local function ApplySounds()
	    for ItemType: string in Skins do
	        local Meta = bedwars.ItemMeta[ItemType]
	        if Meta and Meta.sword then
	            local Family = SkinChanger.Enabled and Families[ItemType]
	            local Option = Family and Options[Family]
	            local Label = Option and Option.Value
	            local Skin = Label and not Extras[Label] and Skins[ItemType][Label] or nil
	            local SkinMeta = Skin and bedwars.getItemSkinMeta(Skin)
	            local Sword = SkinMeta and SkinMeta.sword
	            if Sword and (Sword.swingSounds or Sword.hitSounds) then
	                if not Sounds[ItemType] then
	                    Sounds[ItemType] = {swing = Meta.sword.swingSounds, hit = Meta.sword.hitSounds}
	                end
	                Meta.sword.swingSounds = Sword.swingSounds or Sounds[ItemType].swing
	                Meta.sword.hitSounds = Sword.hitSounds or Sounds[ItemType].hit
	            elseif Sounds[ItemType] then
	                Meta.sword.swingSounds = Sounds[ItemType].swing
	                Meta.sword.hitSounds = Sounds[ItemType].hit
	                Sounds[ItemType] = nil
	            end
	        end
	    end
	end
	
	local function ApplySkins()
	    local Inventory = Store.inventory.inventory
	    local HandSkin: string? = Inventory.hand and Inventory.hand.itemSkin
	    local Changed: boolean = false
	    for _, v: any in Inventory.items do
	        local Family = SkinChanger.Enabled and Families[v.itemType]
	        local Option = Family and Options[Family]
	        local Label = Option and Option.Value
	        local Skin = Label and not Extras[Label] and Skins[v.itemType][Label] or nil
	        if v.itemSkin ~= Skin then
	            v.itemSkin = Skin
	            Changed = true
	        end
	    end
	    if Inventory.hand then
	        local Family = SkinChanger.Enabled and Families[Inventory.hand.itemType]
	        local Option = Family and Options[Family]
	        local Label = Option and Option.Value
	        local Skin = Label and not Extras[Label] and Skins[Inventory.hand.itemType][Label] or nil
	        if Inventory.hand.itemSkin ~= Skin then
	            Inventory.hand.itemSkin = Skin
	            Changed = true
	        end
	    end
	
	    local Hand = Inventory.hand and Inventory.hand.itemType
	    if not Changed and Hand == LastHand then return end
	
	    local HandChanged: boolean = Hand ~= LastHand or (Inventory.hand and Inventory.hand.itemSkin) ~= HandSkin
	    LastHand = Hand
	    if HandChanged then
	        bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState())
	    end
	    if not LocalPlayer.Character then return end
	
	    for _, v: Instance in LocalPlayer.Character:GetChildren() do
	        if not v:IsA("Accessory") then continue end
	
	        local Record = Applied[v]
	        if Record then
	            if Record.Model == GetModel(v.Name) then continue end
	
	            local Handle: Instance? = v:FindFirstChild("Handle")
	            local Template: Instance? = ReplicatedStorage.Items:FindFirstChild(v.Name)
	            for _, Part: BasePart in Record.Parts do
	                Part:Destroy()
	            end
	
	            for _, Child: Instance in Handle and Handle:GetChildren() or {} do
	                local Transparency: number? = Child:GetAttribute("SkinHidden")
	                if Transparency then
	                    Child.Transparency = Transparency
	                    Child:SetAttribute("SkinHidden", nil)
	                end
	            end
	            Applied[v] = nil
	
	            if Handle then
	                if Template and Handle:IsA("MeshPart") and Template.Handle:IsA("MeshPart") then
	                    Handle:ApplyMesh(Template.Handle)
	                end
	                Handle.Size = Record.Size
	
	                local Grip: Instance? = Handle:FindFirstChild("RightGripAttachment")
	                if Grip and Record.Grip then
	                    Grip.CFrame = Record.Grip
	                end
	            end
	        end
	
	        ApplyModel(v)
	    end
	end
	
	local function QueueSkins()
	    if Queued then return end
	
	    Queued = true
	    task.defer(function()
	        Queued = false
	        ApplySkins()
	    end)
	end
	
	SkinChanger = vape.Categories.Render:CreateModule({
	    Name = "SkinChanger",
	    Function = function(Callback: boolean)
	        if Callback then
	            SkinChanger:Clean(VapeEvents.InventoryChanged.Event:Connect(QueueSkins))
	            SkinChanger:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(QueueSkins))
	            SkinChanger:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)
	                LastHand = nil
	                if Watching then
	                    Watching:Disconnect()
	                end
	                Watching = Character.ChildAdded:Connect(function(Child: Instance)
	                    if Child:IsA("Accessory") and Child:WaitForChild("Handle", 3) and SkinChanger.Enabled then
	                        ApplyModel(Child)
	                    end
	                end)
	
	                task.spawn(function()
	                    for _ = 1, 10 do
	                        task.wait(0.4)
	                        if not SkinChanger.Enabled then return end
	                        ApplySkins()
	                    end
	                end)
	            end))
	
	            if LocalPlayer.Character then
	                if Watching then
	                    Watching:Disconnect()
	                end
	                Watching = LocalPlayer.Character.ChildAdded:Connect(function(Child: Instance)
	                    if Child:IsA("Accessory") and Child:WaitForChild("Handle", 3) and SkinChanger.Enabled then
	                        ApplyModel(Child)
	                    end
	                end)
	            end
	        elseif Watching then
	            Watching:Disconnect()
	            Watching = nil
	        end
	        ApplySounds()
	        ApplySkins()
	    end,
	    Tooltip = "Reskins the items and blocks you hold with their sounds, only you can see it"
	})
	
	for _, Family: string in Order do
	    local List, Seen = {}, {}
	    for _, ItemType: string in Groups[Family] do
	        for SkinName: string in Skins[ItemType] do
	            if not Seen[SkinName] then
	                Seen[SkinName] = true
	                table.insert(List, SkinName)
	            end
	        end
	    end
	
	    local Melee: boolean = false
	    for _, ItemType: string in Groups[Family] do
	        local Meta = bedwars.ItemMeta[ItemType]
	        if Meta and Meta.sword then
	            Melee = true
	            break
	        end
	    end
	
	    if Melee then
	        for SkinName: string in Extras do
	            table.insert(List, SkinName)
	        end
	    end
	
	    table.sort(List)
	    table.insert(List, 1, "None")
	    Options[Family] = SkinChanger:CreateDropdown({
	        Name = Names[Family],
	        List = List,
	        Function = function()
	            if SkinChanger.Enabled then
	                ApplySounds()
	                ApplySkins()
	            end
	        end
	    })
	end
end)

Run(function()
	local StorageESP
	local List
	local ShowAmount
	local Background
	local Color = {}
	local Reference = {}
	local Connections: {[BillboardGui]: {RBXScriptConnection}} = setmetatable({}, {__mode = "k"})
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local function RefreshAdornee(Billboard: BillboardGui)
	    local Chest = Billboard.Adornee and Billboard.Adornee:FindFirstChild("ChestFolderValue")
	    Chest = Chest and Chest.Value
	    if not Chest then
	        Billboard.Enabled = false
	        return
	    end
	
	    for _, v: RBXScriptConnection in Connections[Billboard] or {} do
	        v:Disconnect()
	    end
	    Connections[Billboard] = {}
	    for _, v: Instance in Billboard.Frame:GetChildren() do
	        if v:IsA("ImageLabel") then
	            v:Destroy()
	        end
	    end
	
	    local Amounts: {[string]: number} = {}
	    for _, v: Instance in Chest:GetChildren() do
	        Amounts[v.Name] = (Amounts[v.Name] or 0) + (v:GetAttribute("Amount") or 0)
	        if ShowAmount.Enabled then
	            table.insert(Connections[Billboard], v:GetAttributeChangedSignal("Amount"):Connect(function()
	                RefreshAdornee(Billboard)
	            end))
	        end
	    end
	
	    local AlreadyGot: {[string]: boolean} = {}
	    Billboard.Enabled = false
	    for _, v: Instance in Chest:GetChildren() do
	        if AlreadyGot[v.Name] then continue end
	        for _, Item: string in List.ListEnabled do
	            if v.Name:find(Item, 1, true) then
	                AlreadyGot[v.Name] = true
	                Billboard.Enabled = true
	                local BlockImage: ImageLabel = Instance.new("ImageLabel")
	                BlockImage.Size = UDim2.fromOffset(32, 32)
	                BlockImage.BackgroundTransparency = 1
	                BlockImage.Image = bedwars.getIcon({itemType = v.Name}, true)
	                BlockImage.Parent = Billboard.Frame
	                if ShowAmount.Enabled and Amounts[v.Name] > 1 then
	                    local Amount: TextLabel = Instance.new("TextLabel")
	                    Amount.Name = "Amount"
	                    Amount.Size = UDim2.fromOffset(31, 14)
	                    Amount.Position = UDim2.fromOffset(0, 18)
	                    Amount.BackgroundTransparency = 1
	                    Amount.Text = tostring(Amounts[v.Name])
	                    Amount.TextXAlignment = Enum.TextXAlignment.Right
	                    Amount.TextSize = 14
	                    Amount.TextColor3 = UIPallet.Text
	                    Amount.TextStrokeColor3 = Color3.new()
	                    Amount.TextStrokeTransparency = 0.4
	                    Amount.FontFace = UIPallet.Font
	                    Amount.Parent = BlockImage
	                end
	                break
	            end
	        end
	    end
	end
	
	local function Added(Part: Instance)
	    local Chest = Part:WaitForChild("ChestFolderValue", 3)
	    Chest = Chest and Chest.Value
	    if not Chest or not StorageESP.Enabled or Reference[Part] then return end
	
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Parent = Folder
	    Billboard.Name = "chest"
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	    Billboard.Size = UDim2.fromOffset(36, 36)
	    Billboard.AlwaysOnTop = true
	    Billboard.ClipsDescendants = false
	    Billboard.Adornee = Part
	    local Blur: ImageLabel = AddBlur(Billboard)
	    Blur.Visible = Background.Enabled
	    local Frame: Frame = Instance.new("Frame")
	    Frame.Size = UDim2.fromScale(1, 1)
	    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	    Frame.Parent = Billboard
	    local Layout: UIListLayout = Instance.new("UIListLayout")
	    Layout.FillDirection = Enum.FillDirection.Horizontal
	    Layout.Padding = UDim.new(0, 4)
	    Layout.VerticalAlignment = Enum.VerticalAlignment.Center
	    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	    Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
	        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)
	    end)
	    Layout.Parent = Frame
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Frame
	    Reference[Part] = Billboard
	
	    StorageESP:Clean(Chest.ChildAdded:Connect(function()
	        RefreshAdornee(Billboard)
	    end))
	    StorageESP:Clean(Chest.ChildRemoved:Connect(function()
	        RefreshAdornee(Billboard)
	    end))
	    RefreshAdornee(Billboard)
	end
	
	StorageESP = vape.Categories.Render:CreateModule({
	    Name = "StorageESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            StorageESP:Clean(CollectionService:GetInstanceAddedSignal("chest"):Connect(function(Part: Instance)
	                task.spawn(Added, Part)
	            end))
	            StorageESP:Clean(CollectionService:GetInstanceRemovedSignal("chest"):Connect(function(Part: Instance)
	                if Reference[Part] then
	                    Reference[Part]:Destroy()
	                    Reference[Part] = nil
	                end
	            end))
	            for _, v: Instance in CollectionService:GetTagged("chest") do
	                task.spawn(Added, v)
	            end
	        else
	            for _, v: {RBXScriptConnection} in Connections do
	                for _, Connection: RBXScriptConnection in v do
	                    Connection:Disconnect()
	                end
	            end
	            table.clear(Connections)
	            table.clear(Reference)
	            Folder:ClearAllChildren()
	        end
	    end,
	    Tooltip = "Displays items in chests"
	})
	
	List = StorageESP:CreateTextList({
	    Name = "Item",
	    Function = function()
	        for _, v: BillboardGui in Reference do
	            task.spawn(RefreshAdornee, v)
	        end
	    end
	})
	ShowAmount = StorageESP:CreateToggle({
	    Name = "Show Amount",
	    Function = function()
	        for _, v: BillboardGui in Reference do
	            task.spawn(RefreshAdornee, v)
	        end
	    end,
	    Tooltip = "Displays how much of each item the chest holds"
	})
	Background = StorageESP:CreateToggle({
	    Name = "Background",
	    Function = function(Callback: boolean)
	        if Color.Object then
	            Color.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
	            v.Blur.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Color = StorageESP:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
	        end
	    end,
	    Darker = true
	})
end)

Run(function()
	local ShowInventory
	local TargetInfoOverlay = vape.Categories["Target Info"]
	local Card: Frame = TargetInfo.Object
	local Row: Frame?
	local Tiles: {Frame} = {}
	local Lifted: {[Frame]: boolean} = {}
	local TileSize: number = 30
	local TilePadding: number = 5
	local Columns: number = 7
	local Lift: number = 4
	local Looping: boolean = false
	
	local function CreateRow()
	    Row = Instance.new("Frame")
	    Row.Name = "Inventory"
	    Row.BackgroundTransparency = 1
	    Row.Position = UDim2.new(0, 0, 1, TilePadding + Lift)
	    Row.Size = UDim2.fromScale(1, 0)
	    Row.Visible = false
	    Row.Parent = Card
	    local Grid: UIGridLayout = Instance.new("UIGridLayout")
	    Grid.CellPadding = UDim2.fromOffset(TilePadding, TilePadding)
	    Grid.CellSize = UDim2.fromOffset(TileSize, TileSize)
	    Grid.SortOrder = Enum.SortOrder.LayoutOrder
	    Grid.Parent = Row
	end
	
	local function CreateTile(Index: number): Frame
	    local Cell: Frame = Instance.new("Frame")
	    Cell.Name = `Slot{Index}`
	    Cell.BackgroundTransparency = 1
	    Cell.LayoutOrder = Index
	    Cell.Parent = Row
	    local Tile: Frame = Instance.new("Frame")
	    Tile.Name = "Tile"
	    Tile.BackgroundColor3 = Color3.fromRGB(29, 36, 46)
	    Tile.BorderMode = Enum.BorderMode.Inset
	    Tile.BorderSizePixel = 1
	    Tile.Size = UDim2.fromScale(1, 1)
	    Tile.Parent = Cell
	    local Icon: ImageLabel = Instance.new("ImageLabel")
	    Icon.Name = "Icon"
	    Icon.AnchorPoint = Vector2.new(0.5, 0)
	    Icon.BackgroundTransparency = 1
	    Icon.Position = UDim2.fromScale(0.5, 0.15)
	    Icon.Size = UDim2.fromScale(0.8, 0.8)
	    Icon.Parent = Tile
	    local Amount: TextLabel = Instance.new("TextLabel")
	    Amount.Name = "Amount"
	    Amount.AnchorPoint = Vector2.new(1, 1)
	    Amount.BackgroundTransparency = 1
	    Amount.FontFace = Font.fromName("RobotoMono", Enum.FontWeight.Bold)
	    Amount.Position = UDim2.new(1, -2, 1, 0)
	    Amount.Size = UDim2.new(1, -2, 0, 12)
	    Amount.Text = ""
	    Amount.TextColor3 = Color3.new(1, 1, 1)
	    Amount.TextSize = 11
	    Amount.TextStrokeTransparency = 0.5
	    Amount.TextXAlignment = Enum.TextXAlignment.Right
	    Amount.ZIndex = 2
	    Amount.Parent = Tile
	    Tiles[Index] = Cell
	
	    return Cell
	end
	
	local function SetTile(Cell: Frame, Item, Held: boolean)
	    local Tile: Frame = Cell.Tile
	    Cell.Visible = true
	    Tile.Icon.Image = bedwars.getIcon(Item, true)
	    Tile.Amount.Text = (Item.amount or 1) > 1 and tostring(Item.amount) or ""
	    Tile.BackgroundTransparency = Held and 0.2 or 0.4
	    Tile.BorderColor3 = Held and Color3.new(1, 1, 1) or Color3.fromRGB(114, 126, 172)
	
	    if Lifted[Cell] ~= Held then
	        Lifted[Cell] = Held
	        Tween:Tween(Tile, TweenInfo.new(0.12), {
	            Position = UDim2.fromOffset(0, Held and -Lift or 0)
	        })
	    end
	end
	
	local function GetItems(Inventory)
	    local Worn: {[Instance]: boolean} = {}
	    local Items = {}
	
	    for _, v: any in Inventory.armor do
	        if type(v) == "table" and v.tool then
	            Worn[v.tool] = true
	        end
	    end
	
	    for _, v: any in Inventory.items do
	        if v.tool and not Worn[v.tool] then
	            table.insert(Items, v)
	        end
	    end
	
	    table.sort(Items, function(First, Second): boolean
	        local FirstTime: number = First.addedToBackpackTime or 0
	        local SecondTime: number = Second.addedToBackpackTime or 0
	        if FirstTime ~= SecondTime then
	            return FirstTime < SecondTime
	        end
	
	        return First.itemType < Second.itemType
	    end)
	
	    return Items
	end
	
	local function Refresh(Target)
	    if not Row or not Card.Visible or not TargetInfoOverlay.Object.Visible then
	        return
	    end
	
	    local Player: Player? = Target and Target.Player or nil
	    local Inventory = Player and bedwars.getInventory and bedwars.getInventory(Player) or nil
	    local Items = Inventory and GetItems(Inventory) or {}
	    local Hand = Inventory and Inventory.hand or nil
	
	    for i: number, v: any in Items do
	        SetTile(Tiles[i] or CreateTile(i), v, Hand ~= nil and v.tool == Hand.tool)
	    end
	
	    for i: number = #Items + 1, #Tiles do
	        Tiles[i].Visible = false
	    end
	
	    local Rows: number = math.ceil(#Items / Columns)
	    Row.Size = UDim2.new(1, 0, 0, math.max(Rows * (TileSize + TilePadding) - TilePadding, 0))
	    Row.Visible = #Items > 0
	end
	
	local function Clear()
	    if Row then
	        Row:Destroy()
	        Row = nil
	    end
	
	    table.clear(Tiles)
	    table.clear(Lifted)
	end
	
	ShowInventory = TargetInfoOverlay:CreateToggle({
	    Name = "Show Inventory",
	    Function = function(Callback: boolean)
	        if not Callback then
	            Clear()
	            return
	        end
	
	        if not Row then
	            CreateRow()
	        end
	
	        if Looping then
	            return
	        end
	        Looping = true
	
	        task.spawn(function()
	            repeat
	                Refresh(TargetInfo.LastTarget)
	                task.wait(0.1)
	            until not ShowInventory.Enabled or vape.Loaded == nil
	
	            Looping = false
	        end)
	    end,
	    Tooltip = "Shows the target's inventory under the card in tiles like the BedWars hotbar. The item they are holding is lifted like your selected slot, and the armor they are wearing is left out."
	})
	vape:Clean(TargetInfo.TargetChanged:Connect(function(Target)
	    Refresh(Target)
	end))
end)

Run(function()
	local ComboCounter
	local ComboComparator
	local DamageComparator
	local Combo, Comparator = 0, 0
	local Dealt, DealtHits, Taken, TakenHits = 0, 0, 0, 0
	
	ComboCounter = TargetInfo:CreateStat({
	    Name = "Combo Counter",
	    Icon = GetVapeAsset("GyuvapeBedwarsCheat/assets/new/combo_display.png"),
	    IconSize = UDim2.fromOffset(14, 12),
	    Default = true,
	    Tooltip = "Shows how many hits in a direct row you have landed on, or taken from, the target."
	})
	ComboComparator = TargetInfo:CreateStat({
	    Name = "Combo Comparator",
	    Icon = GetVapeAsset("GyuvapeBedwarsCheat/assets/new/sword_header.png"),
	    IconSize = UDim2.fromOffset(12, 12),
	    Signed = true,
	    Tooltip = "Measures how many hits you have landed compared to the target."
	})
	DamageComparator = TargetInfo:CreateStat({
	    Name = "Damage Comparator",
	    Default = true,
	    Signed = true,
	    Tint = true,
	    Tooltip = "Measures the strength of the target compared to yourself, from the damage each of you lands per hit."
	})
	vape:Clean(TargetInfo.TargetChanged:Connect(function()
	    Combo, Comparator = 0, 0
	    Dealt, DealtHits, Taken, TakenHits = 0, 0, 0, 0
	end))
	vape:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	    local Target = TargetInfo.LastTarget
	    if not Target or not Target.Character then return end
	
	    local Landed: boolean = DamageTable.fromEntity == LocalPlayer.Character and DamageTable.entityInstance == Target.Character
	    local Received: boolean = DamageTable.entityInstance == LocalPlayer.Character and DamageTable.fromEntity == Target.Character
	    if not Landed and not Received then return end
	
	    if Landed then
	        Combo = Combo >= 0 and Combo + 1 or 0
	        Comparator += 1
	        Dealt += DamageTable.damage or 0
	        DealtHits += 1
	    else
	        Combo = Combo <= 0 and Combo - 1 or 0
	        Comparator -= 1
	        Taken += DamageTable.damage or 0
	        TakenHits += 1
	    end
	
	    TargetInfo:SetStat(ComboCounter, Combo)
	    TargetInfo:SetStat(ComboComparator, Comparator)
	    TargetInfo:SetStat(DamageComparator, math.clamp(math.round((DealtHits > 0 and Dealt / DealtHits or 0) - (TakenHits > 0 and Taken / TakenHits or 0)), -9, 9))
	end))
end)

Run(function()
	local TeamUpgrades
	local OwnTeam
	local BedUpgrades
	local Color
	local Transparency
	local Scale
	local Reference = {}
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local Numerals: {string} = {"I", "II", "III", "IV", "V"}
	
	local function GetAnchor(Object: Instance)
	    return Object:IsA("Model") and (Object.PrimaryPart or Object:FindFirstChildWhichIsA("BasePart")) or Object
	end
	
	local function GetText(Team: string)
	    local State = bedwars.Store:getState().Bedwars
	    local Upgrades = State.teamUpgrades[Team] or {}
	    local Bought: {string} = {}
	
	    for UpgradeId: string, v: any in bedwars.TeamUpgradeMeta do
	        local Tier: number? = Upgrades[UpgradeId]
	        if Tier and Tier > 0 then
	            table.insert(Bought, `{v.name} {Numerals[Tier] or Tier}`)
	        end
	    end
	
	    table.sort(Bought)
	
	    if BedUpgrades.Enabled then
	        local Bed = State.bedTeamUpgrades[Team] or {}
	        if Bed.bed_shield then
	            table.insert(Bought, "Bed Shield")
	        end
	        if Bed.bed_alarm then
	            table.insert(Bought, "Bed Alarm")
	        end
	    end
	
	    return `Team {Team} | {#Bought > 0 and table.concat(Bought, ", ") or "No upgrades"}`
	end
	
	local function Added(Object: Instance, Tag: string)
	    local Team: string? = Tag:match("^(%d+)_TeamOreGenerator")
	    local Anchor: Instance? = Team and GetAnchor(Object)
	    if not Anchor then return end
	    if not OwnTeam.Enabled and Team == LocalPlayer:GetAttribute("Team") then return end
	
	    local NameTag: TextLabel = Instance.new("TextLabel")
	    NameTag.Name = `Team{Team}`
	    NameTag.Text = GetText(Team)
	    NameTag.TextSize = 14 * Scale.Value
	    NameTag.Font = Enum.Font.Arial
	    local Size: Vector2 = GetFontBounds(NameTag.Text, NameTag.TextSize, NameTag.FontFace)
	    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	    NameTag.AnchorPoint = Vector2.new(0.5, 1)
	    NameTag.BackgroundColor3 = Color3.new()
	    NameTag.BackgroundTransparency = Transparency.Value
	    NameTag.BorderSizePixel = 0
	    NameTag.Visible = false
	    NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    NameTag.Parent = Folder
	    Reference[Anchor] = {Label = NameTag, Team = Team}
	end
	
	local function Refresh()
	    for _, v: {Label: TextLabel, Team: string} in Reference do
	        v.Label.Text = GetText(v.Team)
	        local Size: Vector2 = GetFontBounds(v.Label.Text, v.Label.TextSize, v.Label.FontFace)
	        v.Label.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	    end
	end
	
	TeamUpgrades = vape.Categories.Render:CreateModule({
	    Name = "TeamUpgrades",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, Tag: string in CollectionService:GetAllTags() do
	                if Tag:match("^%d+_TeamOreGenerator$") then
	                    for _, v: Instance in CollectionService:GetTagged(Tag) do
	                        Added(v, Tag)
	                    end
	                    TeamUpgrades:Clean(CollectionService:GetInstanceAddedSignal(Tag):Connect(function(Object: Instance)
	                        Added(Object, Tag)
	                    end))
	                end
	            end
	
	            TeamUpgrades:Clean(RunService.PreRender:Connect(function()
	                for Anchor: BasePart, v: {Label: TextLabel, Team: string} in Reference do
	                    if not Anchor.Parent then
	                        v.Label:Destroy()
	                        Reference[Anchor] = nil
	                        continue
	                    end
	
	                    local ScreenPos, Visible = Camera:WorldToViewportPoint(Anchor.Position + Vector3.new(0, 4, 0))
	                    v.Label.Visible = Visible
	                    if not Visible then continue end
	                    v.Label.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)
	                end
	            end))
	
	            repeat
	                Refresh()
	                task.wait(0.5)
	            until not TeamUpgrades.Enabled
	        else
	            for Anchor: Instance, v: {Label: TextLabel, Team: string} in Reference do
	                v.Label:Destroy()
	                Reference[Anchor] = nil
	            end
	        end
	    end,
	    Tooltip = "Puts every teams upgrades over their generator, and whether their bed is shielded or alarmed which the game never shows you anywhere"
	})
	
	OwnTeam = TeamUpgrades:CreateToggle({
	    Name = "Show own team",
	    Function = function()
	        if TeamUpgrades.Enabled then
	            TeamUpgrades:Toggle()
	            TeamUpgrades:Toggle()
	        end
	    end
	})
	BedUpgrades = TeamUpgrades:CreateToggle({
	    Name = "Bed upgrades",
	    Default = true,
	    Function = function()
	        if TeamUpgrades.Enabled then
	            Refresh()
	        end
	    end,
	    Tooltip = "Bed shield and bed alarm, which no part of the games own UI displays"
	})
	Color = TeamUpgrades:CreateColorSlider({
	    Name = "Text Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        for _, v: {Label: TextLabel, Team: string} in Reference do
	            v.Label.TextColor3 = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end,
	    DefaultSat = 0,
	    DefaultValue = 1
	})
	Transparency = TeamUpgrades:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Default = 0.5,
	    Function = function(Value: number)
	        for _, v: {Label: TextLabel, Team: string} in Reference do
	            v.Label.BackgroundTransparency = Value
	        end
	    end
	})
	Scale = TeamUpgrades:CreateSlider({
	    Name = "Scale",
	    Min = 0.1,
	    Max = 1.5,
	    Decimal = 10,
	    Default = 1,
	    Function = function(Value: number)
	        for _, v: {Label: TextLabel, Team: string} in Reference do
	            v.Label.TextSize = 14 * Value
	            local Size: Vector2 = GetFontBounds(v.Label.Text, v.Label.TextSize, v.Label.FontFace)
	            v.Label.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	        end
	    end
	})
end)

Run(function()
	local TrapESP
	local Traps
	local Distance
	local Owner
	local Transparency
	local Scale
	local Color = {}
	local Reference = {}
	local Folder: Folder?
	
	local Names: {[string]: string} = {
	    ["glue_trap"] = "Gloop",
	    ["grave_trap"] = "Grave",
	    ["grave_trap_block"] = "Grave",
	    ["invisible_landmine"] = "Landmine",
	    ["lucky_block_trap"] = "Lucky Trap",
	    ["snap_trap"] = "Snap Trap",
	    ["spike_trap"] = "Spikes",
	    ["tesla_trap"] = "Tesla"
	}
	
	local function Added(Block: Instance)
	    if Reference[Block] or not Block:IsA("BasePart") then return end
	
	    local Label: string? = Names[Block.Name]
	    if not Label or not table.find(Traps.ListEnabled, Label) then return end
	
	    local NameTag: TextLabel = Instance.new("TextLabel")
	    NameTag.Name = Label
	    NameTag.Text = Label
	    NameTag.TextSize = 14 * Scale.Value
	    NameTag.FontFace = UIPallet.Font
	    local Size: Vector2 = GetFontBounds(NameTag.Text, NameTag.TextSize, NameTag.FontFace)
	    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	    NameTag.AnchorPoint = Vector2.new(0.5, 1)
	    NameTag.BackgroundColor3 = Color3.new()
	    NameTag.BackgroundTransparency = Transparency.Value
	    NameTag.BorderSizePixel = 0
	    NameTag.Visible = false
	    NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    NameTag.Parent = Folder
	    Reference[Block] = NameTag
	end
	
	local function IsMine(Block: Instance)
	    local UserId: number? = Block:GetAttribute("PlacedByUserId")
	    if not UserId or UserId == 0 then
	        return false
	    end
	    if UserId == LocalPlayer.UserId then
	        return true
	    end
	
	    local Placer: Player? = Players:GetPlayerByUserId(UserId)
	    return Placer ~= nil and Placer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team")
	end
	
	TrapESP = vape.Categories.Render:CreateModule({
	    Name = "TrapESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            if not Folder then
	                if vape.ThreadFix then
	                    setthreadidentity(8)
	                end
	                Folder = Instance.new("Folder")
	                Folder.Parent = vape.gui
	            end
	
	            for _, v: Instance in CollectionService:GetTagged("block") do
	                Added(v)
	            end
	
	            TrapESP:Clean(CollectionService:GetInstanceAddedSignal("block"):Connect(Added))
	            TrapESP:Clean(CollectionService:GetInstanceRemovedSignal("block"):Connect(function(Block: Instance)
	                if Reference[Block] then
	                    Reference[Block]:Destroy()
	                    Reference[Block] = nil
	                end
	            end))
	
	            TrapESP:Clean(RunService.PreRender:Connect(function()
	                local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
	                for Block: BasePart, NameTag: TextLabel in Reference do
	                    if not Block.Parent then
	                        NameTag:Destroy()
	                        Reference[Block] = nil
	                        continue
	                    end
	
	                    if not Owner.Enabled and IsMine(Block) then
	                        NameTag.Visible = false
	                        continue
	                    end
	
	                    local ScreenPos, Visible = Camera:WorldToViewportPoint(Block.Position + Vector3.new(0, 2, 0))
	                    NameTag.Visible = Visible
	                    if not Visible then continue end
	
	                    local Text: string = Distance.Enabled and LocalPosition and `{NameTag.Name} | {((LocalPosition - Block.Position).Magnitude) // 1}m` or NameTag.Name
	                    if NameTag.Text ~= Text then
	                        NameTag.Text = Text
	                        local Size: Vector2 = GetFontBounds(Text, NameTag.TextSize, NameTag.FontFace)
	                        NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	                    end
	                    NameTag.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)
	                end
	            end))
	        else
	            for Block: Instance, NameTag: TextLabel in Reference do
	                NameTag:Destroy()
	                Reference[Block] = nil
	            end
	        end
	    end,
	    Tooltip = "Shows every trap on the map through walls, landmines included, which have no visual at all"
	})
	
	Distance = TrapESP:CreateToggle({
	    Name = "Distance",
	    Default = true
	})
	Owner = TrapESP:CreateToggle({
	    Name = "Your traps",
	    Default = true,
	    Tooltip = "Also shows the ones your own team placed"
	})
	Scale = TrapESP:CreateSlider({
	    Name = "Scale",
	    Min = 0.5,
	    Max = 3,
	    Default = 1,
	    Decimal = 10,
	    Function = function(Value: number)
	        for _, v: TextLabel in Reference do
	            v.TextSize = 14 * Value
	            local Size: Vector2 = GetFontBounds(v.Text, v.TextSize, v.FontFace)
	            v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	        end
	    end
	})
	Transparency = TrapESP:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Default = 0.5,
	    Decimal = 100,
	    Function = function(Value: number)
	        for _, v: TextLabel in Reference do
	            v.BackgroundTransparency = Value
	        end
	    end
	})
	Color = TrapESP:CreateColorSlider({
	    Name = "Text Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        for _, v: TextLabel in Reference do
	            v.TextColor3 = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end,
	    DefaultHue = 0,
	    DefaultSat = 0.75,
	    Darker = true
	})
	Traps = TrapESP:CreateTextList({
	    Name = "Traps",
	    Function = function()
	        if TrapESP.Enabled then
	            TrapESP:Toggle()
	            TrapESP:Toggle()
	        end
	    end,
	    Default = {
	        "Gloop",
	        "Grave",
	        "Landmine",
	        "Lucky Trap",
	        "Snap Trap",
	        "Spikes",
	        "Tesla"
	    },
	    Darker = true
	})
end)

Run(function()
	local AntiEffect
	local Dizzy
	local Fear
	local Vignettes
	local OldVignettes: boolean?
	
	AntiEffect = vape.Categories.Utility:CreateModule({
	    Name = "AntiEffect",
	    Function = function(Callback: boolean)
	        if Callback then
	            if Dizzy.Enabled then
	                RunService:UnbindFromRenderStep("dizzy-status")
	            end
	
	            if Fear.Enabled then
	                RunService:UnbindFromRenderStep("werewolf-fear-status")
	            end
	
	            if Vignettes.Enabled then
	                OldVignettes = bedwars.VignetteController.enableOnScreenEffects
	                bedwars.VignetteController.enableOnScreenEffects = false
	                bedwars.VignetteController:destroyAllVignettes()
	            end
	
	            local Connection = bedwars.SyncEvents.StatusEffectAdded:setPriority(1000):connect(function(Event)
	                if Event.entityInstance ~= LocalPlayer.Character then
	                    return
	                end
	
	                if Dizzy.Enabled and Event.statusEffect == bedwars.StatusEffectMeta.DIZZY then
	                    RunService:UnbindFromRenderStep("dizzy-status")
	                end
	
	                if Fear.Enabled and Event.statusEffect == bedwars.StatusEffectMeta.WEREWOLF_FEAR then
	                    RunService:UnbindFromRenderStep("werewolf-fear-status")
	                end
	            end)
	            AntiEffect:Clean(function()
	                Connection:Destroy()
	            end)
	        else
	            if OldVignettes ~= nil then
	                bedwars.VignetteController.enableOnScreenEffects = OldVignettes
	                OldVignettes = nil
	            end
	        end
	    end,
	    Tooltip = "Throws away the parts of a debuff the game plays on your own client"
	})
	
	Dizzy = AntiEffect:CreateToggle({
	    Name = "Dizzy",
	    Default = true,
	    Tooltip = "Stops the dizzy toad swinging your walk direction around, the slow itself is on the server"
	})
	Fear = AntiEffect:CreateToggle({
	    Name = "Werewolf fear",
	    Default = true,
	    Tooltip = "Stops the werewolf tail walking you away from it"
	})
	Vignettes = AntiEffect:CreateToggle({
	    Name = "Vignettes",
	    Function = function(Callback: boolean)
	        if AntiEffect.Enabled and Callback then
	            OldVignettes = bedwars.VignetteController.enableOnScreenEffects
	            bedwars.VignetteController.enableOnScreenEffects = false
	            bedwars.VignetteController:destroyAllVignettes()
	        elseif AntiEffect.Enabled and OldVignettes ~= nil then
	            bedwars.VignetteController.enableOnScreenEffects = OldVignettes
	            OldVignettes = nil
	        end
	    end,
	    Default = true,
	    Tooltip = "Clears the coloured screen border frozen, decay, soaked and the rest put over your view"
	})
end)

Run(function()
	local AntiLasso
	local Chance
	local Check
	local Watching = setmetatable({}, {__mode = "k"})
	
	local function Added(Character: Model)
	    if Watching[Character] then
	        return
	    end
	
	    Watching[Character] = Character.ChildAdded:Connect(function(Child: Instance)
	        if Child:IsA("Accessory") and Child:FindFirstChild("Rope") and Random.new(os.clock()):NextNumber(1, 100) < Chance.Value and (not Check.Enabled or Entity.EntityPosition({
	            Range = 50,
	            Part = "RootPart",
	            Players = true
	        })) then
	            Character.PrimaryPart.Anchored = true
	            Child.Destroying:Once(function()
	                task.wait(0.5)
	                Character.PrimaryPart.Anchored = false
	            end)
	        end
	    end)
	end
	
	AntiLasso = vape.Categories.Utility:CreateModule({
	    Name = "AntiLasso",
	    Function = function(Callback: boolean)
	        if Callback then
	            AntiLasso:Clean(Entity.Events.LocalAdded:Connect(function(Ent)
	                task.delay(1, function()
	                    Added(Ent.Character)
	                end)
	            end))
	            if Entity.isAlive then
	                Added(LocalPlayer.Character)
	            end
	        end
	    end,
	    Tooltip = "Prevents you from getting pulled by lasso projectile."
	})
	
	Chance = AntiLasso:CreateSlider({
	    Name = "Chance",
	    Min = 0,
	    Max = 100,
	    Default = 100,
	    Suffix = "%"
	})
	Check = AntiLasso:CreateToggle({Name = "Only when targeting"})
end)

Run(function()
	local AntiSuffocate
	local Mode
	local Height
	
	local Offsets: {Vector3} = {
	    Vector3.new(0, 3, 0),
	    Vector3.new(3, 0, 0),
	    Vector3.new(-3, 0, 0),
	    Vector3.new(0, 0, 3),
	    Vector3.new(0, 0, -3),
	    Vector3.new(0, -3, 0)
	}
	
	local function GetEscape(Position: Vector3): Vector3?
	    for _, v: Vector3 in Offsets do
	        local Target: Vector3 = Position + v
	        if not GetPlacedBlock(Target) and not GetPlacedBlock(Target + Vector3.new(0, 3, 0)) then
	            return Target
	        end
	    end
	    return nil
	end
	
	AntiSuffocate = vape.Categories.Utility:CreateModule({
	    Name = "AntiSuffocate",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and Store.matchState == 1 then
	                    local Root: BasePart = Entity.character.RootPart
	                    local HeadPosition: Vector3 = Root.Position + Vector3.new(0, Height.Value, 0)
	                    if GetPlacedBlock(HeadPosition) then
	                        if Mode.Value == "Break" then
	                            local Block: BasePart? = GetPlacedBlock(HeadPosition)
	                            if Block then
	                                bedwars.breakBlock(Block, true, true)
	                            end
	                        else
	                            local Escape: Vector3? = GetEscape(RoundPosition(HeadPosition))
	                            if Escape then
	                                Root.CFrame = CFrame.new(Escape - Vector3.new(0, Height.Value, 0)) * (Root.CFrame - Root.Position)
	                                Root.AssemblyLinearVelocity = Vector3.zero
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AntiSuffocate.Enabled
	        end
	    end,
	    Tooltip = "Gets you out of a block that someone placed on top of you before it suffocates you"
	})
	
	Mode = AntiSuffocate:CreateDropdown({
	    Name = "Mode",
	    List = {"Move", "Break"},
	    Tooltip = "Move - shifts you into the nearest open cell\nBreak - breaks the block you are stuck in"
	})
	Height = AntiSuffocate:CreateSlider({
	    Name = "Check height",
	    Min = 0,
	    Max = 4,
	    Default = 1.5,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "How far above your root the check looks, 1.5 is head level"
	})
end)

Run(function()
	local AutoBalloon
	
	AutoBalloon = vape.Categories.Utility:CreateModule({
	    Name = "AutoBalloon",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat task.wait() until Store.matchState ~= 0 or (not AutoBalloon.Enabled)
	            if not AutoBalloon.Enabled then
	                return
	            end
	
	            local LowestPoint: number = math.huge
	            for _, v: BasePart in Store.blocks do
	                local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50
	                if Point < LowestPoint then
	                    LowestPoint = Point
	                end
	            end
	
	            repeat
	                if Entity.isAlive then
	                    if Entity.character.RootPart.Position.Y < LowestPoint and (LocalPlayer.Character:GetAttribute("InflatedBalloons") or 0) < 3 then
	                        local Balloon = GetItem("balloon")
	                        if Balloon then
	                            for _ = 1, 3 do
	                                bedwars.BalloonController:inflateBalloon()
	                            end
	                        end
	                        task.wait(0.1)
	                    end
	                end
	                task.wait(0.1)
	            until not AutoBalloon.Enabled
	        end
	    end,
	    Tooltip = "Inflates when you fall into the void"
	})
end)

Run(function()
	local AutoBlockUp
	local LimitItem
	local LastPlace: number = 0
	local Up: boolean = false
	
	AutoBlockUp = vape.Categories.Utility:CreateModule({
	    Name = "AutoBlockUp",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoBlockUp:Clean(RunService.Heartbeat:Connect(function()
	                if Entity.isAlive and Up then
	                    local Item: string?
	                    if Store.hand.toolType == "block" and (Store.hand.amount or 0) > 0 then
	                        Item = Store.hand.tool and Store.hand.tool.Name
	                    elseif not LimitItem.Enabled then
	                        for _, v: any in Store.inventory.inventory.items do
	                            local Meta = bedwars.ItemMeta[v.itemType]
	                            if Meta and Meta.block and (v.amount or 0) > 0 then
	                                Item = v.itemType
	                                break
	                            end
	                        end
	                    end
	
	                    if Item then
	                        local Position: Vector3 = RoundPosition(Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))
	                        if tick() >= LastPlace and not GetPlacedBlock(Position) then
	                            LastPlace = tick() + 0.15
	                            bedwars.placeBlock(Position, Item, false)
	                        end
	
	                        Entity.character.RootPart.AssemblyLinearVelocity = Vector3.new(Entity.character.RootPart.AssemblyLinearVelocity.X, 35, Entity.character.RootPart.AssemblyLinearVelocity.Z)
	                    end
	                end
	            end))
	            AutoBlockUp:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)
	                if not UserInputService:GetFocusedTextBox() and (Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA) then
	                    Up = true
	                end
	            end))
	            AutoBlockUp:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
	                if Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.ButtonA then
	                    Up = false
	                    Entity.character.RootPart.AssemblyLinearVelocity = Vector3.new(Entity.character.RootPart.AssemblyLinearVelocity.X, 0, Entity.character.RootPart.AssemblyLinearVelocity.Z)
	                end
	            end))
	
	            local TouchGui = UserInputService.TouchEnabled and LocalPlayer.PlayerGui:FindFirstChild("TouchGui")
	            local JumpButton = TouchGui and TouchGui:FindFirstChild("JumpButton", true)
	            if JumpButton then
	                AutoBlockUp:Clean(JumpButton:GetPropertyChangedSignal("ImageRectOffset"):Connect(function()
	                    Up = JumpButton.ImageRectOffset.X == 146
	                end))
	            end
	        end
	    end,
	    Tooltip = "Places a block beneath you while holding jump so you can tower up instantly"
	})
	
	LimitItem = AutoBlockUp:CreateToggle({Name = "Limit to items"})
end)

Run(function()
	local AutoCollect
	local Collectables
	local Range
	local Delay
	local Animation
	
	local Request = bedwars.Handler:Get("CollectCollectableEntity")
	local Cooldowns: {[Instance]: number} = {}
	
	AutoCollect = vape.Categories.Utility:CreateModule({
