	        "alchemy_crystal",
	        "crystalheart_seed",
	        "forest_environment_plant",
	        "jailor_soul",
	        "murder_coin",
	        "shadow_coin",
	        "soulvine_seed",
	        "spirit_gardener_energy",
	        "spirit_gardener_seeds",
	        "tearbloom_seed"
	    },
	    Darker = true,
	    Tooltip = "Collectable tags to pick up, stars and hidden metal have their own modules"
	})
end)

Run(function()
	local AutoCounter
	local Range
	local Limit
	local AutoSwitch = {}
	
	AutoCounter = vape.Categories.Utility:CreateModule({
	    Name = "AutoCounterTNT",
	    Function = function(Callback: boolean)
	        if Callback then
	            local TNTs, Placed = {}, {}
	            AutoCounter:Clean(workspace.ChildAdded:Connect(function(Child: Instance)
	                if Child.Name == "tnt" then
	                    table.insert(TNTs, Child)
	                    Child.Destroying:Once(function()
	                        local Index: number? = table.find(TNTs, Child)
	                        if Index then
	                            table.remove(TNTs, Index)
	                        end
	                    end)
	                end
	            end))
	            repeat
	                for Position: Vector3, Expiry: number in Placed do
	                    if Expiry <= tick() then
	                        Placed[Position] = nil
	                    end
	                end
	                if Entity.isAlive then
	                    local Item: Instance?
	                    if Limit.Enabled then
	                        Item = Store.hand.tool and Store.hand.tool.Name == "tnt" and Store.hand.tool or nil
	                    else
	                        local Held = GetItem("tnt")
	                        Item = Held and Held.tool or nil
	                    end
	
	                    if Item then
	                        local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                        for _, v: BasePart in TNTs do
	                            local RoundedPosition: Vector3 = Vector3.new(math.round(v.Position.X), math.round(v.Position.Y), math.round(v.Position.Z))
	                            if v.AssemblyLinearVelocity.Y >= 0 and not Placed[RoundedPosition] and (LocalPosition - v.Position).Magnitude <= Range.Value then
	                                if not Limit.Enabled and AutoSwitch.Enabled then
	                                    local Hotbar: number? = GetHotbar(Item)
	                                    SwitchItem(Item)
	                                    if Hotbar then
	                                        HotbarSwitch(Hotbar)
	                                    end
	                                end
	                                Placed[RoundedPosition] = tick() + 3
	                                task.spawn(bedwars.placeBlock, v.Position, Item.Name)
	                                task.wait(0.12)
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoCounter.Enabled
	        end
	    end,
	    Tooltip = "Automatically places tnt on opponent's tnt"
	})
	
	AutoCounter:CreateDropdown({
	    Name = "Mode",
	    List = {"Toggle", "On key"},
	    Default = "Toggle"
	})
	Range = AutoCounter:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 30
	})
	Limit = AutoCounter:CreateToggle({
	    Name = "Limit to item",
	    Function = function(Callback: boolean)
	        if AutoSwitch.Object then
	            AutoSwitch.Object.Visible = not Callback
	        end
	    end
	})
	AutoSwitch = AutoCounter:CreateToggle({
	    Name = "Auto Switch",
	    Function = function(Callback: boolean)
	        Limit.Object.Visible = not Callback
	    end,
	    Default = true
	})
end)

Run(function()
	local AutoEnchant
