end)

Run(function()
	local AutoHonor
	local Delay
	
	local Honored = {}
	local function Honor()
	    local PlayerList, Team = Players:GetPlayers(), LocalPlayer:GetAttribute("Team")
	    table.sort(PlayerList, function(A: Player, B: Player)
	        return A:GetAttribute("Team") == Team and B:GetAttribute("Team") ~= Team
	    end)
	    for _, v: Player in PlayerList do
	        local TeamId = v:GetAttribute("Team")
	        if v ~= LocalPlayer and TeamId and not Honored[TeamId] and (LocalPlayer:GetAttribute(TeamId == Team and "HonorPointsLeftToGiveToAllies" or "HonorPointsLeftToGiveToOpponents") or 0) > 0 then
	            Honored[TeamId] = true
	            bedwars.HonorController:honorPlayer(v.UserId):await()
	            task.wait(Delay.Value)
	        end
	    end
	end
	
	AutoHonor = vape.Categories.Utility:CreateModule({
	    Name = "AutoHonor",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoHonor:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.finalKill and DeathTable.entityInstance == LocalPlayer.Character and #bedwars.Store:getState().Party.members <= 0 and Store.matchState ~= 2 then
	                    Honor()
	                end
	            end))
	            AutoHonor:Clean(VapeEvents.MatchEndEvent.Event:Connect(Honor))
	        end
	    end,
	    Tooltip = "Automatically honor your teammates"
	})
	
	Delay = AutoHonor:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.1
	})
end)

Run(function()
	local AutoMiner
	local Delay
	local Animation
	local Range
	
	local Legit: number = GetFunctionRange(bedwars.MinerController.setupMinerPrompts) or 0
	local Session = nil
	
	AutoMiner = vape.Categories.Utility:CreateModule({
	    Name = "AutoMiner",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Petrified = Collection("petrified-player", AutoMiner)
	            local Tries: {[Instance]: number} = setmetatable({}, {__mode = "k"})
	            local LastTry: {[Instance]: number} = setmetatable({}, {__mode = "k"})
	            local Current = {}
	            local Cooldown: number = 0
	            Session = Current
	
	            repeat
	                if Entity.isAlive and tick() - Cooldown >= math.max(Delay.Value, 0.25) then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local MyTeam = bedwars.Store:getState().Game.myTeam
	                    local RetryGap: number = Delay.Value + 1
	                    local Best, BestTries, BestDistance = nil, math.huge, math.huge
	                    for _, v: Instance in Petrified do
	                        local Root: BasePart? = if not v.Parent then nil elseif v:IsA("Model") then v.PrimaryPart elseif v:IsA("BasePart") then v else nil
	                        if not Root or not v:GetAttribute("PetrifyId") then
	                            continue
	                        end
	                        if MyTeam and v:GetAttribute("Team") == MyTeam.id then
	                            continue
	                        end
	                        if LastTry[v] and (tick() - LastTry[v]) < RetryGap then
	                            continue
	                        end
	
	                        local Distance: number = (LocalPosition - Root.Position).Magnitude
	                        local Count: number = Tries[v] or 0
	                        if Distance <= Range.Value and (Count < BestTries or (Count == BestTries and Distance < BestDistance)) then
	                            Best, BestTries, BestDistance = v, Count, Distance
	                        end
	                    end
	
	                    if Best then
	                        local Target: Instance = Best
	                        local PetrifyId = Target:GetAttribute("PetrifyId")
	                        Tries[Target] = BestTries + 1
	                        LastTry[Target] = tick()
	                        if Animation.Enabled then
	                            bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.MINER_MINE_STONE)
	                        end
	
	                        task.delay(Delay.Value, function()
	                            if AutoMiner.Enabled and Target.Parent then
	                                bedwars.Handler:Get("DestroyPetrifiedPlayer"):Fire("SendToServer", {
	                                    petrifyId = PetrifyId
	                                })
	                            end
	                        end)
	                        Cooldown = tick()
	                    end
	                end
	                task.wait(0.1)
	            until not AutoMiner.Enabled or Session ~= Current
	        end
	    end,
	    Tooltip = "Automatically mines the closest enemy petrified player within range"
	})
	
	Range = AutoMiner:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = 12,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	AutoMiner:CreateButton({
	    Name = "Sync to legit range",
	    Function = function()
	        Range:SetValue(Legit)
	    end
	})
	Delay = AutoMiner:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Default = 0.1,
	    Decimal = 10,
	    Suffix = "seconds"
	})
	Animation = AutoMiner:CreateToggle({
	    Name = "Animation",
	    Default = true
	})
end)

Run(function()
	local AutoPearl
	local Legit
	local Back
	local Check
	local LandCheck
	local BackDelay
	local Limit
	local ClutchRange
	local Cooldown
	local LastThrow: number = 0
	local Attempted: boolean = false
	local InFlight
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local function GetLaunch(From: Vector3, Spot: Vector3): Vector3?
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local AimPosition: Vector3? = PredictionLib.SolveTrajectory(From, Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2, Spot, Vector3.zero, workspace.Gravity, 0, 0, nil, false, nil, nil, nil, true)
	    return AimPosition and CFrame.lookAt(From, AimPosition).LookVector * Meta.launchVelocity or nil
	end
	
	local function CanReach(From: Vector3, Spot: Vector3): boolean
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local Speed: number = Meta.launchVelocity
	    local Gravity: number = Meta.gravitationalAcceleration or 196.2
	    local Offset: Vector3 = Spot - From
	    local Flat: number = Vector2.new(Offset.X, Offset.Z).Magnitude
	    return Speed ^ 4 - Gravity * (Gravity * Flat ^ 2 + 2 * Offset.Y * Speed ^ 2) >= 0
	end
	
	local function FirePearl(Spot: Vector3, Item): boolean
	    if not Entity.isAlive or not GetLaunch(Entity.character.RootPart.Position, Spot) then
	        return false
	    end
	
	    local Hotbar, OldHand = GetHotbar(Item.tool), Store.hand
	    local PreviousThrow: number = LastThrow
	    local ThrowUntil: number = tick() + Cooldown.Value
	    LastThrow = ThrowUntil
	
	    SwitchItem(Item.tool)
	    if Legit.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Direction: Vector3? = Entity.isAlive and GetLaunch(Position, Spot) or nil
	    local Landed: boolean = false
	
	    if Direction then
	        local Meta = bedwars.ProjectileMeta.telepearl
	        local Id: string = HttpService:GenerateGUID(true)
	        local Projectile = bedwars.ProjectileController:createLocalProjectile(Meta, "telepearl", "telepearl", Position, Id, Direction, {drawDurationSeconds = 1})
	        InFlight = Projectile
	
	        bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	            Item.tool,
	            "telepearl",
	            "telepearl",
	            Position,
	            Position,
	            Direction,
	            Id,
	            {
	                drawDurationSeconds = 1,
	                shotId = HttpService:GenerateGUID(false)
	            },
	            workspace:GetServerTimeNow() - 0.045
	        ):andThen(function(Result)
	            if Result then
	                Result.Parent = ReplicatedStorage
	                return
	            end
	
	            if LastThrow == ThrowUntil then
	                LastThrow = PreviousThrow
	            end
	            if InFlight == Projectile then
	                InFlight = nil
	            end
	            Attempted = false
	        end)
	
	        task.spawn(function()
	            local Timeout: number = tick() + 10
	            repeat
	                task.wait()
	            until not AutoPearl.Enabled or not Projectile or not Projectile.Parent or tick() >= Timeout
	            Landed = true
	        end)
	    else
	        if LastThrow == ThrowUntil then
	            LastThrow = PreviousThrow
	        end
	        Landed = true
	    end
	
	    if Back.Enabled and LandCheck.Enabled then
	        repeat
	            task.wait()
	        until Landed or not AutoPearl.Enabled
	    end
	
	    if Back.Enabled and OldHand and OldHand.tool then
	        task.wait(BackDelay:GetRandomValue())
	        SwitchItem(OldHand.tool)
	        if Legit.Enabled and GetHotbar(OldHand.tool) then
	            HotbarSwitch(GetHotbar(OldHand.tool))
	        end
	    end
	
	    return Direction ~= nil
	end
	
	local function FindNearGround(Origin: Vector3, From: Vector3): Vector3?
	    for Radius: number = 2, ClutchRange.Value, 3 do
	        local Count: number = math.max(8, math.ceil(2 * math.pi * Radius / 6))
	        for i: number = 1, Count do
	            local Angle: number = 2 * math.pi * i / Count
	            local Start: Vector3 = Origin + Vector3.new(math.cos(Angle) * Radius, 3, math.sin(Angle) * Radius)
	            local Ray: RaycastResult? = workspace:Raycast(Start, Vector3.new(0, -60, 0), RayCheck)
	            if Ray and CanReach(From, Ray.Position) and GetLaunch(From, Ray.Position) then
	                return Ray.Position
	            end
	        end
	    end
	
	    return nil
	end
	
	AutoPearl = vape.Categories.Utility:CreateModule({
	    Name = "AutoPearl",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Connection = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)
	                if Event.projectileType ~= "telepearl" or typeof(Event.projectile) ~= "Instance" or not Event.projectile:IsA("PVInstance") or not Entity.isAlive then
	                    return
	                end
	                if Event.shooter == Entity.character.Character then
	                    InFlight = Event.projectile
	                end
	            end)
	
	            AutoPearl:Clean(function()
	                Connection:Destroy()
	            end)
	
	            local LastGround: Vector3?
	            repeat
	                if Store.map then
	                    RayCheck.FilterDescendantsInstances = {Store.map}
	                    RayCheck.CollisionGroup = Entity.isAlive and Entity.character.RootPart.CollisionGroup or ""
	
	                    local Item
	                    if Entity.isAlive and tick() >= LastThrow and not (Check.Enabled and InFlight and InFlight.Parent) and not (Limit.Enabled and not (Store.hand.tool and Store.hand.tool.Name == "telepearl")) then
	                        Item = GetItem("telepearl")
	                    end
	
	                    local Root = Entity.isAlive and Entity.character.RootPart
	                    if Root and Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
	                        LastGround = Root.Position
	                    end
	
	                    if Item and Root and Root.AssemblyLinearVelocity.Y < -100 and not workspace:Raycast(Root.Position, Vector3.new(0, -200, 0), RayCheck) then
	                        if not Attempted then
	                            Attempted = true
	                            local Ground: Vector3? = FindNearGround(Root.Position + Vector3.new(0, 40, 0), Root.Position) or FindNearGround(LastGround and LastGround + Vector3.new(0, 5, 0) or Root.Position, Root.Position)
	                            if Ground and not FirePearl(Ground, Item) then
	                                Attempted = false
	                            end
	                        end
	                    else
	                        Attempted = false
	                    end
	                end
	
	                task.wait(0.1)
	            until not AutoPearl.Enabled
	        else
	            InFlight = nil
	            Attempted = false
	        end
	    end,
	    Tooltip = "Throws a pearl onto nearby ground when you fall into the void"
	})
	
	Legit = AutoPearl:CreateToggle({
	    Name = "Legit Switch",
	    Tooltip = "Visualizes the switching clientside",
	    Default = true
	})
	Back = AutoPearl:CreateToggle({
	    Name = "Switch back",
	    Function = function(Callback: boolean)
	        if BackDelay then
	            BackDelay.Object.Visible = Callback
	        end
	        if LandCheck then
	            LandCheck.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Switches back to the last slot before pearl"
	})
	LandCheck = AutoPearl:CreateToggle({
	    Name = "Only after landed",
	    Tooltip = "Only switches back after your pearl landed",
	    Darker = true
	})
	Check = AutoPearl:CreateToggle({
	    Name = "Pearl check",
	    Default = true,
	    Tooltip = "Doesn't throw a pearl while one of yours is still in the air, including ones you threw yourself"
	})
	BackDelay = AutoPearl:CreateTwoSlider({
	    Name = "Switch Back Delay",
	    Min = 0,
	    Max = 2,
	    DefaultMin = 0.1,
	    DefaultMax = 0.2,
	    Darker = true
	})
	ClutchRange = AutoPearl:CreateSlider({
	    Name = "Clutch range",
	    Min = 10,
	    Max = 100,
	    Default = 24,
	    Suffix = "studs",
	    Tooltip = "How far away a block can be for a void save, blocks your pearl cannot reach are skipped"
	})
	Cooldown = AutoPearl:CreateSlider({
	    Name = "Cooldown",
	    Min = 0,
	    Max = 5,
	    Default = 1,
	    Decimal = 10,
	    Suffix = "seconds",
	    Tooltip = "Minimum gap between two throws"
	})
	Limit = AutoPearl:CreateToggle({
	    Name = "Limit to item",
	    Tooltip = "Only throws pearl when holding a pearl"
	})
end)

Run(function()
	local AutoPearlAggro
	local Legit
	local Back
	local Check
	local LandCheck
	local BackDelay
	local Limit
	local Distance
	local MinHealth
	local Cooldown
	local LastThrow: number = 0
	local InFlight
	
	local FollowMinimum: number = 12
	local LandingTolerance: number = 4
	local FlightStep: number = 0.05
	local MaxFlight: number = 4
	local PearlBox: Vector3 = Vector3.new(3, 1, 3)
	
	local function PredictLanding(Origin: Vector3, Velocity: Vector3, Gravity: number): Vector3?
	    local Drop: Vector3 = Vector3.new(0, -Gravity, 0)
	    local Last: Vector3 = Origin
	    for Step: number = 1, math.round(MaxFlight / FlightStep) do
	        local Time: number = Step * FlightStep
	        local Position: Vector3 = Origin + Velocity * Time + Drop * (0.5 * Time * Time)
	        local Direction: Vector3 = Position - Last
	        local Hit: RaycastResult? = workspace:Blockcast(CFrame.new(Last), PearlBox, Direction, Store.airRay)
	        if Hit then
	            return Last + Direction.Unit * Hit.Distance
	        end
	        Last = Position
	    end
	
	    return nil
	end
	
	local function GetLaunch(From: Vector3, Spot: Vector3): Vector3?
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local Speed: number = Meta.launchVelocity
	    local Gravity: number = Meta.gravitationalAcceleration or 196.2
	    local Offset: Vector3 = Spot - From
	    local Flat: Vector3 = Offset * Vector3.new(1, 0, 1)
	    local Discriminant: number = Speed ^ 4 - Gravity * (Gravity * Flat.Magnitude ^ 2 + 2 * Offset.Y * Speed ^ 2)
	    if Flat.Magnitude < 1 or Discriminant < 0 then
	        return nil
	    end
	
	    for _, v: number in {-1, 1} do
	        local Angle: number = math.atan((Speed ^ 2 + v * math.sqrt(Discriminant)) / (Gravity * Flat.Magnitude))
	        local Velocity: Vector3 = Flat.Unit * (math.cos(Angle) * Speed) + Vector3.new(0, math.sin(Angle) * Speed, 0)
	        local Landing: Vector3? = PredictLanding(From, Velocity, Gravity)
	        if Landing and (Landing - Spot).Magnitude <= LandingTolerance then
	            return Velocity
	        end
	    end
	
	    return nil
	end
	
	local function FirePearl(Spot: Vector3, Item): boolean
	    if not Entity.isAlive or not GetLaunch(Entity.character.RootPart.Position, Spot) then
	        return false
	    end
	
	    local Hotbar, OldHand = GetHotbar(Item.tool), Store.hand
	    local PreviousThrow: number = LastThrow
	    local ThrowUntil: number = tick() + Cooldown.Value
	    LastThrow = ThrowUntil
	
	    SwitchItem(Item.tool)
	    if Legit.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Direction: Vector3? = Entity.isAlive and GetLaunch(Position, Spot) or nil
	    local Landed: boolean = false
	
	    if Direction then
	        local Meta = bedwars.ProjectileMeta.telepearl
	        local Id: string = HttpService:GenerateGUID(true)
	        local Projectile = bedwars.ProjectileController:createLocalProjectile(Meta, "telepearl", "telepearl", Position, Id, Direction, {drawDurationSeconds = 1})
	        InFlight = Projectile
	
	        bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	            Item.tool,
	            "telepearl",
	            "telepearl",
	            Position,
	            Position,
	            Direction,
	            Id,
	            {
	                drawDurationSeconds = 1,
	                shotId = HttpService:GenerateGUID(false)
	            },
	            workspace:GetServerTimeNow() - 0.045
	        ):andThen(function(Result)
	            if Result then
	                Result.Parent = ReplicatedStorage
	                return
	            end
	
	            if LastThrow == ThrowUntil then
	                LastThrow = PreviousThrow
	            end
	            if InFlight == Projectile then
	                InFlight = nil
	            end
	        end)
	
	        task.spawn(function()
	            local Timeout: number = tick() + 10
	            repeat
	                task.wait()
	            until not AutoPearlAggro.Enabled or not Projectile or not Projectile.Parent or tick() >= Timeout
	            Landed = true
	        end)
	    else
	        if LastThrow == ThrowUntil then
	            LastThrow = PreviousThrow
	        end
	        Landed = true
	    end
	
	    if Back.Enabled and LandCheck.Enabled then
	        repeat
	            task.wait()
	        until Landed or not AutoPearlAggro.Enabled
	    end
	
	    if Back.Enabled and OldHand and OldHand.tool then
	        task.wait(BackDelay:GetRandomValue())
	        SwitchItem(OldHand.tool)
	        if Legit.Enabled and GetHotbar(OldHand.tool) then
	            HotbarSwitch(GetHotbar(OldHand.tool))
	        end
	    end
	
	    return Direction ~= nil
	end
	
	local function Follow(Origin: Vector3, Velocity: Vector3)
	    if not Entity.isAlive or not Store.airRay then
	        return
	    end
	
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local Spot: Vector3? = PredictLanding(Origin, Velocity, Meta.gravitationalAcceleration or 196.2)
	    if not Spot or not AutoPearlAggro.Enabled or not Entity.isAlive then
	        return
	    end
	
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Gap: number = (Spot - Position).Magnitude
	    if Gap > Distance.Value or Gap < FollowMinimum or Gap < (Origin - Position).Magnitude then
	        return
	    end
	    if tick() < LastThrow or (Check.Enabled and InFlight and InFlight.Parent) then
	        return
	    end
	    if MinHealth.Value > 0 and Entity.character.Health < MinHealth.Value then
	        return
	    end
	    if Limit.Enabled and not (Store.hand.tool and Store.hand.tool.Name == "telepearl") then
	        return
	    end
	
	    local Item = GetItem("telepearl")
	    if Item then
	        FirePearl(Spot, Item)
	    end
	end
	
	AutoPearlAggro = vape.Categories.Utility:CreateModule({
	    Name = "AutoPearlAggro",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Connection = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)
	                if Event.projectileType ~= "telepearl" or typeof(Event.projectile) ~= "Instance" or not Event.projectile:IsA("PVInstance") or not Entity.isAlive then
	                    return
	                end
	                if Event.shooter == Entity.character.Character then
	                    InFlight = Event.projectile
	                    return
	                end
	                if typeof(Event.origin) ~= "Vector3" or typeof(Event.launchVelocity) ~= "Vector3" then
	                    return
	                end
	
	                for _, v: any in Entity.List do
	                    if v.Character == Event.shooter then
	                        if v.Targetable then
	                            task.spawn(Follow, Event.origin, Event.launchVelocity)
	                        end
	                        break
	                    end
	                end
	            end)
	
	            AutoPearlAggro:Clean(function()
	                Connection:Destroy()
	            end)
