Run(function()
	local AutoPlay
	local Delay
	local Random
	
	local Pending: boolean = false
	local NextJoin: number = 0
	
	local function JoinQueue()
	    if Pending then
	        return
	    end
	
	    Pending = true
	    task.delay(Delay.Value, function()
	        Pending = false
	        local State = bedwars.Store:getState()
	        if not AutoPlay.Enabled or os.clock() < NextJoin or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId or State.Party.queueState ~= 0 then
	            return
	        end
	
	        NextJoin = os.clock() + 5
	        if Random.Enabled then
	            local Modes: {string} = {}
	            for QueueType: string, v: any in bedwars.QueueMeta do
	                if not v.disabled and not v.voiceChatOnly and not v.rankCategory then
	                    table.insert(Modes, QueueType)
	                end
	            end
	            bedwars.QueueController:joinQueue(Modes[math.random(1, #Modes)])
	        else
	            bedwars.QueueController:joinQueue(Store.queueType)
	        end
	    end)
	end
	
	AutoPlay = vape.Categories.Utility:CreateModule({
	    Name = "AutoQueue",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoPlay:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.finalKill and DeathTable.entityInstance == LocalPlayer.Character and #bedwars.Store:getState().Party.members <= 0 and Store.matchState ~= 2 then
	                    JoinQueue()
	                end
	            end))
	            AutoPlay:Clean(VapeEvents.MatchEndEvent.Event:Connect(JoinQueue))
	        end
	    end,
	    Tooltip = "Automatically queues after the match ends."
	})
	
	Delay = AutoPlay:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 10,
	    Decimal = 10,
	    Default = 0,
	    Suffix = function(Value: number)
	        return Value == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long to wait after the match ends, or after your final death when you are solo, before queueing"
	})
	Random = AutoPlay:CreateToggle({
	    Name = "Random",
	    Tooltip = "Chooses a random mode"
	})
end)

Run(function()
	local AutoReset
	local Delay
	local Pearl
	local Whisper
	local Lasso
	local LowestPoint: number = math.huge
	
	local function GetVoidLine(): number
	    if LowestPoint == math.huge then
	        for _, v: BasePart in Store.blocks do
	            local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50
	            if Point < LowestPoint then
	                LowestPoint = Point
	            end
	        end
	    end
	    return LowestPoint
	end
	
	local function IsLassoed(): boolean
	    for _, v: Instance in LocalPlayer.Character and LocalPlayer.Character:GetChildren() or {} do
	        if v:IsA("Accessory") and v:FindFirstChild("Rope") then
	            return true
	        end
	    end
	    return false
	end
	
	local function CanSave(): boolean
	    if Pearl.Enabled and GetItem("telepearl") then
	        return true
	    end
	    if Whisper.Enabled and LocalPlayer:GetAttribute("IsOwlTarget") then
	        return true
	    end
	    return Lasso.Enabled and IsLassoed()
	end
	
	AutoReset = vape.Categories.Utility:CreateModule({
	    Name = "AutoReset",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Falling
	            repeat
	                if Store.matchState == 1 and Entity.isAlive then
	                    local Character = Entity.character
	                    local Root: BasePart = Character.RootPart
	                    if Falling and Falling ~= Character then
	                        Falling = nil
	                    end
	
	                    if not Falling and not CanSave() and Root.Position.Y < GetVoidLine() and Root.AssemblyLinearVelocity.Y < 0 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), Store.airRay) then
	                        Falling = Character
	                        task.delay(Delay.Value, function()
	                            if AutoReset.Enabled and Entity.isAlive and Entity.character == Character and Root.Parent and not CanSave() and Root.AssemblyLinearVelocity.Y < 0 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), Store.airRay) then
	                                bedwars.Handler:Get("ResetCharacter"):Fire("SendToServer")
	                            elseif Falling == Character then
	                                Falling = nil
	                            end
	                        end)
	                    end
	                else
	                    Falling = nil
	                end
	                task.wait(0.05)
	            until not AutoReset.Enabled
	        end
	    end,
	    Tooltip = "Resets once you fall past the void line so you can respawn sooner, leaving you room to clutch before then"
	})
	
	Delay = AutoReset:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Default = 0,
	    Decimal = 10,
	    Suffix = function(Value: number)
	        return Value == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long to wait before resetting. 0 resets instantly"
	})
	Pearl = AutoReset:CreateToggle({
	    Name = "Pearl check",
	    Default = true,
	    Tooltip = "Never resets while you are carrying a telepearl, so you keep the chance to pearl back"
	})
	Whisper = AutoReset:CreateToggle({
	    Name = "Whisper check",
	    Default = true,
	    Tooltip = "Never resets while an owl is assigned to you, so a Whisper can still lift you out"
	})
	Lasso = AutoReset:CreateToggle({
	    Name = "Lasso check",
	    Default = true,
	    Tooltip = "Never resets while a lasso is attached to you, so the pull can drag you back to safety"
	})
end)

Run(function()
	local AutoShoot
	local Targets
	local Check
	local Animation
	local Projectiles
	local UseSophia
	local UseWhim
	local UseNazar
	local UseUmeko
	local UseLasso
	local FireRate
	local SwitchDelay
	
	local FireDelays = {}
	
	local function GetShots(): {{any}}
	    local Shots: {{any}} = GetProjectiles(Projectiles.ListEnabled, UseSophia.Enabled, UseWhim.Enabled, UseNazar.Enabled, UseUmeko.Enabled)
	    local Lasso = UseLasso.Enabled and GetItem("lasso") or nil
	    local Source = Lasso and bedwars.ItemMeta.lasso.projectileSource or nil
	    if not Source then
	        return Shots
	    end
	
	    for _, v: {any} in Shots do
	        if v[1].itemType == "lasso" then
	            return Shots
	        end
	    end
	    table.insert(Shots, {Lasso, "lasso", Source.projectileType("lasso"), Source})
	    return Shots
	end
	
	local function GetEntity()
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Entities = Entity.AllPosition({
	        Origin = LocalPosition,
	        Part = "RootPart",
	        Range = 22,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    })
	    if #Entities > 0 then
	        for _, v: any in Entities do
	            local LocalFacing: Vector3 = Entity.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
	            local Delta: Vector3 = (v.RootPart.Position - LocalPosition) * Vector3.new(1, 0, 1)
	            local Angle: number = LocalFacing.Magnitude > 0 and Delta.Magnitude > 0 and math.acos(math.clamp(LocalFacing.Unit:Dot(Delta.Unit), -1, 1)) or 0
	            if Angle > (math.rad(120) / 2) then
	                continue
	            end
	            return v
	        end
	    end
	    return nil
	end
	
	AutoShoot = vape.Categories.Utility:CreateModule({
	    Name = "AutoShoot",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and Store.hand.toolType == "sword" and (tick() - bedwars.SwordController.lastSwing) < 0.2 then
	                    local OldTool, OldHotbar = Store.hand.tool, Store.inventory.hotbarSlot
	                    for _, v: {any} in GetShots() do
	                        local Item, Ammo, Projectile, ItemMeta = unpack(v)
	                        if (FireDelays[Item.itemType] or 0) < tick() then
	                            local Ent = GetEntity()
	                            if not Check.Enabled or Ent then
	                                local Hotbar: number? = GetHotbar(Item.tool)
	                                SwitchItem(Item.tool)
	                                if Hotbar then
	                                    HotbarSwitch(Hotbar)
	                                end
	
	                                local Meta = bedwars.ProjectileMeta[Projectile]
	                                local ProjectileSpeed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2
	                                local Origin: Vector3 = Entity.character.RootPart.Position
	                                local TargetPosition = Ent and PredictionLib.SolveTrajectory(Origin, ProjectileSpeed, Gravity, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true) or (not Ent and (Origin + Camera.CFrame.LookVector * 100))
	                                if TargetPosition then
	                                    local ShootPosition: Vector3 = (CFrame.new(Origin, TargetPosition) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
	                                    local Aim: Vector3 = Ent and PredictionLib.SolveTrajectory(ShootPosition, ProjectileSpeed, Gravity, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true) or TargetPosition
	                                    if Animation.Enabled then
	                                        bedwars.ProjectileController:launchProjectileWithValues({
	                                            initialVelocity = CFrame.lookAt(ShootPosition, Aim).LookVector * ProjectileSpeed,
	                                            positionFrom = ShootPosition,
	                                            drawDurationSeconds = 1
	                                        }, Item.tool, ItemMeta, Ammo, nil, Projectile):await()
	                                    else
	                                        local Direction, Id = CFrame.lookAt(ShootPosition, Aim).LookVector, HttpService:GenerateGUID(true)
	                                        bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	                                            Item.tool,
	                                            Ammo,
	                                            Projectile,
	                                            ShootPosition,
	                                            Origin,
	                                            Direction * ProjectileSpeed,
	                                            Id,
	                                            {
	                                                drawDurationSeconds = 1,
	                                                shotId = HttpService:GenerateGUID(false),
	                                            },
	                                            workspace:GetServerTimeNow() - 0.045
	                                        ):andThen(function(Result)
	                                            if Result then
	                                                Result.Parent = ReplicatedStorage
	                                            end
	                                        end)
	                                        if Ent then
	                                            WatchProjectile(Id, ShootPosition, Direction * ProjectileSpeed, Gravity, Ent, Meta.lifetimeSec)
	                                        end
	                                    end
	                                    if Ent then
	                                        PredictionLib.trackShot(Ent.RootPart)
	                                    end
	                                    FireDelays[Item.itemType] = tick() + (ItemMeta.fireDelaySec + FireRate:GetRandomValue())
	                                    task.wait(SwitchDelay.Value)
	                                end
	                            end
	                        end
	                    end
	                    if OldTool then
	                        SwitchItem(OldTool)
	                    end
	                    HotbarSwitch(OldHotbar)
	                end
	                task.wait(0.1)
	            until not AutoShoot.Enabled
	        end
	    end,
	    Tooltip = "Automatically crossbow macro's"
	})
	
	Targets = AutoShoot:CreateTargets({Players = true})
	Check = AutoShoot:CreateToggle({
	    Name = "Target check",
	    Function = function(Callback: boolean)
	        if Targets.Object then
	            Targets.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Animation = AutoShoot:CreateToggle({
	    Name = "Animation",
	    Default = true,
	    Tooltip = "Plays the shot animation and arrow"
	})
	Projectiles = AutoShoot:CreateTextList({
	    Name = "Projectiles",
	    Default = {"arrow", "snowball"}
	})
	UseSophia = AutoShoot:CreateToggle({
	    Name = "Use sophia",
	    Tooltip = "Also shoots sophia's frost staff, swapping it out of mist mode on its own"
	})
	UseWhim = AutoShoot:CreateToggle({
	    Name = "Use whim",
	    Tooltip = "Also casts whim's magic book, follows whatever element you have cycled"
	})
	UseNazar = AutoShoot:CreateToggle({
	    Name = "Use nazar",
	    Tooltip = "Also shoots nazar's life bow, crossbow and headhunter"
	})
	UseUmeko = AutoShoot:CreateToggle({
	    Name = "Use umeko",
	    Tooltip = "Also throws umeko's chakram, waiting for it to come back between throws"
	})
	UseLasso = AutoShoot:CreateToggle({
	    Name = "Use Lasso",
	    Tooltip = "Also throws lassy's lasso, waiting out its cooldown between throws"
	})
	FireRate = AutoShoot:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	SwitchDelay = AutoShoot:CreateSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.02
	})
end)

Run(function()
	local AutoToxic
	local GG
	local Toggles, Lists, Said, Dead = {}, {}, {}
	local Presets = {}
	
	local function SendMessage(Name: string, Target: string?, Default: string?)
	    local List: {string} = Lists[Name].ListEnabled
	    local Message: string? = #List > 0 and List[math.random(1, #List)] or Default
	    if not Message then
	        return
	    end
	    if #List > 1 and Message == Said[Name] then
	        repeat
	            task.wait()
	            Message = List[math.random(1, #List)]
	        until Message ~= Said[Name]
	    end
	    Said[Name] = Message
	
	    Message = Message and Message:gsub("<obj>", Target or "") or ""
	    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
	        if TextChatService:CanUserChatAsync(LocalPlayer.UserId) then
	            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(Message)
	        else
	            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendPresetAsync(Presets[Name] or Presets["So close"])
	        end
	    else
	        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(Message, "All")
	    end
	end
	
	AutoToxic = vape.Categories.Utility:CreateModule({
	    Name = "AutoToxic",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoToxic:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function(BedTable)
	                if Toggles.BedDestroyed.Enabled and BedTable.brokenBedTeam.id == LocalPlayer:GetAttribute("Team") then
	                    SendMessage("BedDestroyed", (BedTable.player.DisplayName or BedTable.player.Name), "how dare you >:( | <obj>")
	                elseif Toggles.Bed.Enabled and BedTable.player.UserId == LocalPlayer.UserId then
	                    local Team = bedwars.QueueMeta[Store.queueType].teams[tonumber(BedTable.brokenBedTeam.id)]
	                    SendMessage("Bed", Team and Team.displayName:lower() or "white", "nice bed lul | <obj>")
	                end
	            end))
	            AutoToxic:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.finalKill then
	                    local Killer: Player? = Players:GetPlayerFromCharacter(DeathTable.fromEntity)
	                    local Killed: Player? = Players:GetPlayerFromCharacter(DeathTable.entityInstance)
	                    if not Killed or not Killer then
	                        return
	                    end
	                    if Killed == LocalPlayer then
	                        if (not Dead) and Killer ~= LocalPlayer and Toggles.Death.Enabled then
	                            Dead = true
	                            SendMessage("Death", (Killer.DisplayName or Killer.Name), "my gaming chair subscription expired :( | <obj>")
	                        end
	                    elseif Killer == LocalPlayer and Toggles.Kill.Enabled then
	                        SendMessage("Kill", (Killed.DisplayName or Killed.Name), "vxp on top | <obj>")
	                    end
	                end
	            end))
	            AutoToxic:Clean(VapeEvents.MatchEndEvent.Event:Connect(function(WinTable)
	                if GG.Enabled then
	                    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
	                        TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync("gg")
	                    else
	                        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer("gg", "All")
	                    end
	                end
	
	                local MyTeam = bedwars.Store:getState().Game.myTeam
	                if MyTeam and MyTeam.id == WinTable.winningTeamId or LocalPlayer.Neutral then
	                    if Toggles.Win.Enabled then
	                        SendMessage("Win", nil, "yall garbage")
	                    end
	                end
	            end))
	        end
	    end,
	    Tooltip = "Says a message after a certain action"
	})
	
	GG = AutoToxic:CreateToggle({
	    Name = "AutoGG",
	    Default = true
	})
	for _, v: string in {"Kill", "Death", "Bed", "BedDestroyed", "Win"} do
	    Toggles[v] = AutoToxic:CreateToggle({
	        Name = `{v} `,
	        Function = function(Callback: boolean)
	            if Lists[v] then
	                Lists[v].Object.Visible = Callback
	            end
	        end
	    })
	    Lists[v] = AutoToxic:CreateTextList({
	        Name = v,
	        Darker = true,
	        Visible = false
	    })
	end
	
	task.spawn(pcall, function()
	    for _, Group: any in TextChatService:GetPresetsAsync().categoryGroups do
	        for _, Category: any in Group.categories do
	            for _, Message: any in Category.messages do
	                Presets[Message.value] = Message.presetId
	            end
	        end
	    end
	end)
end)

Run(function()
	local AutoVoidDrop
	local OwlCheck
	local AutoReset
	
	AutoVoidDrop = vape.Categories.Utility:CreateModule({
	    Name = "AutoVoidDrop",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat task.wait() until Store.matchState ~= 0 or (not AutoVoidDrop.Enabled)
	            if not AutoVoidDrop.Enabled then
	                return
	            end
	
	            local LowestPoint: number = math.huge
	            for _, v: BasePart in Store.blocks do
	                local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50
	                if Point < LowestPoint then
	                    LowestPoint = Point
