Run(function()
	local NickHider
	local Replacement
	local ChatTags
	local Level
	local HideOthers
	local Kit
	local Hidden = setmetatable({}, {__mode = "k"})
	local Swapped = setmetatable({}, {__mode = "k"})
	local Watched = setmetatable({}, {__mode = "k"})
	local Patterns: {string} = {}
	local Plain: {string} = {}
	local Shortest: number = math.huge
	local TextClasses: {[string]: boolean} = {TextLabel = true, TextButton = true, TextBox = true}
	local Fake: string = "hidden"
	local Writing: Instance?
	local OldUsername, OldDisplayName, OldClanTag, OldLevel
	
	local Refreshing: boolean = false
	
	local function QueueRefresh()
	    if Refreshing or not NickHider or not NickHider.Enabled then
	        return
	    end
	    Refreshing = true
	
	    task.delay(0.35, function()
	        Refreshing = false
	        if NickHider.Enabled then
	            NickHider:Toggle()
	            NickHider:Toggle()
	        end
	    end)
	end
	
	local function ShouldHidePlayer(Player: Player?)
	    return Player and (Player.UserId == LocalPlayer.UserId or HideOthers.Enabled)
	end
	
	local function AddPlayerNames(Player: Player)
	    for _, v: string in {Player.Name, Player.DisplayName} do
	        if v ~= "" then
	            local LowerName: string = v:lower()
	            if not table.find(Plain, LowerName) then
	                table.insert(Plain, LowerName)
	                Shortest = math.min(Shortest, #LowerName)
	            end
	        end
	        for _, Variant: string in {v, v:lower(), v:upper()} do
	            local Pattern: string = (Variant:gsub("%W", "%%%0"))
	            if Variant ~= "" and not table.find(Patterns, Pattern) then
	                table.insert(Patterns, Pattern)
	            end
	        end
	    end
	end
	
	local function ReplaceText(Object: Instance) LPH_ATTRIBUTES(PRESET(FAST))
	    if Writing == Object then
	        return
	    end
	
	    local Text: string = Object.Text
	    if type(Text) ~= "string" or #Text < Shortest then
	        return
	    end
	
	    local Hit: boolean = false
	    for _, v: string in Plain do
	        if Text:find(v, 1, true) then
	            Hit = true
	            break
	        end
	    end
	    if not Hit then
	        local LowerText: string = Text:lower()
	        for _, v: string in Plain do
	            if LowerText:find(v, 1, true) then
	                Hit = true
	                break
	            end
	        end
	    end
	    if not Hit then
	        return
	    end
	
	    local NewText: string = Text
	    for _, v: string in Patterns do
	        if NewText:find(v) then
	            NewText = NewText:gsub(v, Fake)
	        end
	    end
	    if NewText == Text then
	        return
	    end
	
	    Swapped[Object] = Text
	    Object:SetAttribute("NickHiderOriginalText", Text)
	    Writing = Object
	    Object.Text = NewText
	    Writing = nil
	
	    if not Watched[Object] then
	        Watched[Object] = Object:GetPropertyChangedSignal("Text"):Connect(function()
	            ReplaceText(Object)
	        end)
	    end
	end
	
	local function HideObject(Object: Instance) LPH_ATTRIBUTES(PRESET(FAST))
	    if TextClasses[Object.ClassName] then
	        ReplaceText(Object)
	    end
	end
	
	local function HideKit(Object: Instance)
	    if not Kit.Enabled or Object.Name ~= "PlayerKitFrame" or Hidden[Object] ~= nil then
	        return
	    end
	
	    task.defer(function()
	        local Label = Object.Parent and Object.Parent:FindFirstChild("PlayerName", true)
	        if not NickHider.Enabled or not Kit.Enabled or not Label or not Label.Text:find(Fake, 1, true) then
	            return
	        end
	
	        Hidden[Object] = Object.Visible
	        Object.Visible = false
	    end)
	end
	
	local function Watch(Root: Instance?)
	    if not Root then
	        return
	    end
	
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	    NickHider:Clean(Root.DescendantAdded:Connect(function(Object: Instance)
	        if NickHider.Enabled then
	            HideObject(Object)
	            HideKit(Object)
	        end
	    end))
	
	    local Clock: number = os.clock()
	    for _, v: Instance in Root:GetDescendants() do
	        HideObject(v)
	        HideKit(v)
	
	        if os.clock() - Clock > 0.002 then
	            task.wait()
	            if not NickHider.Enabled then
	                return
	            end
	            Clock = os.clock()
	
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	        end
	    end
	end
	
	NickHider = vape.Categories.Utility:CreateModule({
	    Name = "NickHider",
	    ConfigName = "NameHider",
	    Function = function(Callback: boolean)
	        if Callback then
	            table.clear(Patterns)
	            table.clear(Plain)
	            Shortest = math.huge
	            for _, Player: Player in Players:GetPlayers() do
	                if Player == LocalPlayer or HideOthers.Enabled then
	                    AddPlayerNames(Player)
	                end
	            end
	
	            Fake = Replacement.Value ~= "" and Replacement.Value or "hidden"
	            for _, v: string in Patterns do
	                if Fake:find(v) then
	                    Fake = "hidden"
	                    break
	                end
	            end
	
	            local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)
	            GamePlayer = GamePlayer and getmetatable(GamePlayer)
	            GamePlayer = GamePlayer and GamePlayer.__index
	            if GamePlayer and not OldUsername then
	                OldUsername, OldDisplayName = GamePlayer.getUsername, GamePlayer.getDisplayName
	                OldClanTag, OldLevel = GamePlayer.getClanTag, GamePlayer.getLevel
	                GamePlayer.getUsername = function(self, ...)
	                    local Player: Player? = self:getPlayer()
	                    return ShouldHidePlayer(Player) and Fake or OldUsername(self, ...)
	                end
	                GamePlayer.getDisplayName = function(self, ...)
	                    local Player: Player? = self:getPlayer()
	                    return ShouldHidePlayer(Player) and Fake or OldDisplayName(self, ...)
	                end
	                GamePlayer.getClanTag = function(self, ...)
	                    local Player: Player? = self:getPlayer()
	                    return (Player and Player.UserId == LocalPlayer.UserId) and ChatTags.Enabled and "" or OldClanTag(self, ...)
	                end
	                GamePlayer.getLevel = function(self, ...)
	                    local Player: Player? = self:getPlayer()
	                    if Player and (HideOthers.Enabled or (Player.UserId == LocalPlayer.UserId and Level.Enabled)) then
	                        return -1
	                    end
	                    return OldLevel(self, ...)
	                end
	            end
	
	            for _, v: Instance in {LocalPlayer:FindFirstChildOfClass("PlayerGui"), CoreGui, gethui and gethui() or nil, LocalPlayer.Character} do
	                Watch(v)
	            end
	
	            NickHider:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)
	                if NickHider.Enabled then
	                    Watch(Character)
	                end
	            end))
	            NickHider:Clean(Players.PlayerAdded:Connect(function()
	                if HideOthers.Enabled then
	                    QueueRefresh()
	                end
	            end))
	            NickHider:Clean(Players.PlayerRemoving:Connect(function()
	                if HideOthers.Enabled then
	                    QueueRefresh()
	                end
	            end))
	        else
	            local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)
	            GamePlayer = GamePlayer and getmetatable(GamePlayer)
	            GamePlayer = GamePlayer and GamePlayer.__index
	            if OldUsername and GamePlayer then
	                GamePlayer.getUsername, GamePlayer.getDisplayName = OldUsername, OldDisplayName
	                GamePlayer.getClanTag, GamePlayer.getLevel = OldClanTag, OldLevel
	                OldUsername, OldDisplayName, OldClanTag, OldLevel = nil, nil, nil, nil
	            end
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            for _, v: RBXScriptConnection in Watched do
	                v:Disconnect()
	            end
	            table.clear(Watched)
	
	            for Object: GuiObject, Visible: boolean in Hidden do
	                if Object.Parent then
	                    Object.Visible = Visible
	                end
	            end
	            table.clear(Hidden)
	
	            for Object: Instance, OriginalText: string in Swapped do
	                if Object.Parent then
	                    Writing = Object
	                    Object.Text = OriginalText
	                    Object:SetAttribute("NickHiderOriginalText", nil)
	                end
	            end
	            Writing = nil
	            table.clear(Swapped)
	        end
	    end,
	    Tooltip = "Replaces your username and display name everywhere it shows up on your screen",
	    ExtraText = function()
	        return Replacement.Value ~= "" and Replacement.Value or "hidden"
	    end
	})
	
	Replacement = NickHider:CreateTextBox({
	    Name = "Name",
	    Function = QueueRefresh,
	    Default = "hidden"
	})
	HideOthers = NickHider:CreateToggle({
	    Name = "Hide others",
	    Function = QueueRefresh,
	    Tooltip = "Hides every player's username and level"
	})
	ChatTags = NickHider:CreateToggle({
	    Name = "Hide chat tags",
	    Tooltip = "Hides your clan tag wherever it renders"
	})
	Level = NickHider:CreateToggle({
	    Name = "Hide level",
	    Function = QueueRefresh,
	    Tooltip = "Hides your level wherever it renders"
	})
	Kit = NickHider:CreateToggle({
	    Name = "Hide kit",
	    Function = QueueRefresh,
	    Tooltip = "Hides your kit icon in the tab list"
	})
end)

Run(function()
	local PhaseMine
	
	local Ignored = setmetatable({}, {__mode = "k"})
	local Watching = setmetatable({}, {__mode = "k"})
	
	local function SetIgnored(Part: Instance)
	    if Part:IsA("BasePart") and not Ignored[Part] then
	        Ignored[Part] = true
	        bedwars.QueryUtil:setQueryIgnored(Part, true)
	    end
	end
	
	local function Added(Character: Model)
	    for _, v: BasePart in Character:QueryDescendants("BasePart") do
	        SetIgnored(v)
	    end
	
	    if not Watching[Character] then
	        Watching[Character] = Character.ChildAdded:Connect(SetIgnored)
	    end
	end
	
	PhaseMine = vape.Categories.Utility:CreateModule({
	    Name = "PhaseMine",
	    Function = function(Callback: boolean)
	        if Callback then
	            PhaseMine:Clean(Entity.Events.EntityAdded:Connect(function(Ent)
	                if Ent.Player then
	                    task.delay(1, Added, Ent.Character)
	                end
	            end))
	
	            for _, v: any in Entity.List do
	                if v.Player and v.Player ~= LocalPlayer and v.Character then
	                    Added(v.Character)
	                end
	            end
	        else
	            for _, v: RBXScriptConnection in Watching do
	                v:Disconnect()
	            end
	            table.clear(Watching)
	
	            for Part: BasePart in Ignored do
	                if Part.Parent then
	                    bedwars.QueryUtil:setQueryIgnored(Part, false)
	                end
	            end
	            table.clear(Ignored)
	        end
	    end,
	    Tooltip = "Allows you to mine through opponents"
	})
end)

Run(function()
	local PickupRange
	local Range
	local Network
	local Lower
	local Picked = setmetatable({}, {__mode = "k"})
	
	PickupRange = vape.Categories.Utility:CreateModule({
	    Name = "PickupRange",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Items = Collection("ItemDrop", PickupRange)
	            repeat
	                if Entity.isAlive then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    for _, v: BasePart in Items do
	                        if tick() - (v:GetAttribute("ClientDropTime") or 0) < 2 or Picked[v] then
	                            continue
	                        end
	                        if Network.Enabled and isnetworkowner(v) and Entity.character.Humanoid.Health > 0 then
	                            v.CFrame = CFrame.new(LocalPosition - Vector3.new(0, 3, 0))
	                        end
	
	                        if (LocalPosition - v.Position).Magnitude <= Range.Value then
	                            if Lower.Enabled and (LocalPosition.Y - v.Position.Y) < (Entity.character.HipHeight - 1) then
	                                continue
	                            end
	                            Picked[v] = true
	                            task.spawn(function()
	                                bedwars.Handler:Get("PickupItemDrop"):Fire("CallServerAsync", {
	                                    itemDrop = v
	                                }):andThen(function(Success)
	                                    Picked[v] = nil
	                                    if Success and bedwars.SoundList then
	                                        bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)
	                                        local Sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
	                                        if Sound then
	                                            bedwars.AudioManager:playAudio(Sound, {
	                                                position = v.Position,
	                                                volumeMultiplier = 0.9
	                                            })
	                                        end
	                                    end
	                                end)
	                            end)
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not PickupRange.Enabled
	        end
	    end,
	    Tooltip = "Picks up items from a farther distance"
	})
	
	Range = PickupRange:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 10,
	    Default = 10,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	Network = PickupRange:CreateToggle({
	    Name = "Network TP",
	    Default = true
	})
	Lower = PickupRange:CreateToggle({Name = "Feet Check"})
end)

Run(function()
	local RegionLock
	local Regions
	local Timeout
	local Requeue
	
	local Status: string = "Next match"
	local ServerRegion: string?
	local RegionPending: boolean?
	local RegionRetry: number = 0
	local Warned: boolean = false
	local Requeued: boolean = false
	local RequeueTries: number = 0
	local RequeueRetry: number = 0
	local Aliases: {[string]: string} = {
	    AU = "SEA",
	    AUS = "SEA",
	    AUSTRALIA = "SEA",
	    NZ = "SEA",
	    OCE = "SEA",
	    OCEANIA = "SEA",
	    AS = "SEA",
	    ASIA = "SEA",
	    SG = "SEA",
	    SGP = "SEA",
	    US = "NA",
	    USA = "NA",
	    AMERICA = "NA",
	    EUROPE = "EU",
	    GB = "EU",
	    UK = "EU"
	}
	
	local function Canonical(Value: string): string
	    Value = tostring(Value):gsub("%s+", ""):upper()
	    return Aliases[Value] or Value
	end
	
	local function GetRegion(): string?
	    local State = bedwars.Store:getState().Game
	    local Region = type(State) == "table" and State.serverRegion or nil
	    if type(Region) == "string" and Region ~= "" then
	        ServerRegion = Region
	        return Region
	    end
	    if not ServerRegion and not RegionPending and os.clock() >= RegionRetry then
	        RegionPending = true
	        task.spawn(function()
	            local Success, Response = pcall(function()
	                return bedwars.Handler:Get("FetchServerRegion"):Fire("CallServer")
	            end)
	            RegionRetry = os.clock() + 5
	            RegionPending = false
	            if Success and type(Response) == "string" and Response ~= "" then
	                ServerRegion = Response
	            end
	        end)
	    end
	    return ServerRegion
	end
	
	local function IsRegionAllowed(): boolean
	    if #Regions.ListEnabled == 0 then
	        return true
	    end
	
	    local Region = GetRegion()
	    if not Region then
	        return false
	    end
	
	    Region = Canonical(Region)
	    for _, v: string in Regions.ListEnabled do
	        v = Canonical(v)
	        if v ~= "" and Region:sub(1, #v) == v then
	            return true
	        end
	    end
	    return false
	end
	
	local function RequeueMatch(): string?
	    local State = bedwars.Store:getState()
	    if Requeued or State.Party.queueState ~= 0 then
	        Requeued = true
	        return "Requeued"
	    end
	
	    local Data = TeleportService:GetLocalPlayerTeleportData()
	    if (type(Data) == "table" and Data.customMatch) or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId then
	        return nil
	    end
	
	    local Match = type(Data) == "table" and Data.match
	    local QueueType: string? = Match and Match.queueType or Store.queueType
	    local Meta = QueueType and bedwars.QueueMeta[QueueType]
	    if not Meta or Meta.disabled then
	        return nil
	    end
	
	    if os.clock() >= RequeueRetry then
	        if RequeueTries >= 3 then
	            return "Requeue failed"
	        end
	        RequeueTries += 1
	        RequeueRetry = os.clock() + 5
	        pcall(bedwars.QueueController.joinQueue, bedwars.QueueController, QueueType)
	    end
	    return "Requeueing"
	end
	
	local function Release()
	    if not getgenv().matchDodgeActive then
	        if getgenv().dodged and not Store.readyHold.Remote then
	            bedwars.Handler:Get("PlayerConnect"):Fire("SendToServer", TeleportService:GetLocalPlayerTeleportData())
	        end
	        Store.readyHold.Release()
	        getgenv().dodged = false
	    end
	end
	
	RegionLock = vape.Categories.Utility:CreateModule({
	    Name = "RegionLock",
	    Function = function(Callback: boolean)
	        writefile("GyuvapeBedwarsCheat/profiles/regionlock.txt", tostring(Callback))
	        getgenv().regionLockActive = Callback
	        getgenv().regionLockAllowed = not Callback
	        if Callback then
	            Store.readyHold.Claimed = true
	            RegionLock:Clean(coroutine.running())
	            Warned = false
	            repeat
	                if not getgenv().dodged and not Store.readyHold.Held then
	                    Status = LocalPlayer:GetAttribute("PlayerConnected") and "Loaded" or "Next match"
	                else
	                    local Started: number = Store.readyHold.Started or os.clock()
	                    getgenv().regionLockAllowed = IsRegionAllowed()
	                    if getgenv().regionLockAllowed then
	                        Status = ServerRegion or "Any region"
	                        Release()
	                    elseif ServerRegion then
	                        local RequeueStatus: string? = Requeue.Enabled and RequeueMatch() or nil
	                        Status = `{RequeueStatus or "Wrong region"} ({ServerRegion})`
	                    elseif Timeout.Value > 0 and (os.clock() - Started) >= Timeout.Value then
	                        if not Warned then
	                            Warned = true
	                            SendNotification("RegionLock", "Could not read this server region, loading anyway", 8, "warning")
	                        end
	                        getgenv().regionLockAllowed = true
	                        Status = "Unknown region"
	                        Release()
	                    else
	                        Status = "Finding region"
	                    end
	                end
	                task.wait(0.5)
	            until not RegionLock.Enabled
	        else
	            Release()
	            Status = "Loaded"
	            Store.readyHold.Claimed = getgenv().matchDodgeActive
	        end
	    end,
	    Tooltip = "Stays out of matches that are not hosted in one of your selected server regions. BedWars only hosts NA, EU and SEA, and picks yours from your account country, so this can only reject the odd cross-region server, not move you to another region",
	    ExtraText = function()
	        return Status
	    end
	})
	
	Regions = RegionLock:CreateTextList({
	    Name = "Regions",
	    Placeholder = "NA / EU / SEA",
	    Default = {"NA", "EU", "SEA"},
	    Function = function()
	        if not Regions then
	            return
	        end
	        for i: number, v: string in Regions.List do
	            Regions.List[i] = v:gsub("%s+", ""):upper()
	        end
	        for i: number, v: string in Regions.ListEnabled do
	            Regions.ListEnabled[i] = v:gsub("%s+", ""):upper()
	        end
	    end,
	    Tooltip = "Turn off the regions you do not want. AUS, OCE, AU and NZ all count as SEA, US counts as NA. Leaving every region on accepts anything"
	})
	Timeout = RegionLock:CreateSlider({
	    Name = "Timeout",
	    Min = 0,
	    Max = 120,
	    Default = 20,
	    Suffix = function(Value: number)
	        return Value == 1 and "second" or "seconds"
	    end,
	    Tooltip = "Loads anyway when the server never reports a region. 0 waits forever"
	})
	Requeue = RegionLock:CreateToggle({
	    Name = "Requeue",
	    Tooltip = "When the region is wrong, queues the same mode again from the loading screen (party leader only, up to 3 tries) and keeps you there until the new match is found"
	})
	
	task.spawn(function()
	    repeat task.wait() until vape.Loaded or vape.Loaded == nil
	    local Last = isfile("GyuvapeBedwarsCheat/profiles/regionlock.json") and readfile("GyuvapeBedwarsCheat/profiles/regionlock.json")
	    if vape.Loaded and Last then
	        local Success, Response = pcall(HttpService.JSONDecode, HttpService, Last)
	        if Success and type(Response) == "table" then
	            RegionLock:Load(Response)
	        end
	    end
	
	    repeat
	        if vape.Loaded then
	            local Data = {}
	            RegionLock:Save(Data)
	            Data.RegionLock.Favorited = nil
	            local Encoded: string = HttpService:JSONEncode(Data.RegionLock)
	            if Encoded ~= Last then
	                Last = Encoded
	                writefile("GyuvapeBedwarsCheat/profiles/regionlock.json", Encoded)
	            end
	        end
	        task.wait(1)
	    until vape.Loaded == nil
	end)
end)

Run(function()
	local Scaffold
	local Expand
	local Tower
	local Downwards
	local Diagonal
	local LimitItem
	local Mouse
	local FillColor
	local OutlineColor
	local Adjacent, LastPosition, Label, VisualBlock = {}, Vector3.zero
	local VisualTween, VisualPosition
	local VisualSpeed: number = 0.1
	
	for X: number = -3, 3, 3 do
	    for Y: number = -3, 3, 3 do
	        for Z: number = -3, 3, 3 do
	            local Offset: Vector3 = Vector3.new(X, Y, Z)
	            if Offset ~= Vector3.zero then
	                table.insert(Adjacent, Offset)
	            end
	        end
	    end
	end
	
	local function NearCorner(BlockPosition: Vector3, Position: Vector3): Vector3
	    local StartPosition: Vector3 = BlockPosition - Vector3.new(3, 3, 3)
	    local EndPosition: Vector3 = BlockPosition + Vector3.new(3, 3, 3)
	    local Check: Vector3 = BlockPosition + (Position - BlockPosition).Unit * 100
	    return Vector3.new(math.clamp(Check.X, StartPosition.X, EndPosition.X), math.clamp(Check.Y, StartPosition.Y, EndPosition.Y), math.clamp(Check.Z, StartPosition.Z, EndPosition.Z))
	end
	getgenv().nearCorner = NearCorner
	
	local function BlockProximity(Position: Vector3): Vector3?
	    local Magnitude, Closest = 60
	    local Blocks = GetBlocksInPoints(bedwars.BlockController:getBlockPosition(Position - Vector3.new(21, 21, 21)), bedwars.BlockController:getBlockPosition(Position + Vector3.new(21, 21, 21)))
	    for _, v: Vector3 in Blocks do
	        local BlockPosition: Vector3 = NearCorner(v, Position)
	        local NewMagnitude: number = (Position - BlockPosition).Magnitude
	        if NewMagnitude < Magnitude then
	            Magnitude, Closest = NewMagnitude, BlockPosition
	        end
	    end
	    table.clear(Blocks)
	    return Closest
	end
	getgenv().blockProximity = BlockProximity
	
	local function CheckAdjacent(Position: Vector3): boolean
	    for _, v: Vector3 in Adjacent do
	        if GetPlacedBlock(Position + v) then
	            return true
	        end
	    end
	    return false
	end
	getgenv().checkAdjacent = CheckAdjacent
	
	local function GetScaffoldBlock()
	    if Store.hand.toolType == "block" then
	        return Store.hand.tool.Name, Store.hand.amount
	    elseif (not LimitItem.Enabled) then
	        local Wool, Amount = GetWool()
	        if Wool then
	            return Wool, Amount
	        else
	            for _, v: any in Store.inventory.inventory.items do
	                if bedwars.ItemMeta[v.itemType].block then
	                    return v.itemType, v.amount
	                end
	            end
	        end
	    end
	
	    return nil, 0
	end
	
	Scaffold = vape.Categories.Utility:CreateModule({
	    Name = "Scaffold",
	    Function = function(Callback: boolean)
	        if Label then
	            Label.Visible = Callback
	        end
	
	        if Callback then
	            repeat
	                if Entity.isAlive and not vape.MovementOwner then
	                    local Wool, Amount = GetScaffoldBlock()
	
	                    if Mouse.Enabled then
	                        if not UserInputService:IsMouseButtonPressed(0) then
	                            Wool = nil
	                        end
	                    end
	
	                    if Label then
	                        Amount = Amount or 0
	                        Label.Text = `{Amount} <font color="rgb(170, 170, 170)">(Scaffold)</font>`
	                        Label.TextColor3 = Color3.fromHSV((Amount / 128) / 2.8, 0.86, 1)
	                    end
	
	                    if Wool then
	                        local Root: BasePart = Entity.character.RootPart
	                        if Tower.Enabled and UserInputService:IsKeyDown(Enum.KeyCode.Space) and (not UserInputService:GetFocusedTextBox()) then
	                            Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 38, Root.AssemblyLinearVelocity.Z)
	                        end
	
	                        for Step: number = Expand.Value, 1, -1 do
	                            local CurrentPosition: Vector3 = RoundPosition(Root.Position - Vector3.new(0, Entity.character.HipHeight + (Downwards.Enabled and UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0) + Entity.character.Humanoid.MoveDirection * (Step * 3))
	                            if Diagonal.Enabled then
	                                if math.abs(math.round(math.deg(math.atan2(-Entity.character.Humanoid.MoveDirection.X, -Entity.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
	                                    local Delta: Vector3 = (LastPosition - CurrentPosition)
	                                    if ((Delta.X == 0 and Delta.Z ~= 0) or (Delta.X ~= 0 and Delta.Z == 0)) and ((LastPosition - Root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
	                                        CurrentPosition = LastPosition
	                                    end
	                                end
	                            end
	
	                            if VisualBlock and CurrentPosition then
	                                local VisualTarget: Vector3 = bedwars.BlockController:getBlockPosition(CurrentPosition) * 3
	                                if VisualPosition ~= VisualTarget then
	                                    if VisualTween then
	                                        VisualTween:Cancel()
	                                        VisualTween = nil
	                                    end
	
	                                    if VisualBlock.Parent == Camera then
	                                        VisualTween = TweenService:Create(VisualBlock, TweenInfo.new(VisualSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = CFrame.new(VisualTarget)})
	                                        VisualTween:Play()
	                                    else
	                                        VisualBlock.CFrame = CFrame.new(VisualTarget)
	                                        VisualBlock.Parent = Camera
	                                    end
	                                    VisualPosition = VisualTarget
	                                end
	                            end
	
	                            local Block, BlockPosition = GetPlacedBlock(CurrentPosition)
	                            if not Block then
	                                BlockPosition = CheckAdjacent(BlockPosition * 3) and BlockPosition * 3 or BlockProximity(CurrentPosition)
	                                if BlockPosition then
	                                    task.delay(0, bedwars.placeBlock, BlockPosition, Wool, false)
	                                end
	                            end
	                            LastPosition = CurrentPosition
	                        end
	                    end
	                end
	                task.wait(0.03)
	            until not Scaffold.Enabled
	            if VisualTween then
	                VisualTween:Cancel()
	                VisualTween = nil
	            end
	            if VisualBlock then
	                VisualBlock.Parent = nil
	            end
	            VisualPosition = nil
	        end
	    end,
	    Tooltip = "Helps you make bridges/scaffold walk."
	})
	
	Expand = Scaffold:CreateSlider({
	    Name = "Expand",
	    Min = 1,
	    Max = 6
	})
	Tower = Scaffold:CreateToggle({
	    Name = "Tower",
	    Default = true
	})
	Downwards = Scaffold:CreateToggle({
	    Name = "Downwards",
	    Default = true
	})
	Diagonal = Scaffold:CreateToggle({
	    Name = "Diagonal",
	    Default = true
	})
	LimitItem = Scaffold:CreateToggle({Name = "Limit to items"})
	Mouse = Scaffold:CreateToggle({Name = "Require mouse down"})
	Scaffold:CreateToggle({
	    Name = "Visual",
	    Function = function(Callback: boolean)
	        FillColor.Object.Visible = Callback
	        OutlineColor.Object.Visible = Callback
	        if Callback then
	            VisualBlock = Instance.new("Part")
	            VisualBlock.Size = Vector3.new(3, 3, 3)
	            VisualBlock.Anchored = true
	            VisualBlock.CanCollide = false
	            VisualBlock.CanQuery = false
	            VisualBlock.CanTouch = false
	            VisualBlock.CastShadow = false
	            VisualBlock.Transparency = 1
	            local Selection: SelectionBox = Instance.new("SelectionBox")
	            Selection.Adornee = VisualBlock
	            Selection.LineThickness = 0.04
	            Selection.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
	            Selection.Transparency = 1 - OutlineColor.Opacity
	            Selection.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
	            Selection.SurfaceTransparency = 1 - FillColor.Opacity
	            Selection.Parent = VisualBlock
	            bedwars.QueryUtil:setQueryIgnored(VisualBlock, true)
	        else
	            if VisualTween then
	                VisualTween:Cancel()
	                VisualTween = nil
	            end
	            if VisualBlock then
	                VisualBlock.Parent = nil
	            end
	            VisualPosition = nil
	            VisualBlock:Destroy()
	            VisualBlock = nil
	        end
	    end,
	    Tooltip = "Renders an overlay on the block about to be placed"
	})
	FillColor = Scaffold:CreateColorSlider({
	    Name = "Fill Color",
	    DefaultSat = 0,
	    DefaultOpacity = 0.4,
	    Darker = true,
	    Visible = false,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if VisualBlock then
	            VisualBlock.SelectionBox.SurfaceColor3 = Color3.fromHSV(Hue, Sat, Val)
	            VisualBlock.SelectionBox.SurfaceTransparency = 1 - Opacity
	        end
	    end
	})
	OutlineColor = Scaffold:CreateColorSlider({
	    Name = "Outline Color",
	    DefaultValue = 0,
	    Darker = true,
	    Visible = false,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if VisualBlock then
	            VisualBlock.SelectionBox.Color3 = Color3.fromHSV(Hue, Sat, Val)
	            VisualBlock.SelectionBox.Transparency = 1 - Opacity
	        end
	    end
	})
	Scaffold:CreateToggle({
	    Name = "Block Count",
	    Function = function(Callback: boolean)
	        if Callback then
	            Label = Instance.new("TextLabel")
	            Label.Size = UDim2.fromOffset(100, 20)
	            Label.Position = UDim2.new(0.5, 6, 0.5, 60)
	            Label.BackgroundTransparency = 1
	            Label.AnchorPoint = Vector2.new(0.5, 0)
	            Label.Text = "0"
	            Label.TextColor3 = Color3.new(0, 1, 0)
	            Label.TextSize = 18
	            Label.RichText = true
	            Label.Font = Enum.Font.Arial
	            Label.Visible = Scaffold.Enabled
	            Label.Parent = vape.gui
	        else
	            Label:Destroy()
	            Label = nil
	        end
	    end
	})
end)

Run(function()
	local SetEmote
	local Emote
	local Track: AnimationTrack?
	
	local List, EmoteTypes = {}, {}
	for EmoteType: any, v: any in bedwars.EmoteMeta do
	    if EmoteType ~= bedwars.EmoteType.NONE and v.name and not EmoteTypes[v.name] then
	        EmoteTypes[v.name] = EmoteType
	        table.insert(List, v.name)
	    end
	end
	table.sort(List)
	
	local function CancelEmote()
	    if Entity.isAlive then
	        if Track then
	            Track:Stop()
	            Track:Destroy()
	            Track = nil
	        end
	        if LocalPlayer.Character:GetAttribute("PlayingEmote") then
	            LocalPlayer.Character:SetAttribute("PlayingEmote", nil)
	        end
	    end
	end
	
	SetEmote = vape.Categories.Utility:CreateModule({
	    Name = "SetEmote",
	    Function = function(Callback: boolean)
	        if Callback then
	            SetEmote:Toggle()
	            if Entity.isAlive then
	                local EmoteType = EmoteTypes[Emote.Value]
	                local Meta = bedwars.EmoteMeta[EmoteType]
	                if Meta then
	                    LocalPlayer.Character:SetAttribute("PlayingEmote", EmoteType)
	                    local PlayBeginSounds = bedwars.EmoteController.createEmoteBeginAudioPlayers or bedwars.EmoteController.playEmoteBeginSounds
	                    if PlayBeginSounds then
	                        PlayBeginSounds(bedwars.EmoteController, EmoteType, LocalPlayer)
	                    end
	                    local Animation = Meta.animation
	                    if not Animation and Meta.emoteDisplayType then
	                        local Display = bedwars.EmoteDisplayMeta[Meta.emoteDisplayType]
	                        Animation = Display and Display.animation
	                    end
	                    if Animation and not noAutoPlayAnimation then
	                        Track = LocalPlayer.Character.Humanoid:LoadAnimation(bedwars.GameAnimationUtil:getAnimation(Animation.type))
	                        Track.Looped = Animation.looped or false
	                        Track:Play(nil, nil, Animation.speed or 1)
	                    end
	                    if not Meta.animation then
	                        local Gui: BillboardGui = Instance.new("BillboardGui")
	                        Gui.Size = UDim2.fromScale(6, 2.5)
	                        Gui.StudsOffset = Vector3.new(0, 2, 0)
	                        Gui.AlwaysOnTop = true
	                        Gui.Adornee = LocalPlayer.Character.Head
	
	                        local Image: ImageLabel = Instance.new("ImageLabel")
	                        Image.AnchorPoint = Vector2.new(0.5, 1)
	                        Image.Position = UDim2.fromScale(0.5, 1)
	                        Image.Size = UDim2.fromScale(0, 0)
	                        Image.Image = Meta.image
	                        Image.BackgroundTransparency = 1
	                        Image.ImageTransparency = 1
	                        Image.ScaleType = Enum.ScaleType.Fit
	                        Image.Parent = Gui
	
	                        Gui.Parent = LocalPlayer.Character.Head
	                        TweenService:Create(Image, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
	                            Position = UDim2.fromScale(0.5, 0.5),
	                            Size = UDim2.fromScale(1, 1),
	                            ImageTransparency = 0
	                        }):Play()
	                    end
	                    if Meta.allowMovement then
	                        task.delay(6, CancelEmote)
	                    else
	                        LocalPlayer.Character.Humanoid:GetPropertyChangedSignal("MoveDirection"):Once(CancelEmote)
	                    end
	                end
	            end
	        end
	    end,
	    Tooltip = "Plays the selected emote on your character, other players can see it too"
	})
	
	Emote = SetEmote:CreateDropdown({
	    Name = "Emote",
	    List = List,
	    Default = "nightmare"
	})
end)

Run(function()
	local ShopQuickBuy
	local HoldDelay
	local CPS
	
	local Holding: boolean = false
	local ClickThread: thread?
	
	local function GetShopId()
	    if not Entity.isAlive then
	        return nil
	    end
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Id
	    for _, v: any in Store.shop do
	        if v.Shop and (v.RootPart.Position - LocalPosition).Magnitude <= 20 then
	            Id = v.Id
	        end
	    end
	    return Id
	end
	
	local function GetHoveredItem(): string?
	    local MousePosition: Vector2 = (UserInputService:GetMouseLocation() - GuiService:GetGuiInset())
	    for _, v: GuiObject in LocalPlayer.PlayerGui:GetGuiObjectsAtPosition(MousePosition.X, MousePosition.Y) do
	        local Object: Instance? = v
	        while Object and Object ~= LocalPlayer.PlayerGui do
	            local ItemType: string? = Object.Name:match("^(.+)_ShopItemCard$")
	            if ItemType then
	                return ItemType
	            end
	            Object = Object.Parent
	        end
	    end
	end
	
	local function StartClicking(ItemType: string)
	    if ClickThread then
	        task.cancel(ClickThread)
	    end
	    ClickThread = task.spawn(function()
	        repeat
	            local ShopId = bedwars.AppController:isAppOpen("BedwarsItemShopApp") and Store.shopLoaded and GetShopId()
	            if ShopId and bedwars.BedwarsShopController.alreadyPurchasedMap[ItemType] == nil then
	                local Item = bedwars.Shop.getShopItem(ItemType, LocalPlayer, {shopId = ShopId})
	                local Currency = Item and GetItem(Item.currency)
	                local Buyable = Item and not (Item.ignoredByKit and table.find(Item.ignoredByKit, Store.equippedKit or "")) and not Item.lockedByForge and not Item.disabled and (Currency and Currency.amount or 0) >= Item.price
	                if Buyable and Item.require and Item.require.teamUpgrade and (bedwars.Store:getState().Bedwars.teamUpgrades[Item.require.teamUpgrade.upgradeId] or -1) < Item.require.teamUpgrade.lowestTierIndex then
	                    Buyable = false
	                end
	
	                if Buyable then
	                    bedwars.Handler:Get("BedwarsPurchaseItem"):Fire("CallServerAsync", {
	                        shopItem = Item,
	                        shopId = ShopId
	                    }):andThen(function(Success)
	                        if not Success then
	                            return
	                        end
	                        bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)
	                        bedwars.Store:dispatch({
	                            type = "BedwarsAddItemPurchased",
	                            itemType = ItemType
	                        })
	                        if Item.tiered then
	                            bedwars.BedwarsShopController.alreadyPurchasedMap[ItemType] = true
	                        end
	                    end)
	                end
	            end
	            task.wait(1 / CPS.Value)
	        until not Holding
	        ClickThread = nil
	    end)
	end
	
	ShopQuickBuy = vape.Categories.Utility:CreateModule({
	    Name = "ShopClicker",
	    Function = function(Callback: boolean)
	        if Callback then
	            ShopQuickBuy:Clean(UserInputService.InputBegan:Connect(function(Input: InputObject)
	                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
	                    return
	                end
	                if not bedwars.AppController:isAppOpen("BedwarsItemShopApp") then
	                    return
	                end
	
	                local ItemType: string? = GetHoveredItem()
	                if not ItemType then
	                    return
	                end
	
	                Holding = true
	                task.delay(HoldDelay.Value, function()
	                    if Holding and GetHoveredItem() == ItemType then
	                        StartClicking(ItemType)
	                    end
	                end)
	            end))
	
	            ShopQuickBuy:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
	                if Input.UserInputType == Enum.UserInputType.MouseButton1 then
	                    Holding = false
	                end
	            end))
	        else
	            Holding = false
	            if ClickThread then
	                task.cancel(ClickThread)
	                ClickThread = nil
	            end
	        end
	    end,
	    Tooltip = "Hold on a shop item to rapidly buy it."
	})
	
	HoldDelay = ShopQuickBuy:CreateSlider({
	    Name = "Hold Delay",
	    Min = 0,
	    Max = 1,
	    Default = 0.15,
	    Decimal = 20,
	    Suffix = "seconds"
	})
	CPS = ShopQuickBuy:CreateSlider({
	    Name = "CPS",
	    Min = 1,
	    Max = 20,
	    Default = 20,
	    Darker = true
	})
end)

Run(function()
	local StaffDetector
	local Mode
	local Clans
	local Party
	local Profile
	local Users
	local BlacklistedClans: {string} = {"gg", "gg2", "DV", "DV2"}
	local BlacklistedUserIds: {number} = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275}
	local Joined, Rejoins, JoinTimes = {}, {}, {}
	local Watchers: {[Player]: RBXScriptConnection} = {}
	local Counts: {[string]: number} = {Spectate = 0, Mod = 0, Impossible = 0}
	local FlagColors: {[string]: string} = {Spectate = "rgb(236,129,43)", Mod = "rgb(250,50,56)", Impossible = "rgb(180,90,250)"}
	local Entries = {}
	local Window, InfoLabel, Expanded
	
	local function RefreshViewer()
	    if not Window then
	        return
	    end
	
	    local ShowList = Expanded and #Entries > 0
	    local Lines: {string} = {"<b>StaffDetector</b>", '<font size="4"> </font>'}
	    for _, v: string in {"Spectate", "Mod", "Impossible"} do
	        table.insert(Lines, `<font color="{FlagColors[v]}">{v}: {Counts[v]}</font>`)
	    end
	
	    if ShowList then
	        table.insert(Lines, '<font size="4"> </font>')
	        for i: number, v: {Name: string, Reason: string, Category: string} in Entries do
	            if i > 8 then
	                break
	            end
	            table.insert(Lines, `{v.Name} <font color="{FlagColors[v.Category]}">{v.Reason}</font>`)
	        end
	    end
	
	    InfoLabel.Text = table.concat(Lines, "\n")
	    local Bounds: Vector2 = GetFontBounds(RemoveTags(InfoLabel.Text), InfoLabel.TextSize, InfoLabel.FontFace)
	    local TitleBounds: Vector2 = GetFontBounds("StaffDetector", InfoLabel.TextSize, Font.new(InfoLabel.FontFace.Family, Enum.FontWeight.Bold))
	    Window.Size = UDim2.fromOffset(math.max(Bounds.X, TitleBounds.X) + 16, Bounds.Y + (ShowList and -8 or 4))
	end
	
	local function StaffFunction(Player: Player, CheckType: string)
	    if not vape.Loaded then
	        repeat task.wait() until vape.Loaded
	    end
	
	    SendNotification("StaffDetector", `Staff Detected ({CheckType}): {Player.Name} ({Player.UserId})`, 60, "alert")
	    Whitelist.customtags[Player.Name] = {{text = "GAME STAFF", color = Color3.new(1, 0, 0)}}
	    local Category: string = CheckType == "impossible_join" and "Impossible" or CheckType == "spectator" and "Spectate" or "Mod"
	    Counts[Category] += 1
	    table.insert(Entries, 1, {Name = Player.Name, Reason = CheckType, Category = Category})
	    RefreshViewer()
	
	    if Party.Enabled and not CheckType:find("clan") then
	        bedwars.PartyController:leaveParty()
	    end
	
	    if Mode.Value == "Uninject" then
	        task.spawn(function()
	            vape:Uninject()
	        end)
	        game:GetService("StarterGui"):SetCore("SendNotification", {
	            Title = "StaffDetector",
	            Text = `Staff Detected ({CheckType})\n{Player.Name} ({Player.UserId})`,
	            Duration = 60,
	        })
	    elseif Mode.Value == "Requeue" then
	        bedwars.QueueController:joinQueue(Store.queueType)
	    elseif Mode.Value == "Profile" then
	        vape.Save = function() end
	        if vape.Profile ~= Profile.Value then
	            vape:Load(true, Profile.Value)
	        end
	    elseif Mode.Value == "AutoConfig" then
	        local SafeModules: {string} = {"AutoClicker", "Reach", "Sprint", "HitFix", "StaffDetector"}
	        vape.Save = function() end
	        for ModuleName: string, v: any in vape.Modules do
	            if not (table.find(SafeModules, ModuleName) or v.Category == "Render") then
	                if v.Enabled then
	                    v:Toggle()
	                end
	                v:SetBind("")
	            end
	        end
	    end
	end
	
	local function NoteSpectator(Player: Player, Reason: string)
	    SendNotification("StaffDetector", `Spectator {Player.Name} joined {Reason}`, 20, "warning")
	    Counts.Spectate += 1
	    table.insert(Entries, 1, {Name = Player.Name, Reason = "spectator", Category = "Spectate"})
	    RefreshViewer()
	end
	
	local function CheckJoin(Player: Player, Connection: RBXScriptConnection)
	    if Player:GetAttribute("Team") or not Player:GetAttribute("Spectator") or Store.matchState ~= 1 or bedwars.Store:getState().Game.customMatch or (tick() - (JoinTimes[Player.UserId] or 0)) > 20 then
	        return
	    end
	
	    Connection:Disconnect()
	    task.wait(5)
	    if (not StaffDetector.Enabled) or Player.Parent ~= Players or Player:GetAttribute("Team") or not Player:GetAttribute("Spectator") then
	        return
	    end
	
	    if Rejoins[Player.UserId] then
	        NoteSpectator(Player, "back after leaving")
	        return
	    end
	
	    if Player.FollowUserId ~= 0 and Joined[Player.FollowUserId] then
	        NoteSpectator(Player, `following {Joined[Player.FollowUserId]}`)
	        return
	    end
	
	    local Success, Pages = pcall(Players.GetFriendsAsync, Players, Player.UserId)
	    if not Success then
	        return
	    end
	
	    local Friend, Finished = nil, Pages.IsFinished
	    for _ = 1, 6 do
	        for _, v: any in Pages:GetCurrentPage() do
	            if Joined[v.Id] then
	                Friend = Joined[v.Id]
	                break
	            end
	        end
	        if Friend or Finished then
	            break
	        end
	        if not pcall(Pages.AdvanceToNextPageAsync, Pages) then
	            return
	        end
	        Finished = Pages.IsFinished
	    end
	
	    if Friend then
	        NoteSpectator(Player, `from {Friend}`)
	    elseif Finished then
	        StaffFunction(Player, "impossible_join")
	        return true
	    end
	end
	
	local function Added(Player: Player)
	    if Joined[Player.UserId] then
	        Rejoins[Player.UserId] = true
	    end
	    Joined[Player.UserId] = Player.Name
	    local Teleported = Player:GetAttribute("LastTeleported")
	    JoinTimes[Player.UserId] = Teleported and (tick() - math.min(workspace:GetServerTimeNow() - Teleported, 60)) or tick()
	    if Player == LocalPlayer then
	        return
	    end
	
	    if table.find(BlacklistedUserIds, Player.UserId) or table.find(Users.ListEnabled, tostring(Player.UserId)) then
	        StaffFunction(Player, "blacklisted_user")
	    else
	        local Success, Response = pcall(function()
	            return Player:GetRankInGroup(5774246)
	        end)
	        if not Success then
	            SendNotification("StaffDetector", Response, 30, "alert")
	        end
	
	        if (Success and Response or 0) >= 100 then
	            StaffFunction(Player, "staff_role")
	        else
	            local Connection: RBXScriptConnection
	            Connection = Player:GetAttributeChangedSignal("Spectator"):Connect(function()
	                CheckJoin(Player, Connection)
	            end)
	            Watchers[Player] = Connection
	            StaffDetector:Clean(Connection)
	            if CheckJoin(Player, Connection) then
	                return
	            end
	
	            if not Player:GetAttribute("ClanTag") then
	                Player:GetAttributeChangedSignal("ClanTag"):Wait()
	            end
	
	            if table.find(BlacklistedClans, Player:GetAttribute("ClanTag")) and vape.Loaded and Clans.Enabled then
	                Connection:Disconnect()
	                StaffFunction(Player, `blacklisted_clan_{Player:GetAttribute("ClanTag"):lower()}`)
	            end
	        end
	    end
	end
	
	StaffDetector = vape.Categories.Utility:CreateModule({
	    Name = "StaffDetector",
	    Function = function(Callback: boolean)
	        if Callback then
	            StaffDetector:Clean(Players.PlayerAdded:Connect(Added))
	            StaffDetector:Clean(Players.PlayerRemoving:Connect(function(Player: Player)
	                local Connection: RBXScriptConnection? = Watchers[Player]
	                if Connection then
	                    Connection:Disconnect()
	                    Watchers[Player] = nil
	                end
	            end))
	            for _, v: Player in Players:GetPlayers() do
	                task.spawn(Added, v)
	            end
	        else
	            table.clear(Joined)
	            table.clear(Rejoins)
	            table.clear(JoinTimes)
	            table.clear(Watchers)
	        end
	    end,
	    Tooltip = "Detects people with a staff rank ingame"
	})
	
	Mode = StaffDetector:CreateDropdown({
	    Name = "Mode",
	    List = {"Uninject", "Profile", "Requeue", "AutoConfig", "Notify"},
	    Function = function(Val: string)
	        if Profile.Object then
	            Profile.Object.Visible = Val == "Profile"
	        end
	    end
	})
	Clans = StaffDetector:CreateToggle({
	    Name = "Blacklist clans",
	    Default = true
	})
	Party = StaffDetector:CreateToggle({
	    Name = "Leave party"
	})
	Profile = StaffDetector:CreateTextBox({
	    Name = "Profile",
	    Default = "default",
	    Darker = true,
	    Visible = false
	})
	Users = StaffDetector:CreateTextList({
	    Name = "Users",
	    Placeholder = "player (userid)"
	})
	StaffDetector:CreateToggle({
	    Name = "Viewer",
	    Function = function(Callback: boolean)
	        if Callback and not Window then
	            Window = Instance.new("TextButton")
	            Window.Name = "StaffDetectorViewer"
	            Window.Position = UDim2.fromOffset(12, 120)
	            Window.BackgroundColor3 = Color3.new()
	            Window.BackgroundTransparency = 0.5
	            Window.Text = ""
	            Window.AutoButtonColor = false
	            Window.Parent = vape.gui.ScaledGui
	            AddBlur(Window)
	            local Corner: UICorner = Instance.new("UICorner")
	            Corner.CornerRadius = UDim.new(0, 5)
	            Corner.Parent = Window
	
	            InfoLabel = Instance.new("TextLabel")
	            InfoLabel.Size = UDim2.new(1, -16, 1, -16)
	            InfoLabel.Position = UDim2.fromOffset(8, 8)
	            InfoLabel.BackgroundTransparency = 1
	            InfoLabel.TextXAlignment = Enum.TextXAlignment.Left
	            InfoLabel.TextYAlignment = Enum.TextYAlignment.Top
	            InfoLabel.TextSize = 16
	            InfoLabel.TextColor3 = Color3.new(1, 1, 1)
	            InfoLabel.TextStrokeColor3 = Color3.new()
	            InfoLabel.TextStrokeTransparency = 0.8
	            InfoLabel.Font = Enum.Font.Arial
	            InfoLabel.RichText = true
	            InfoLabel.Parent = Window
	            StaffDetector:AddHUD(Window)
	
	            local PressPosition: UDim2? = nil
	            Window.MouseButton1Down:Connect(function()
	                PressPosition = Window.Position
	            end)
	
	            Window.MouseButton1Click:Connect(function()
	                if PressPosition == Window.Position then
	                    Expanded = not Expanded
	                    RefreshViewer()
	                end
	            end)
	        end
	
	        if Window then
	            Window.Visible = Callback
	            RefreshViewer()
	        end
	    end,
	    Tooltip = "Shows a panel with detection counts, click it to list who tripped them and drag it while the GUI is open to move it"
	})
	task.spawn(function()
	    repeat task.wait(1) until vape.Loaded or vape.Loaded == nil
	    if vape.Loaded and StaffDetector.Toggle and not StaffDetector.Enabled then
	        StaffDetector:Toggle()
	    end
	end)
end)

