Run(function()
	local AutoBedDefense
	local Repair
	local Upgrade
	local Range
	local Reserve
	
	local Holding, Held
	
	AutoBedDefense = vape.Categories.World:CreateModule({
	    Name = "AutoBedDefense",
	    Function = function(Callback: boolean)
	        if Callback then
	            Holding, Held = nil, false
	
	            AutoBedDefense:Clean(ProximityPromptService.PromptButtonHoldBegan:Connect(function(Prompt: ProximityPrompt)
	                if Prompt == Holding then
	                    Held = true
	                end
	            end))
	            AutoBedDefense:Clean(ProximityPromptService.PromptButtonHoldEnded:Connect(function(Prompt: ProximityPrompt)
	                if Prompt == Holding then
	                    Held = false
	                end
	            end))
	
	            repeat
	                if Entity.isAlive then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local Iron = GetItem("iron")
	                    Iron = (Iron and Iron.amount or 0) - Reserve.Value
	                    local Target
	
	                    for _, v: ProximityPrompt in CollectionService:GetTagged("UpgradeBedDefense") do
	                        local Part = v.Parent
	                        if not Part or not Part:IsA("BasePart") or (LocalPosition - Part.Position).Magnitude > Range.Value then
	                            continue
	                        end
	
	                        local Tier = bedwars.BedDefenseMeta[(v:GetAttribute("DefenseLevel") or 0) + 2]
	                        local Missing: number = v:GetAttribute("MissingBlocks") or 0
	                        if Missing > 0 and Repair.Enabled and Iron >= bedwars.NoBuildUtil.REPAIR_COST then
	                            Target = v
	                            break
	                        elseif Missing <= 0 and Upgrade.Enabled and Tier and Iron >= Tier.cost.amount then
	                            Target = v
	                            break
	                        end
	                    end
	
	                    if Target ~= Holding then
	                        if Holding then
	                            Holding:InputHoldEnd()
	                        end
	                        Holding, Held = Target, false
	                        if Target then
	                            Target:InputHoldBegin()
	                        end
	                    elseif Target and not Held then
	                        Target:InputHoldBegin()
	                    end
	                end
	                task.wait(0.2)
	            until not AutoBedDefense.Enabled
	        else
	            if Holding then
	                Holding:InputHoldEnd()
	            end
	            Holding, Held = nil, false
	        end
	    end,
	    Tooltip = "Holds the bed defense prompt for you so your bed stays repaired and upgraded"
	})
	
	Range = AutoBedDefense:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = 14,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Reserve = AutoBedDefense:CreateSlider({
	    Name = "Reserve",
	    Min = 0,
	    Max = 64,
	    Default = 0,
	    Suffix = "iron",
	    Tooltip = "Iron to leave alone for the shop"
	})
	Repair = AutoBedDefense:CreateToggle({
	    Name = "Repair",
	    Default = true,
	    Tooltip = "Replaces the layers an enemy broke, 5 iron each"
	})
	Upgrade = AutoBedDefense:CreateToggle({
	    Name = "Upgrade",
	    Default = true,
	    Tooltip = "Buys the next defense tier once the defense is whole again"
	})
end)

Run(function()
	local AutoTool
	local Mode
	local Delay = {}
	local SwitchBack
	local Old, BreakEvent
	local Looking, Deadline, Previous, Switching = nil, 0, nil, false
	
	local function GetToolSlot(Block)
	    if not Block or Block:GetAttribute("NoBreak") or Block:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or 0}NoBreak`) then
	        return
	    end
	
	    local Meta = bedwars.ItemMeta[Block.Name]
	    local Tool = Meta and Meta.block and Store.tools[Meta.block.breakType]
	    if not Tool or (Store.hand and Store.hand.tool == Tool.tool) then
	        return
	    end
	
	    for i: number, v: any in Store.inventory.hotbar do
	        if v.item and v.item.itemType == Tool.itemType then
	            return i - 1
	        end
	    end
	    return
	end
	
	local function SwitchTo(Slot: number)
	    if Switching then
	        return
	    end
	
	    Switching = true
	    task.spawn(function()
	        HotbarSwitch(Slot)
	        Switching = false
	    end)
	end
	
	AutoTool = vape.Categories.World:CreateModule({
	    Name = "AutoTool",
	    Function = function(Callback: boolean)
	        if Callback then
	            Looking, Deadline, Previous, Switching = nil, 0, nil, false
	
	            BreakEvent = Instance.new("BindableEvent")
	            AutoTool:Clean(BreakEvent)
	            AutoTool:Clean(BreakEvent.Event:Connect(function()
	                ContextActionService:CallFunction("block-break", Enum.UserInputState.Begin, newproxy(true))
	            end))
	
	            AutoTool:Clean(RunService.Heartbeat:Connect(function()
	                if Mode.Value ~= "Look" or not Entity.isAlive then
	                    return
	                end
	
	                local HeldMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]
	                if not (HeldMeta and HeldMeta.breakBlock) then
	                    Looking, Previous = nil, nil
	                    return
	                end
	
	                local Placer = Store.blockPlacer or (bedwars.BlockPlacementController and bedwars.BlockPlacementController.blockPlacer)
	                local Selector = Placer and Placer.clientManager and Placer.clientManager:getBlockSelector()
	                local Info = Selector and Selector:getMouseInfo(1, {ray = not UserInputService.KeyboardEnabled and Camera:ScreenPointToRay(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2 - GuiService:GetGuiInset().Y) or nil})
	                local Block = Info and Info.target and Info.target.blockInstance or nil
	                if not Block then
	                    Looking = nil
	                    if SwitchBack.Enabled and Previous then
	                        SwitchTo(Previous)
	                        Previous = nil
	                    end
	                    return
	                end
	
	                if Block ~= Looking then
	                    Looking, Deadline = Block, tick() + Delay:GetRandomValue()
	                    return
	                end
	                if tick() < Deadline then
	                    return
	                end
	
	                local Slot = GetToolSlot(Block)
	                if Slot then
	                    Previous = Previous or (Store.hand.tool and GetHotbar(Store.hand.tool) or nil)
	                    SwitchTo(Slot)
	                end
	            end))
	
	            Old = bedwars.BlockBreaker.hitBlock
	            bedwars.BlockBreaker.hitBlock = function(self, Maid, MouseRay, ...)
	                if Mode.Value == "Break" then
	                    local Info = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay})
	                    local Slot = GetToolSlot(Info and Info.target and Info.target.blockInstance or nil)
	                    if Slot then
	                        task.spawn(function()
	                            if HotbarSwitch(Slot) and UserInputService:IsMouseButtonPressed(0) then
	                                BreakEvent:Fire()
	                            end
	                        end)
	                    end
	                end
	                return Old(self, Maid, MouseRay, ...)
	            end
	        else
	            Looking, Previous = nil, nil
	            if Old then
	                bedwars.BlockBreaker.hitBlock = Old
	                Old = nil
	            end
	        end
	    end,
	    Tooltip = "Automatically selects the correct tool"
	})
	
	Mode = AutoTool:CreateDropdown({
	    Name = "Mode",
	    List = {"Look", "Break"},
	    Function = function(Val: string)
	        if Delay.Object then
	            Delay.Object.Visible = Val == "Look"
	            SwitchBack.Object.Visible = Val == "Look"
	        end
	    end,
	    Default = "Break",
	    Tooltip = "Look swaps while you are still aiming at the block, Break swaps on the first hit like it used to"
	})
	Delay = AutoTool:CreateTwoSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    DefaultMin = 0.06,
	    DefaultMax = 0.16,
	    Darker = true,
	    Suffix = "seconds",
	    Tooltip = "How long you have to be looking at the block before it swaps"
	})
	SwitchBack = AutoTool:CreateToggle({
	    Name = "Switch back",
	    Darker = true,
	    Tooltip = "Puts the item you were holding back once you look away"
	})
end)

Run(function()
	local AutoTrap
	local Mode
	local Traps
	local Target
	local Radius
	local Range
	local Amount
	local PlaceRange
	local Delay
	local Snap
	local IgnoreWalls
	local Switch
	local Notify
	
	local Placed = {}
	local Previous
	local Offsets: {number} = {3, 0, -3, -6}
	local SightParams: RaycastParams = RaycastParams.new()
	SightParams.FilterType = Enum.RaycastFilterType.Exclude
	
	local function GetBed(LocalPosition: Vector3)
	    local Own: string = `Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`
	    local Closest, ClosestDistance = nil, Range.Value
	
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        local Mine: boolean = v:GetAttribute(Own) and true or false
	        if Mine ~= (Target.Value == "Your bed") then
	            continue
	        end
	
	        local Distance: number = (LocalPosition - v.Position).Magnitude
	        if Distance < ClosestDistance then
	            Closest, ClosestDistance = v, Distance
	        end
	    end
	    return Closest
	end
	
	local function GetTrap()
	    for _, Name: string in Traps.ListEnabled do
	        if GetItem(Name) then
	            return Name
	        end
	    end
	end
	
	local function GetRing(Bed: BasePart): {Vector3}
	    local Spots: {Vector3} = {}
	    local Step: number = Radius.Value * 3
	
	    for X: number = -Step, Step, 3 do
	        for Z: number = -Step, Step, 3 do
	            if math.abs(X) ~= Step and math.abs(Z) ~= Step then
	                continue
	            end
	
	            local Position: Vector3 = Bed.Position + Vector3.new(X, 0, Z)
	            if not GetPlacedBlock(Position) and GetPlacedBlock(Position - Vector3.new(0, 3, 0)) then
	                table.insert(Spots, Position)
	            end
	        end
	    end
	
	    table.sort(Spots, function(A: Vector3, B: Vector3): boolean
	        return (Bed.Position - A).Magnitude < (Bed.Position - B).Magnitude
	    end)
	    return Spots
	end
	
	local function GetFeetCell(Ent: any): Vector3
	    return RoundPosition(Ent.RootPart.Position - Vector3.new(0, Ent.HipHeight - 1.5, 0))
	end
	
	local function IsInside(Ent: any, Cell: Vector3): boolean
	    local Feet: Vector3 = GetFeetCell(Ent)
	    return Feet.X == Cell.X and Feet.Z == Cell.Z and (Cell.Y == Feet.Y or Cell.Y == Feet.Y + 3)
	end
	
	local function IsOccupied(Cell: Vector3): boolean
	    if IsInside(Entity.character, Cell) then
	        return true
	    end
	
	    for _, v: any in Entity.List do
	        if v.Player and IsInside(v, Cell) then
	            return true
	        end
	    end
	    return false
	end
	
	local function GetGround(Cell: Vector3): Vector3?
	    for Drop: number = 1, 4 do
	        local Below: Vector3 = Cell - Vector3.new(0, Drop * 3, 0)
	        if GetPlacedBlock(Below) then
	            return Below + Vector3.new(0, 3, 0)
	        end
	    end
	    return nil
	end
	
	local function GetSpot(Ent: any): Vector3?
	    local Heading: Vector3 = Ent.Humanoid.MoveDirection * Vector3.new(1, 0, 1)
	    if Heading.Magnitude < 0.5 then
	        return nil
	    end
	
	    local Ground: Vector3? = GetGround(GetFeetCell(Ent))
	    if not Ground then
	        return nil
	    end
	
	    local Root: BasePart = Ent.RootPart
	    local Direction: Vector3 = Heading.Unit
	    local Speed: number = math.max((Root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude, 16)
	    local Lead: number = math.clamp(Speed * (0.6 + (Store.ping.total or 0)), 6, 15)
	    local Level: number = Ground.Y
	    local Spot: Vector3?
	
	    for Step: number = 3, Lead, 3 do
	        local Point: Vector3 = Root.Position + Direction * Step
	        local Found: Vector3?
	        for _, Offset: number in Offsets do
	            local Cell: Vector3 = RoundPosition(Vector3.new(Point.X, Level + Offset, Point.Z))
	            if not GetPlacedBlock(Cell) and GetPlacedBlock(Cell - Vector3.new(0, 3, 0)) then
	                Found = Cell
	                break
	            end
	        end
	
	        if not Found then
	            break
	        end
	        Spot, Level = Found, Found.Y
	    end
	
	    return Spot
	end
	
	local function InSight(Ent: any): boolean
	    local Origin: Vector3 = Entity.character.Head.Position
	    return Entity.Raycast(Origin, Ent.Head.Position - Origin, SightParams) == nil
	end
	
	local function TrapBed()
	    local Item = GetTrap()
	    local Bed = Item and GetBed(Entity.character.RootPart.Position)
	    if not Bed then
	        return
	    end
	
	    if Switch.Enabled then
	        Previous = Previous or (Store.hand.tool and GetHotbar(Store.hand.tool) or nil)
	    end
	
	    local Used: number = 0
	    for _, Position: Vector3 in GetRing(Bed) do
	        if Used >= Amount.Value then
	            break
	        end
	        if tick() < (Placed[Position] or 0) then
	            continue
	        end
	
	        bedwars.placeBlock(Position, Item)
	        Placed[Position] = tick() + 10
	        Used += 1
	
	        if Notify.Enabled then
	            SendNotification("AutoTrap", `Placed {Item}`, 3)
	        end
	        task.wait(1 / 12)
	
	        Item = GetTrap()
	        if not Item then
	            break
	        end
	    end
	
	    if Used > 0 and Switch.Enabled then
	        HotbarSwitch(Previous)
	        Previous = nil
	    end
	end
	
	local function TrapEnemies(): boolean
	    local Item: string? = Snap.Enabled and GetItem("snap_trap") and "snap_trap" or nil
	    if not Item then
	        return false
	    end
	
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Enemies: {any} = {}
	    for _, v: any in Entity.List do
	        if v.Targetable and v.Player and v.Health > 0 and (v.RootPart.Position - LocalPosition).Magnitude <= PlaceRange.Value + 15 then
	            table.insert(Enemies, v)
	        end
	    end
	    if #Enemies == 0 then
	        return false
	    end
	
	    table.sort(Enemies, function(A: any, B: any): boolean
	        return (A.RootPart.Position - LocalPosition).Magnitude < (B.RootPart.Position - LocalPosition).Magnitude
	    end)
	
	    if IgnoreWalls.Enabled then
	        local Filter: {Instance} = {Camera, LocalPlayer.Character}
	        for _, v: any in Entity.List do
	            table.insert(Filter, v.Character)
	        end
	        SightParams.FilterDescendantsInstances = Filter
	    end
	
	    for _, v: any in Enemies do
	        if IgnoreWalls.Enabled and not InSight(v) then
	            continue
	        end
	
	        local Spot: Vector3? = GetSpot(v)
	        if not Spot or (Spot - LocalPosition).Magnitude > PlaceRange.Value or tick() < (Placed[Spot] or 0) or IsOccupied(Spot) then
	            continue
	        end
	
	        if Switch.Enabled then
	            Previous = Previous or (Store.hand.tool and GetHotbar(Store.hand.tool) or nil)
	        end
	
	        bedwars.placeBlock(Spot, Item)
	        Placed[Spot] = tick() + 10
	
	        if Notify.Enabled then
	            SendNotification("AutoTrap", `Placed {Item} in front of {v.Player.DisplayName}`, 3)
	        end
	
	        if Switch.Enabled then
	            HotbarSwitch(Previous)
	            Previous = nil
	        end
	        return true
	    end
	    return false
	end
	
	AutoTrap = vape.Categories.World:CreateModule({
	    Name = "AutoTrap",
	    Function = function(Callback: boolean)
	        if Callback then
	            table.clear(Placed)
	            Previous = nil
	
	            repeat
	                local Pause: number = Delay.Value
	                if Entity.isAlive and CanPlace() then
	                    if Mode.Value == "Enemies" then
	                        Pause = TrapEnemies() and Delay.Value or 0.1
	                    else
	                        TrapBed()
	                    end
	                end
	                task.wait(Pause)
	            until not AutoTrap.Enabled
	        else
	            table.clear(Placed)
	            HotbarSwitch(Previous)
	            Previous = nil
	        end
	    end,
	    Tooltip = "Places traps for you, either in a ring around a bed or right where nearby enemies are walking"
	})
	
	Mode = AutoTrap:CreateDropdown({
	    Name = "Mode",
	    List = {"Bed ring", "Enemies"},
	    Function = function(Val: string)
	        if Traps then
	            local EnemyMode: boolean = Val == "Enemies"
	            Target.Object.Visible = not EnemyMode
	            Radius.Object.Visible = not EnemyMode
	            Range.Object.Visible = not EnemyMode
	            Amount.Object.Visible = not EnemyMode
	            Traps.Object.Visible = not EnemyMode
	            PlaceRange.Object.Visible = EnemyMode
	            Snap.Object.Visible = EnemyMode
	            IgnoreWalls.Object.Visible = EnemyMode
	        end
	    end,
	    Tooltip = "Bed ring - circles a bed with the traps from the list\nEnemies - drops a trap on the block an enemy is about to walk over"
	})
	Target = AutoTrap:CreateDropdown({
	    Name = "Target",
	    List = {"Your bed", "Enemy bed"},
	    Tooltip = "Your bed - defends your own base\nEnemy bed - leaves them for whoever comes back to defend"
	})
	Radius = AutoTrap:CreateSlider({
	    Name = "Radius",
	    Min = 1,
	    Max = 5,
	    Default = 2,
	    Suffix = function(Val: number)
	        return Val <= 1 and "block" or "blocks"
	    end,
	    Tooltip = "How far out from the bed the ring sits"
	})
	Range = AutoTrap:CreateSlider({
	    Name = "Range",
	    Min = 4,
	    Max = 40,
	    Default = 20,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "How close the bed has to be before it starts placing"
	})
	Amount = AutoTrap:CreateSlider({
	    Name = "Amount",
	    Min = 1,
	    Max = 8,
	    Default = 3,
	    Suffix = function(Val: number)
	        return Val <= 1 and "trap" or "traps"
	    end,
	    Tooltip = "Traps to place per pass"
	})
	PlaceRange = AutoTrap:CreateSlider({
	    Name = "Place Range",
	    Min = 1,
	    Max = 30,
	    Default = 15,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "How far from you the trap can go, it aims at where the enemy will be in about half a second"
	})
	Delay = AutoTrap:CreateSlider({
	    Name = "Delay",
	    Min = 0.2,
	    Max = 10,
	    Default = 2,
	    Decimal = 100,
	    Suffix = "seconds",
	    Tooltip = "Wait between passes, in Enemies mode the wait after each trap"
	})
	Snap = AutoTrap:CreateToggle({
	    Name = "Use Snap",
	    Default = true,
	    Visible = false,
	    Tooltip = "Places the Trapper kit's snap traps from your inventory"
	})
	IgnoreWalls = AutoTrap:CreateToggle({
	    Name = "Ignore behind walls",
	    Visible = false,
	    Tooltip = "Skips enemies you cannot see from your head"
	})
	Switch = AutoTrap:CreateToggle({
	    Name = "Switch back",
	    Default = true,
	    Tooltip = "Gives your old hotbar slot back after placing"
	})
	Notify = AutoTrap:CreateToggle({
	    Name = "Notify",
	    Tooltip = "Tells you every time it places one"
	})
	Traps = AutoTrap:CreateTextList({
	    Name = "Traps",
	    Default = {
	        "invisible_landmine",
	        "snap_trap",
	        "spike_trap",
	        "tesla_trap",
	        "grave_trap",
	        "lucky_block_trap"
	    },
	    Darker = true,
	    Placeholder = "item",
	    Tooltip = "Which traps to place, in this order"
	})
end)

Run(function()
	local BedAssist
	local AimMode
	local Speed
	local Range
	local Angle
	local Shake
	local Mode
	local Limit
	local AutoMine
	local MineBed
	local Started, NextSearch = 0, 0
	local Target, TargetBed, TargetPosition
	local Old, MiningRay, MiningPosition
	local Generator: Random = Random.new()
	local Sides: {Vector3} = {Vector3.xAxis, -Vector3.xAxis, Vector3.yAxis, -Vector3.yAxis, Vector3.zAxis, -Vector3.zAxis}
	local Points: {Vector3} = {Vector3.zero, Vector3.xAxis * 1.35, -Vector3.xAxis * 1.35, Vector3.yAxis * 1.35, -Vector3.yAxis * 1.35, Vector3.zAxis * 1.35, -Vector3.zAxis * 1.35}
	local RayParams: RaycastParams = RaycastParams.new()
	RayParams.FilterType = Enum.RaycastFilterType.Exclude
	
	local function GetAim(Block, Position: Vector3, Direction: Vector3)
	    for _, v: Vector3 in Points do
	        if Block.Name == "bed" and (v == Vector3.zero or GetPlacedBlock(Position + v.Unit * 3)) then
	            continue
	        end
	        local Aim: Vector3 = Position + v
	        local Offset: Vector3 = Aim - Camera.CFrame.Position
	        if Offset.Magnitude > 0.001 and Offset.Unit:Dot(Direction) >= math.cos(math.rad(Angle.Value)) then
	            local Hit: RaycastResult? = bedwars.QueryUtil:raycast(Camera.CFrame.Position, Offset.Unit * (Offset.Magnitude + 3), RayParams)
	            if Hit and (Hit.Instance == Block or Hit.Instance:IsDescendantOf(Block)) then
	                return Block.Name == "bed" and Aim or Hit.Position
	            end
	        end
	    end
	    return nil
	end
	
	local function GetBestPosition(Bed: BasePart, Direction: Vector3)
	    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(Bed.Name)
	    local Positions = Handler and Handler:getContainedPositions(Bed) or {bedwars.BlockController:getBlockPosition(Bed.Position)}
	    local Queue, Distances, Depths, Visited = {}, {}, {}, {}
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local BlockStore = bedwars.BlockController:getStore()
	    local Cost, Depth, Distance, Magnitude = math.huge, math.huge, math.huge, math.huge
	    local Block, Position
	    for _, v: Vector3 in Positions do
	        if BlockStore:getBlockAt(v) == Bed then
	            Distances[v], Depths[v] = 0, 0
	            table.insert(Queue, {position = v, cost = 0, depth = 0})
	        end
	    end
	
	    for _ = 1, 512 do
	        local BestIndex, Node
	        for i: number, v: {position: Vector3, cost: number, depth: number} in Queue do
	            if not Node or v.cost < Node.cost or v.cost == Node.cost and v.depth < Node.depth then
	                BestIndex, Node = i, v
	            end
	        end
	        if not Node or Node.cost > Cost then
	            break
	        end
	        table.remove(Queue, BestIndex)
	        if Visited[Node.position] then
	            continue
	        end
	        Visited[Node.position] = true
	        local Current = BlockStore:getBlockAt(Node.position)
	        local WorldPosition: Vector3 = Node.position * 3
	        local NodeMagnitude: number = (LocalPosition - WorldPosition).Magnitude
	        local NodeDistance: number = math.huge
	        for _, v: Vector3 in Positions do
	            NodeDistance = math.min(NodeDistance, (Node.position - v).Magnitude)
	        end
	        if Current and NodeMagnitude <= math.min(Range.Value, bedwars.BlockBreaker:getRange()) then
	            local Point = GetAim(Current, WorldPosition, Direction)
	            if Point and (Node.cost < Cost or Node.depth < Depth or Node.depth == Depth and (NodeDistance < Distance or NodeDistance == Distance and ((Current == Target and Block ~= Target) or (Current == Target) == (Block == Target) and NodeMagnitude < Magnitude))) then
	                Block, Position = Current, WorldPosition
	                Cost, Depth, Distance, Magnitude = Node.cost, Node.depth, NodeDistance, NodeMagnitude
	            end
	        end
	
	        for _, v: Vector3 in Sides do
	            local NextPosition: Vector3 = Node.position + v
	            if Visited[NextPosition] or (NextPosition * 3 - Bed.Position).Magnitude > 18 then
	                continue
	            end
	            local NextBlock = BlockStore:getBlockAt(NextPosition)
	            local Meta = NextBlock and bedwars.ItemMeta[NextBlock.Name]
	            if not Meta or not Meta.block or NextBlock:GetAttribute("NoBreak") or NextBlock:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or not bedwars.BlockController:isBlockBreakable({blockPosition = NextPosition}, LocalPlayer) then
	                continue
	            end
	            local Data = BlockStore:getBlockData(NextPosition)
	            local Health = Data and Data:GetAttribute(bedwars.BlockBreaker.blockHealthbar:getHealthKey(NextBlock)) or NextBlock:GetAttribute("Health") or Meta.block.health
	            local Damage = bedwars.BlockController:calculateBlockDamage(LocalPlayer, {blockPosition = NextPosition})
	            if Damage <= 0 then
	                continue
	            end
	            local Hits: number = Node.cost + math.max(math.ceil((Health or 10) / Damage), 1)
	            local Steps: number = Node.depth + 1
	            if Hits < (Distances[NextPosition] or math.huge) or Hits == Distances[NextPosition] and Steps < Depths[NextPosition] then
	                Distances[NextPosition], Depths[NextPosition] = Hits, Steps
	                table.insert(Queue, {position = NextPosition, cost = Hits, depth = Steps})
	            end
	        end
	    end
	    return Block, Position, Cost, Depth, Magnitude
	end
	
	BedAssist = vape.Categories.World:CreateModule({
	    Name = "BedAssist",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Beds = Collection("bed", BedAssist)
	            local Maid = getmetatable(bedwars.BlockBreaker.maid).new()
	            BedAssist:Clean(function()
	                Maid:DoCleaning()
	            end)
	            Old = bedwars.BlockBreaker.clientManager:getBlockSelector().getMouseInfo
	            bedwars.BlockBreaker.clientManager:getBlockSelector().getMouseInfo = function(self, SelectMode, Params)
	                local Info = Old(self, SelectMode, Params)
	                if MiningRay and Params and Params.ray == MiningRay and Info and Info.target and Info.target.blockInstance == TargetBed then
	                    Info = table.clone(Info)
	                    Info.target = table.clone(Info.target)
	                    Info.target.blockRef = {blockPosition = bedwars.BlockController:getBlockPosition(TargetPosition)}
	                    Info.target.hitPosition = MiningPosition
	                end
	                return Info
	            end
	
	            BedAssist:Clean(RunService.PostSimulation:Connect(function(DeltaTime: number)
	                local HeldMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]
	                if not Entity.isAlive or Store.matchState ~= 1 or LocalPlayer:GetAttribute("Spectator") or LocalPlayer:GetAttribute("DenyBlockBreak") or UserInputService:GetFocusedTextBox() or GuiService.MenuIsOpen or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) or Limit.Enabled and not (HeldMeta and HeldMeta.breakBlock) then
	                    Target, TargetBed, TargetPosition, NextSearch = nil, nil, nil, 0
	                    return
	                end
	
	                local MouseLocation: Vector2 = UserInputService.MouseEnabled and UserInputService:GetMouseLocation() or Camera.ViewportSize / 2
	                local MouseRay: Ray = Camera:ViewportPointToRay(MouseLocation.X, MouseLocation.Y)
	                RayParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera}
	                if tick() >= NextSearch or Target and not Target.Parent then
	                    local Block, Bed, Position
	                    local Cost, Depth, Distance = math.huge, math.huge, math.huge
	                    for _, v: BasePart in Beds do
	                        if not v.Parent or v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or (v:GetAttribute("BedShieldEndTime") or 0) > workspace:GetServerTimeNow() or (v.Position - Entity.character.RootPart.Position).Magnitude > Range.Value + 3 or not bedwars.BlockController:isBlockBreakable({blockPosition = bedwars.BlockController:getBlockPosition(v.Position)}, LocalPlayer) then
	                            continue
	                        end
	                        local BedBlock, BedPosition, BedCost, BedDepth, BedMagnitude = GetBestPosition(v, MouseRay.Direction)
	                        if BedBlock and (BedCost < Cost or BedCost == Cost and (BedDepth < Depth or BedDepth == Depth and BedMagnitude < Distance)) then
	                            Block, Bed, Position, Cost, Depth, Distance = BedBlock, v, BedPosition, BedCost, BedDepth, BedMagnitude
	                        end
	                    end
	                    if Block ~= Target then
	                        Started = tick()
	                    end
	                    Target, TargetBed, TargetPosition, NextSearch = Block, Bed, Position, tick() + 0.15
	                end
	
	                if not Target or not Target.Parent or not TargetBed.Parent or TargetBed:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) or (TargetBed:GetAttribute("BedShieldEndTime") or 0) > workspace:GetServerTimeNow() or Target == TargetBed and not MineBed.Enabled or (Entity.character.RootPart.Position - TargetPosition).Magnitude > math.min(Range.Value, bedwars.BlockBreaker:getRange()) then
	                    return
	                end
	                local AimPosition = GetAim(Target, TargetPosition, MouseRay.Direction)
	                if not AimPosition then
	                    return
	                end
	                local AimSpeed: number = Speed.Value
	                if AimMode.Value == "Adaptive" then
	                    local Progress: number = math.clamp((tick() - Started) * AimSpeed * 0.5, 0, 1)
	                    AimSpeed *= Progress < 0.5 and 4 * Progress ^ 3 or 1 - (-2 * Progress + 2) ^ 3 / 2
	                end
	                local Alpha: number = 1 - math.exp(-AimSpeed * DeltaTime)
	                local Aim: Vector3 = AimPosition + Vector3.new(Generator:NextNumber(-1, 1), Generator:NextNumber(-1, 1), Generator:NextNumber(-1, 1)) * Shake.Value * 0.005
	                if Mode.Value == "Mouse" then
	                    local Screen, Visible = Camera:WorldToViewportPoint(Aim)
	                    if Visible then
	                        local Delta: Vector2 = (Vector2.new(Screen.X, Screen.Y) - MouseLocation) * Alpha
	                        mousemoverel(Delta.X, Delta.Y)
	                    end
	                else
	                    local Direction: Vector3 = (Aim - MouseRay.Origin).Unit
	                    local Axis: Vector3 = MouseRay.Direction:Cross(Direction)
	                    if Axis.Magnitude > 0.0001 then
	                        local Rotation: CFrame = CFrame.fromAxisAngle(Axis.Unit, math.acos(math.clamp(MouseRay.Direction:Dot(Direction), -1, 1)) * Alpha)
	                        Camera.CFrame = CFrame.new(Camera.CFrame.Position) * Rotation * Camera.CFrame.Rotation
	                    end
	                end
	
	                if AutoMine.Enabled and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and tick() - bedwars.BlockBreaker.lastHitTime >= bedwars.BlockBreaker:getCooldown() then
	                    MouseRay = Camera:ViewportPointToRay(MouseLocation.X, MouseLocation.Y)
	                    local Info = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(1, {ray = MouseRay, range = math.min(Range.Value, bedwars.BlockBreaker:getRange())})
	                    if Info and Info.target and Info.target.blockInstance == Target then
	                        Maid:DoCleaning()
	                        MiningRay, MiningPosition = Target == TargetBed and MouseRay or nil, AimPosition
	                        bedwars.BlockBreaker:hitBlock(Maid, MouseRay)
	                        MiningRay, MiningPosition = nil, nil
	                    end
	                end
	            end))
	        else
	            bedwars.BlockBreaker.clientManager:getBlockSelector().getMouseInfo = Old
	            MiningRay, MiningPosition = nil, nil
	            Target, TargetBed, TargetPosition, NextSearch = nil, nil, nil, 0
	        end
	    end,
	    Tooltip = "Smoothly aims and mines the weakest visible route into an enemy bed using normal reach and mining speed"
	})
	
	AimMode = BedAssist:CreateDropdown({
	    Name = "Mode",
	    List = {"Simple", "Adaptive"},
	    Default = "Simple"
	})
	local AimModes: {string} = {"Camera"}
	if UserInputService.MouseEnabled and mousemoverel then
	    table.insert(AimModes, "Mouse")
	end
	Mode = BedAssist:CreateDropdown({
	    Name = "Aim mode",
	    List = AimModes,
	    Default = "Camera"
	})
	Speed = BedAssist:CreateSlider({
	    Name = "Aim speed",
	    Min = 1,
	    Max = 20,
	    Default = 7
	})
	Range = BedAssist:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Never exceeds the game's normal mining reach"
	})
	Angle = BedAssist:CreateSlider({
	    Name = "View angle",
	    Min = 5,
	    Max = 180,
	    Default = 60,
	    Suffix = "degrees",
	    Tooltip = "Maximum angle away from your crosshair, 180 allows every direction"
	})
	Shake = BedAssist:CreateSlider({
	    Name = "Shake",
	    Min = 0,
	    Max = 100,
	    Default = 3
	})
	Limit = BedAssist:CreateToggle({Name = "Limit to item", Default = true})
	AutoMine = BedAssist:CreateToggle({
	    Name = "Auto mine",
	    Default = true,
	    Tooltip = "Mines only when your crosshair reaches the chosen block; disable for aim assistance only"
	})
	MineBed = BedAssist:CreateToggle({
	    Name = "Mine bed",
	    Default = true,
	    Tooltip = "Mines the bed as soon as it is visible; disable to stop once the defense is open"
	})
end)

Run(function()
	local BedPatcher
	local Mode
	local Whitelist
	local PlaceRange
	local Radius
	local Wool
	local Switch
	local NoAnimation
	local Limit
	local Layout, Adjacent = {}, {}
	local PlaceAnimation = bedwars.BlockController:getAnimationController():getAssetId(0)
	local Placing, Old = false
	
	for _, v: EnumItem in Enum.NormalId:GetEnumItems() do
	    table.insert(Adjacent, Vector3.FromNormalId(v) * 3)
	end
	
	local function GetBedNear()
	    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude < (PlaceRange.Value + Radius.Value) and v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            return v
	        end
	    end
	    return nil
	end
	
	local function GetBlock(ItemType: string?)
	    if Limit.Enabled then
	        local Hand = Store.hand.toolType == "block" and Store.hand.tool
	        if Hand and (not Wool.Enabled or Hand.Name:find("wool")) and table.find(Whitelist.ListEnabled, Hand.Name:find("wool") and "wool" or Hand.Name) then
	            return Hand.Name, Hand
	        end
	        return nil
	    end
	
	    local Best, Health
	    for _, v: any in Store.inventory.inventory.items do
	        local Block = bedwars.ItemMeta[v.itemType].block
	        if not Block or (Wool.Enabled and not v.itemType:find("wool")) then
	            continue
	        end
	        if not table.find(Whitelist.ListEnabled, v.itemType:find("wool") and "wool" or v.itemType) then
	            continue
	        end
	        if v.itemType == ItemType then
	            return v.itemType, v.tool
	        end
	        if not Health or (Block.health or 0) > Health then
	            Best, Health = v, Block.health or 0
	        end
	    end
	    return Best and Best.itemType or nil, Best and Best.tool or nil
	end
	
	local function ScanBed(Bed: BasePart)
	    table.clear(Layout)
	    for _, v: BasePart in Store.blocks do
	        if not v:HasTag("bed") and (v.Position - Bed.Position).Magnitude <= Radius.Value then
	            Layout[v.Position] = v.Name
	        end
	    end
	
	    local Holes = {}
	    for Position: Vector3, v: string in Layout do
	        for _, Offset: Vector3 in Adjacent do
	            local Cell: Vector3 = Position + Offset
	            if Layout[Cell] or Holes[Cell] or GetPlacedBlock(Cell) then
	                continue
	            end
	
	            local Walls: number = 0
	            for _, Side: Vector3 in Adjacent do
	                if Layout[Cell + Side] then
	                    Walls += 1
	                end
	            end
	
	            if Walls >= 4 then
	                Holes[Cell] = v
	            end
	        end
	    end
	
	    for Position: Vector3, v: string in Holes do
	        Layout[Position] = v
	    end
	end
	
	BedPatcher = vape.Categories.World:CreateModule({
	    Name = "BedPatcher",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Bed
	            Old = bedwars.AnimationUtil.playAnimation
	            bedwars.AnimationUtil.playAnimation = function(self, Player, AssetId, Config)
	                if Placing and NoAnimation.Enabled and AssetId == PlaceAnimation then
	                    return
	                end
	                return Old(self, Player, AssetId, Config)
	            end
	
	            BedPatcher:Clean(CollectionService:GetInstanceAddedSignal("block"):Connect(function(Block)
	                if Bed and not Block:HasTag("bed") and (Block.Position - Bed.Position).Magnitude <= Radius.Value then
	                    Layout[Block.Position] = Block.Name
	                end
	            end))
	
	            BedPatcher:Clean(VapeEvents.BreakBlockEvent.Event:Connect(function(BlockTable)
	                local Player = BlockTable.player
	                if Player and (Player == LocalPlayer or Player:GetAttribute("Team") == LocalPlayer:GetAttribute("Team")) then
	                    Layout[BlockTable.blockRef.blockPosition * 3] = nil
	                end
	            end))
	
	            repeat
	                local Found = GetBedNear()
	                if Found ~= Bed then
	                    Bed = Found
	                    if Bed then
	                        ScanBed(Bed)
	                    else
	                        table.clear(Layout)
	                    end
	                end
	
	                if Bed and Entity.isAlive then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local Holes = {}
	
	                    for Position: Vector3, v: string in Layout do
	                        if (LocalPosition - Position).Magnitude <= PlaceRange.Value and not GetPlacedBlock(Position) then
	                            table.insert(Holes, {Position, v})
	                        end
	                    end
	
	                    table.sort(Holes, function(A, B): boolean
	                        return (A[1] - Bed.Position).Magnitude < (B[1] - Bed.Position).Magnitude
	                    end)
	
	                    for _, v: {any} in Holes do
	                        local Position, ItemType = unpack(v)
	                        if GetPlacedBlock(Position) then
	                            continue
	                        end
	
	                        local Item, Tool = GetBlock(ItemType)
	                        if not Item then
	                            break
	                        end
	
	                        if Switch.Enabled and GetHotbar(Tool) and HotbarSwitch(GetHotbar(Tool)) then
	                            task.wait()
	                        end
	
	                        Placing = true
	                        bedwars.placeBlock(Position, Item)
	                        Placing = false
	                        task.wait(1 / bedwars.SharedConstants.BLOCK_PLACE_CPS)
	                    end
	                elseif not Bed and Mode.Value == "On Key" then
	                    SendNotification("BedPatcher", "Unable to locate bed", 5)
	                    BedPatcher:Toggle()
	                    break
	                end
	
	                task.wait(0.5)
	                if Mode.Value == "On Key" then
	                    BedPatcher:Toggle()
	                    break
	                end
	            until not BedPatcher.Enabled
	        else
	            bedwars.AnimationUtil.playAnimation = Old
	            Placing = false
	        end
	    end,
	    Tooltip = "Puts back the blocks an enemy broke out of your bed defense."
	})
	
	Mode = BedPatcher:CreateDropdown({
	    Name = "Mode",
	    List = {"Toggle", "On Key"},
	    Default = "Toggle"
	})
	Whitelist = BedPatcher:CreateTextList({
	    Name = "Whitelist",
	    Default = {"wool", "obsidian"}
	})
	PlaceRange = BedPatcher:CreateSlider({
	    Name = "Place Range",
	    Min = 1,
	    Max = 60,
	    Default = 15
	})
	Radius = BedPatcher:CreateSlider({
	    Name = "Defense Radius",
	    Min = 3,
	    Max = 30,
	    Default = 15,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end,
	    Tooltip = "How far out from the bed still counts as your defense"
	})
	Wool = BedPatcher:CreateToggle({Name = "Wool only", Tooltip = "Only uses wools to patch."})
	Switch = BedPatcher:CreateToggle({Name = "Auto Switch"})
	NoAnimation = BedPatcher:CreateToggle({
	    Name = "No Animation",
	    Tooltip = "Hides the arm swing every patched block would otherwise play"
	})
	Limit = BedPatcher:CreateToggle({Name = "Limit to item"})
end)

Run(function()
	local BedPlates
	local Background
	local Color
	local LayerCounter
	local LayerColor
	local Reference = {}
	local Shown: {[BillboardGui]: string} = setmetatable({}, {__mode = "k"})
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local function GetBlockLayerHealth(Block: string): number
	    local Meta = bedwars.ItemMeta[Block]
	    return Meta and Meta.block and Meta.block.health or 0
	end
	
	local function ScanSide(self, Start: Vector3, Layers)
	    for _, v: Vector3 in Sides do
	        local Found = {}
	        for Depth: number = 1, 15 do
	            local Block = GetPlacedBlock(Start + (v * Depth))
	            if not Block or Block == self or Block.Name == "bed" then
	                break
	            end
	            if not Block:GetAttribute("NoBreak") then
	                Found[Block.Name] = (Found[Block.Name] or 0) + 1
	            end
	        end
	
	        for Name: string, Count: number in Found do
	            Layers[Name] = math.max(Layers[Name] or 0, Count)
	        end
	    end
	end
	
	local function RefreshAdornee(Billboard: BillboardGui)
	    local Start: Vector3 = Billboard.Adornee.Position
	    local Layers = {}
	    local AlreadyGot = {}
	    ScanSide(Billboard.Adornee, Start, Layers)
	    ScanSide(Billboard.Adornee, Start + Vector3.new(0, 0, 3), Layers)
	    for Name: string, Count: number in Layers do
	        table.insert(AlreadyGot, {Name, Count})
	    end
	    table.sort(AlreadyGot, function(A, B): boolean
	        local HealthA, HealthB = GetBlockLayerHealth(A[1]), GetBlockLayerHealth(B[1])
	        return HealthA == HealthB and A[1] < B[1] or HealthA > HealthB
	    end)
	    Billboard.Enabled = #AlreadyGot > 0
	
	    local Key: {string} = {tostring(not LayerCounter or LayerCounter.Enabled)}
	    for _, v: {any} in AlreadyGot do
	        table.insert(Key, `{v[1]}:{v[2]}`)
	    end
	    local LayerKey: string = table.concat(Key, ",")
	    if Shown[Billboard] == LayerKey then return end
	    Shown[Billboard] = LayerKey
	
	    for _, v: Instance in Billboard.Frame:GetChildren() do
	        if v:IsA("ImageLabel") and v.Name ~= "Blur" then
	            v:Destroy()
	        end
	    end
	
	    for _, v: {any} in AlreadyGot do
	        local Block, Amount = v[1], v[2]
	        local BlockImage: ImageLabel = Instance.new("ImageLabel")
	        BlockImage.Size = UDim2.fromOffset(32, 32)
	        BlockImage.BackgroundTransparency = 1
	        BlockImage.Image = bedwars.getIcon({itemType = Block}, true)
	        BlockImage.Parent = Billboard.Frame
	        if Amount > 1 and (not LayerCounter or LayerCounter.Enabled) then
	            local AmountText: TextLabel = Instance.new("TextLabel")
	            AmountText.Name = "Amount"
	            AmountText.Size = UDim2.fromScale(1, 1)
	            AmountText.BackgroundTransparency = 1
	            AmountText.Text = tostring(Amount)
	            AmountText.TextColor3 = (LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1))
	            AmountText.TextSize = 16
	            AmountText.TextStrokeTransparency = 0.3
	            AmountText.Font = Enum.Font.Arial
	            AmountText.Parent = BlockImage
	        end
	    end
	end
	
	local function Added(Bed: BasePart)
	    if Reference[Bed] then return end
	
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Parent = Folder
	    Billboard.Name = "bed"
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	    Billboard.Size = UDim2.fromOffset(36, 36)
	    Billboard.AlwaysOnTop = true
	    Billboard.ClipsDescendants = false
	    Billboard.Adornee = Bed
	    local Blur: ImageLabel = AddBlur(Billboard)
	    Blur.Visible = Background.Enabled
	    local Frame: Frame = Instance.new("Frame")
	    Frame.Size = UDim2.fromScale(1, 1)
	    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	    Frame.Parent = Billboard
	    local Layout: UIListLayout = Instance.new("UIListLayout")
	    Layout.FillDirection = Enum.FillDirection.Horizontal
	    Layout.Padding = UDim.new(0, 4)
	    Layout.VerticalAlignment = Enum.VerticalAlignment.Center
	    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	    Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
	        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)
	    end)
	    Layout.Parent = Frame
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Frame
	    Reference[Bed] = Billboard
	    RefreshAdornee(Billboard)
	end
	
	local function RefreshNear(Data)
	    Data = Data.blockRef.blockPosition * 3
	    for Bed: BasePart, v: BillboardGui in Reference do
	        if (Data - Bed.Position).Magnitude <= 30 then
	            RefreshAdornee(v)
	        end
	    end
	end
	
	BedPlates = vape.Categories.World:CreateModule({
	    Name = "BedPlates",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, v: BasePart in CollectionService:GetTagged("bed") do
	                task.spawn(Added, v)
	            end
	            BedPlates:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(RefreshNear))
	            BedPlates:Clean(VapeEvents.BreakBlockEvent.Event:Connect(RefreshNear))
	            BedPlates:Clean(CollectionService:GetInstanceAddedSignal("bed"):Connect(Added))
	            BedPlates:Clean(CollectionService:GetInstanceRemovedSignal("bed"):Connect(function(Bed: Instance)
	                if Reference[Bed] then
	                    Reference[Bed]:Destroy()
	                    Reference[Bed] = nil
	                end
	            end))
	        else
	            table.clear(Reference)
	            Folder:ClearAllChildren()
	        end
	    end,
	    Tooltip = "Displays blocks over the bed"
	})
	
	Background = BedPlates:CreateToggle({
	    Name = "Background",
	    Function = function(Callback: boolean)
	        if Color and Color.Object then
	            Color.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
	            v.Blur.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Color = BedPlates:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
	        end
	    end,
	    Darker = true
	})
	LayerCounter = BedPlates:CreateToggle({
	    Name = "Layer Counter",
	    Function = function(Callback: boolean)
	        if LayerColor and LayerColor.Object then
	            LayerColor.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            RefreshAdornee(v)
	        end
	    end,
	    Default = true
	})
	LayerColor = BedPlates:CreateColorSlider({
	    Name = "Counter Text Color",
	    Function = function()
	        local TextColor: Color3 = (LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1))
	        for _, Billboard: BillboardGui in Reference do
	            for _, v: Instance in Billboard.Frame:GetDescendants() do
	                if v:IsA("TextLabel") and v.Name == "Amount" then
	                    v.TextColor3 = TextColor
	                end
	            end
	        end
	    end,
	    DefaultSat = 0,
	    DefaultValue = 1
	})
end)

Run(function()
	local BedProtector
	local PlaceRange
	local Layers
	local Blacklist
	local Wool
	local Mode
	local Smart
	local Switch
	
	local function GetBlocks()
	    local Blocks = {}
	    for _, v: any in Store.inventory.inventory.items do
	        local Block = bedwars.ItemMeta[v.itemType].block
	        if Block and (Wool.Enabled and v.itemType:find("wool") or not Wool.Enabled and not table.find(Blacklist.ListEnabled, v.itemType:find("wool") and "wool" or v.itemType)) then
	            table.insert(Blocks, {Type = v.itemType, Health = Block.health, Tool = v.tool, Amount = v.amount or math.huge})
	        end
	    end
	    if #Blocks > 1 then
	        table.sort(Blocks, function(A, B): boolean
	            return A.Health > B.Health
	        end)
	    end
	    return Blocks
	end
	
	local function GetLayerBlock(Blocks, Layer: number)
	    local Count: number = #Blocks
	    for i: number = 0, Count - 1 do
	        local Block = Blocks[(math.min(Layer, Count) + i - 1) % Count + 1]
	        if Block.Amount > 0 then
	            return Block
	        end
	    end
	    return nil
	end
	
	local function GetPyramid(Size: number, Grid: number): {Vector3}
	    local Positions: {Vector3} = {}
	    for Height: number = Size, 0, -1 do
	        for Width: number = Height, 0, -1 do
	            table.insert(Positions, Vector3.new(Width, (Size - Height), ((Height + 1) - Width)) * Grid)
	            table.insert(Positions, Vector3.new(Width * -1, (Size - Height), ((Height + 1) - Width)) * Grid)
	            table.insert(Positions, Vector3.new(Width, (Size - Height), (Height - Width) * -1) * Grid)
	            table.insert(Positions, Vector3.new(Width * -1, (Size - Height), (Height - Width) * -1) * Grid)
	        end
	    end
	    return Positions
	end
	
	local function GetPyramidRange(Size: number): number
	    local Far: number = 0
	    for _, v: Vector3 in GetPyramid(Size, 3) do
	        Far = math.max(Far, v.Magnitude)
	    end
	    return Far
	end
	
	local function GetBedNear()
	    local LocalPosition: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Vector3.zero
	    local Range: number = PlaceRange.Value + GetPyramidRange(Layers.Value)
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude < Range and v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            return v
	        end
	    end
	    return nil
	end
	
	local function PlaceLayer(Bed: BasePart, Blocks, Layer: number): boolean
	    local PlaceDelay: number = 1 / math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS)
	    for _, Offset: Vector3 in GetPyramid(Layer, 3) do
	        if not BedProtector.Enabled or not Entity.isAlive then
	            return false
	        end
	        local Position: Vector3 = (Bed.CFrame * CFrame.new(Offset)).Position
	        if GetPlacedBlock(Position) then
	            continue
	        end
	        if (Entity.character.RootPart.Position - Position).Magnitude > PlaceRange.Value then
	            continue
	        end
	        local Block = GetLayerBlock(Blocks, Layer)
	        if not Block then
	            return false
	        end
	
	        repeat
	            task.wait()
	        until not BedProtector.Enabled or not Entity.isAlive or (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= PlaceDelay
	        if not BedProtector.Enabled or not Entity.isAlive then
	            return false
	        end
	
	        if Switch.Enabled and HotbarSwitch(GetHotbar(Block.Tool)) then
	            task.wait()
	        end
	        task.spawn(bedwars.placeBlock, Position, Block.Type, false)
	        if GetPlacedBlock(Position) then
	            Block.Amount -= 1
	        end
	    end
	    return true
	end
	
	BedProtector = vape.Categories.World:CreateModule({
	    Name = "BedProtector",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                local Bed = GetBedNear()
	                if Bed then
	                    local Blocks = GetBlocks()
	                    local PreviousSlot: number? = Switch.Enabled and Store.hand and Store.hand.tool and GetHotbar(Store.hand.tool) or nil
	
	                    for Layer: number = 1, Layers.Value do
	                        if #Blocks == 0 or not PlaceLayer(Bed, Blocks, Layer) then
	                            break
	                        end
	                    end
	
	                    if PreviousSlot and HotbarSwitch(PreviousSlot) then
	                        task.wait()
	                    end
	                else
	                    if Mode.Value == "On Key" then
	                        SendNotification("BedProtector", "Unable to locate bed", 5)
	                        BedProtector:Toggle()
	                        break
	                    end
	                end
	                task.wait(0.5)
	                if Mode.Value == "On Key" then
	                    BedProtector:Toggle()
	                    break
	                end
	            until not BedProtector.Enabled
	        end
	    end,
	    Tooltip = "Automatically places strong blocks around the bed."
	})
	
	Mode = BedProtector:CreateDropdown({
	    Name = "Mode",
	    List = {"Toggle", "On Key"},
	    Function = function(Val: string)
	        if Smart then
	            Smart.Object.Visible = Val == "Toggle"
	        end
	    end,
	    Default = "Toggle"
	})
	Blacklist = BedProtector:CreateTextList({
	    Name = "Blacklist",
	    Default = {"siege_tnt", "tnt"}
	})
	PlaceRange = BedProtector:CreateSlider({
	    Name = "Place Range",
	    Min = 1,
	    Max = 30,
	    Default = 15
	})
	Layers = BedProtector:CreateSlider({
	    Name = "Layers",
	    Min = 1,
	    Max = 6,
	    Default = 2,
	    Tooltip = "How many layers go around your bed. Your strongest block goes closest to it, and your weakest one is reused when you have fewer block types than layers"
	})
	Wool = BedProtector:CreateToggle({Name = "Wool only", Tooltip = "Only uses wools to bed defend."})
	Switch = BedProtector:CreateToggle({Name = "Auto Switch"})
	Smart = BedProtector:CreateToggle({Name = "Smart", Default = true})
end)

Run(function()
	local BlockIn
	local Mode
	local Center
	local Priority
	local Return
	local Switch
	local Wool
	local Blacklist
	local CenterOrigin: Vector3?
	
	local Scan: number = 30
	local Directions: {Vector3} = {
	    Vector3.new(1, 0, 0),
	    Vector3.new(-1, 0, 0),
	    Vector3.new(0, 0, 1),
	    Vector3.new(0, 0, -1)
	}
	local Priorities = {
	    ["Lowest cost"] = function(A, B): boolean
	        return A.Health < B.Health
	    end,
	    ["Hardest"] = function(A, B): boolean
	        return A.Health > B.Health
	    end
	}
	
	local function GetOrigin(): Vector3
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Hit: RaycastResult? = Entity.Raycast(Position, Vector3.new(0, -Scan, 0), Store.airRay)
	    return RoundPosition(Hit and Vector3.new(Position.X, Hit.Position.Y + 1.5, Position.Z) or Position)
	end
	
	local function GetBedNear()
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        if (LocalPosition - v.Position).Magnitude >= 14 or v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            continue
	        end
	
	        local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(v.Name)
	        local Cells = Handler and Handler:getContainedPositions(v) or {v.Position / 3}
	        local Occupied = {}
	        for _, Cell: Vector3 in Cells do
	            Occupied[Cell * 3] = true
	        end
	
	        local Defended: boolean = true
	        for _, Cell: Vector3 in Cells do
	            for i: number = 1, #Sides do
	                local Position: Vector3 = (Cell * 3) + Sides[i]
	                if not Occupied[Position] and not GetPlacedBlock(Position) then
	                    Defended = false
	                    break
	                end
	            end
	            if not Defended then
	                break
	            end
	        end
	
	        if Defended then
	            return v
	        end
	    end
	    return nil
	end
	
	local function GetBlocks()
	    local Blocks = {}
	    for _, v: any in Store.inventory.inventory.items do
	        local Block = bedwars.ItemMeta[v.itemType].block
	        if Block and (Wool.Enabled and v.itemType:find("wool") or not Wool.Enabled and not table.find(Blacklist.ListEnabled, v.itemType:find("wool") and "wool" or v.itemType)) then
	            local Slot: number? = GetHotbar(v.tool)
	            if Slot or not Switch.Enabled then
	                table.insert(Blocks, {Type = v.itemType, Health = Block.health, Slot = Slot, Amount = v.amount or math.huge})
	            end
	        end
	    end
	    if #Blocks > 1 then
	        table.sort(Blocks, Priorities[Priority.Value])
	    end
	    return Blocks
	end
	
	local function GetEnclosure(Origin: Vector3, Grounded: boolean): {Vector3}
	    local Enemy = Entity.EntityPosition({
	        Range = 60,
	        Part = "RootPart",
	        Players = true
	    })
	    local Facing: Vector3 = Enemy and Enemy.RootPart.Position - Origin or Vector3.zero
	    local Order: {Vector3} = table.clone(Directions)
	    table.sort(Order, function(A: Vector3, B: Vector3): boolean
	        return A:Dot(Facing) > B:Dot(Facing)
	    end)
	
	    local Cells: {Vector3} = {}
	    if Grounded and not Entity.Raycast(Origin, Vector3.new(0, -3, 0), Store.airRay) then
	        table.insert(Cells, Vector3.new(0, -3, 0))
	    end
	    for _, Height: number in {0, 3} do
	        for _, Direction: Vector3 in Order do
	            table.insert(Cells, Vector3.new(Direction.X * 3, Height, Direction.Z * 3))
	        end
	    end
	    if Grounded then
	        table.insert(Cells, Vector3.new(0, 6, 0))
	    end
	    return Cells
	end
	
	local function HoldCenter()
	    if not CenterOrigin or not Center.Enabled or vape.MovementOwner or not Entity.isAlive then
	        return
	    end
	
	    local Root: BasePart = Entity.character.RootPart
	    if isnetworkowner(Root) then
	        Root.CFrame = CFrame.new(CenterOrigin.X, Root.Position.Y, CenterOrigin.Z) * Root.CFrame.Rotation
	        Root.AssemblyLinearVelocity = Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
	    end
	end
	
	local function PlacePattern(Origin: Vector3, Cells: {Vector3}, Blocks, Limit: number)
	    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil
	    local PlaceDelay: number = 1 / math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS)
	    local Placed: number = 0
	
	    for _, Offset: Vector3 in Cells do
	        if Placed >= Limit or not BlockIn.Enabled or not Entity.isAlive then
	            break
	        end
	        local Position: Vector3 = Origin + Offset
	        if GetPlacedBlock(Position) then
	            continue
	        end
	        while Blocks[1] and Blocks[1].Amount <= 0 do
	            table.remove(Blocks, 1)
	        end
	        local Block = Blocks[1]
	        if not Block then
	            break
	        end
	
	        if Center.Enabled then
	            CenterOrigin = Origin
	        end
	        repeat
	            task.wait()
	        until not BlockIn.Enabled or not Entity.isAlive or (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= PlaceDelay
	        if not BlockIn.Enabled or not Entity.isAlive then
	            break
	        end
	
	        if Switch.Enabled then
	            HotbarSwitch(Block.Slot)
	        end
	        task.spawn(bedwars.placeBlock, Position, Block.Type)
	        if GetPlacedBlock(Position) then
	            Block.Amount -= 1
	            Placed += 1
	        end
	    end
	    if Return.Enabled and Switch.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	end
	
	BlockIn = vape.Categories.World:CreateModule({
	    Name = "Block-In",
	    Function = function(Callback: boolean)
	        if Callback then
	            BlockIn:Clean(RunService.PreSimulation:Connect(HoldCenter))
	            BlockIn:Clean(function()
	                CenterOrigin = nil
	            end)
	
	            repeat
	                if Entity.isAlive and (Mode.Value == "On bind" or GetBedNear()) then
	                    local Blocks = GetBlocks()
	                    local Early: boolean = false
	                    repeat
	                        task.wait()
	                        if Entity.isAlive and not Early then
	                            local Origin: Vector3 = GetOrigin()
	                            local Drop: number = Entity.character.RootPart.Position.Y - Origin.Y
	                            Early = Drop >= 6 and Drop <= 24
	                            if Early then
	                                PlacePattern(Origin, GetEnclosure(Origin, false), Blocks, Center.Enabled and math.huge or 3)
	                            end
	                        end
	                    until not BlockIn.Enabled or not Entity.isAlive or Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air
	
	                    if Entity.isAlive then
	                        local Origin: Vector3 = GetOrigin()
	                        PlacePattern(Origin, GetEnclosure(Origin, true), Blocks, math.huge)
	                    end
	                    CenterOrigin = nil
	                end
	
	                if Mode.Value == "On bind" then
	                    BlockIn:Toggle()
	                    break
	                end
	                task.wait(0.5)
	            until not BlockIn.Enabled
	        end
	    end,
	    Tooltip = "Automatically blocks you in by building walls around you"
	})
	
	Mode = BlockIn:CreateDropdown({
	    Name = "Mode",
	    List = {"On bind", "When near"},
	    Default = "On bind",
	    Tooltip = "On bind blocks you in once per keypress, When near keeps you blocked in while you are on an enemy bed"
	})
	Center = BlockIn:CreateToggle({
	    Name = "Center",
	    Default = true,
	    Tooltip = "Holds you in the middle of your block while it builds, so no side gets skipped"
	})
	Priority = BlockIn:CreateDropdown({
	    Name = "Block priority",
	    List = {"Lowest cost", "Hardest"},
	    Default = "Lowest cost"
	})
	Switch = BlockIn:CreateToggle({Name = "Switch", Default = true})
	Return = BlockIn:CreateToggle({Name = "Return to last slot", Default = true})
	Wool = BlockIn:CreateToggle({Name = "Wool only"})
	Blacklist = BlockIn:CreateTextList({
	    Name = "Blacklist",
	    Default = {"cannon", "siege_tnt", "tnt"}
	})
end)

Run(function()
	local ChestSteal
	local Range
	local Open
	local Skywars
	local Legit
	local Visualize
	local FillColor
	local OutlineColor
	local Animate
	local Speed
	local Delays = {}
	local Boxes = {}
	local Tweens = {}
	local BoxTargets = {}
	
	local function UpdateBoxes(Targets)
	    for i: number, Box: Part in Boxes do
	        local Chest = Targets and Targets[i]
	        if Chest ~= BoxTargets[i] then
	            if Tweens[i] then
	                Tweens[i]:Cancel()
	                Tweens[i] = nil
	            end
	
	            if not Chest then
	                Box.Parent = nil
	            elseif Animate.Enabled and Box.Parent == Camera then
	                Tweens[i] = TweenService:Create(Box, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = Chest.CFrame})
	                Tweens[i]:Play()
	            else
	                Box.CFrame = Chest.CFrame
	                Box.Parent = Camera
	            end
	            BoxTargets[i] = Chest
	        end
	
	        if Chest then
	            Box.SelectionBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
	            Box.SelectionBox.Transparency = 1 - OutlineColor.Opacity
	            Box.SelectionBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
	            Box.SelectionBox.SurfaceTransparency = 1 - FillColor.Opacity
	        end
	    end
	end
	
	local function LootChest(Chest)
	    Chest = Chest and Chest.Value or nil
	    
	    local ChestItems = Chest and Chest:GetChildren() or {}
	    if #ChestItems > 1 and (Delays[Chest] or 0) < tick() then
	        Delays[Chest] = tick() + 0.2
	        local Observed = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("ObservedChestFolder")
	        Observed = Observed and Observed.Value or nil
	        bedwars.Client:GetNamespace("Inventory"):Get("SetObservedChest"):SendToServer(Chest)
	
	        for _, v: Instance in ChestItems do
	            if v:IsA("Accessory") then
	                task.spawn(function()
	                    pcall(function()
	                        bedwars.Client:GetNamespace("Inventory"):Get("ChestGetItem"):CallServer(Chest, v)
	                    end)
	                end)
	                if Legit.Enabled then
	                    task.wait(0.2)
	                end
	            end
	        end
	
	        bedwars.Client:GetNamespace("Inventory"):Get("SetObservedChest"):SendToServer(Observed)
	    end
	end
	
	ChestSteal = vape.Categories.World:CreateModule({
	    Name = "ChestSteal",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Chests = Collection("chest", ChestSteal)
	            repeat
	                task.wait()
	            until Store.queueType ~= "bedwars_test"
	            local function GetChestPart(Folder: Instance)
	                for _, v: BasePart in Chests do
	                    local FolderValue: ObjectValue? = v:FindFirstChild("ChestFolderValue")
	                    if FolderValue and FolderValue.Value == Folder then
	                        return v
	                    end
	                end
	                return nil
	            end
	
	            if (not Skywars.Enabled) or Store.queueType:find("skywars") then
	                repeat
	                    local Targets = {}
	                    if Entity.isAlive and Store.matchState ~= 2 then
	                        if Open.Enabled then
	                            if bedwars.AppController:isAppOpen("ChestApp") then
	                                local Observed = LocalPlayer.Character:FindFirstChild("ObservedChestFolder")
	                                LootChest(Observed)
	                                Targets[1] = Observed and Observed.Value and GetChestPart(Observed.Value) or nil
	                            end
	                        else
	                            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                            local Closest: number = math.huge
	                            for _, v: BasePart in Chests do
	                                local Magnitude: number = (LocalPosition - v.Position).Magnitude
	                                if Magnitude <= Range.Value then
	                                    LootChest(v:FindFirstChild("ChestFolderValue"))
	                                    if Magnitude < Closest then
	                                        Closest, Targets[1] = Magnitude, v
	                                    end
	                                end
	                            end
	                        end
	                    end
	
	                    UpdateBoxes(Targets)
	                    task.wait(0.1)
	                until not ChestSteal.Enabled
	            end
	        else
	            UpdateBoxes(nil)
	        end
	    end,
	    Tooltip = "Grabs items from near chests."
	})
	
	Range = ChestSteal:CreateSlider({
	    Name = "Range",
	    Min = 0,
	    Max = 18,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	Visualize = ChestSteal:CreateToggle({
	    Name = "Visualize",
	    Function = function(Callback: boolean)
	        FillColor.Object.Visible = Callback
	        OutlineColor.Object.Visible = Callback
	        Animate.Object.Visible = Callback
	        Speed.Object.Visible = Callback
	        if Callback then
	            local Part: Part = Instance.new("Part")
	            Part.Size = Vector3.new(3, 3, 3)
	            Part.Anchored = true
	            Part.CanCollide = false
	            Part.CanQuery = false
	            Part.CanTouch = false
	            Part.CastShadow = false
	            Part.Transparency = 1
	            local Selection: SelectionBox = Instance.new("SelectionBox")
	            Selection.Adornee = Part
	            Selection.LineThickness = 0.04
	            Selection.Parent = Part
	            bedwars.QueryUtil:setQueryIgnored(Part, true)
	            Boxes[1] = Part
	        else
	            UpdateBoxes(nil)
	            for _, v: Part in Boxes do
	                v:Destroy()
	            end
	            table.clear(Boxes)
	            table.clear(Tweens)
	            table.clear(BoxTargets)
	        end
	    end,
	    Tooltip = "Draws a box around the closest chest being looted"
	})
	FillColor = ChestSteal:CreateColorSlider({
	    Name = "Fill Color",
	    DefaultSat = 0,
	    DefaultOpacity = 0.25,
	    Darker = true,
	    Visible = false
	})
	OutlineColor = ChestSteal:CreateColorSlider({
	    Name = "Outline Color",
	    DefaultSat = 0,
	    Darker = true,
	    Visible = false
	})
	Animate = ChestSteal:CreateToggle({
	    Name = "Animate",
	    Default = true,
	    Darker = true,
	    Visible = false,
	    Tooltip = "Glides the box onto the next chest instead of snapping to it"
	})
	Speed = ChestSteal:CreateSlider({
	    Name = "Animation time",
	    Min = 0.01,
	    Max = 0.5,
	    Default = 0.08,
	    Decimal = 100,
	    Suffix = "s",
	    Darker = true,
	    Visible = false
	})
	Open = ChestSteal:CreateToggle({Name = "GUI Check"})
	Legit = ChestSteal:CreateToggle(({Name = "Legit mode"}))
	Skywars = ChestSteal:CreateToggle({
	    Name = "Only Skywars",
	    Function = function()
	        if ChestSteal.Enabled then
	            ChestSteal:Toggle()
	            ChestSteal:Toggle()
	        end
	    end,
	    Default = true
	})
end)

Run(function()
	local FastPlace
	local CPS
	
	bedwars.DefaultPlaceCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS
	
	FastPlace = vape.Categories.World:CreateModule({
	    Name = "FastPlace",
	    Function = function(Callback: boolean)
	        bedwars.SharedConstants.BLOCK_PLACE_CPS = Callback and CPS.Value or bedwars.DefaultPlaceCPS
	    end,
	    Tooltip = "Changes the block place delay. Block-In and BedProtector keep the normal speed so none of their blocks get dropped"
	})
	
	CPS = FastPlace:CreateSlider({
	    Name = "Cps",
	    Min = 1,
	    Max = 100,
	    Function = function(Val: number)
	        if FastPlace.Enabled then
	            bedwars.SharedConstants.BLOCK_PLACE_CPS = Val
	        end
	    end,
	    Default = 13
	})
	FastPlace:CreateButton({
	    Name = "Reset to bedwars cps",
	    Function = function()
	        CPS:SetValue(bedwars.DefaultPlaceCPS)
	    end
	})
end)

Run(function()
	local Nuker
	local Mode
	local ClosestBreak
	local Range
	local BreakSpeed
	local UpdateRate
	local Custom
	local Bed
	local Tesla
	local Hive
	local LuckyBlock
	local IronOre
	local Effect
	local CustomHealth = {}
	local Animation = {}
	local SelfBreak
	local LimitItem
	local Wallcheck
	local ViewAngle
	local AutoTool
	local PlayerCheck
	local CustomList, Parts = {}, {}
	local Mouse: Mouse = cloneref(LocalPlayer:GetMouse())
	local MouseParams: RaycastParams = RaycastParams.new()
	MouseParams.FilterType = Enum.RaycastFilterType.Exclude
	local MouseOrigin, MouseDirection, MouseHit = Vector3.zero, Vector3.zero, nil
	local PlayerParams: RaycastParams = RaycastParams.new()
	PlayerParams.FilterType = Enum.RaycastFilterType.Include
	local Session = nil
	local ActiveBlock: BasePart?
	local NextBreak: number = 0
	local PathShown: boolean = false
	local HealthbarProgress
	local HealthbarCleanup: (() -> ())?
	
	local function ClearHealthbar()
	    local Cleanup: (() -> ())? = HealthbarCleanup
	    HealthbarCleanup = nil
	    if Cleanup then
	        Cleanup()
	    end
	end
	
	local function CustomHealthbar(self, BlockRef, Health: number, MaxHealth: number, ChangeHealth: number, Block)
	    xpcall(function()
	        if Block:GetAttribute("NoHealthbar") then
	            return
	        end
	        if not self.healthbarPart or not self.healthbarBlockRef or self.healthbarBlockRef.blockPosition ~= BlockRef.blockPosition then
	            if self.healthbarPart then
	                bedwars.QueryUtil:setQueryIgnored(self.healthbarPart, true)
	            end
	            ClearHealthbar()
	            self.healthbarBlockRef = BlockRef
	            local Roact = bedwars.Roact
	            local Create = Roact.createElement
	            local Meta = bedwars.ItemMeta[Block.Name]
	            local DisplayName: string = Meta and Meta.displayName or Block.Name
	            HealthbarProgress = HealthbarProgress or Roact.createRef()
	            local Percent: number = math.clamp(Health / MaxHealth, 0, 1)
	            local CleanCheck: boolean = true
	            local Part: Part = Instance.new("Part")
	            Part.Size = Vector3.one
	            Part.CFrame = CFrame.new(bedwars.BlockController:getWorldPosition(BlockRef.blockPosition))
	            Part.Transparency = 1
	            Part.Anchored = true
	            Part.CanCollide = false
	            Part.Parent = workspace
	            bedwars.QueryUtil:setQueryIgnored(Part, true)
	            self.healthbarPart = Part
	
	            local Mounted = Roact.mount(Create("BillboardGui", {
	                Size = UDim2.fromOffset(249, 102),
	                StudsOffset = Vector3.new(0, 2.5, 0),
	                Adornee = Part,
	                MaxDistance = 40,
	                AlwaysOnTop = true
	            }, {
	                Create("Frame", {
	                    Size = UDim2.fromOffset(160, 50),
	                    Position = UDim2.fromOffset(44, 32),
	                    BackgroundColor3 = Color3.new(),
	                    BackgroundTransparency = 0.5
	                }, {
	                    Create("UICorner", {CornerRadius = UDim.new(0, 5)}),
	                    Create("ImageLabel", {
	                        Size = UDim2.new(1, 89, 1, 52),
	                        Position = UDim2.fromOffset(-48, -31),
	                        BackgroundTransparency = 1,
	                        Image = GetVapeAsset("GyuvapeBedwarsCheat/assets/new/blur.png"),
	                        ScaleType = Enum.ScaleType.Slice,
	                        SliceCenter = Rect.new(52, 31, 261, 502)
	                    }),
	                    Create("TextLabel", {
	                        Size = UDim2.fromOffset(145, 14),
	                        Position = UDim2.fromOffset(13, 12),
	                        BackgroundTransparency = 1,
	                        Text = DisplayName,
	                        TextXAlignment = Enum.TextXAlignment.Left,
	                        TextYAlignment = Enum.TextYAlignment.Top,
	                        TextColor3 = Color3.new(),
	                        TextScaled = true,
	                        Font = Enum.Font.Arial
	                    }),
	                    Create("TextLabel", {
	                        Size = UDim2.fromOffset(145, 14),
	                        Position = UDim2.fromOffset(12, 11),
	                        BackgroundTransparency = 1,
	                        Text = DisplayName,
	                        TextXAlignment = Enum.TextXAlignment.Left,
	                        TextYAlignment = Enum.TextYAlignment.Top,
	                        TextColor3 = Color.Dark(UIPallet.Text, 0.16),
	                        TextScaled = true,
	                        Font = Enum.Font.Arial
	                    }),
	                    Create("Frame", {
	                        Size = UDim2.fromOffset(138, 4),
	                        Position = UDim2.fromOffset(12, 32),
	                        BackgroundColor3 = UIPallet.Main
	                    }, {
	                        Create("UICorner", {CornerRadius = UDim.new(1, 0)}),
	                        Create("Frame", {
	                            [Roact.Ref] = HealthbarProgress,
	                            Size = UDim2.fromScale(Percent, 1),
	                            BackgroundColor3 = Color3.fromHSV(math.clamp(Percent / 2.5, 0, 1), 0.89, 0.75)
	                        }, {Create("UICorner", {CornerRadius = UDim.new(1, 0)})})
	                    })
	                })
	            }), Part)
	
	            HealthbarCleanup = function()
	                CleanCheck = false
	                self.healthbarBlockRef = nil
	                Roact.unmount(Mounted)
	                if self.healthbarPart then
	                    self.healthbarPart:Destroy()
	                end
	                self.healthbarPart = nil
	            end
	
	            bedwars.RuntimeLib.Promise.delay(5):andThen(function()
	                if CleanCheck then
	                    ClearHealthbar()
	                end
	            end)
	        end
	
	        local Progress: Frame? = HealthbarProgress and HealthbarProgress:getValue()
	        if not Progress then
	            return
	        end
	
	        local NewPercent: number = math.clamp((Health - ChangeHealth) / MaxHealth, 0, 1)
	        TweenService:Create(Progress, TweenInfo.new(0.3), {
	            Size = UDim2.fromScale(NewPercent, 1), BackgroundColor3 = Color3.fromHSV(math.clamp(NewPercent / 2.5, 0, 1), 0.89, 0.75)
	        }):Play()
	    end, function(...)
	        if shared.VapeDeveloper then
	            warn(...)
	        end
	    end)
	end
	
	local function GetContainedPositions(Block)
	    local Handler = bedwars.BlockController:getHandlerRegistry():getHandler(Block.Name)
	    return Handler and Handler:getContainedPositions(Block) or {bedwars.BlockController:getBlockPosition(Block.Position)}
	end
	
	local function IsBlockBreakable(Block): boolean
	    for _, Position: Vector3 in GetContainedPositions(Block) do
	        if bedwars.BlockController:isBlockBreakable({blockPosition = Position}, LocalPlayer) then
	            return true
	        end
	    end
	    return false
	end
	
	local function AttemptBreak(List, LocalPosition: Vector3, Route: boolean?, TeamCheck: boolean?)
	    if not List then
	        return
	    end
	
	    local Block, Closest = nil, math.huge
	    for _, v: BasePart in List do
	        if (v.Position - LocalPosition).Magnitude >= Range.Value or not IsBlockBreakable(v) then
	            continue
	        end
	        if not SelfBreak.Enabled and v:GetAttribute("PlacedByUserId") == LocalPlayer.UserId then
	            continue
	        end
	        if TeamCheck then
	            local Placer: Player? = Players:GetPlayerByUserId(v:GetAttribute("PlacedByUserId") or 0)
	            if Placer and Placer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team") then
	                continue
	            end
	        end
	        if Wallcheck.Enabled and not ClosestBreak.Enabled and ViewAngle.Value < 180 then
	            local Offset: Vector3 = v.Position - Camera.CFrame.Position
	            if Offset.Magnitude > 0 and math.deg(math.acos(math.clamp(Offset.Unit:Dot(Camera.CFrame.LookVector), -1, 1))) > ViewAngle.Value then
	                continue
	            end
	        end
	        if (v:GetAttribute("BedShieldEndTime") or 0) > workspace:GetServerTimeNow() then
	            continue
	        end
	        if LimitItem.Enabled and not (Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name] and bedwars.ItemMeta[Store.hand.tool.Name].breakBlock) then
	            continue
	        end
	        if PlayerCheck.Enabled and workspace:Raycast(Entity.character.Head.Position, v.Position - Entity.character.Head.Position, PlayerParams) then
	            continue
	        end
	
	        if not ClosestBreak.Enabled or v == MouseHit then
	            local Distance: number = (v.Position - LocalPosition).Magnitude
	            if v == ActiveBlock then
	                Block = v
	                break
	            end
	            if Distance < Closest then
	                Block, Closest = v, Distance
	            end
	            continue
	        end
	
	        local Offset: Vector3 = v.Position - MouseOrigin
	        local Along: number = Offset:Dot(MouseDirection)
	        local Spread: number = Along > 0 and (Offset - MouseDirection * Along).Magnitude or Offset.Magnitude
	        if Spread < Closest then
	            Block, Closest = v, Spread
	        end
	    end
	
	    if not Block then
	        return false
	    end
	
	    ActiveBlock = Block
	    if tick() < NextBreak then return true end
	    local Started: number = tick()
	    local BreakPosition, BreakPath, EndPosition, Requested = bedwars.breakBlock(Block, Effect.Enabled, Animation.Value ~= "No Animation" and Animation.Value or nil, CustomHealth.Enabled and CustomHealthbar or nil, AutoTool.Enabled, Wallcheck.Enabled, ClosestBreak.Enabled and BreakMethods.Distance or BreakMethods[Mode.Value], not Route, true)
	    if Requested then NextBreak = Started + math.max(BreakSpeed.Value, bedwars.BlockBreaker:getCooldown()) end
	    local CurrentNode = BreakPosition
	    if CurrentNode or PathShown then
	        PathShown = CurrentNode ~= nil
	        for _, v: Part in Parts do
	            v.Position = CurrentNode or Vector3.zero
	            if CurrentNode then
	                v.BoxHandleAdornment.Color3 = CurrentNode == EndPosition and Color3.new(1, 0.2, 0.2) or CurrentNode == BreakPosition and Color3.new(0.2, 0.2, 1) or Color3.new(0.2, 1, 0.2)
	            end
	            CurrentNode = BreakPath and BreakPath[CurrentNode]
	        end
	    end
	
	    return BreakPosition ~= nil
	end
	
	Nuker = vape.Categories.World:CreateModule({
	    Name = "Nuker",
	    ConfigName = "Breaker",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Current = {}
	            Session = Current
	            ActiveBlock, NextBreak = nil, 0
	            for _ = 1, 30 do
	                local Part: Part = Instance.new("Part")
	                Part.Anchored = true
	                Part.CanQuery = false
	                Part.CanCollide = false
	                Part.Transparency = 1
	                Part.Parent = Camera
	                local Highlight: BoxHandleAdornment = Instance.new("BoxHandleAdornment")
	                Highlight.Size = Vector3.one
	                Highlight.AlwaysOnTop = true
	                Highlight.ZIndex = 1
	                Highlight.Transparency = 0.5
	                Highlight.Adornee = Part
	                Highlight.Parent = Part
	                table.insert(Parts, Part)
	            end
	
	            local Beds = Collection("bed", Nuker)
	            local Teslas = Collection("tesla-trap", Nuker)
	            local Hives = Collection("beehive", Nuker)
	            local LuckyBlocks = Collection("LuckyBlock", Nuker)
	            local IronOres = Collection("iron_ore_mesh_block", Nuker)
	            CustomList = Collection("block", Nuker, function(List, Object: Instance)
	                if table.find(Custom.ListEnabled, Object.Name) then
	                    table.insert(List, Object)
	                end
	            end)
	
	            repeat
	                task.wait(1 / UpdateRate.Value)
	                if not Nuker.Enabled or Session ~= Current then
	                    break
	                end
	                if Entity.isAlive then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	
	                    if ClosestBreak.Enabled then
	                        local Ignore: {Instance} = {LocalPlayer.Character, Camera}
	                        for _, v: any in Entity.List do
	                            if v.Character then
	                                table.insert(Ignore, v.Character)
	                            end
	                        end
	                        MouseParams.FilterDescendantsInstances = Ignore
	                        MouseOrigin, MouseDirection = Mouse.UnitRay.Origin, Mouse.UnitRay.Direction
	                        local Result: RaycastResult? = workspace:Raycast(MouseOrigin, MouseDirection * 999, MouseParams)
	                        MouseHit = Result and Result.Instance or nil
	                    end
	                    if PlayerCheck.Enabled then
	                        local Characters: {Model} = {}
	                        for _, v: any in Entity.List do
	                            if v.Player and v.Character then
	                                table.insert(Characters, v.Character)
	                            end
	                        end
	                        PlayerParams.FilterDescendantsInstances = Characters
	                    end
	
	                    if AttemptBreak(Bed.Enabled and Beds, LocalPosition, true) then
	                        continue
	                    end
	                    if AttemptBreak(Hive.Enabled and Hives, LocalPosition, nil, true) then
	                        continue
	                    end
	                    if AttemptBreak(Tesla.Enabled and Teslas, LocalPosition, nil, true) then
	                        continue
	                    end
	                    if AttemptBreak(IronOre.Enabled and IronOres, LocalPosition) then
	                        continue
	                    end
	                    if AttemptBreak(LuckyBlock.Enabled and LuckyBlocks, LocalPosition) then
	                        continue
	                    end
	                    if AttemptBreak(CustomList, LocalPosition) then
	                        continue
	                    end
	
	                    ActiveBlock = nil
	                    if PathShown then
	                        PathShown = false
	                        for _, v: Part in Parts do
	                            v.Position = Vector3.zero
	                        end
	                    end
	                end
	            until not Nuker.Enabled or Session ~= Current
	        else
	            ActiveBlock = nil
	            ClearHealthbar()
	            for _, v: Part in Parts do
	                v:ClearAllChildren()
	                v:Destroy()
	            end
	            table.clear(Parts)
	            PathShown = false
	        end
	    end,
	    Tooltip = "Break blocks around you automatically"
	})
	
	Mode = Nuker:CreateDropdown({
	    Name = "Break mode",
	    List = {"Health", "Distance"},
	    Default = "Health"
	})
	ClosestBreak = Nuker:CreateToggle({
	    Name = "Closest break",
	    Function = function(Callback: boolean)
	        Mode.Object.Visible = not Callback
	    end,
	    Tooltip = "Ignores the break mode and always takes the block nearest your crosshair, seeing straight through players"
	})
	Range = Nuker:CreateSlider({
	    Name = "Break range",
	    Min = 1,
	    Max = 30,
	    Default = 30,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	BreakSpeed = Nuker:CreateSlider({
	    Name = "Break speed",
	    Min = 0,
	    Max = 0.3,
	    Default = 0.25,
	    Decimal = 100,
	    Suffix = "seconds"
	})
	UpdateRate = Nuker:CreateSlider({
	    Name = "Update rate",
	    Min = 1,
	    Max = 120,
	    Default = 60,
	    Suffix = "hz"
	})
	Custom = Nuker:CreateTextList({
	    Name = "Custom",
	    Function = function()
	        if not CustomList then
	            return
	        end
	        table.clear(CustomList)
	        for _, v: BasePart in Store.blocks do
	            if table.find(Custom.ListEnabled, v.Name) then
	                table.insert(CustomList, v)
	            end
	        end
	    end
	})
	Bed = Nuker:CreateToggle({
	    Name = "Break Bed",
	    Default = true
	})
	Tesla = Nuker:CreateToggle({
	    Name = "Break Tesla",
	    Default = true
	})
	Hive = Nuker:CreateToggle({
	    Name = "Break Hive",
	    Default = true
	})
	LuckyBlock = Nuker:CreateToggle({
	    Name = "Break Lucky Block",
	    Default = true
	})
	IronOre = Nuker:CreateToggle({
	    Name = "Break Iron Ore",
	    Default = true
	})
	Effect = Nuker:CreateToggle({
	    Name = "Show Healthbar & Effects",
	    Function = function(Callback: boolean)
	        if CustomHealth.Object then
	            CustomHealth.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	CustomHealth = Nuker:CreateToggle({
	    Name = "Custom Healthbar",
	    Default = true,
	    Darker = true
	})
	Animation = Nuker:CreateDropdown({
	    Name = "Animation Mode",
	    List = {"No Animation", "Minimal", "Full"},
	    Tooltip = "Minimal plays the tiny stub you get while macroing, Full plays the whole swing"
	})
	SelfBreak = Nuker:CreateToggle({Name = "Self Break"})
	Wallcheck = Nuker:CreateToggle({
	    Name = "Legit mode",
	    Function = function(Callback: boolean)
	        if ViewAngle then
	            ViewAngle.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Checks for blocks inside the bed instead of directly targetting bed,\nand only breaks what you are actually looking at"
	})
	ViewAngle = Nuker:CreateSlider({
	    Name = "View angle",
	    Min = 5,
	    Max = 180,
	    Default = 60,
	    Suffix = "degrees",
	    Darker = true,
	    Tooltip = "How far off your crosshair a block can sit in legit mode, 180 breaks anything in range"
	})
	AutoTool = Nuker:CreateToggle({
	    Name = "Auto Tool",
	    Tooltip = "Visualises tool switching on ur client"
	})
	LimitItem = Nuker:CreateToggle({
	    Name = "Limit to items",
	    Tooltip = "Only breaks when tools are held"
	})
	PlayerCheck = Nuker:CreateToggle({
	    Name = "Player check",
	    Tooltip = "Skips a block while a player stands between you and it, so you dont mine through them"
	})
end)

Run(function()
	local ArmorSwitch
	local Mode
	local Targets
	local Range
	
	ArmorSwitch = vape.Categories.Inventory:CreateModule({
	    Name = "ArmorSwitch",
	    Function = function(Callback: boolean)
	        if Callback then
	            if Mode.Value == "Toggle" then
	                repeat
	                    local State: boolean = Entity.EntityPosition({
	                        Part = "RootPart",
	                        Range = Range.Value,
	                        Players = Targets.Players.Enabled,
	                        NPCs = Targets.NPCs.Enabled,
	                        Priority = Targets.Priority.Value,
	                        Wallcheck = Targets.Walls.Enabled
	                    }) and true or false
	
	                    for Slot: number = 0, 2 do
	                        if (Store.inventory.inventory.armor[Slot + 1] ~= "empty") ~= State and ArmorSwitch.Enabled then
	                            bedwars.Store:dispatch({
	                                type = "InventorySetArmorItem",
	                                item = Store.inventory.inventory.armor[Slot + 1] == "empty" and State and GetBestArmor(Slot) or nil,
	                                armorSlot = Slot
	                            })
	                            VapeEvents.InventoryChanged.Event:Wait()
	                        end
	                    end
	                    task.wait(0.1)
	                until not ArmorSwitch.Enabled
	            else
	                ArmorSwitch:Toggle()
	                for Slot: number = 0, 2 do
	                    bedwars.Store:dispatch({
	                        type = "InventorySetArmorItem",
	                        item = Store.inventory.inventory.armor[Slot + 1] == "empty" and GetBestArmor(Slot) or nil,
	                        armorSlot = Slot
	                    })
	                    VapeEvents.InventoryChanged.Event:Wait()
	                end
	            end
	        end
	    end,
	    Tooltip = "Puts on / takes off armor when toggled for baiting."
	})
	
	Mode = ArmorSwitch:CreateDropdown({
	    Name = "Mode",
	    List = {"Toggle", "On Key"}
	})
	Targets = ArmorSwitch:CreateTargets({
	    Players = true,
	    NPCs = true
	})
	Range = ArmorSwitch:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = 30,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local AutoBuy
	local Sword
	local Armor
	local Upgrades
	local BedwarsCheck
	local GUI
	local SmartCheck
	local Custom = {}
	local CustomPost = {}
	local UpgradeToggles = {}
	local Functions, ShopId = {}
	local Callbacks = {Custom, Functions, CustomPost}
	local NPCTick: number = tick()
	
	local Swords: {string} = {
	    "wood_sword",
	    "stone_sword",
	    "iron_sword",
	    "diamond_sword",
	    "emerald_sword"
	}
	
	local Daos: {string} = {
	    "wood_dao",
	    "stone_dao",
	    "iron_dao",
	    "diamond_dao",
	    "emerald_dao"
	}
	
	local KitSwords: {[string]: string} = {
	    ice_queen = "ice_sword",
	    ember = "infernal_saber",
	    lumen = "light_sword"
	}
	
	local BedwarsQueues: {string} = {
	    "combined_kit_to4",
	    "overpowered",
	    "hyper_gen_to4",
	    "all_random_kit_to4",
	    "all_same_kit_to4"
	}
	
	local Armors: {string} = {
	    "none",
	    "leather_chestplate",
	    "iron_chestplate",
	    "diamond_chestplate",
	    "emerald_chestplate"
	}
	
	local Axes: {string} = {
	    "none",
	    "wood_axe",
	    "stone_axe",
	    "iron_axe",
	    "diamond_axe"
	}
	
	local Pickaxes: {string} = {
	    "none",
	    "wood_pickaxe",
	    "stone_pickaxe",
	    "iron_pickaxe",
	    "diamond_pickaxe"
	}
	
	local function HasKit(Kits: {string}?): boolean
	    if not Kits then
	        return false
	    end
	    for _, v: string in Store.equippedKits or {} do
	        if table.find(Kits, v) then
	            return true
	        end
	    end
	    return false
	end
	
	local function IsHidden(Item): boolean
	    if Item.requiresKit and #Item.requiresKit > 0 and not HasKit(Item.requiresKit) then
	        return true
	    end
	    if Item.ignoreAttribute and Item.ignoreAttribute ~= "" and LocalPlayer:GetAttribute(Item.ignoreAttribute) then
	        return true
	    end
	    if Item.requireAttribute and Item.requireAttribute ~= "" and not LocalPlayer:GetAttribute(Item.requireAttribute) then
	        return true
	    end
	    return HasKit(Item.ignoredByKit)
	end
	
	local function GetSwords(): {string}
	    if HasKit({"dasher"}) then
	        return Daos
	    end
	
	    for _, v: string in Store.equippedKits or {} do
	        if KitSwords[v] then
	            local List: {string} = table.clone(Swords)
	            List[5] = KitSwords[v]
	            return List
	        end
	    end
	
	    return Swords
	end
	
	local function GetShopNPC()
	    local Shop, ItemShop, UpgradeShop, NewId = nil, false, false, nil
	    if Entity.isAlive then
	        local LocalPosition: Vector3 = Entity.character.RootPart.Position
	        for _, v: any in Store.shop do
	            if (v.RootPart.Position - LocalPosition).Magnitude <= 20 then
	                Shop = v.Upgrades or v.Shop or nil
	                UpgradeShop = UpgradeShop or v.Upgrades
	                ItemShop = ItemShop or v.Shop
	                NewId = v.Shop and v.Id or NewId
	            end
	        end
	    end
	    return Shop, ItemShop, UpgradeShop, NewId
	end
	
	local function CanBuy(Item, CurrencyTable, Amount: number?): boolean
	    Amount = Amount or 1
	    if not CurrencyTable[Item.currency] then
	        local Currency = GetItem(Item.currency)
	        CurrencyTable[Item.currency] = Currency and Currency.amount or 0
	    end
	    if IsHidden(Item) then
	        return false
	    end
	    if Item.lockedByForge or Item.disabled then
	        return false
	    end
	    if Item.require and Item.require.teamUpgrade then
	        if (bedwars.Store:getState().Bedwars.teamUpgrades[Item.require.teamUpgrade.upgradeId] or -1) < Item.require.teamUpgrade.lowestTierIndex then
	            return false
	        end
	    end
	    return CurrencyTable[Item.currency] >= (Item.price * Amount)
	end
	
	local function BuyItem(Item, CurrencyTable)
	    if not ShopId then
	        return
	    end
	    bedwars.Handler:Get("BedwarsPurchaseItem"):Fire("CallServerAsync", {
	        shopItem = Item,
	        shopId = ShopId
	    }):andThen(function(Success)
	        if Success then
	            local Meta = bedwars.ItemMeta[Item.itemType]
	            SendNotification("AutoBuy", `Bought {Meta and Meta.displayName or Item.itemType}`, 3)
	            bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)
	            bedwars.Store:dispatch({
	                type = "BedwarsAddItemPurchased",
	                itemType = Item.itemType
	            })
	            if Item.tiered and not Item.nextTier then
	                bedwars.BedwarsShopController.alreadyPurchasedMap[Item.itemType] = true
	            end
	        end
	    end)
	    CurrencyTable[Item.currency] -= Item.price
	end
	
	local function BuyTool(Tool, Tools: {string}, CurrencyTable): boolean
	    local Bought, Buyable = false
	    Tool = Tool and table.find(Tools, Tool.itemType) and table.find(Tools, Tool.itemType) + 1 or math.huge
	
	    for i: number = Tool, #Tools do
	        local ShopItem = bedwars.Shop.getShopItem(Tools[i], LocalPlayer)
	        if not ShopItem or IsHidden(ShopItem) then
	            continue
	        end
	
	        if CanBuy(ShopItem, CurrencyTable) then
	            local Meta = bedwars.ItemMeta[Tools[i]]
	            if SmartCheck.Enabled and Meta and Meta.breakBlock and i > 2 then
	                if Armor.Enabled then
	                    local CurrentArmor = Store.inventory.inventory.armor[2]
	                    CurrentArmor = CurrentArmor and CurrentArmor ~= "empty" and CurrentArmor.itemType or "none"
	                    if (table.find(Armors, CurrentArmor) or 3) < 3 then
	                        break
	                    end
	                end
	                if Sword.Enabled then
	                    if Store.tools.sword and (table.find(GetSwords(), Store.tools.sword.itemType) or 2) < 2 then
	                        break
	                    end
	                end
	            end
	            Bought = true
	            Buyable = ShopItem
	        end
	        if ShopItem.nextTier then
	            break
	        end
	    end
	
	    if Buyable then
	        BuyItem(Buyable, CurrencyTable)
	    end
	
	    return Bought
	end
	
	AutoBuy = vape.Categories.Inventory:CreateModule({
	    Name = "AutoBuy",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                task.wait()
	            until Store.queueType ~= "bedwars_test"
	            if BedwarsCheck.Enabled and not (Store.queueType:find("bedwars") or table.find(BedwarsQueues, Store.queueType)) then
	                return
	            end
	
	            local LastUpgradeShop
	            AutoBuy:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(function()
	                if (NPCTick - tick()) > 1 then
	                    NPCTick = tick()
	                end
	            end))
	
	            repeat
	                local NPC, ItemShop, UpgradeShop, NewId = GetShopNPC()
	                ShopId = NewId
	                local MenuOpen: boolean = bedwars.AppController:isAppOpen("BedwarsItemShopApp") or bedwars.AppController:isAppOpen("TeamUpgradeApp")
	                if (GUI.Enabled and not MenuOpen) or (not GUI.Enabled and MenuOpen) then
	                    NPC = nil
	                end
	
	                if NPC and LastUpgradeShop ~= UpgradeShop then
	                    if (NPCTick - tick()) > 1 then
	                        NPCTick = tick()
	                    end
	                    LastUpgradeShop = UpgradeShop
	                end
	
	                if NPC and NPCTick <= tick() and Store.matchState ~= 2 and Store.shopLoaded then
	                    local CurrencyTable = {}
	                    local WaitCheck
	                    for _, v: {(...any) -> ...any} in Callbacks do
	                        for _, BuyFunction: (...any) -> ...any in v do
	                            local Success, Bought = pcall(BuyFunction, CurrencyTable, ItemShop, UpgradeShop)
	                            if Success and Bought then
	                                WaitCheck = true
	                            end
	                        end
	                    end
	                    NPCTick = tick() + (WaitCheck and 0.4 or math.huge)
	                end
	
	                task.wait(0.1)
	            until not AutoBuy.Enabled
	        else
	            NPCTick = tick()
	        end
	    end,
	    Tooltip = "Automatically buys items when you go near the shop"
	})
	
	Sword = AutoBuy:CreateToggle({
	    Name = "Buy Sword",
	    Function = function(Callback: boolean)
	        NPCTick = tick()
	        Functions[2] = Callback and function(CurrencyTable, Shop)
	            if not Shop then
	                return
	            end
	
	            return BuyTool(Store.tools.sword, GetSwords(), CurrencyTable)
	        end or nil
	    end
	})
	Armor = AutoBuy:CreateToggle({
	    Name = "Buy Armor",
	    Function = function(Callback: boolean)
	        NPCTick = tick()
	        Functions[1] = Callback and function(CurrencyTable, Shop)
	            if not Shop then
	                return
	            end
	            local CurrentArmor = Store.inventory.inventory.armor[2] ~= "empty" and Store.inventory.inventory.armor[2] or GetBestArmor(1)
	            CurrentArmor = CurrentArmor and CurrentArmor.itemType or "none"
	            return BuyTool({itemType = CurrentArmor}, Armors, CurrencyTable)
	        end or nil
	    end,
	    Default = true
	})
	AutoBuy:CreateToggle({
	    Name = "Buy Axe",
	    Function = function(Callback: boolean)
	        NPCTick = tick()
	        Functions[3] = Callback and function(CurrencyTable, Shop)
	            if not Shop then
	                return
	            end
	            return BuyTool(Store.tools.wood or {itemType = "none"}, Axes, CurrencyTable)
	        end or nil
	    end
	})
	AutoBuy:CreateToggle({
	    Name = "Buy Pickaxe",
	    Function = function(Callback: boolean)
	        NPCTick = tick()
	        Functions[4] = Callback and function(CurrencyTable, Shop)
	            if not Shop then
	                return
	            end
	            return BuyTool(Store.tools.stone, Pickaxes, CurrencyTable)
	        end or nil
	    end
	})
	Upgrades = AutoBuy:CreateToggle({
	    Name = "Buy Upgrades",
	    Function = function(Callback: boolean)
	        for _, v: any in UpgradeToggles do
	            v.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	local Count: number = 0
	for UpgradeId: string, v: any in bedwars.TeamUpgradeMeta do
	    local ToggleCount: number = Count
	    table.insert(UpgradeToggles, AutoBuy:CreateToggle({
	        Name = `Buy {v.name == "Armor" and "Protection" or v.name}`,
	        Function = function(Callback: boolean)
	            NPCTick = tick()
	            Functions[5 + ToggleCount + (v.name == "Armor" and 20 or 0)] = Callback and function(CurrencyTable, Shop, UpgradeShop)
	                if not UpgradeShop or not Upgrades.Enabled then
	                    return
	                end
	                if v.disabledInQueue and table.find(v.disabledInQueue, Store.queueType) then
	                    return
	                end
	
	                local CurrentUpgrades = bedwars.Store:getState().Bedwars.teamUpgrades[LocalPlayer:GetAttribute("Team")] or {}
	                local Bought: boolean = false
	                for TierIndex: number = (CurrentUpgrades[UpgradeId] or 0) + 1, #v.tiers do
	                    local Tier = v.tiers[TierIndex]
	                    if Tier.availableOnlyInQueue and not table.find(Tier.availableOnlyInQueue, Store.queueType) then
	                        continue
	                    end
	                    if not CanBuy({currency = "diamond", price = Tier.cost}, CurrencyTable) then
	                        break
	                    end
	
	                    bedwars.Handler:Get("RequestPurchaseTeamUpgrade"):Fire("CallServerAsync", UpgradeId):andThen(function(Success)
	                        if Success then
	                            SendNotification("AutoBuy", `Bought {v.name == "Armor" and "Protection" or v.name} {TierIndex}`, 3)
	                        end
	                    end)
	                    CurrencyTable.diamond -= Tier.cost
	                    Bought = true
	                end
	
	                return Bought
	            end or nil
	        end,
	        Darker = true,
	        Default = (UpgradeId == "ARMOR" or UpgradeId == "DAMAGE")
	    }))
	    Count += 1
	end
	BedwarsCheck = AutoBuy:CreateToggle({
	    Name = "Only Bedwars",
	    Function = function()
	        if AutoBuy.Enabled then
	            AutoBuy:Toggle()
	            AutoBuy:Toggle()
	        end
	    end,
	    Default = true,
	    Tooltip = "Only buys in BedWars modes, including Kit Fusion and Hyper Kits"
	})
	GUI = AutoBuy:CreateToggle({
	    Name = "GUI check",
	    Tooltip = "On: only buys while the shop menu is open. Off: pauses while the shop menu is open so it never fights your own purchases"
	})
	SmartCheck = AutoBuy:CreateToggle({
	    Name = "Smart check",
	    Default = true,
	    Tooltip = "Buys iron armor before iron axe"
	})
	AutoBuy:CreateTextList({
	    Name = "Item",
	    Placeholder = "priority/item/amount/after",
	    Function = function(List: {string})
	        table.clear(Custom)
	        table.clear(CustomPost)
	        for _, v: string in List do
	            local Fields: {string} = v:split("/")
	            local Priority: number? = tonumber(Fields[1])
	            if Priority then
	                (Fields[4] and CustomPost or Custom)[Priority] = function(CurrencyTable, Shop)
	                    if not Shop then
	                        return
	                    end
	
	                    local Item = bedwars.Shop.getShopItem(Fields[2], LocalPlayer)
	                    local Amount: number? = tonumber(Fields[3])
	                    if Item and Amount then
	                        local Held = GetItem(Fields[2] == "wool_white" and bedwars.Shop.getTeamWoolById(LocalPlayer:GetAttribute("Team")) or Fields[2])
	                        Held = (Held and Amount - Held.amount or Amount) // math.max(Item.amount, 1)
	                        if Held > 0 and CanBuy(Item, CurrencyTable, Held) then
	                            for _ = 1, Held do
	                                BuyItem(Item, CurrencyTable)
	                            end
	                            return true
	                        end
	                    end
	                end
	            end
	        end
	    end
	})
end)

Run(function()
	local AutoConsume
	local Health
	local SpeedPotion
	local Apple
	local ShieldPotion
	
	local function ConsumeCheck(Attribute: string?)
	    if Entity.isAlive then
	        if SpeedPotion.Enabled and (not Attribute or Attribute == "StatusEffect_speed") then
	            local SpeedPotionItem = GetItem("speed_potion")
	            if SpeedPotionItem and (not LocalPlayer.Character:GetAttribute("StatusEffect_speed")) then
	                for _ = 1, 4 do
	                    if bedwars.Handler:Get("ConsumeItem"):Fire("CallServer", {item = SpeedPotionItem.tool}) then
	                        break
	                    end
	                end
	            end
	        end
	
	        if Apple.Enabled and (not Attribute or Attribute:find("Health")) then
	            if (LocalPlayer.Character:GetAttribute("Health") / LocalPlayer.Character:GetAttribute("MaxHealth")) <= (Health.Value / 100) then
	                local AppleItem = GetItem("orange") or (not LocalPlayer.Character:GetAttribute("StatusEffect_golden_apple") and GetItem("golden_apple")) or GetItem("apple")
	                if AppleItem then
	                    bedwars.Handler:Get("ConsumeItem"):Fire("CallServerAsync", {
	                        item = AppleItem.tool
	                    })
	                end
	            end
	        end
	
	        if ShieldPotion.Enabled and (not Attribute or Attribute:find("Shield")) then
	            if (LocalPlayer.Character:GetAttribute("Shield_POTION") or 0) == 0 then
	                local ShieldItem = GetItem("big_shield") or GetItem("mini_shield")
	                if ShieldItem then
	                    bedwars.Handler:Get("ConsumeItem"):Fire("CallServerAsync", {
	                        item = ShieldItem.tool
	                    })
	                end
	            end
	        end
	    end
	end
	
	AutoConsume = vape.Categories.Inventory:CreateModule({
	    Name = "AutoConsume",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoConsume:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(ConsumeCheck))
	            AutoConsume:Clean(VapeEvents.AttributeChanged.Event:Connect(function(Attribute: string)
	                if Attribute:find("Shield") or Attribute:find("Health") or Attribute == "StatusEffect_speed" then
	                    ConsumeCheck(Attribute)
	                end
	            end))
	            ConsumeCheck()
	        end
	    end,
	    Tooltip = "Automatically heals for you when health or shield is under threshold."
	})
	
	Health = AutoConsume:CreateSlider({
	    Name = "Health Percent",
	    Min = 1,
	    Max = 99,
	    Default = 70,
	    Suffix = "%"
	})
	SpeedPotion = AutoConsume:CreateToggle({
	    Name = "Speed Potions",
	    Default = true
	})
	Apple = AutoConsume:CreateToggle({
	    Name = "Apple",
	    Default = true
	})
	ShieldPotion = AutoConsume:CreateToggle({
	    Name = "Shield Potions",
	    Default = true
	})
end)

Run(function()
	local AutoFish
	local Show
	local Blacklist
	local Minigame
	local MinigameMode = {}
	local CompleteDelay = {}
	local Reaction = {}
	local Clicks = {}
	local Cast
	local CastDelay = {}
	local GUI
	local Rejects: {Vector3} = {}
	
	local Old
	
	local function IsMenuOpen(): boolean
	    return GUI.Enabled and bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)
	end
	
	local function GetBobber(): Instance?
	    for _, v: Instance in workspace:GetChildren() do
	        if v.Name == "fisherman_bobber" and v:GetAttribute("ProjectileShooter") == LocalPlayer.UserId then
	            return v
	        end
	    end
	    return nil
	end
	
	local function GetCastSpot(): Vector3?
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local OpenSpot: Vector3?
	
	    for Distance: number = 5, 17, 3 do
	        for Angle: number = 0, 330, 30 do
	            local Spot: Vector3 = LocalPosition + (CFrame.Angles(0, math.rad(Angle), 0).LookVector * Distance)
	            local RayResult = Entity.Raycast(Spot + Vector3.new(0, 8, 0), Vector3.new(0, -26, 0), Store.airRay)
	            local CheckPosition: Vector3 = RayResult and RayResult.Position or Spot
	            local Rejected: boolean = false
	            for _, v: Vector3 in Rejects do
	                if (v - CheckPosition).Magnitude < 4 then
	                    Rejected = true
	                    break
	                end
	            end
	
	            if not RayResult then
	                if not OpenSpot and not Rejected then
	                    OpenSpot = Spot
	                end
	            elseif RayResult.Material == Enum.Material.Water and not Rejected then
	                return RayResult.Position
	            end
	        end
	    end
	    return OpenSpot
	end
	
	local function PlayMinigame()
	    local FishermanUtil = bedwars.FishermanUtil
	    local Marker, Zone
	    local Deadline: number = tick() + 3
	    repeat
	        for _, v: Instance in LocalPlayer.PlayerGui:GetDescendants() do
	            if v.Name == "Marker" and v.Parent and v.Parent.Name == "Minigame" then
	                local FoundZone: Instance? = v.Parent:FindFirstChild("FishZone")
	                if FoundZone then
	                    Marker, Zone = v, FoundZone
	                    break
	                end
	            end
	        end
	        if not Marker then
	            task.wait()
	        end
	    until Marker or tick() > Deadline
	    if not Marker then
	        return
	    end
	
	    local Speed, AimOffset = FishermanUtil.startingMarkerIncrementSpeed, 0
	    repeat
	        if not Marker.Parent or not Zone.Parent then
	            return
	        end
	
	        if IsMenuOpen() then
	            TweenService:Create(Marker, TweenInfo.new(FishermanUtil.totalDecaySpeedSec * (Marker.Position.X.Scale + Marker.Size.X.Scale), Enum.EasingStyle.Linear), {
	                Position = UDim2.new(0, 2, 0.5, 0)
	            }):Play()
	            Speed = FishermanUtil.startingMarkerIncrementSpeed
	            repeat
	                task.wait(0.1)
	            until not IsMenuOpen() or not Marker.Parent or not AutoFish.Enabled or not Minigame.Enabled
	            continue
	        end
	
	        local Width: number = Marker.AbsoluteSize.X
	        local Center: number = Marker.AbsolutePosition.X + (Width / 2)
	        local Delta: number = ((Zone.AbsolutePosition.X + (Zone.AbsoluteSize.X / 2) + AimOffset) - Center) / math.max(Width, 1)
	        if Delta > 0.2 then
	            TweenService:Create(Marker, TweenInfo.new(math.max(Speed, FishermanUtil.holdMinimumMarkerIncrementSpeed), Enum.EasingStyle.Linear), {
	                Position = UDim2.new(math.min(Marker.Position.X.Scale + FishermanUtil.markerIncrementAmount, 1 - Marker.Size.X.Scale), 0, 0.5, 0)
	            }):Play()
	            Speed -= 0.01
	            task.wait(0.05)
	        elseif Delta < -0.2 then
	            TweenService:Create(Marker, TweenInfo.new(FishermanUtil.totalDecaySpeedSec * (Marker.Position.X.Scale + Marker.Size.X.Scale), Enum.EasingStyle.Linear), {
	                Position = UDim2.new(0, 2, 0.5, 0)
	            }):Play()
	            Speed = FishermanUtil.startingMarkerIncrementSpeed
	            AimOffset = (math.random() - 0.5) * Width * 0.1
	            task.wait(Reaction:GetRandomValue())
	        else
	            local Period: number = 1 / Clicks:GetRandomValue()
	            TweenService:Create(Marker, TweenInfo.new(math.max(FishermanUtil.startingMarkerIncrementSpeed, FishermanUtil.holdMinimumMarkerIncrementSpeed), Enum.EasingStyle.Linear), {
	                Position = UDim2.new(math.min(Marker.Position.X.Scale + FishermanUtil.markerIncrementAmount, 1 - Marker.Size.X.Scale), 0, 0.5, 0)
	            }):Play()
	            task.wait(Period * (0.35 + (math.random() * 0.25)))
	            TweenService:Create(Marker, TweenInfo.new(FishermanUtil.totalDecaySpeedSec * (Marker.Position.X.Scale + Marker.Size.X.Scale), Enum.EasingStyle.Linear), {
	                Position = UDim2.new(0, 2, 0.5, 0)
	            }):Play()
	            Speed = FishermanUtil.startingMarkerIncrementSpeed
	            AimOffset = (math.random() - 0.5) * Width * 0.1
	            task.wait(Period * (0.35 + (math.random() * 0.25)))
	        end
	    until not AutoFish.Enabled or not Minigame.Enabled
	end
	
	AutoFish = vape.Categories.Inventory:CreateModule({
	    Name = "AutoFish",
	    Function = function(Callback: boolean)
	        if Callback then
	            Old = bedwars.FishingMinigameController.startMinigame
	            bedwars.FishingMinigameController.startMinigame = function(...)
	                if Minigame.Enabled and MinigameMode.Value == "Instant" then
	                    local Deadline: number = tick() + bedwars.FishermanUtil.minigameDuration
	                    while IsMenuOpen() and tick() < Deadline do
	                        task.wait(0.1)
	                    end
	                    task.wait(CompleteDelay:GetRandomValue())
	                    return select(3, ...)({win = true})
	                end
	
	                local Call = (Old or bedwars.FishingMinigameController.startMinigame)(...)
	                if Minigame.Enabled then
	                    task.spawn(PlayMinigame)
	                end
	                return Call
	            end
	
	            AutoFish:Clean(bedwars.Handler:Get("FishFound").Remote:Connect(function(Data)
	                local Reroll: boolean = #Blacklist.ListEnabled > 0
	                for _, v: any in Data.dropData.drops do
	                    local Amount: number = tonumber(v.amount) or 0
	                    if Show.Enabled then
	                        local ItemDisplay: string = bedwars.ItemMeta[v.itemType] and bedwars.ItemMeta[v.itemType].displayName or v.itemType
	                        SendNotification("AutoFish", `You can get {Amount} {ItemDisplay:lower()}{Amount >= 2 and "s" or ""} on ur next fish`, 20, "info")
	                    end
	                    if not table.find(Blacklist.ListEnabled, v.itemType) then
	                        Reroll = false
	                    end
	                end
	
	                if Reroll and Entity.isAlive then
	                    LocalPlayer.Character.Humanoid.Jump = true
	                end
	            end))
	            repeat
	                if Entity.isAlive and Cast.Enabled and (Store.hand.tool and Store.hand.tool.Name == "fishing_rod") and not GetBobber() and not IsMenuOpen() then
	                    local Spot: Vector3? = GetCastSpot()
	                    if not Spot and #Rejects > 0 then
	                        table.clear(Rejects)
	                        Spot = GetCastSpot()
	                    end
	
	                    if Spot then
	                        task.wait(CastDelay:GetRandomValue())
	                        if AutoFish.Enabled and not IsMenuOpen() then
	                            local Item = bedwars.FishingRodController:getHandItem()
	                            if Item and not bedwars.FishingRodController.projectileHandler and bedwars.FishingRodController:canLaunch() then
	                                bedwars.FishingRodController:beginHolding(Item, nil, bedwars.FishingRodController.aimingMaid, false)
	                                task.wait()
	                                local Handler = bedwars.FishingRodController.projectileHandler
	                                if Handler then
	                                    local ProjectileMeta = bedwars.ProjectileMeta.fisherman_bobber
	                                    local Origin: Vector3 = (bedwars.ProjectileController:getLaunchPosition(Item.tool) or Entity.character.RootPart.Position) + Handler.fromPositionOffset
	                                    Handler.targetPoint = PredictionLib.SolveTrajectory(Origin, ProjectileMeta.launchVelocity, ProjectileMeta.gravitationalAcceleration, Spot, Vector3.zero, workspace.Gravity, 0, 0) or Spot
	                                end
	                                bedwars.FishingRodController:releaseChargeInput(bedwars.FishingRodController.aimingMaid, function()
	                                    return true
	                                end, nil)
	                            end
	
	                            task.wait(2.5)
	                            local Bobber: Instance? = GetBobber()
	                            if not Bobber or not Bobber:GetAttribute("WaitingForFish") then
	                                table.insert(Rejects, Spot)
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoFish.Enabled
	        else
	            table.clear(Rejects)
	            if Old then
	                bedwars.FishingMinigameController.startMinigame = Old
	                Old = nil
	            end
	        end
	    end,
	    Tooltip = "Automatically fishes with fishing rod"
	})
	
	Blacklist = AutoFish:CreateTextList({
	    Name = "Blacklisted loot",
	    Default = {"iron"},
	    Tooltip = "Jumps to cancel the catch when every item the fish drops is blacklisted"
	})
	Show = AutoFish:CreateToggle({
	    Name = "Show loot drops",
	    Tooltip = "Notifies ur next lootdrops"
	})
	Minigame = AutoFish:CreateToggle({
	    Name = "Auto Minigame",
	    Function = function(Callback: boolean)
	        if MinigameMode.Object then
	            MinigameMode.Object.Visible = Callback
	            CompleteDelay.Object.Visible = Callback and MinigameMode.Value == "Instant"
	            Reaction.Object.Visible = Callback and MinigameMode.Value == "Legit"
	            Clicks.Object.Visible = Callback and MinigameMode.Value == "Legit"
	        end
	    end,
	    Default = true,
	    Tooltip = "Automatically completes the minigame"
	})
	MinigameMode = AutoFish:CreateDropdown({
	    Name = "Minigame mode",
	    List = {"Instant", "Legit"},
	    Darker = true,
	    Function = function(Val: string)
	        if CompleteDelay.Object then
	            CompleteDelay.Object.Visible = Minigame.Enabled and Val == "Instant"
	            Reaction.Object.Visible = Minigame.Enabled and Val == "Legit"
	            Clicks.Object.Visible = Minigame.Enabled and Val == "Legit"
	        end
	    end,
	    Tooltip = "Instant wins the moment the minigame opens, Legit plays the bar out itself"
	})
	CompleteDelay = AutoFish:CreateTwoSlider({
	    Name = "Complete delay",
	    Min = 0,
	    Max = 25,
	    Decimal = 5,
	    DefaultMin = 0.1,
	    DefaultMax = 0.9,
	    Darker = true
	})
	Reaction = AutoFish:CreateTwoSlider({
	    Name = "Reaction",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    DefaultMin = 0.06,
	    DefaultMax = 0.19,
	    Darker = true,
	    Visible = false,
	    Tooltip = "How long it takes to notice the fish moved away before it lets go"
	})
	Clicks = AutoFish:CreateTwoSlider({
	    Name = "Clicks",
	    Min = 3,
	    Max = 20,
	    DefaultMin = 8,
	    DefaultMax = 13,
	    Darker = true,
	    Visible = false,
	    Suffix = "cps",
	    Tooltip = "How fast it taps to hover the bar on the fish"
	})
	Cast = AutoFish:CreateToggle({
	    Name = "Auto Cast",
	    Function = function(Callback: boolean)
	        if CastDelay.Object then
	            CastDelay.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Finds a spot to fish at and casts there, ignoring where ur camera looks"
	})
	CastDelay = AutoFish:CreateTwoSlider({
	    Name = "Cast delay",
	    Min = 0,
	    Max = 5,
	    Decimal = 5,
	    DefaultMin = 0.3,
	    DefaultMax = 1.2,
	    Darker = true,
	    Visible = false
	})
	GUI = AutoFish:CreateToggle({
	    Name = "GUI Check",
	    Tooltip = "Waits while a game menu like the shop or ur inventory is open before casting or playing the minigame"
	})
end)

Run(function()
	local AutoHotbar
	local Mode
	local Clear
	local List
	local Active
	
	local function CreateWindow(self): Frame
	    local SelectedSlot: number = 1
	    local Window: Frame = Instance.new("Frame")
	    Window.Name = "HotbarGUI"
	    Window.Size = UDim2.fromOffset(660, 465)
	    Window.Position = UDim2.fromScale(0.5, 0.5)
	    Window.BackgroundColor3 = UIPallet.Main
	    Window.AnchorPoint = Vector2.new(0.5, 0.5)
	    Window.Visible = false
	    Window.Parent = vape.gui.ScaledGui
	    local Title: TextLabel = Instance.new("TextLabel")
	    Title.Name = "Title"
	    Title.Size = UDim2.new(1, -10, 0, 20)
	    Title.Position = UDim2.fromOffset(math.abs(Title.Size.X.Offset), 12)
	    Title.BackgroundTransparency = 1
	    Title.Text = "AutoHotbar"
