	    local function IndexSearch(Text: string)
	        for _, v: Instance in Children:GetChildren() do
	            if v:IsA("TextButton") then
	                v:ClearAllChildren()
	                v:Destroy()
	            end
	        end
	
	        if Text == "" then
	            for _, v: string in {"diamond_sword", "diamond_pickaxe", "diamond_axe", "shears", "wood_bow", "wool_white", "fireball", "apple", "iron", "gold", "diamond", "emerald"} do
	                CreateItem(v, bedwars.ItemMeta[v].image)
	            end
	            return
	        end
	
	        for ItemId: string, v: any in bedwars.ItemMeta do
	            if Text:lower() == ItemId:lower():sub(1, Text:len()) then
	                if not v.image then
	                    continue
	                end
	                CreateItem(ItemId, v.image)
	            end
	        end
	    end
	
	    Search:GetPropertyChangedSignal("Text"):Connect(function()
	        IndexSearch(Search.Text)
	    end)
	    IndexSearch("")
	
	    return Window
	end
	
