	local function Sort()
	    local Wanted: {[string]: string} = {}
	    for Slot: string, v: string in List.Hotbars[List.Selected] and List.Hotbars[List.Selected].Hotbar or {} do
	        Wanted[Slot] = v
	        if v == "diamond_sword" then
	            local Sword = Store.tools.sword
	            Wanted[Slot] = Sword and Sword.itemType or "wood_sword"
	        elseif v == "diamond_pickaxe" then
	            local Pickaxe = Store.tools.stone
	            Wanted[Slot] = Pickaxe and Pickaxe.itemType or "wood_pickaxe"
	        elseif v == "diamond_axe" then
	            local Axe = Store.tools.wood
	            Wanted[Slot] = Axe and Axe.itemType or "wood_axe"
	        elseif v == "wood_bow" then
	            local Bow = GetBow()
	            Wanted[Slot] = Bow and Bow.itemType or "wood_bow"
	        elseif v == "wool_white" then
	            local SortedItems = table.clone(Store.inventory.inventory.items)
	            table.sort(SortedItems, function(A, B)
	                return A.amount < B.amount
	            end)
	            for _, Item: any in SortedItems do
	                local Meta = bedwars.ItemMeta[Item.itemType]
	                local Block = Meta and Meta.block
	                if Block and not Block.seeThrough then
	                    Wanted[Slot] = Item.itemType
	                    break
	                end
	            end
	        end
	    end
	
	    for _, v: any in Store.inventory.inventory.items do
	        local Slot
	        for SlotKey: string, ItemType: string in Wanted do
	            if v.itemType == ItemType then
	                Slot = tonumber(SlotKey)
	                break
	            end
	        end
	
	        if Slot then
	            local OldItem = Store.inventory.hotbar[Slot]
	            if OldItem.item and OldItem.item.itemType == v.itemType then
	                continue
	            end
	            if OldItem.item then
	                bedwars.Store:dispatch({
	                    type = "InventoryRemoveFromHotbar",
	                    slot = Slot - 1
	                })
	                VapeEvents.InventoryChanged.Event:Wait()
	            end
	
	            local NewSlot
	            for i: number, HotbarSlot: any in Store.inventory.hotbar do
	                if HotbarSlot.item and HotbarSlot.item.itemType == v.itemType then
	                    NewSlot = i - 1
	                    break
	                end
	            end
	
	            if NewSlot then
	                bedwars.Store:dispatch({
	                    type = "InventoryRemoveFromHotbar",
	                    slot = NewSlot
	                })
	                VapeEvents.InventoryChanged.Event:Wait()
	                if OldItem.item then
	                    local Swap
	                    for _, Item: any in Store.inventory.inventory.items do
	                        if Item.itemType == OldItem.item.itemType then
	                            Swap = Item
	                            break
	                        end
	                    end
	                    bedwars.Store:dispatch({
	                        type = "InventoryAddToHotbar",
	                        item = Swap,
	                        slot = NewSlot
	                    })
	                    VapeEvents.InventoryChanged.Event:Wait()
	                end
	            end
	
	            local Held
	            for _, Item: any in Store.inventory.inventory.items do
	                if Item.itemType == v.itemType then
	                    Held = Item
	                    break
	                end
	            end
	            bedwars.Store:dispatch({
	                type = "InventoryAddToHotbar",
	                item = Held,
	                slot = Slot - 1
	            })
	            VapeEvents.InventoryChanged.Event:Wait()
	        elseif Clear.Enabled then
	            local NewSlot
	            for i: number, HotbarSlot: any in Store.inventory.hotbar do
	                if HotbarSlot.item and HotbarSlot.item.itemType == v.itemType then
	                    NewSlot = i - 1
	                    break
	                end
	            end
	
	            if NewSlot then
	                bedwars.Store:dispatch({
	                    type = "InventoryRemoveFromHotbar",
	                    slot = NewSlot
	                })
	                VapeEvents.InventoryChanged.Event:Wait()
	            end
	        end
	    end
	end
	
	local function SortCallback()
	    if Active then
	        return
	    end
	
	    Active = true
	    local Success, Error = pcall(Sort)
	    Active = false
	
	    if not Success and shared.VapeDeveloper then
	        warn(`[catvape] AutoHotbar failed to sort: {Error}`)
	    end
	end
	
	AutoHotbar = vape.Categories.Inventory:CreateModule({
	    Name = "AutoHotbar",
	    Function = function(Callback: boolean)
	        if Callback then
	            task.spawn(SortCallback)
	            if Mode.Value == "On Key" then
	                AutoHotbar:Toggle()
	                return
	            end
	
	            AutoHotbar:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(SortCallback))
	        end
	    end,
	    Tooltip = "Automatically arranges hotbar to your liking."
	})
	
	Mode = AutoHotbar:CreateDropdown({
	    Name = "Activation",
	    List = {"Toggle", "On Key"},
	    Function = function()
	        if AutoHotbar.Enabled then
	            AutoHotbar:Toggle()
	            AutoHotbar:Toggle()
	        end
	    end
	})
	Clear = AutoHotbar:CreateToggle({Name = "Clear Hotbar"})
	List = AutoHotbar:CreateHotbarList({})
end)

Run(function()
	local AutoSteal
	local Range
	local Delay
	local GUI
	local Stash = {}
	
	local function StealCrate(Crate: Instance)
	    local FolderValue: Instance? = Crate:FindFirstChild("ChestFolderValue")
	    local Folder = FolderValue and FolderValue.Value or nil
	    if not Folder then
	        return
	    end
	
	    local Items: {Instance} = {}
	    for _, v: Instance in Folder:GetChildren() do
	        if v:IsA("Accessory") then
	            table.insert(Items, v)
	        end
	    end
	    if #Items == 0 then
	        return
	    end
	
	    local Observed = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("ObservedChestFolder")
	    Observed = Observed and Observed.Value or nil
	    bedwars.Client:GetNamespace("Inventory"):Get("SetObservedChest"):SendToServer(Folder)
	
	    for _, v: Instance in Items do
	        local ItemType: string = v.Name
	        task.spawn(function()
	            local Success, Result = pcall(function()
	                return bedwars.Client:GetNamespace("Inventory"):Get("ChestGetItem"):CallServer(Folder, v)
	            end)
	
	            if Success and Result then
	                table.insert(Stash, {Type = ItemType, Expire = tick() + 5})
	            end
	        end)
	    end
	
	    bedwars.Client:GetNamespace("Inventory"):Get("SetObservedChest"):SendToServer(Observed)
	end
	
	local function DepositStash()
	    local Inventory: Instance? = ReplicatedStorage:FindFirstChild("Inventories")
	    Inventory = Inventory and Inventory:FindFirstChild(`{LocalPlayer.Name}_personal`) or nil
	    if not Inventory then
	        return
	    end
	
	    local Pending = table.clone(Stash)
	    table.clear(Stash)
	
	    for _, v: {Type: string, Expire: number} in Pending do
	        local Item = GetItem(v.Type)
	        if Item then
	            task.spawn(function()
	                local Success, Result = pcall(function()
	                    return bedwars.Client:GetNamespace("Inventory"):Get("ChestGiveItem"):CallServer(Inventory, Item.tool)
	                end)
	
	                if not (Success and Result) and tick() < v.Expire then
	                    table.insert(Stash, v)
	                end
	            end)
	        elseif tick() < v.Expire then
	            table.insert(Stash, v)
	        end
	    end
	end
	
	AutoSteal = vape.Categories.Inventory:CreateModule({
	    Name = "AutoSteal",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                task.wait()
	            until Store.matchState ~= 0 or (not AutoSteal.Enabled)
	            if not AutoSteal.Enabled then
	                return
	            end
	
	            local Crates = Collection("team-crate", AutoSteal)
	            local Chests = Collection("personal-chest", AutoSteal)
	            local NextSteal: number = 0
	
	            repeat
	                if Entity.isAlive and tick() > NextSteal and (not GUI.Enabled or bedwars.AppController:isAppOpen("ChestApp")) then
	                    NextSteal = tick() + Delay.Value
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local Team = LocalPlayer:GetAttribute("Team")
	
	                    for _, v: BasePart in Crates do
	                        if v:GetAttribute("Team") ~= Team and (LocalPosition - v.Position).Magnitude <= Range.Value then
	                            StealCrate(v)
	                        end
	                    end
	
	                    if #Stash > 0 then
	                        for _, v: BasePart in Chests do
	                            if (LocalPosition - v.Position).Magnitude <= Range.Value then
	                                DepositStash()
	                                break
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoSteal.Enabled
	        end
	
	        table.clear(Stash)
	    end,
	    Tooltip = "Automatically steals loot from the enemy team's crate and banks it in your personal chest"
	})
	
	Range = AutoSteal:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 18,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	Delay = AutoSteal:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0
	})
	GUI = AutoSteal:CreateToggle({Name = "GUI Check"})
end)

