Run(function()
	local AutoCyber
	local Mode
	local Whitelist
	local Visual
	local Steal
	local Target
	local Limit
	
	local TeamCache, CacheExpire = nil, 0
	local function GetTeamGenerator()
	    if CacheExpire > tick() and TeamCache and TeamCache.Parent then
	        return TeamCache
	    end
	    TeamCache, CacheExpire = CollectionService:GetTagged(`{LocalPlayer:GetAttribute("Team")}_TeamOreGenerator`)[1], tick() + 5
	    return TeamCache
	end
	local DroneCache = nil
	local Watching = setmetatable({}, {__mode = "k"})
	local function GetDrone()
	    if Limit.Enabled and (not Store.hand.tool or Store.hand.tool.Name ~= "drone") then
	        return nil
	    end
	    if DroneCache and DroneCache.Parent then
	        return DroneCache
	    end
	    for _, v: Model in CollectionService:GetTagged("Drone") do
	        if v:GetAttribute("PlayerUserId") == LocalPlayer.UserId then
	            local function Changed()
	                if v:GetAttribute("HeldItem") then
	                    repeat
	                        bedwars.Handler:Get("DropDroneItem"):Fire("SendToServer", {
	                            direction = Vector3.new(1000, 10, 0),
	                            position = v.PrimaryPart.Position
	                        })
	                        task.wait(0.1)
	                    until not v:GetAttribute("HeldItem") or not AutoCyber.Enabled
	                end
	            end
	            if not Watching[v] then
	                Watching[v] = {
	                    v:GetAttributeChangedSignal("HeldItem"):Connect(Changed),
	                    v:GetAttributeChangedSignal("HeldItemAmount"):Connect(Changed)
	                }
	            end
	            DroneCache = v
	            return v
	        end
	    end
	    if GetItem("drone") and bedwars.Handler:Get("FireGuidedProjectile"):Fire("CallServer", "drone") then
	        task.wait(0.1)
	        return GetDrone()
	    end
	    return nil
	end
	local Blacklist: {[BasePart]: number} = {}
	local function GetItemDrop(Drone: Model): BasePart?
	    local Generator = GetTeamGenerator()
	    Generator = Generator and Generator.PrimaryPart.Position or Vector3.zero
	    local Children: {BasePart} = workspace.ItemDrops:GetChildren()
	    local Position: Vector3 = Drone.PrimaryPart.Position
	    local Distances: {[BasePart]: number} = {}
	
	    local function GetDistance(Part: BasePart): number
	        local Distance: number? = Distances[Part]
	        if not Distance then
	            Distance = (Position - Part.Position).Magnitude
	            Distances[Part] = Distance
	        end
	        return Distance
	    end
	
	    table.sort(Children, function(A: BasePart, B: BasePart)
	        return GetDistance(A) < GetDistance(B)
	    end)
	    for _, v: BasePart in Children do
	        if tick() > (Blacklist[v] or 0) and table.find(Whitelist.ListEnabled, v.Name) and v.Position.Y > 0 and math.abs(v.AssemblyLinearVelocity.Y) <= 0 and (not Steal.Enabled or (v.Position - Generator).Magnitude > 20) and (not Target.Enabled or not Entity.EntityPosition({
	            Origin = Position,
	            Range = 60,
	            Part = "RootPart",
	            Players = true
	        })) then
	            return v
	        end
	    end
	    return nil
	end
	AutoCyber = vape.Categories.Kits:CreateModule({
	    Name = "AutoCyber",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoCyber:Clean(workspace.ItemDrops.ChildAdded:Connect(function(ItemDrop: BasePart)
	                task.wait()
	                if ItemDrop.AssemblyLinearVelocity.X > 100 then
	                    Blacklist[ItemDrop] = tick() + 5
	                    local Amount = ItemDrop:GetAttribute("Amount")
	                    local LastParent: Instance? = ItemDrop.Parent
	                    if Mode.Value == "Player" then
	                        SendNotification("AutoCyber", `Collecting {Amount} {ItemDrop.Name}`, 4, "info")
	                        repeat
	                            ItemDrop.AssemblyLinearVelocity = Vector3.zero
	                            ItemDrop.CFrame = Entity.character.RootPart.CFrame - Vector3.new(0, 4, 0)
	                            task.spawn(function()
	                                bedwars.Handler:Get("PickupItemDrop"):Fire("CallServerAsync", {
	                                    itemDrop = ItemDrop
	                                }):andThen(function(Success: boolean)
	                                    if Success and bedwars.SoundList then
	                                        bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)
	                                        local Sound = bedwars.ItemMeta[ItemDrop.Name].pickUpOverlaySound
	                                        if Sound then
	                                            bedwars.AudioManager:playAudio(Sound, {
	                                                position = ItemDrop.Position,
	                                                volumeMultiplier = 0.9
	                                            })
	                                        end
	                                    end
	                                end)
	                            end)
	                            task.wait(0.02)
	                        until not ItemDrop or ItemDrop.Parent ~= LastParent
	
	                        SendNotification("AutoCyber", `Collected {Amount} {ItemDrop.Name}{Amount > 1 and "s" or ""}`, 4, "info")
	                    else
	                        local Start: number = tick()
	                        local Generator = GetTeamGenerator()
	                        if Generator then
	                            repeat
	                                ItemDrop.AssemblyLinearVelocity = Vector3.zero
	                                ItemDrop.CFrame = Generator.PrimaryPart.CFrame
	                                task.wait()
	                            until (tick() - Start) >= 1 or not ItemDrop or ItemDrop.Parent ~= LastParent
	                            SendNotification("AutoCyber", `Dropped {Amount} {ItemDrop.Name}`, 8, "info")
	                        else
	                            SendNotification("AutoCyber", "Generator not found", 20, "alert")
	                        end
	                    end
	                end
	            end))
	
	            repeat
	                local Drone: Model? = GetDrone()
	                if Drone then
	                    local ItemDrop: BasePart? = GetItemDrop(Drone)
	                    if ItemDrop then
	                        task.wait(0.3)
	                        local Highlight: Highlight?
	                        if Visual.Enabled then
	                            Highlight = Instance.new("Highlight")
	                            Highlight.FillColor = Color3.new(1, 1, 1)
	                            Highlight.FillTransparency = 0
	                            Highlight.OutlineTransparency = 0.5
	                            Highlight.OutlineColor = Color3.new()
	                            Highlight.Parent = ItemDrop
	                        end
	                        Drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
	                        Drone.PrimaryPart.CFrame = CFrame.new(Drone.PrimaryPart.CFrame.X, 10000, Drone.PrimaryPart.CFrame.Z)
	                        local Magnitude, LastMagnitude = 0, 9e9
	                        local Position: Vector3 = ItemDrop.Position
	                        repeat
	                            if Drone and Drone.Parent then
	                                Position = ItemDrop.Position
	                                local Multiplier = Drone:GetAttribute("SpeedBoost")
	                                Multiplier = Multiplier == 0 or Multiplier == "" or not Multiplier and true or false
	                                Drone.PrimaryPart.CanCollide = false
	                                Drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
	                                Drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(Drone.PrimaryPart.Position * Vector3.new(1, 0, 1), Position * Vector3.new(1, 0, 1)).LookVector * 30
	                                Magnitude = ((Drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (Position * Vector3.new(1, 0, 1))).Magnitude
	                                if (LastMagnitude - Magnitude) >= 25 then
	                                    LastMagnitude = Magnitude
	                                    SendNotification("AutoCyber", `Drone is {math.floor(Magnitude)} studs away from {ItemDrop.Name}.`, 1, "info")
	                                end
	                            else
	                                break
	                            end
	                            task.wait()
	                        until not ItemDrop or ItemDrop.Parent ~= workspace.ItemDrops or not AutoCyber.Enabled or Magnitude <= 2
	                        if not AutoCyber.Enabled then
	                            if Highlight and Highlight.Parent then
	                                Highlight:Destroy()
	                            end
	                            break
	                        end
	
	                        if Magnitude <= 5 then
	                            local Start: number = tick()
	                            if Visual.Enabled then
	                                SendNotification("AutoCyber", `Attempting to collect {ItemDrop.Name}`, 4, "info")
	                            end
	                            repeat
	                                if Drone and Drone.Parent then
	                                    Drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
	                                    Drone.PrimaryPart.AssemblyAngularVelocity = Vector3.new(0, -30, 0)
	                                    Drone.PrimaryPart.CFrame = CFrame.new(Position - Vector3.new(0, Drone.Hitbox.Size.Y, 0))
	                                end
	                                task.wait(0.02)
	                            until (tick() - Start) >= 1.25
	                        elseif Visual.Enabled then
	                            SendNotification("AutoCyber", `Too far away to collect {ItemDrop.Name} ({Magnitude} studs).`, 8, "info")
	                        end
	                        if Highlight and Highlight.Parent then
	                            Highlight:Destroy()
	                        end
	                    else
	                        Drone.PrimaryPart.CFrame = CFrame.new(Drone.PrimaryPart.CFrame.X, 10000, Drone.PrimaryPart.CFrame.Z)
	                        Drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
	                        for _, v: string in Whitelist.ListEnabled do
	                            local Item: string = v
	                            local Children: {Model} = CollectionService:GetTagged(`{Item}_OreGenerator`)
	                            local Position: Vector3 = Drone.PrimaryPart.Position
	                            table.sort(Children, function(A: Model, B: Model)
	                                return (Position - A.PrimaryPart.Position).Magnitude < (Position - B.PrimaryPart.Position).Magnitude
	                            end)
	                            local Generator: BasePart? = Children[1] and Children[1].PrimaryPart or nil
	                            if Generator then
	                                local Magnitude: number = 0
	                                repeat
	                                    if Drone and Drone.Parent then
	                                        if GetItemDrop(Drone) then
	                                            break
	                                        end
	                                        Drone.PrimaryPart.CanCollide = false
	                                        Drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
	                                        Drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(Drone.PrimaryPart.Position * Vector3.new(1, 0, 1), Generator.Position * Vector3.new(1, 0, 1)).LookVector * 30
	                                        Magnitude = ((Drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (Generator.Position * Vector3.new(1, 0, 1))).Magnitude
	                                    else
	                                        break
	                                    end
	                                    task.wait()
	                                until not AutoCyber.Enabled or Magnitude <= 5
	                            end
	                        end
	                    end
	                end
	                task.wait()
	            until not AutoCyber.Enabled
	        else
	            local Drone: Model? = GetDrone()
	            if Drone then
	                Drone.PrimaryPart.CFrame = CFrame.new(Drone.PrimaryPart.CFrame.X, 500, Drone.PrimaryPart.CFrame.Z)
	            end
	        end
	    end,
	    Tooltip = "Allows you to steal other's opponent resources via drone."
	})
	
	Mode = AutoCyber:CreateDropdown({
	    Name = "Drop mode",
	    List = {"Player", "Generator"},
	    Default = "Player",
	    Tooltip = "Where cyber items gets dropped to."
	})
	Whitelist = AutoCyber:CreateTextList({
	    Name = "Whitelist",
	    Default = {"emerald", "diamond"}
	})
	Visual = AutoCyber:CreateToggle({
	    Name = "Visualize",
	    Default = true,
	    Tooltip = "Shows what item the drone is targeting and updates\non where how far the drone is to the item."
	})
	Steal = AutoCyber:CreateToggle({
	    Name = "Steal split",
	    Default = true,
	    Tooltip = "Steals other opponent team's generator split."
	})
	Target = AutoCyber:CreateToggle({Name = "Target check"})
	Limit = AutoCyber:CreateToggle({Name = "Limit to item"})
end)

Run(function()
	local AutoDavey
	local Switch
	local Break
	local Jump
	local LimitItem
	
	local Old, OldAim
	
	local function CanBreak(): boolean
	    if not LimitItem.Enabled then
	        return true
	    end
	    local ItemMeta = Store.hand.tool and bedwars.ItemMeta[Store.hand.tool.Name]
	    return ItemMeta ~= nil and ItemMeta.breakBlock ~= nil
	end
	
	local function BreakCannon(Block: BasePart, KeepLast: boolean?)
	    local Deadline: number = tick() + 0.6 + (Store.ping.total or 0)
	    local Hits: number = KeepLast and math.max(math.ceil(GetBlockHits(Block, Block.Position)) - 1, 0) or math.huge
	
	    repeat
	        if not AutoDavey.Enabled or not Entity.isAlive or not CanBreak() or Hits <= 0 then
	            return
	        end
	        if (Block.Position - Entity.character.RootPart.Position).Magnitude > 30 then
	            return
	        end
	        bedwars.breakBlock(Block, true, true, nil, Switch.Enabled)
	        Hits -= 1
	        task.wait(0.1)
	    until not Block.Parent or tick() > Deadline
	end
	
	AutoDavey = vape.Categories.Kits:CreateModule({
	    Name = "AutoDavey",
	    Function = function(Callback: boolean)
	        if Callback then
	            OldAim = bedwars.CannonController.startAiming
	            bedwars.CannonController.startAiming = function(self, Block, ...)
	                local Call = OldAim(self, Block, ...)
	
	                if Break.Enabled and Block and Block.Parent and Entity.isAlive and CanBreak() and GetBlockHits(Block, Block.Position) > 1 then
	                    task.spawn(BreakCannon, Block, true)
	                end
	
	                return Call
	            end
	
	            Old = bedwars.CannonHandController.launchSelf
	            bedwars.CannonHandController.launchSelf = function(self, Block, ...)
	                if Break.Enabled and Block and Block.Parent and Entity.isAlive and (Block.Position - Entity.character.RootPart.Position).Magnitude <= 30 and CanBreak() then
	                    pcall(BreakCannon, Block, true)
	                    task.spawn(BreakCannon, Block)
	                end
	
	                local Call = Old(self, Block, ...)
	
	                if Jump.Enabled and Entity.isAlive then
	                    Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	                end
	                return Call
	            end
	        else
	            bedwars.CannonHandController.launchSelf = Old
	            bedwars.CannonController.startAiming = OldAim
	        end
	    end,
	    Tooltip = "Automatically breaks cannon/jump on launch"
	})
	
	Jump = AutoDavey:CreateToggle({Name = "Jump on impact"})
	
	Break = AutoDavey:CreateToggle({Name = "Break on impact", Default = true})
	
	Switch = AutoDavey:CreateToggle({Name = "Legit switch"})
	
	LimitItem = AutoDavey:CreateToggle({
	    Name = "Limit to items",
	    Tooltip = "Only breaks when tools are held"
	})
end)

Run(function()
	local AutoDragonSword
	local Range
	local Targets
	
	AutoDragonSword = vape.Categories.Kits:CreateModule({
	    Name = "AutoDragonSword",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and Store.equippedKit == "dragon_sword" and bedwars.AbilityController:canUseAbility("dragon_sword_ult", {disableBlockedAbilityAlert = true}) then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	                    local Found: number = 0
	                    for _, v: any in Entity.List do
	                        if v.Targetable and (v.RootPart.Position - Origin).Magnitude <= Range.Value then
	                            Found += 1
	                        end
	                    end
	
	                    if Found >= Targets.Value then
	                        bedwars.AbilityController:useAbility("dragon_sword_ult")
	                    end
	                end
	                task.wait(0.1)
