	    NPCs = true,
	    Walls = true
	})
	Range = AutoElektra:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 25,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Face = AutoElektra:CreateToggle({
	    Name = "Face target",
	    Default = true,
	    Tooltip = "Turns you at them first so the dash actually goes through them"
	})
end)

