Run(function()
	local AutoFarmer
	local Harvest
	local Collect
	local Range
	local Delay
	local NextAction: number = 0
	
	local Drops: {[string]: boolean} = {
	    carrot = true,
	    carrot_seeds = true,
	    melon = true,
	    melon_seeds = true,
	    watermelon = true,
	    pumpkin = true,
	    pumpkin_block = true,
	    pumpkin_seeds = true
	}
	
	local function HarvestCrop(Origin: Vector3): boolean
	    for _, v: Instance in CollectionService:GetTagged("HarvestableCrop") do
	        local Owner: number = v:GetAttribute("PlacedByUserId") or 0
	        local Player = Owner ~= 0 and Players:GetPlayerByUserId(Owner)
	        if v:IsA("BasePart") and (v.Position - Origin).Magnitude <= Range.Value and (not Player or Player:GetAttribute("Team") == LocalPlayer:GetAttribute("Team")) then
	            bedwars.Handler:Get("CropHarvest"):Fire("CallServer", {
	                position = bedwars.BlockController:getBlockPosition(v.Position)
	            })
	            return true
	        end
	    end
	    return false
	end
	
	local function CollectDrop(Origin: Vector3): boolean
	    for _, v: BasePart in CollectionService:GetTagged("ItemDrop") do
	        if Drops[v.Name] and (v:GetAttribute("PickupReadyTime") or math.huge) < workspace:GetServerTimeNow() and (v.Position - Origin).Magnitude <= Range.Value then
	            bedwars.Handler:Get("PickupItemDrop"):Fire("CallServerAsync", {itemDrop = v})
	            return true
	        end
	    end
	    return false
	end
	
	AutoFarmer = vape.Categories.Kits:CreateModule({
	    Name = "AutoFarmer",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextAction = 0
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "farmer_cletus" and tick() >= NextAction then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	                    if (Harvest.Enabled and HarvestCrop(Origin)) or (Collect.Enabled and CollectDrop(Origin)) then
	                        NextAction = tick() + Delay.Value
	                    end
	                end
	                task.wait(0.1)
	            until not AutoFarmer.Enabled
	        end
	    end,
	    Tooltip = "Harvests your ripe crops and picks up what they drop"
	})
	
	Harvest = AutoFarmer:CreateToggle({
	    Name = "Harvest crops",
	    Default = true,
	    Tooltip = "Reaps anything ripe, the same call the Harvest prompt makes"
	})
	Collect = AutoFarmer:CreateToggle({
	    Name = "Collect drops",
	    Default = true,
	    Tooltip = "Picks up the crops and seeds lying on the ground"
	})
	Range = AutoFarmer:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 25,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "The games own harvest prompt stops at 6 studs, so the server may refuse anything much further out"
	})
	AutoFarmer:CreateButton({
	    Name = "Sync to legit range",
	    Function = function()
	        Range:SetValue(6)
	    end
	})
	Delay = AutoFarmer:CreateSlider({
	    Name = "Delay",
	    Min = 0.05,
	    Max = 3,
	    Default = 0.15,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end
	})
end)

