	    star_collector = function(Session)
	        KitCollection("stars", function(Star: Instance)
	            bedwars.StarCollectorController:collectEntity(LocalPlayer, Star, Star.Name)
	        end, 20, false, Session)
	    end,
	    summoner = function()
	        repeat
	            local Ent = Entity.EntityPosition({
	                Range = 31,
