Run(function()
	local AutoLani
	local Delay
	local UseEnemy
	local Enemy
	local Player
	
	local Request = bedwars.Handler:Get("PaladinAbilityRequest")
	
	AutoLani = vape.Categories.Kits:CreateModule({
	    Name = "AutoLani",
	    Function = function(Callback: boolean)
	        if Callback then
	            local OldStart
	
	            repeat
	                local Start = LocalPlayer:GetAttribute("PaladinStartTime")
	                if OldStart and OldStart ~= Start then
	                    local Target = UseEnemy.Enabled and Players:FindFirstChild(Enemy.Value) or not UseEnemy.Enabled and Players:FindFirstChild(Player.Value) or nil
	                    if Target then
	                        task.delay(Delay.Value, function()
	                            Request:Fire("SendToServer", {target = Target})
	                        end)
	                    end
	                end
	                OldStart = Start
	                task.wait(0.1)
	            until not AutoLani.Enabled
	        end
	    end,
	    Tooltip = 'Automatically uses the "scepter of light" ability'
	})
	
	local Friends, Enemies = {"None"}, {"None"}
	
	local function AddConnection(TargetPlayer: Player, Connected: boolean?)
	    local Friendly: boolean = TargetPlayer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team")
	
	    if not Connected then
	        vape:Clean(TargetPlayer:GetAttributeChangedSignal("Team"):Connect(function()
	            AddConnection(TargetPlayer, true)
	        end))
	    end
	
	    if Friendly and not table.find(Friends, TargetPlayer.Name) then
	        table.insert(Friends, TargetPlayer.Name)
	        Player:Change(Friends)
	    elseif not Friendly and TargetPlayer.Team and TargetPlayer.Team.Name ~= "Spectators" and not table.find(Enemies, TargetPlayer.Name) then
	        table.insert(Enemies, TargetPlayer.Name)
	        Enemy:Change(Enemies)
	    end
	end
	
	Player = AutoLani:CreateDropdown({
	    Name = "Selected Player",
	    List = {},
	    Tooltip = "Player to use the ability on"
	})
	Enemy = AutoLani:CreateDropdown({
	    Name = "Selected Enemy",
	    List = {},
	    Visible = false,
	    Tooltip = "Target to use the ability on"
	})
	UseEnemy = AutoLani:CreateToggle({
	    Name = "Use enemy",
	    Function = function(Callback: boolean)
	        Enemy.Object.Visible = Callback
	        Player.Object.Visible = not Callback
	    end,
	    Tooltip = "Uses the ability on other people instead of your teammates"
	})
	Delay = AutoLani:CreateSlider({
	    Name = "Delay",
	    Min = 1,
	    Max = 20,
	    Default = 5,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end,
	    Tooltip = "Delay between triggers"
	})
	for _, v: Player in Players:GetPlayers() do
	    AddConnection(v)
	end
	vape:Clean(Players.PlayerAdded:Connect(AddConnection))
end)

Run(function()
	local AutoLasso
	local Targets
	local Range
	local FireRate
