	        if Callback then
	            Aura = ""
	            AutoSilas:Clean(bedwars.Handler:Get("UpdateRebellionAura").Remote:Connect(function(Data)
	                if Data.player == LocalPlayer then
	                    Aura = Data.newAura
	                end
	            end))
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "rebellion_leader" then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	                    local Enemy = Entity.EntityPosition({
	                        Origin = Origin,
	                        Range = Range.Value,
	                        Part = "RootPart",
	                        Players = true
