Run(function()
	local AutoSophia
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local NextFire: number = 0
	local NextSwap: number = 0
	
	local Staffs: {string} = {"frost_staff_3", "frost_staff_2", "frost_staff_1"}
	
	local function ShootStaff()
	    local Item, ItemType
	    for _, v: string in Staffs do
	        Item = GetItem(v)
	        if Item then
	            ItemType = v
	            break
	        end
	    end
	    local Source = Item and bedwars.ItemMeta[ItemType].projectileSource or nil
	    local Target = Source and GetFacingEntity({
	        Part = "RootPart",
	        Range = Range.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    }) or nil
	    if not Target then
	        return
	    end
	
	    local Ready: boolean = bedwars.FrostyGunController.projectileMode == bedwars.FrostyGunMode.PROJECTILE
	    local Swapping: boolean = not Ready and tick() >= NextSwap and bedwars.AbilityController:canUseAbility("frosty_gun_swap", {disableBlockedAbilityAlert = true})
	    if not Ready and not Swapping then
	        return
	    end
	
	    local Hotbar = Store.hand.tool and GetHotbar(Store.hand.tool) or nil
	    if HotbarSwitch(GetHotbar(Item.tool)) then
	        task.wait(Store.ping.total or 0)
	        if Ready then
	            if FireProjectile(Item, ItemType, Source.projectileType(ItemType), Target) then
	                NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()
	                task.wait(SwitchDelay.Value)
	            end
	        else
	            NextSwap = tick() + 1
	            bedwars.AbilityController:useAbility("frosty_gun_swap")
	            task.wait(SwitchDelay.Value)
	        end
	        HotbarSwitch(Hotbar)
	    end
	end
	
	AutoSophia = vape.Categories.Kits:CreateModule({
	    Name = "AutoSophia",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextFire, NextSwap = 0, 0
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "winter_lady" and Store.hand.toolType == "sword" and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then
	                    ShootStaff()
	                end
	                task.wait(0.1)
	            until not AutoSophia.Enabled
	        end
	    end,
	    Tooltip = "Automatically shoots Sophia's frost staff at whoever you're meleeing, swapping it out of mist mode when needed"
	})
	
	Targets = AutoSophia:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	Range = AutoSophia:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 22,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	FireRate = AutoSophia:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	SwitchDelay = AutoSophia:CreateSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.02
	})
end)

