Run(function()
	local Zoom
	local Level
	local Speed
	local Sensitivity
	
	local OldSetFOV, OldGetFOV, OldSensitivity
	local Current, Target = 0, 0
	
	Zoom = vape.Legit:CreateModule({
	    Name = "Zoom",
	    Category = "Game",
	    Icon = GetVapeAsset("GyuvapeBedwarsCheat/assets/new/legit_fov.png"),
	    Function = function(Callback: boolean)
	        if Callback then
	            local Base: number = bedwars.FovController:getFOV()
	            Current, Target = Base, Base / Level.Value
	
	            OldSetFOV = bedwars.FovController.setFOV
	            OldGetFOV = bedwars.FovController.getFOV
	            bedwars.FovController.setFOV = function(self, Value: number?)
	                Base = Value or Base
	                Target = Base / Level.Value
	                return OldSetFOV(self, Current)
	            end
	            bedwars.FovController.getFOV = function()
	                return Current
	            end
	
	            if Sensitivity.Enabled then
	                OldSensitivity = UserInputService.MouseDeltaSensitivity
	                UserInputService.MouseDeltaSensitivity = OldSensitivity / Level.Value
	            end
	
	            Zoom:Clean(RunService.PreRender:Connect(function(Delta: number)
	                Target = Base / Level.Value
	                Current = Current + (Target - Current) * math.clamp(Speed.Value * Delta, 0, 1)
	                OldSetFOV(bedwars.FovController, Current)
	            end))
	        else
	            bedwars.FovController.setFOV = OldSetFOV
	            bedwars.FovController.getFOV = OldGetFOV
	
	            if OldSensitivity then
	                UserInputService.MouseDeltaSensitivity = OldSensitivity
	                OldSensitivity = nil
	            end
	
	            if OldSetFOV then
	                bedwars.FovController:setFOV(bedwars.Store:getState().Settings.fov)
	            end
	        end
	    end,
	    Tooltip = "Zooms your view in while it is on, bind it to a key and hold it like a scope"
	})
	
	Level = Zoom:CreateSlider({
	    Name = "Level",
	    Min = 1.1,
	    Max = 6,
	    Default = 3,
	    Decimal = 10,
	    Suffix = "x"
	})
	Speed = Zoom:CreateSlider({
	    Name = "Speed",
	    Min = 1,
	    Max = 30,
	    Default = 12,
	    Tooltip = "How fast the zoom eases in and out, higher is snappier"
	})
	Sensitivity = Zoom:CreateToggle({
	    Name = "Sensitivity",
	    Default = true,
	    Tooltip = "Slows your mouse by the same amount you zoomed in"
	})
end)
