	if not chunk then
		task.spawn(error, v3)
	else
		local thread = task.spawn(chunk)
		local now = os.clock()

		while true do
			task.wait()
			if not (coroutine.status(thread) == "dead" or os.clock() - now > 15) then
				continue
			end
			break
		end
	end
else
	local v3 = request({
		Url = "https://api.catvape.dev/login",
		Method = "POST",
		Body = ("{\"key\":\"%*\"}"):format(tbl.Key),
	})

	if v3.StatusCode == 200 and v3.Body:find("return ") then
		local chunk, v4 = loadstring(v3.Body, "premium")

		if not chunk then
			task.spawn(error, v4)
		else
			local thread = task.spawn(chunk)
			local now = os.clock()

			while true do
				task.wait()
				if not (coroutine.status(thread) == "dead" or os.clock() - now > 15) then
					continue
				end
				break
			end
