				end
			end
		end
	elseif v3.StatusCode == 404 then
		local data = v2:JSONDecode(v3.Body)

		if typeof(data) == "table" and data.response then
			if data.response.name == "HWID_MISMATCH" then
				getgenv().catrole = ""
				vape:CreateNotification("Cat", "HWID MISMATCH, Go to the script panel to reset hwid", 25, "alert")
			elseif fn4(data.response.name) or fn4(data.response.message) then
				fn5(data.response.message)
			else
				vape:CreateNotification(data.response.name, data.response.message, 20, "alert")
			end
		end
	end
end

