		local v18

		v14 = vape.Legit:CreateModule({
			Name = "BedAlarm",
			Category = "Game",
			Icon = getvapeasset("GyuvapeBedwarsCheat/assets/new/legit_bedalarm.png"),
			Function = function(arg)
				if arg then
					local obj2 = setmetatable({}, { __mode = "k" })
					local n = 0

					local v19 = bedwars.SyncEvents.ProjectileLaunched:connect(function(arg2)
						if not v16.Enabled or not table.find(tbl3, arg2.projectileType) or typeof(arg2.origin) ~= "Vector3" or typeof(arg2.launchVelocity) ~= "Vector3" then
							return
						end
						local v19 = entity.getEntity(arg2.shooter)
						local isAlive = v19 and v19.Targetable and entity.isAlive
						local v20 = nil

						if isAlive then
							v20 = nil

							for _, v21 in v8:GetTagged("bed") do
								if tonumber(v21:GetAttribute("TeamId")) == tonumber(localPlayer:GetAttribute("Team")) then
									v20 = v21
									break
								else
									v20 = nil
								end
							end
						end

						if not v20 or os.clock() < n then
							return
						end
						local v21 = bedwars.ProjectileMeta[arg2.projectileType]
						local vector = Vector3.new(0, -(v21 and v21.gravitationalAcceleration or 196.2), 0)
						local filterDescendantsInstances = { arg2.shooter }

						for _, v22 in entity.List, nil, nil do
							table.insert(filterDescendantsInstances, v22.Character)
						end

						raycastParams.FilterDescendantsInstances = filterDescendantsInstances
						local origin = arg2.origin

						for i = 1, 100 do
							local n2 = i * 0.05
							local n3 = arg2.origin + arg2.launchVelocity * n2 + vector * 0.5 * n2 * n2
							local v22 = entity.Raycast(origin, n3 - origin, raycastParams)

							if v22 then
								origin = v22.Position
								break
							else
								origin = n3
							end
						end

						if v17.Value < (origin - v20.Position).Magnitude then
							return
						end
						n = os.clock() + 3.05

						if v15.Enabled and v19.Player and not obj2[v19.Character] then
							obj2[v19.Character] = true
							bedwars.BedAlarmController:addIntruderPlayerHighlight(v19.Player)
						end

						bedwars.NotificationController:sendInfoNotification({ message = "[Bed Alarm]: An intruder pearled to your bed!" })
						local flag = (entity.character.RootPart.Position - v20.Position).Magnitude < 30
						bedwars.AudioManager:playAudio(flag and bedwars.SoundList.BED_ALARM or bedwars.SoundList.BED_ALARM_TRIGGERED_FAR, { volumeMultiplier = v18.Value, position = flag and v20.Position or nil, rollOffMaxDistance = 100 })
					end)

					v14:Clean(function()
						v19:Destroy()
					end)
					;(function(...) end)()
				end
			end,
			Tooltip = "Notifies when an enemy is near your bed",
		})

		v15 = v14:CreateToggle({
			Name = "Highlight intruders",
			Default = true,
			Tooltip = "Outlines the intruders through walls\n(just like bedwars own bed alarm)",
		})

		v16 = v14:CreateToggle({
			Name = "Pearl detection",
			Default = true,
			Tooltip = "Also alarms the moment an enemy throws a pearl that lands at your bed",
		})

		v17 = v14:CreateSlider({
			Name = "Range",
			Min = 1,
			Max = 100,
			Default = 70,
			Suffix = function(arg)
				return arg == 1 and "stud" or "studs"
			end,
		})

		v18 = v14:CreateSlider({ Name = "Volume multiplier", Min = 0.1, Max = 2, Default = 1.4, Decimal = 100 })
	end)

